class ComposePilotActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        applyPilotSystemBars()
        val authStore = AuthStore(this)
        val api = ApiClient(authStore)
        val initialSettingsPageName = intent.getStringExtra("initial_settings_page")
            ?: getSharedPreferences(BuildConfig.MULTICA_AUTH_PREFS_NAME, Context.MODE_PRIVATE).getString("initial_settings_page", null)
        val initialIssueId = intent.getStringExtra("initial_issue_id")
        val initialTabName = intent.data?.host
        if (intent.getBooleanExtra("preview_agent_transcript", false)) {
            setContent {
                MulticaTheme {
                    PilotAgentTranscriptPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_projects_loading", false)) {
            setContent {
                MulticaTheme {
                    ProjectListLoadingSkeleton(zh = false)
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_inline_result_banners", false)) {
            setContent {
                MulticaTheme {
                    PilotInlineResultBannersPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_system_loading", false)) {
            setContent {
                MulticaTheme {
                    MulticaLoadingState("Loading workspace")
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_system_error", false)) {
            setContent {
                MulticaTheme {
                    MulticaErrorState(
                        message = "Session failed\nCheck your connection and try again.",
                        onRetry = {},
                        fullScreen = true,
                    )
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_my_invitations", false)) {
            setContent {
                MulticaTheme {
                    PilotMyInvitationsPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_members_settings", false)) {
            setContent {
                MulticaTheme {
                    PilotMembersPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_notification_settings", false)) {
            setContent {
                MulticaTheme {
                    PilotNotificationSettingsPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_workspace_settings", false)) {
            setContent {
                MulticaTheme {
                    PilotWorkspaceSettingsPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_labels_settings", false)) {
            setContent {
                MulticaTheme {
                    PilotLabelsSettingsPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_skills_settings", false)) {
            setContent {
                MulticaTheme {
                    PilotSkillsSettingsPreview()
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_feedback_settings", false)) {
            val showInlineError = intent.getBooleanExtra("preview_feedback_error", false)
            setContent {
                MulticaTheme {
                    PilotFeedbackSettingsPreview(showInlineError = showInlineError)
                }
            }
            return
        }
        if (intent.getBooleanExtra("preview_no_workspace_onboarding", false)) {
            val previewCreationSuccess = intent.getBooleanExtra("preview_no_workspace_success", false)
            val previewUser = Models.User(JSONObject()
                .put("id", "preview-user")
                .put("email", "preview@multica.ai")
                .put("name", "Preview User")
                .put("language", "en")
                .put("starter_content_state", JSONObject.NULL)
                .put("onboarding_questionnaire", JSONObject()
                    .put("team_size", "solo")
                    .put("role", "developer")
                    .put("use_case", "coding")))
            setContent {
                MulticaTheme {
                    PilotNoWorkspaceOnboarding(
                        api = api,
                        authStore = authStore,
                        user = previewUser,
                        onWorkspaceCreated = {},
                        previewCreationSuccess = previewCreationSuccess,
                    )
                }
            }
            return
        }
        setContent {
            MulticaTheme {
                ComposePilotApp(
                    authStore = authStore,
                    api = api,
                    initialSettingsPageName = initialSettingsPageName,
                    initialIssueId = initialIssueId,
                    initialTabName = initialTabName,
                )
            }
        }
    }

    private fun applyPilotSystemBars() {
        val darkTheme = (resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK) == Configuration.UI_MODE_NIGHT_YES
        WindowCompat.setDecorFitsSystemWindows(window, false)
        window.statusBarColor = AndroidColor.TRANSPARENT
        window.navigationBarColor = AndroidColor.TRANSPARENT
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            window.isStatusBarContrastEnforced = false
            window.isNavigationBarContrastEnforced = false
        }
        WindowInsetsControllerCompat(window, window.decorView).apply {
            isAppearanceLightStatusBars = !darkTheme
            isAppearanceLightNavigationBars = !darkTheme
        }
    }
}

