private enum class PilotSettingsPage {
    WorkspaceDetails,
    MyInvitations,
    Members,
    Notifications,
    ApiTokens,
    Agents,
    Autopilots,
    Runtimes,
    Labels,
    Skills,
    Feedback,
}

private fun pilotSettingsPageFromName(value: String?): PilotSettingsPage? {
    return when (value?.lowercase()?.replace("-", "_")) {
        "workspace_details", "workspacedetails" -> PilotSettingsPage.WorkspaceDetails
        "my_invitations", "myinvitations" -> PilotSettingsPage.MyInvitations
        "members" -> PilotSettingsPage.Members
        "notifications" -> PilotSettingsPage.Notifications
        "api_tokens", "apitokens" -> PilotSettingsPage.ApiTokens
        "agents" -> PilotSettingsPage.Agents
        "autopilots" -> PilotSettingsPage.Autopilots
        "runtimes" -> PilotSettingsPage.Runtimes
        "labels" -> PilotSettingsPage.Labels
        "skills" -> PilotSettingsPage.Skills
        "feedback" -> PilotSettingsPage.Feedback
        else -> null
    }
}

private sealed interface PilotState {
    data object Loading : PilotState
    data object SignedOut : PilotState
    data class Error(val message: String) : PilotState
    data class NoWorkspace(val user: Models.User) : PilotState
    data class Ready(val session: PilotSession) : PilotState
}

private sealed interface TabState {
    data object Loading : TabState
    data class Error(val message: String) : TabState
    data class Inbox(val items: List<Models.InboxItem>, val loading: Boolean = false, val hasMore: Boolean = false) : TabState
    data class Issues(val issues: List<Models.Issue>, val personal: Boolean, val loading: Boolean = false) : TabState
    data class Projects(val projects: List<Models.Project>) : TabState
    data object Settings : TabState
}

@Composable
private fun ComposePilotApp(
    authStore: AuthStore,
    api: ApiClient,
    initialSettingsPageName: String? = null,
    initialIssueId: String? = null,
    initialTabName: String? = null,
) {
    var appState by remember { mutableStateOf<PilotState>(PilotState.Loading) }
    var refresh by remember { mutableIntStateOf(0) }

    LaunchedEffect(refresh) {
        appState = PilotState.Loading
        if (authStore.token().isNullOrBlank()) {
            appState = PilotState.SignedOut
            return@LaunchedEffect
        }
        appState = withContext(Dispatchers.IO) {
            runCatching {
                val (user, workspaces) = coroutineScope {
                    val userDeferred = async { api.me() }
                    val workspacesDeferred = async { api.workspaces() }
                    userDeferred.await() to workspacesDeferred.await()
                }
                val preferred = authStore.workspaceId()
                val workspace = WorkspaceSelection.chooseWorkspace(workspaces, preferred)
                if (workspace == null) {
                    PilotState.NoWorkspace(user)
                } else {
                    authStore.saveWorkspaceId(workspace.id)
                    PilotState.Ready(PilotSession(user, workspaces, workspace))
                }
            }.getOrElse {
                if ((it is ApiClient.ApiException && it.code == 401) || it.message.orEmpty().contains("HTTP 401")) {
                    authStore.clearToken()
                    PilotState.SignedOut
                } else {
                    PilotState.Error(it.message ?: it.toString())
                }
            }
        }
    }

    when (val state = appState) {
        PilotState.Loading -> MulticaLoadingState("Loading Multica...")
        PilotState.SignedOut -> PilotLoginScreen(
            api = api,
            authStore = authStore,
            onAuthenticated = { refresh++ },
        )
        is PilotState.Error -> MulticaErrorState(
            message = "Session failed\n${state.message}",
            onRetry = { refresh++ },
            fullScreen = true,
        )
        is PilotState.NoWorkspace -> PilotNoWorkspaceOnboarding(
            api = api,
            authStore = authStore,
            user = state.user,
            onWorkspaceCreated = { refresh++ },
        )
        is PilotState.Ready -> ComposePilotShell(
            session = state.session,
            api = api,
            authStore = authStore,
            initialSettingsPageName = initialSettingsPageName,
            initialIssueId = initialIssueId,
            initialTabName = initialTabName,
            onReloadSession = { refresh++ },
            onSessionUpdated = { appState = PilotState.Ready(it) },
        )
    }
}

@Composable
private fun PilotLoginScreen(
    api: ApiClient,
    authStore: AuthStore,
    onAuthenticated: () -> Unit,
) {
    val zh = authStore.isChinese()
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val haptic = LocalHapticFeedback.current
    var email by remember { mutableStateOf("") }
    var code by remember { mutableStateOf("") }
    var codeSentTo by remember { mutableStateOf<String?>(null) }
    var loading by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }

    fun sendCode() {
        val cleanEmail = email.trim()
        if (cleanEmail.isEmpty() || loading) {
            message = if (zh) "请输入邮箱" else "Enter your email."
            return
        }
        loading = true
        message = null
        scope.launch {
            withContext(Dispatchers.IO) { runCatching { api.sendCode(cleanEmail) } }
                .onSuccess {
                    codeSentTo = cleanEmail
                    code = ""
                    message = if (zh) "验证码已发送，请检查邮箱。" else "Code sent. Check your email."
                    haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                }
                .onFailure {
                    message = "${if (zh) "验证码发送失败" else "Failed to send code"}: ${it.message ?: it.toString()}"
                }
            loading = false
        }
    }

    fun verifyCode() {
        val cleanEmail = codeSentTo ?: email.trim()
        val cleanCode = code.trim()
        if (cleanEmail.isEmpty() || cleanCode.length < 4 || loading) {
            message = if (zh) "请输入邮箱验证码" else "Enter the email code."
            return
        }
        loading = true
        message = null
        scope.launch {
            withContext(Dispatchers.IO) { runCatching { api.verifyCode(cleanEmail, cleanCode) } }
                .onSuccess { token ->
                    if (token.isBlank()) {
                        message = if (zh) "登录失败：服务端未返回 token。" else "Sign in failed: no token returned."
                    } else {
                        authStore.saveToken(token)
                        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                        onAuthenticated()
                    }
                }
                .onFailure {
                    message = "${if (zh) "登录失败" else "Sign in failed"}: ${it.message ?: it.toString()}"
                }
            loading = false
        }
    }

    Surface(color = MulticaColors.Background) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .imePadding()
                .semantics { contentDescription = "Multica Login Screen Email Code" },
            contentPadding = PaddingValues(horizontal = 28.dp, vertical = 78.dp),
            verticalArrangement = Arrangement.spacedBy(18.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            item {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Box(
                        modifier = Modifier
                            .size(64.dp)
                            .clip(RoundedCornerShape(20.dp))
                            .background(MulticaColors.Accent.copy(alpha = 0.12f)),
                        contentAlignment = Alignment.Center,
                    ) {
                        Text(
                            text = "M",
                            style = MaterialTheme.typography.titleLarge.copy(fontSize = 28.sp, lineHeight = 32.sp, fontWeight = FontWeight.Bold),
                            color = MulticaColors.Accent,
                        )
                    }
                    Text(
                        text = if (zh) "登录 Multica" else "Sign in to Multica",
                        style = MaterialTheme.typography.titleLarge.copy(fontSize = 30.sp, lineHeight = 36.sp, fontWeight = FontWeight.Bold),
                        color = MulticaColors.Text,
                        textAlign = TextAlign.Center,
                    )
                    Text(
                        text = if (zh) "输入邮箱获取验证码，和 Web/桌面端使用同一套官方登录服务。" else "Use your email code. This is the same official sign-in service as web and desktop.",
                        style = MaterialTheme.typography.bodyMedium.copy(fontSize = 15.sp, lineHeight = 21.sp),
                        color = MulticaColors.Muted,
                        textAlign = TextAlign.Center,
                    )
                }
            }
            item {
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Multica Login Email Code Card" },
                    shape = RoundedCornerShape(20.dp),
                    color = MulticaColors.Surface,
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                    border = androidx.compose.foundation.BorderStroke(0.75.dp, MulticaColors.Border.copy(alpha = 0.62f)),
                ) {
                    Column(
                        modifier = Modifier.padding(18.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp),
                    ) {
                        MulticaTextField(
                            value = email,
                            onValueChange = {
                                email = it
                                if (codeSentTo != null && it.trim() != codeSentTo) codeSentTo = null
                            },
                            label = if (zh) "邮箱" else "Email",
                            contentDescription = "Login Email Field",
                            enabled = !loading,
                            singleLine = true,
                        )
                        if (codeSentTo != null) {
                            MulticaTextField(
                                value = code,
                                onValueChange = { code = it },
                                label = if (zh) "验证码" else "Code",
                                contentDescription = "Login Code Field",
                                enabled = !loading,
                                singleLine = true,
                            )
                        }
                        MulticaPillButton(
                            text = when {
                                loading -> "..."
                                codeSentTo == null -> if (zh) "发送验证码" else "Send Code"
                                else -> if (zh) "登录" else "Sign In"
                            },
                            onClick = { if (codeSentTo == null) sendCode() else verifyCode() },
                            modifier = Modifier.fillMaxWidth(),
                            tone = MulticaButtonTone.Primary,
                            enabled = !loading,
                            contentDescription = if (codeSentTo == null) "Login Send Code" else "Login Verify Code",
                        )
                        if (codeSentTo != null) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    text = codeSentTo.orEmpty(),
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                                    color = MulticaColors.Muted,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                MulticaPillButton(
                                    text = if (zh) "重发" else "Resend",
                                    onClick = { sendCode() },
                                    tone = MulticaButtonTone.Ghost,
                                    enabled = !loading,
                                    contentDescription = "Login Resend Code",
                                )
                            }
                        }
                    }
                }
            }
            if (!message.isNullOrBlank()) {
                item {
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Login Result Message" },
                        shape = RoundedCornerShape(14.dp),
                        color = if (message!!.contains("失败") || message!!.contains("failed", ignoreCase = true)) {
                            MulticaColors.Danger.copy(alpha = 0.10f)
                        } else {
                            MulticaColors.AccentSoft.copy(alpha = 0.62f)
                        },
                        tonalElevation = 0.dp,
                        shadowElevation = 0.dp,
                    ) {
                        Text(
                            text = message.orEmpty(),
                            modifier = Modifier.padding(14.dp),
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = 13.sp, lineHeight = 18.sp),
                            color = if (message!!.contains("失败") || message!!.contains("failed", ignoreCase = true)) MulticaColors.Danger else MulticaColors.Text,
                        )
                    }
                }
            }
            item {
                MulticaPillButton(
                    text = if (zh) "用浏览器打开 Web 登录" else "Open Web Sign In",
                    onClick = {
                        context.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("${BuildConfig.MULTICA_WEB_BASE_URL}/login")))
                    },
                    tone = MulticaButtonTone.Ghost,
                    contentDescription = "Login Open Web Sign In",
                )
            }
        }
    }
}

@Composable
private fun PilotNoWorkspaceOnboarding(
    api: ApiClient,
    authStore: AuthStore,
    user: Models.User,
    onWorkspaceCreated: () -> Unit,
    previewCreationSuccess: Boolean = false,
) {
    val zh = authStore.isChinese()
    val contextHandle = LocalContext.current
    val haptic = LocalHapticFeedback.current
    val scope = rememberCoroutineScope()
    var name by remember { mutableStateOf("") }
    var slug by remember { mutableStateOf("") }
    var slugTouched by remember { mutableStateOf(false) }
    var teamSize by remember { mutableStateOf(user.onboardingQuestionnaire.optString("team_size", "")) }
    var role by remember { mutableStateOf(user.onboardingQuestionnaire.optString("role", "")) }
    var useCase by remember { mutableStateOf(user.onboardingQuestionnaire.optString("use_case", "")) }
    var notes by remember { mutableStateOf(user.onboardingQuestionnaire.optString("notes", "")) }
    var cloudEmail by remember { mutableStateOf(user.email) }
    var cloudReason by remember { mutableStateOf("") }
    var starterChoice by remember { mutableStateOf("import") }
    var saving by remember { mutableStateOf(false) }
    var onboardingSaving by remember { mutableStateOf(false) }
    var cloudSaving by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var creationSuccess by remember { mutableStateOf(previewCreationSuccess) }
    val slugFieldError = noWorkspaceSlugValidationError(slug, zh)

    fun saveQuestionnaire() {
        if (onboardingSaving) return
        onboardingSaving = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    api.patchOnboarding(OnboardingPayload.questionnaire(teamSize, role, useCase, notes))
                }
            }
            onboardingSaving = false
            result.onSuccess {
                message = if (zh) "入门问卷已保存" else "Onboarding answers saved"
            }.onFailure {
                message = "${if (zh) "入门问卷保存失败" else "Onboarding save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun joinWaitlist() {
        val email = cloudEmail.trim()
        if (cloudSaving || email.isBlank()) return
        cloudSaving = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.joinCloudWaitlist(email, cloudReason) }
            }
            cloudSaving = false
            result.onSuccess {
                message = if (zh) "已加入云端 Runtime 等候列表" else "Joined the cloud runtime waitlist"
            }.onFailure {
                message = "${if (zh) "加入等候列表失败" else "Cloud waitlist failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun createWorkspace() {
        val trimmedName = name.trim()
        val trimmedSlug = slug.trim()
        if (saving || trimmedName.isBlank() || trimmedSlug.isBlank()) return
        if (slugFieldError != null) {
            slugTouched = true
            return
        }
        saving = true
        message = null
        creationSuccess = false
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.createWorkspace(trimmedName, trimmedSlug, "", "") }
            }
            saving = false
            result.onSuccess { workspace ->
                withContext(Dispatchers.IO) {
                    runCatching {
                        val questionnaire = OnboardingPayload.questionnaire(teamSize, role, useCase, notes)
                        if (questionnaire.length() > 0) api.patchOnboarding(questionnaire)
                    }
                    val completionPath = when (starterChoice) {
                        "import" -> {
                            runCatching {
                                api.importStarterContent(OnboardingPayload.starterContentPayload(workspace.id, true))
                            }
                            "starter_content_imported"
                        }
                        "dismiss" -> {
                            runCatching { api.dismissStarterContent(workspace.id) }
                            "starter_content_dismissed"
                        }
                        else -> "runtime_skipped"
                    }
                    runCatching { api.markOnboardingComplete(completionPath) }
                }
                creationSuccess = true
                message = if (zh) "工作区已创建，正在进入 Multica..." else "Workspace created. Opening Multica..."
                haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                delay(450)
                authStore.saveWorkspaceId(workspace.id)
                onWorkspaceCreated()
            }.onFailure {
                creationSuccess = false
                message = "${if (zh) "工作区创建失败" else "Workspace create failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun logOut() {
        authStore.clearToken()
        contextHandle.startActivity(
            Intent(contextHandle, MainActivity::class.java)
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)
        )
    }

    Surface(color = MulticaColors.Background) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(20.dp)
                .semantics { contentDescription = "No Workspace Global State" },
            contentPadding = PaddingValues(vertical = 24.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
            item {
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics(mergeDescendants = true) { contentDescription = "No Workspace Web Hero" },
                    shape = RoundedCornerShape(18.dp),
                    color = MulticaColors.Surface,
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                ) {
                    Column(
                        modifier = Modifier.padding(horizontal = 16.dp, vertical = 18.dp),
                        verticalArrangement = Arrangement.spacedBy(7.dp),
                    ) {
                        Text(
                            text = "Multica",
                            style = MaterialTheme.typography.titleLarge.copy(fontSize = 28.sp, lineHeight = 33.sp),
                            color = MulticaColors.Text,
                            fontWeight = FontWeight.Bold,
                        )
                        Text(
                            text = if (zh) {
                                "欢迎，${user.name.ifBlank { user.email }}。创建第一个工作区即可进入 Multica。"
                            } else {
                                "Welcome, ${user.name.ifBlank { user.email }}. Create your first workspace to enter Multica."
                            },
                            style = MaterialTheme.typography.bodyMedium,
                            color = MulticaColors.Muted,
                        )
                    }
                }
            }
            item {
                NoWorkspaceStepGroupPanel(contentDescription = "No Workspace Create Workspace Web Panel") {
                    OnboardingStepHeader(
                        title = if (zh) "创建第一个工作区" else "Create your first workspace",
                        subtitle = if (zh) {
                            "名称和 slug 对齐 Web 创建流程；创建成功后自动进入主界面。"
                        } else {
                            "Name and slug match the web creation flow. You will enter the app after creation."
                        },
                        contentDescription = "No Workspace Web Step Group Create Workspace",
                    )
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                            .semantics { contentDescription = "No Workspace Create Workspace Fields" },
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaTextField(
                            value = name,
                            onValueChange = {
                                name = it
                                if (!slugTouched) slug = workspaceSlugFromName(it)
                            },
                            label = if (zh) "工作区名称" else "Workspace name",
                            singleLine = true,
                        )
                        MulticaTextField(
                            value = slug,
                            onValueChange = {
                                slugTouched = true
                                slug = it
                            },
                            label = if (zh) "工作区 slug" else "Workspace slug",
                            singleLine = true,
                        )
                        if (slugTouched && slugFieldError != null) {
                            Text(
                                text = slugFieldError,
                                modifier = Modifier.semantics { contentDescription = "No Workspace Slug Field Error" },
                                style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                                color = MulticaColors.Danger,
                            )
                        }
                        MulticaPillButton(
                            text = if (saving) "..." else if (zh) "创建工作区" else "Create Workspace",
                            onClick = { createWorkspace() },
                            modifier = Modifier.fillMaxWidth(),
                            tone = MulticaButtonTone.Primary,
                            contentDescription = "No Workspace Primary Create Action",
                        )
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = "No Workspace Bottom Account Actions" },
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Text(
                                text = if (zh) "当前账号 ${user.email}" else "Signed in as ${user.email}",
                                modifier = Modifier
                                    .weight(1f)
                                    .semantics { contentDescription = "No Workspace Signed In Account" },
                                style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                                color = MulticaColors.Muted,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            MulticaPillButton(
                                text = if (zh) "退出" else "Log out",
                                onClick = { logOut() },
                                tone = MulticaButtonTone.Ghost,
                                contentDescription = "No Workspace Account Escape",
                            )
                        }
                        if (creationSuccess) {
                            MulticaSuccessState(
                                if (zh) "工作区已创建，正在进入 Multica..." else "Workspace created. Opening Multica..."
                            )
                        } else {
                            message?.let {
                                PilotInlineResultState(
                                    message = it,
                                    isError = pilotInlineResultIsError(it),
                                    contentDescription = "No Workspace Result Web Banner",
                                )
                            }
                        }
                    }
                }
            }
            item {
                NoWorkspaceStepGroupPanel(contentDescription = "No Workspace Questionnaire Web Panel") {
                    OnboardingStepHeader(
                        title = if (zh) "入门问卷" else "Onboarding questions",
                        subtitle = if (zh) {
                            "用于生成更贴合你的 starter content，也对齐 web 的首次使用流程。"
                        } else {
                            "Used to personalize starter content and match the web first-run flow."
                        },
                        contentDescription = "No Workspace Web Step Group Questionnaire",
                    )
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                            .semantics { contentDescription = "No Workspace Questionnaire Fields" },
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaTextField(
                            value = teamSize,
                            onValueChange = { teamSize = it },
                            label = if (zh) "团队规模" else "Team size",
                            singleLine = true,
                        )
                        MulticaTextField(
                            value = role,
                            onValueChange = { role = it },
                            label = if (zh) "你的角色" else "Your role",
                            singleLine = true,
                        )
                        MulticaTextField(
                            value = useCase,
                            onValueChange = { useCase = it },
                            label = if (zh) "使用场景" else "Use case",
                            singleLine = true,
                        )
                        MulticaTextField(
                            value = notes,
                            onValueChange = { notes = it },
                            label = if (zh) "补充说明" else "Notes",
                            minLines = 2,
                        )
                        MulticaPillButton(
                            text = if (onboardingSaving) "..." else if (zh) "保存入门问卷" else "Save Onboarding Answers",
                            onClick = { saveQuestionnaire() },
                            modifier = Modifier.fillMaxWidth(),
                            tone = MulticaButtonTone.Secondary,
                        )
                    }
                }
            }
            item {
                NoWorkspaceStepGroupPanel(contentDescription = "No Workspace Starter Content Web Panel") {
                    OnboardingStepHeader(
                        title = if (zh) "Starter content" else "Starter content",
                        subtitle = if (zh) {
                            "创建工作区后，可以自动导入入门项目，或明确跳过。"
                        } else {
                            "After workspace creation, import a starter project or explicitly skip it."
                        },
                        contentDescription = "No Workspace Web Step Group Starter Content",
                    )
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(12.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            MulticaPillButton(
                                text = if (zh) "导入" else "Import",
                                onClick = { starterChoice = "import" },
                                modifier = Modifier.weight(1f),
                                tone = if (starterChoice == "import") MulticaButtonTone.Secondary else MulticaButtonTone.Ghost,
                                contentDescription = "Starter Content Import",
                            )
                            MulticaPillButton(
                                text = if (zh) "不导入" else "Dismiss",
                                onClick = { starterChoice = "dismiss" },
                                modifier = Modifier.weight(1f),
                                tone = if (starterChoice == "dismiss") MulticaButtonTone.Secondary else MulticaButtonTone.Ghost,
                                contentDescription = "Starter Content Dismiss",
                            )
                            MulticaPillButton(
                                text = if (zh) "稍后" else "Later",
                                onClick = { starterChoice = "skip" },
                                modifier = Modifier.weight(1f),
                                tone = if (starterChoice == "skip") MulticaButtonTone.Secondary else MulticaButtonTone.Ghost,
                                contentDescription = "Starter Content Later",
                            )
                        }
                        Text(
                            text = if (zh) {
                                "导入会创建 Getting Started 项目和入门 issues；不导入会调用 dismiss，稍后只完成基础 onboarding。"
                            } else {
                                "Import creates a Getting Started project and starter issues; Dismiss records the decision; Later completes only the base onboarding path."
                            },
                            style = MaterialTheme.typography.bodySmall,
                            color = MulticaColors.Muted,
                        )
                    }
                }
            }
            item {
                NoWorkspaceStepGroupPanel(contentDescription = "No Workspace Runtime Setup Web Panel") {
                    OnboardingStepHeader(
                        title = if (zh) "Runtime 与 Agent 设置" else "Runtime and agent setup",
                        subtitle = if (zh) {
                            "移动端不会自动创建或删除 runtime。创建 workspace 后，可按这三步完成 web onboarding 的后续配置。"
                        } else {
                            "Mobile will not automatically create or delete runtimes. After workspace creation, use these three steps to finish the rest of web onboarding."
                        },
                        contentDescription = "No Workspace Web Step Group Runtime Setup",
                    )
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                            .semantics(mergeDescendants = false) { contentDescription = "No Workspace Runtime Setup Rows" },
                    ) {
                        OnboardingInfoRow(
                            title = if (zh) "稍后连接 Runtime" else "Connect Runtime later",
                            subtitle = if (zh) {
                                "进入 Settings -> Runtimes 查看 connect remote 命令，或加入云端 Runtime 等候列表。"
                            } else {
                                "Open Settings -> Runtimes for the connect remote command, or join the cloud runtime waitlist."
                            },
                            icon = Icons.Outlined.Dashboard,
                            showDivider = true,
                        )
                        OnboardingInfoRow(
                            title = if (zh) "稍后创建 Agent" else "Create Agent later",
                            subtitle = if (zh) {
                                "进入 Settings -> Agents 创建 agent，绑定 runtime、skills、model、env 和 custom args。"
                            } else {
                                "Open Settings -> Agents to create an agent and configure runtime, skills, model, env, and custom args."
                            },
                            icon = Icons.Outlined.Bolt,
                            showDivider = true,
                        )
                        OnboardingInfoRow(
                            title = if (zh) "第一个 Issue" else "First Issue",
                            subtitle = if (zh) {
                                "导入 starter content 会创建入门 issues；也可以进入主界面后用 New Issue 自己创建。"
                            } else {
                                "Importing starter content creates starter issues, or you can create one with New Issue after entering the app."
                            },
                            icon = Icons.Outlined.Add,
                        )
                    }
                }
            }
            item {
                NoWorkspaceStepGroupPanel(contentDescription = "No Workspace Cloud Waitlist Web Panel") {
                    OnboardingStepHeader(
                        title = if (zh) "云端 Runtime 等候列表" else "Cloud runtime waitlist",
                        subtitle = if (zh) {
                            "如果暂时没有自己的 runtime，可以在移动端加入等候列表。"
                        } else {
                            "If you do not have your own runtime yet, join the mobile waitlist."
                        },
                        contentDescription = "No Workspace Web Step Group Cloud Waitlist",
                    )
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp)
                            .semantics { contentDescription = "No Workspace Cloud Waitlist Fields" },
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaTextField(
                            value = cloudEmail,
                            onValueChange = { cloudEmail = it },
                            label = if (zh) "邮箱" else "Email",
                            singleLine = true,
                        )
                        MulticaTextField(
                            value = cloudReason,
                            onValueChange = { cloudReason = it },
                            label = if (zh) "原因" else "Reason",
                            minLines = 2,
                        )
                        MulticaPillButton(
                            text = if (cloudSaving) "..." else if (zh) "加入等候列表" else "Join Cloud Waitlist",
                            onClick = { joinWaitlist() },
                            modifier = Modifier.fillMaxWidth(),
                            tone = MulticaButtonTone.Secondary,
                        )
                    }
                }
            }
            item {
                Text(
                    text = if (zh) "受邀加入已有工作区时，请使用相同账号登录。" else "Invited to an existing workspace? Sign in with that same account.",
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "No Workspace Invite Hint" },
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                    color = MulticaColors.Muted,
                    textAlign = TextAlign.Center,
                )
            }
        }
    }
}

@Composable
private fun NoWorkspaceStepGroupPanel(
    contentDescription: String,
    content: @Composable ColumnScope.() -> Unit,
) {
    val shape = RoundedCornerShape(14.dp)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { this.contentDescription = contentDescription },
        shape = shape,
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.66f), shape)
                .padding(vertical = 2.dp),
            content = content,
        )
    }
}

@Composable
private fun OnboardingStepHeader(
    title: String,
    subtitle: String,
    contentDescription: String,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 12.dp, vertical = 12.dp)
            .semantics(mergeDescendants = true) {
                this.contentDescription = "No Workspace Web Step Group $contentDescription"
            },
        verticalArrangement = Arrangement.spacedBy(3.dp),
    ) {
        Text(
            text = title,
            style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
            color = MulticaColors.Text,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
        )
        Text(
            text = subtitle,
            style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
            color = MulticaColors.Muted,
            maxLines = 3,
            overflow = TextOverflow.Ellipsis,
        )
        Spacer(modifier = Modifier.height(2.dp))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(1.dp)
                .background(MulticaColors.Border)
        )
    }
}

@Composable
private fun OnboardingInfoRow(
    title: String,
    subtitle: String,
    icon: ImageVector,
    showDivider: Boolean = false,
) {
    Column(modifier = Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 8.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Surface(
                modifier = Modifier.size(28.dp),
                shape = RoundedCornerShape(8.dp),
                color = MulticaColors.Border.copy(alpha = 0.38f),
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Icon(
                        imageVector = icon,
                        contentDescription = null,
                        tint = MulticaColors.Muted,
                        modifier = Modifier.size(15.dp),
                    )
                }
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodySmall.copy(
                        fontSize = 13.sp,
                        lineHeight = 16.sp,
                        fontWeight = FontWeight.Medium,
                    ),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = subtitle,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp),
                    color = MulticaColors.Muted,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
        if (showDivider) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border)
            )
        }
    }
}

private fun workspaceSlugFromName(value: String): String {
    return value.trim()
        .lowercase()
        .replace(Regex("[^a-z0-9]+"), "-")
        .trim('-')
        .take(48)
}

private fun noWorkspaceSlugValidationError(slug: String, zh: Boolean): String? {
    val trimmed = slug.trim()
    if (trimmed.isBlank()) return null
    if (!Regex("^[a-z0-9]+(?:-[a-z0-9]+)*$").matches(trimmed)) {
        return if (zh) {
            "只能使用小写字母、数字和单个连字符，且不能以连字符开头或结尾。"
        } else {
            "Use lowercase letters, numbers, and single hyphens; do not start or end with a hyphen."
        }
    }
    val reserved = setOf("api", "app", "auth", "login", "new", "settings", "signup", "www", "workspaces")
    if (trimmed in reserved) {
        return if (zh) "这个 slug 被系统保留，请换一个。" else "This workspace URL is reserved. Choose another slug."
    }
    return null
}

@Composable
private fun ComposePilotShell(
    session: PilotSession,
    api: ApiClient,
    authStore: AuthStore,
    initialSettingsPageName: String? = null,
    initialIssueId: String? = null,
    initialTabName: String? = null,
    onReloadSession: () -> Unit,
    onSessionUpdated: (PilotSession) -> Unit,
) {
    val initialSettingsPage = remember(initialSettingsPageName) { pilotSettingsPageFromName(initialSettingsPageName) }
    val initialTab = remember(initialSettingsPage, initialTabName) {
        when {
            initialSettingsPage != null -> MulticaTab.Settings
            initialTabName.equals("issues", ignoreCase = true) -> MulticaTab.Issues
            initialTabName.equals("inbox", ignoreCase = true) -> MulticaTab.Inbox
            initialTabName.equals("projects", ignoreCase = true) -> MulticaTab.Projects
            else -> MulticaTab.Inbox
        }
    }
    var selectedTab by remember(session.workspace.id, initialTab) {
        mutableStateOf(initialTab)
    }
    var zh by remember { mutableStateOf(authStore.isChinese()) }
    var tabState by remember { mutableStateOf<TabState>(TabState.Loading) }
    var issueDetailId by remember(session.workspace.id, initialIssueId) {
        mutableStateOf(initialIssueId?.takeIf { it.isNotBlank() })
    }
    var projectDetail by remember { mutableStateOf<Models.Project?>(null) }
    var issueFormOpen by remember { mutableStateOf(false) }
    var issueFormIssue by remember { mutableStateOf<Models.Issue?>(null) }
    var issueFormParentId by remember { mutableStateOf<String?>(null) }
    var issueFormParentIdentifier by remember { mutableStateOf<String?>(null) }
    var searchOpen by remember { mutableStateOf(initialTabName.equals("search", ignoreCase = true)) }
    var chatOpen by remember { mutableStateOf(false) }
    var chatSession by remember { mutableStateOf<Models.ChatSession?>(null) }
    var settingsPage by remember(session.workspace.id, initialSettingsPage) { mutableStateOf(initialSettingsPage) }
    var profileOpen by remember(session.user.id) { mutableStateOf(false) }
    var selectedIssueIds by remember(session.workspace.id) { mutableStateOf(setOf<String>()) }
    var inboxIssueContext by remember(session.workspace.id) { mutableStateOf<InboxIssueContext?>(null) }
    var retainedSearchQuery by remember(session.workspace.id) { mutableStateOf("") }
    var returnToSearchAfterDetail by remember(session.workspace.id) { mutableStateOf(false) }
    var tabRefresh by remember { mutableIntStateOf(0) }
    val shellScope = rememberCoroutineScope()

    fun markInboxReadOnOpen(item: Models.InboxItem) {
        if (item.read || item.id.isBlank()) return
        shellScope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.markInboxRead(session.workspace.id, item.id) }
            }
            result.onSuccess { tabRefresh++ }
        }
    }

    LaunchedEffect(selectedTab, session.workspace.id, tabRefresh) {
        if (issueDetailId != null || projectDetail != null || searchOpen || chatOpen || settingsPage != null || profileOpen) return@LaunchedEffect
        val currentTabState = tabState
        tabState = when (selectedTab) {
            MulticaTab.Inbox -> {
                val cached = withContext(Dispatchers.IO) {
                    runCatching { api.cachedInbox(session.workspace.id) }.getOrNull()
                }
                if (cached != null && cached.items.isNotEmpty()) {
                    TabState.Inbox(cached.items, loading = false, hasMore = cached.hasMore)
                } else {
                    TabState.Inbox(emptyList(), loading = true)
                }
            }
            MulticaTab.Issues -> TabState.Issues(emptyList(), personal = false, loading = true)
            MulticaTab.MyIssues -> TabState.Issues(emptyList(), personal = true, loading = true)
            MulticaTab.Projects -> if (currentTabState is TabState.Projects) currentTabState else TabState.Loading
            MulticaTab.Settings -> TabState.Settings
        }
        tabState = withContext(Dispatchers.IO) {
            runCatching {
                when (selectedTab) {
                    MulticaTab.Inbox -> {
                        val page = api.inbox(session.workspace.id, PILOT_INBOX_PAGE_SIZE, 0)
                        TabState.Inbox(page.items, hasMore = page.hasMore)
                    }
                    MulticaTab.Issues -> TabState.Issues(
                        IssueBuckets.loadAllConcurrent(
                            { status, limit, offset -> api.issues(session.workspace.id, limit, offset, null, status) },
                            100,
                        ),
                        personal = false,
                    )
                    MulticaTab.MyIssues -> TabState.Issues(
                        IssueBuckets.loadAllConcurrent(
                            { status, limit, offset -> api.issues(session.workspace.id, limit, offset, session.user.id, status) },
                            100,
                        ),
                        personal = true,
                    )
                    MulticaTab.Projects -> TabState.Projects(api.projects(session.workspace.id, 100, 0).items)
                    MulticaTab.Settings -> TabState.Settings
                }
            }.getOrElse { TabState.Error(it.message ?: it.toString()) }
        }
    }

    val secondaryScreenOpen = issueFormOpen ||
        profileOpen ||
        issueDetailId != null ||
        projectDetail != null ||
        searchOpen ||
        chatOpen ||
        chatSession != null ||
        settingsPage != null

    BackHandler(enabled = secondaryScreenOpen) {
        when {
            issueFormOpen -> {
                issueFormOpen = false
                issueFormIssue = null
                issueFormParentId = null
                issueFormParentIdentifier = null
            }
            searchOpen -> searchOpen = false
            profileOpen -> profileOpen = false
            settingsPage != null -> settingsPage = null
            chatSession != null -> chatSession = null
            chatOpen -> chatOpen = false
            issueDetailId != null -> {
                if (inboxIssueContext != null) tabRefresh++
                issueDetailId = null
                inboxIssueContext = null
                if (returnToSearchAfterDetail) {
                    searchOpen = true
                    returnToSearchAfterDetail = false
                }
            }
            projectDetail != null -> {
                projectDetail = null
                if (returnToSearchAfterDetail) {
                    searchOpen = true
                    returnToSearchAfterDetail = false
                }
            }
        }
    }

    MulticaShell(
        selectedTab = selectedTab,
        workspaceName = session.workspace.name,
        languageLabel = if (zh) "EN" else "中文",
        zh = zh,
        onLanguageClick = {
            zh = !zh
            authStore.setChinese(zh)
        },
        onWorkspaceClick = {
            selectedTab = MulticaTab.Settings
            settingsPage = PilotSettingsPage.WorkspaceDetails
            issueDetailId = null
            inboxIssueContext = null
            returnToSearchAfterDetail = false
            projectDetail = null
            searchOpen = false
            chatOpen = false
            chatSession = null
            profileOpen = false
            issueFormOpen = false
            issueFormIssue = null
            issueFormParentId = null
            issueFormParentIdentifier = null
        },
        onSearchClick = {
            searchOpen = true
            issueDetailId = null
            inboxIssueContext = null
            returnToSearchAfterDetail = false
            projectDetail = null
            chatOpen = false
            chatSession = null
            settingsPage = null
            profileOpen = false
            issueFormOpen = false
            issueFormIssue = null
            issueFormParentId = null
            issueFormParentIdentifier = null
        },
        onChatClick = {
            selectedTab = MulticaTab.Inbox
            issueDetailId = null
            inboxIssueContext = null
            returnToSearchAfterDetail = false
            projectDetail = null
            searchOpen = false
            chatOpen = true
            chatSession = null
            settingsPage = null
            profileOpen = false
            issueFormOpen = false
            issueFormIssue = null
            issueFormParentId = null
            issueFormParentIdentifier = null
        },
        onTabClick = {
            selectedTab = it
            issueDetailId = null
            inboxIssueContext = null
            returnToSearchAfterDetail = false
            projectDetail = null
            searchOpen = false
            chatOpen = false
            chatSession = null
            settingsPage = null
            profileOpen = false
            if (it != MulticaTab.Issues && it != MulticaTab.MyIssues) selectedIssueIds = emptySet()
        },
        showChrome = !secondaryScreenOpen,
    ) {
        val detailId = issueDetailId
        val activeInboxContext = inboxIssueContext?.takeIf { it.issueId == detailId }
        val activeProject = projectDetail
        val activeChat = chatSession
        val activeSettingsPage = settingsPage
        if (issueFormOpen) {
            PilotIssueForm(
                api = api,
                session = session,
                issue = issueFormIssue,
                parentIssueId = issueFormParentId,
                parentIssueIdentifier = issueFormParentIdentifier,
                zh = zh,
                onCancel = {
                    issueFormOpen = false
                    issueFormIssue = null
                    issueFormParentId = null
                    issueFormParentIdentifier = null
                },
                onSaved = { saved ->
                    issueFormOpen = false
                    issueFormIssue = null
                    issueFormParentId = null
                    issueFormParentIdentifier = null
                    projectDetail = null
                    chatOpen = false
                    chatSession = null
                    issueDetailId = saved.id
                    tabRefresh++
                },
            )
        } else if (searchOpen) {
            PilotSearchPage(
                api = api,
                workspaceId = session.workspace.id,
                zh = zh,
                query = retainedSearchQuery,
                onQueryChange = { retainedSearchQuery = it },
                onBack = { searchOpen = false },
                onIssueClick = {
                    searchOpen = false
                    issueDetailId = it
                    inboxIssueContext = null
                    returnToSearchAfterDetail = true
                },
                onProjectClick = {
                    searchOpen = false
                    projectDetail = it
                    returnToSearchAfterDetail = true
                },
                onTabClick = {
                    selectedTab = it
                    searchOpen = false
                    returnToSearchAfterDetail = false
                },
                onSettingsPageClick = {
                    selectedTab = MulticaTab.Settings
                    settingsPage = it
                    searchOpen = false
                    returnToSearchAfterDetail = false
                },
            )
        } else if (activeSettingsPage != null) {
            PilotSettingsSubpage(
                page = activeSettingsPage,
                api = api,
                workspaceId = session.workspace.id,
                currentUserId = session.user.id,
                zh = zh,
                onReloadSession = onReloadSession,
                onSwitchWorkspace = { nextWorkspaceId ->
                    authStore.saveWorkspaceId(nextWorkspaceId)
                    onReloadSession()
                },
                onBack = { settingsPage = null },
            )
        } else if (chatOpen && activeChat == null) {
            PilotChatSessions(
                api = api,
                workspaceId = session.workspace.id,
                zh = zh,
                onBack = { chatOpen = false },
                onSessionClick = { chatSession = it },
            )
        } else if (activeChat != null) {
            PilotChatMessages(
                api = api,
                workspaceId = session.workspace.id,
                session = activeChat,
                zh = zh,
                onBack = { chatSession = null },
                onArchived = {
                    chatSession = null
                    chatOpen = false
                },
            )
        } else if (detailId != null) {
            PilotIssueDetail(
                api = api,
                workspaceId = session.workspace.id,
                workspaceSlug = session.workspace.slug,
                issueId = detailId,
                currentUser = session.user,
                zh = zh,
                onBack = {
                    if (activeInboxContext != null) tabRefresh++
                    issueDetailId = null
                    inboxIssueContext = null
                    if (returnToSearchAfterDetail) {
                        searchOpen = true
                        returnToSearchAfterDetail = false
                    }
                },
                onOpenIssue = {
                    issueDetailId = it
                    inboxIssueContext = null
                    returnToSearchAfterDetail = false
                },
                onEditIssue = {
                    issueFormIssue = it
                    issueFormParentId = null
                    issueFormParentIdentifier = null
                    issueFormOpen = true
                },
                onCreateChildIssue = {
                    issueFormIssue = null
                    issueFormParentId = it.id
                    issueFormParentIdentifier = it.identifier
                    issueFormOpen = true
                },
                onDeleted = {
                    issueDetailId = null
                    inboxIssueContext = null
                    returnToSearchAfterDetail = false
                    tabRefresh++
                },
                highlightCommentId = activeInboxContext?.commentId,
                inboxItemId = activeInboxContext?.itemId,
                inboxNextIssueId = activeInboxContext?.nextIssueId,
                onInboxDone = { nextIssueId ->
                    issueDetailId = nextIssueId.takeIf { !it.isNullOrBlank() }
                    inboxIssueContext = null
                    tabRefresh++
                },
            )
        } else if (activeProject != null) {
            PilotProjectDetail(
                api = api,
                workspaceId = session.workspace.id,
                project = activeProject,
                zh = zh,
                onBack = {
                    projectDetail = null
                    if (returnToSearchAfterDetail) {
                        searchOpen = true
                        returnToSearchAfterDetail = false
                    }
                },
                onIssueClick = {
                    issueDetailId = it
                    returnToSearchAfterDetail = false
                },
            )
        } else {
            PilotTabContent(
                api = api,
                state = tabState,
                selectedTab = selectedTab,
                zh = zh,
                session = session,
                authStore = authStore,
                selectedIssueIds = selectedIssueIds,
                onSelectedIssueIdsChange = { selectedIssueIds = it },
                onIssueClick = { issueDetailId = it },
                onInboxIssueClick = { item, nextIssueId ->
                    if (item.issueId.isNotBlank()) {
                        markInboxReadOnOpen(item)
                        selectedTab = MulticaTab.Inbox
                        issueDetailId = item.issueId
                        inboxIssueContext = InboxIssueContext(
                            itemId = item.id,
                            issueId = item.issueId,
                            commentId = item.commentId,
                            nextIssueId = nextIssueId,
                        )
                    }
                },
                onProjectClick = { projectDetail = it },
                onNewIssueClick = {
                    issueFormIssue = null
                    issueFormParentId = null
                    issueFormParentIdentifier = null
                    issueFormOpen = true
                },
                onOpenSettingsPage = { settingsPage = it },
                profileOpen = profileOpen,
                onProfileOpenChange = { profileOpen = it },
                onRetry = { tabRefresh++ },
                onReloadSession = onReloadSession,
                onSessionUpdated = onSessionUpdated,
            )
        }
    }
}

@Composable
private fun PilotTabContent(
    api: ApiClient,
    state: TabState,
    selectedTab: MulticaTab,
    zh: Boolean,
    session: PilotSession,
    authStore: AuthStore,
    selectedIssueIds: Set<String>,
    onSelectedIssueIdsChange: (Set<String>) -> Unit,
    onIssueClick: (String) -> Unit,
    onInboxIssueClick: (Models.InboxItem, String?) -> Unit,
    onProjectClick: (Models.Project) -> Unit,
    onNewIssueClick: () -> Unit,
    onOpenSettingsPage: (PilotSettingsPage) -> Unit,
    profileOpen: Boolean,
    onProfileOpenChange: (Boolean) -> Unit,
    onRetry: () -> Unit,
    onReloadSession: () -> Unit,
    onSessionUpdated: (PilotSession) -> Unit,
) {
    when (state) {
        TabState.Loading -> {
            if (selectedTab == MulticaTab.Projects) {
                ProjectListLoadingSkeleton(zh = zh)
            } else {
                MulticaLoadingState(if (zh) "加载中..." else "Loading...")
            }
        }
        is TabState.Error -> MulticaErrorState(
            message = "${if (zh) "加载失败" else "Load failed"}\n${state.message}",
            onRetry = onRetry,
        )
        is TabState.Inbox -> PilotInbox(
            api = api,
            workspaceId = session.workspace.id,
            items = state.items,
            loading = state.loading,
            hasMore = state.hasMore,
            zh = zh,
            onIssueClick = onInboxIssueClick,
            onRefresh = onRetry,
        )
        is TabState.Issues -> PilotIssues(
            api = api,
            workspaceId = session.workspace.id,
            workspaceName = session.workspace.name,
            issues = state.issues,
            currentUser = session.user,
            personal = state.personal,
            loading = state.loading,
            selectedIds = selectedIssueIds,
            zh = zh,
            onSelectedIdsChange = onSelectedIssueIdsChange,
            onIssueClick = onIssueClick,
            onNewIssueClick = onNewIssueClick,
            onRefresh = onRetry,
        )
        is TabState.Projects -> PilotProjects(
            api = api,
            workspaceId = session.workspace.id,
            workspace = session.workspace,
            projects = state.projects,
            zh = zh,
            onProjectClick = onProjectClick,
            onRefresh = onRetry,
        )
        TabState.Settings -> PilotSettings(
            api = api,
            session = session,
            zh = zh,
            authStore = authStore,
            profileOpen = profileOpen,
            onProfileOpenChange = onProfileOpenChange,
            onOpenSettingsPage = onOpenSettingsPage,
            onReloadSession = onReloadSession,
            onSessionUpdated = onSessionUpdated,
        )
    }
}

@Composable
private fun PilotSearchPage(
    api: ApiClient,
    workspaceId: String,
    zh: Boolean,
    query: String,
    onQueryChange: (String) -> Unit,
    onBack: () -> Unit,
    onIssueClick: (String) -> Unit,
    onProjectClick: (Models.Project) -> Unit,
    onTabClick: (MulticaTab) -> Unit,
    onSettingsPageClick: (PilotSettingsPage) -> Unit,
) {
    var loading by remember(workspaceId) { mutableStateOf(false) }
    var result by remember(workspaceId) { mutableStateOf<Result<PilotSearchData>?>(null) }
    var message by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current

    fun runSearch() {
        val text = query.trim()
        if (text.isBlank() || loading) {
            message = if (zh) "请输入搜索内容" else "Enter a search query"
            return
        }
        loading = true
        message = null
        result = null
        scope.launch {
            val searchResult = withContext(Dispatchers.IO) {
                runCatching {
                    PilotSearchData(
                        issues = api.searchIssues(workspaceId, text, 20),
                        projects = api.searchProjects(workspaceId, text, 10),
                        agents = runCatching { searchLocalAgents(api.agents(workspaceId), text) }.getOrElse { emptyList() },
                        skills = runCatching { searchLocalSkills(api.skills(workspaceId), text) }.getOrElse { emptyList() },
                    )
                }
            }
            loading = false
            result = searchResult
            searchResult.onFailure {
                message = "${if (zh) "搜索失败" else "Search failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    PilotListPage(
        title = if (zh) "搜索 Multica" else "Search Multica",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        item {
            MulticaTextField(
                value = query,
                onValueChange = {
                    onQueryChange(it)
                    message = null
                    if (it.isBlank()) result = null
                },
                label = if (zh) "输入命令或搜索" else "Type a command or search",
                contentDescription = "Search Web Command Input",
                singleLine = true,
            )
        }
        item {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 6.dp)
                    .semantics(mergeDescendants = true) { contentDescription = "Search Web Action Row" },
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MulticaPillButton(
                    text = if (loading) "..." else if (zh) "执行搜索" else "Run Search",
                    onClick = { runSearch() },
                    tone = MulticaButtonTone.Primary,
                )
                MulticaPillButton(
                    text = if (zh) "清空" else "Clear",
                    onClick = {
                        onQueryChange("")
                        result = null
                        message = null
                    },
                    tone = MulticaButtonTone.Ghost,
                )
            }
        }
        if (!message.isNullOrBlank()) {
            item {
                PilotInlineResultState(
                    message = message.orEmpty(),
                    isError = pilotInlineResultIsError(message.orEmpty()),
                    contentDescription = "Search Result Web Banner",
                )
            }
        }
        if (loading) {
            item { MulticaLoadingState(if (zh) "正在搜索..." else "Searching...") }
        }
        if (!loading && query.trim().isBlank() && result == null) {
            item {
                SearchWebResultsGroup(
                    title = if (zh) "建议" else "Suggestions",
                    count = 5,
                    contentDescription = "Search Web Suggestions Group",
                ) {
                    SearchWebResultRow(
                        icon = Icons.Outlined.Add,
                        eyebrow = if (zh) "命令" else "Command",
                        title = if (zh) "查看 Issues" else "Open Issues",
                        subtitle = if (zh) "浏览工作区事项" else "Browse workspace issues",
                        trailing = if (zh) "页面" else "Page",
                        contentDescription = "Search Web Suggestion Row Issues",
                        showDivider = true,
                        onClick = { onTabClick(MulticaTab.Issues) },
                    )
                    SearchWebResultRow(
                        icon = Icons.Outlined.Folder,
                        eyebrow = if (zh) "页面" else "Page",
                        title = if (zh) "查看 Projects" else "Open Projects",
                        subtitle = if (zh) "按项目查看进展" else "Review project progress",
                        trailing = if (zh) "页面" else "Page",
                        contentDescription = "Search Web Suggestion Row Projects",
                        showDivider = true,
                        onClick = { onTabClick(MulticaTab.Projects) },
                    )
                    SearchWebResultRow(
                        icon = Icons.Outlined.Bolt,
                        eyebrow = if (zh) "配置" else "Configure",
                        title = if (zh) "查看 Agents" else "Open Agents",
                        subtitle = if (zh) "管理自动化成员" else "Manage automation members",
                        trailing = if (zh) "设置" else "Settings",
                        contentDescription = "Search Web Suggestion Row Agents",
                        showDivider = true,
                        onClick = { onSettingsPageClick(PilotSettingsPage.Agents) },
                    )
                    SearchWebResultRow(
                        icon = Icons.Outlined.Tune,
                        eyebrow = if (zh) "配置" else "Configure",
                        title = if (zh) "查看 Skills" else "Open Skills",
                        subtitle = if (zh) "管理可复用能力" else "Manage reusable capabilities",
                        trailing = if (zh) "设置" else "Settings",
                        contentDescription = "Search Web Suggestion Row Skills",
                        showDivider = true,
                        onClick = { onSettingsPageClick(PilotSettingsPage.Skills) },
                    )
                    SearchWebResultRow(
                        icon = Icons.Outlined.Search,
                        eyebrow = if (zh) "提示" else "Hint",
                        title = if (zh) "输入关键词搜索 issue 和项目" else "Type to search issues and projects",
                        subtitle = if (zh) "也会匹配 Agents 与 Skills" else "Also matches Agents and Skills",
                        trailing = "⌘K",
                        contentDescription = "Search Web Suggestion Row Type To Search",
                        showDivider = false,
                        onClick = {},
                    )
                }
            }
        }
        val loaded = result
        if (loaded != null && loaded.isSuccess) {
            val data = loaded.getOrThrow()
            val hasResults = data.issues.isNotEmpty() || data.projects.isNotEmpty() || data.agents.isNotEmpty() || data.skills.isNotEmpty()
            if (!hasResults) {
                item { SearchWebEmptyState(zh = zh) }
            }
            if (data.projects.isNotEmpty()) {
                item {
                    SearchWebResultsGroup(
                        title = if (zh) "项目" else "Projects",
                        count = data.projects.size,
                        contentDescription = "Search Web Results Group Projects",
                    ) {
                        data.projects.forEachIndexed { index, project ->
                            SearchWebResultRow(
                                icon = Icons.Outlined.Folder,
                                eyebrow = clean(project.matchSource).ifBlank { if (zh) "项目" else "Project" },
                                title = project.name,
                                subtitle = clean(project.matchedSnippet).ifBlank { clean(project.description).ifBlank { null } },
                                trailing = Models.projectStatusLabel(project.status, zh),
                                contentDescription = "Search Web Project Result Row ${project.id}",
                                showDivider = index < data.projects.lastIndex,
                                onClick = {
                                    focusManager.clearFocus()
                                    onProjectClick(project)
                                },
                            )
                        }
                    }
                }
            }
            if (data.issues.isNotEmpty()) {
                item {
                    SearchWebResultsGroup(
                        title = "Issues",
                        count = data.issues.size,
                        contentDescription = "Search Web Results Group Issues",
                    ) {
                        data.issues.forEachIndexed { index, issue ->
                            SearchWebResultRow(
                                icon = issueStatusIcon(issue.status),
                                eyebrow = issue.identifier,
                                title = issue.title,
                                subtitle = clean(issue.matchedSnippet).ifBlank {
                                    listOf(
                                        clean(issue.matchSource).ifBlank { null },
                                        Models.statusLabel(issue.status, zh),
                                        Models.priorityLabel(issue.priority, zh),
                                    ).filterNotNull().joinToString(" · ")
                                },
                                trailing = Models.statusLabel(issue.status, zh),
                                contentDescription = "Search Web Issue Result Row ${issue.id}",
                                showDivider = index < data.issues.lastIndex,
                                onClick = {
                                    focusManager.clearFocus()
                                    onIssueClick(issue.id)
                                },
                            )
                        }
                    }
                }
            }
            if (data.agents.isNotEmpty()) {
                item {
                    SearchWebResultsGroup(
                        title = if (zh) "Agents" else "Agents",
                        count = data.agents.size,
                        contentDescription = "Search Web Results Group Agents",
                    ) {
                        data.agents.forEachIndexed { index, agent ->
                            SearchWebResultRow(
                                icon = Icons.Outlined.Bolt,
                                eyebrow = clean(agent.status).ifBlank { if (zh) "Agent" else "Agent" },
                                title = agent.name,
                                subtitle = clean(agent.description).ifBlank { clean(agent.model).ifBlank { null } },
                                trailing = clean(agent.visibility).ifBlank { if (zh) "私有" else "Private" },
                                contentDescription = "Search Web Agent Result Row ${agent.id}",
                                showDivider = index < data.agents.lastIndex,
                                onClick = {
                                    focusManager.clearFocus()
                                    onSettingsPageClick(PilotSettingsPage.Agents)
                                },
                            )
                        }
                    }
                }
            }
            if (data.skills.isNotEmpty()) {
                item {
                    SearchWebResultsGroup(
                        title = if (zh) "Skills" else "Skills",
                        count = data.skills.size,
                        contentDescription = "Search Web Results Group Skills",
                    ) {
                        data.skills.forEachIndexed { index, skill ->
                            SearchWebResultRow(
                                icon = Icons.Outlined.Tune,
                                eyebrow = clean(skill.originType).ifBlank { if (zh) "Skill" else "Skill" },
                                title = skill.name,
                                subtitle = clean(skill.description).ifBlank { clean(skill.originSourceUrl).ifBlank { null } },
                                trailing = skill.files.size.takeIf { it > 0 }?.let { if (zh) "$it 个文件" else "$it files" } ?: if (zh) "能力" else "Skill",
                                contentDescription = "Search Web Skill Result Row ${skill.id}",
                                showDivider = index < data.skills.lastIndex,
                                onClick = {
                                    focusManager.clearFocus()
                                    onSettingsPageClick(PilotSettingsPage.Skills)
                                },
                            )
                        }
                    }
                }
            }
        }
    }
}

