private fun searchLocalAgents(agents: List<Models.Agent>, text: String): List<Models.Agent> {
    val query = text.trim()
    if (query.isBlank()) return emptyList()
    return agents
        .asSequence()
        .filter { it.archivedAt.isBlank() }
        .filter { agent ->
            listOf(agent.name, agent.description, agent.model, agent.status, agent.visibility)
                .any { it.contains(query, ignoreCase = true) }
        }
        .take(8)
        .toList()
}

private fun searchLocalSkills(skills: List<Models.Skill>, text: String): List<Models.Skill> {
    val query = text.trim()
    if (query.isBlank()) return emptyList()
    return skills
        .asSequence()
        .filter { skill ->
            listOf(skill.name, skill.description, skill.originSourceUrl, skill.originType)
                .any { it.contains(query, ignoreCase = true) }
        }
        .take(8)
        .toList()
}

