@Composable
private fun PilotInbox(
    api: ApiClient,
    workspaceId: String,
    items: List<Models.InboxItem>,
    loading: Boolean,
    hasMore: Boolean,
    zh: Boolean,
    onIssueClick: (Models.InboxItem, String?) -> Unit,
    onRefresh: () -> Unit,
) {
    val scope = rememberCoroutineScope()
    var mutating by remember(workspaceId) { mutableStateOf(false) }
    var loadingMore by remember(workspaceId, items) { mutableStateOf(false) }
    var extraItems by remember(workspaceId, items) { mutableStateOf<List<Models.InboxItem>>(emptyList()) }
    var localHasMore by remember(workspaceId, items, hasMore) { mutableStateOf(hasMore) }
    var resultText by remember(workspaceId) { mutableStateOf<String?>(null) }
    var batchMenuExpanded by remember(workspaceId) { mutableStateOf(false) }
    val visibleItems = remember(items, extraItems) {
        InboxNotificationDeduper.deduplicateByIssue(items + extraItems.filter { extra -> items.none { it.id == extra.id } })
    }

    LaunchedEffect(workspaceId) {
        while (true) {
            delay(30_000)
            onRefresh()
        }
    }

    fun runInboxAction(action: suspend () -> String) {
        if (mutating) return
        mutating = true
        resultText = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { action() } }
            mutating = false
            result.onSuccess {
                resultText = it
                onRefresh()
            }.onFailure {
                resultText = "${if (zh) "收件箱操作失败" else "Inbox action failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun loadMoreInbox() {
        if (loadingMore || !localHasMore) return
        loadingMore = true
        resultText = null
        val offset = visibleItems.size
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.inbox(workspaceId, PILOT_INBOX_PAGE_SIZE, offset) }
            }
            loadingMore = false
            result.onSuccess { page ->
                val existingIds = (items + extraItems).map { it.id }.toSet()
                extraItems = extraItems + page.items.filter { it.id !in existingIds }
                localHasMore = page.hasMore
            }.onFailure {
                resultText = "${if (zh) "加载更多失败" else "Load more failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    PilotListPage(
        title = if (zh) "收件箱" else "Inbox",
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.MoreHoriz,
                contentDescription = "Inbox Batch Menu",
                onClick = { batchMenuExpanded = true },
                tone = MulticaButtonTone.Ghost,
            )
            MulticaCupertinoActionSheet(
                visible = batchMenuExpanded,
                title = if (zh) "收件箱批量操作" else "Inbox actions",
                message = if (zh) "对当前工作区收件箱执行批量整理。" else "Triage the current workspace inbox.",
                items = listOf(
                    MulticaCupertinoActionSheetItem(
                        title = if (mutating) "..." else if (zh) "全部已读" else "Mark All Read",
                        icon = Icons.Outlined.DoneAll,
                        contentDescription = "Inbox Batch Cupertino Action Sheet Mark All Read",
                        enabled = !mutating,
                        onClick = {
                            runInboxAction {
                                val count = api.markAllInboxRead(workspaceId)
                                if (zh) "已标记 $count 条为已读" else "Marked $count read"
                            }
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (mutating) "..." else if (zh) "全部归档" else "Archive All",
                        icon = Icons.Outlined.Archive,
                        contentDescription = "Inbox Batch Cupertino Action Sheet Archive All",
                        enabled = !mutating,
                        onClick = {
                            runInboxAction {
                                val count = api.archiveAllInbox(workspaceId)
                                if (zh) "已归档 $count 条消息" else "Archived $count items"
                            }
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (mutating) "..." else if (zh) "归档已读" else "Archive Read",
                        icon = Icons.Outlined.Archive,
                        contentDescription = "Inbox Batch Cupertino Action Sheet Archive Read",
                        enabled = !mutating,
                        onClick = {
                            runInboxAction {
                                val count = api.archiveAllReadInbox(workspaceId)
                                if (zh) "已归档 $count 条已读消息" else "Archived $count read items"
                            }
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (mutating) "..." else if (zh) "归档完成" else "Archive Done",
                        icon = Icons.Outlined.CheckCircle,
                        contentDescription = "Inbox Batch Cupertino Action Sheet Archive Completed",
                        enabled = !mutating,
                        onClick = {
                            runInboxAction {
                                val count = api.archiveCompletedInbox(workspaceId)
                                if (zh) "已归档 $count 条完成消息" else "Archived $count completed items"
                            }
                        },
                    ),
                ),
                cancelText = if (zh) "取消" else "Cancel",
                onDismissRequest = { batchMenuExpanded = false },
            )
        },
        pinnedHeader = {
            InboxPinnedTriageHeader(
                unreadCount = visibleItems.count { !it.read },
                totalCount = visibleItems.size,
                loading = loading,
                zh = zh,
                onRefresh = onRefresh,
            )
        },
    ) {
        if (!resultText.isNullOrBlank()) {
            item {
                val isError = resultText!!.contains("failed", true) || resultText!!.contains("失败")
                PilotInlineResultState(
                    message = resultText.orEmpty(),
                    isError = isError,
                    contentDescription = "Inbox Result Web Banner",
                )
            }
        }
        if (loading) {
            item { MulticaLoadingState(if (zh) "正在加载收件箱..." else "Loading inbox...") }
        } else if (visibleItems.isEmpty()) {
            item { InboxWebEmptyState(zh = zh) }
        }
        itemsIndexed(visibleItems, key = { _, item -> item.id }) { index, item ->
            val next = visibleItems.getOrNull(index + 1) ?: visibleItems.getOrNull(index - 1)
            PilotInboxRow(
                item = item,
                zh = zh,
                mutating = mutating,
                onIssueClick = {
                    onIssueClick(item, next?.issueId)
                },
                onMarkRead = {
                    runInboxAction {
                        api.markInboxRead(workspaceId, item.id)
                        if (zh) "已标记为已读" else "Marked read"
                    }
                },
                onArchive = {
                    runInboxAction {
                        api.archiveInbox(workspaceId, item.id)
                        if (zh) "已归档" else "Archived"
                    }
                },
            )
        }
        if (!loading && localHasMore) {
            item {
                MulticaPillButton(
                    text = if (loadingMore) "..." else if (zh) "加载更多" else "Load More",
                    onClick = { loadMoreInbox() },
                    tone = MulticaButtonTone.Ghost,
                    contentDescription = "Inbox Load More",
                    enabled = !loadingMore,
                    modifier = Modifier.fillMaxWidth(),
                )
            }
        }
    }
}

