@Composable
private fun PilotInboxRow(
    item: Models.InboxItem,
    zh: Boolean,
    mutating: Boolean,
    onIssueClick: () -> Unit,
    onMarkRead: () -> Unit,
    onArchive: () -> Unit,
) {
    val density = LocalDensity.current
    val archiveRevealPx = with(density) { 92.dp.toPx() }
    var horizontalDrag by remember(item.id) { mutableStateOf(0f) }
    var archiveRevealed by remember(item.id) { mutableStateOf(false) }
    val rowOffset = if (archiveRevealed) -archiveRevealPx else horizontalDrag.coerceIn(-archiveRevealPx, 0f)
    Column(modifier = Modifier.fillMaxWidth()) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = 62.dp),
        ) {
            if (archiveRevealed) {
                Box(
                    modifier = Modifier
                        .align(Alignment.CenterEnd)
                        .padding(end = 2.dp)
                        .width(82.dp)
                        .height(48.dp)
                        .clip(RoundedCornerShape(12.dp))
                        .background(MulticaColors.Danger.copy(alpha = 0.12f))
                        .clickable(enabled = !mutating) { onArchive() }
                        .semantics { contentDescription = "Inbox Swipe Archive ${item.id}" },
                    contentAlignment = Alignment.Center,
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(2.dp),
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Archive,
                            contentDescription = null,
                            tint = MulticaColors.Danger,
                            modifier = Modifier.size(16.dp),
                        )
                        Text(
                            text = if (mutating) "..." else if (zh) "归档" else "Archive",
                            style = MaterialTheme.typography.labelSmall.copy(
                                fontSize = 10.sp,
                                lineHeight = 12.sp,
                                fontWeight = FontWeight.SemiBold,
                            ),
                            color = MulticaColors.Danger,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
            }
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(min = 62.dp)
                    .graphicsLayer { translationX = rowOffset }
                    .background(MulticaColors.Background)
                    .pointerInput(item.id, mutating, archiveRevealed) {
                        detectHorizontalDragGestures(
                            onDragCancel = {
                                horizontalDrag = 0f
                            },
                            onDragEnd = {
                                archiveRevealed = if (archiveRevealed) {
                                    horizontalDrag < archiveRevealPx * 0.34f
                                } else {
                                    horizontalDrag < -archiveRevealPx * 0.42f
                                }
                                horizontalDrag = 0f
                            },
                            onHorizontalDrag = { change, dragAmount ->
                                if (!mutating) {
                                    val base = if (archiveRevealed) -archiveRevealPx else 0f
                                    horizontalDrag = (base + horizontalDrag + dragAmount).coerceIn(-archiveRevealPx, archiveRevealPx * 0.36f)
                                    change.consume()
                                }
                            },
                        )
                    }
                    .clickable {
                        if (archiveRevealed) {
                            archiveRevealed = false
                        } else {
                            onIssueClick()
                        }
                    }
                    .padding(vertical = 9.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Box(
                    modifier = Modifier
                        .size(30.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(MulticaColors.AccentSoft.copy(alpha = if (!item.read) 0.46f else 0.18f))
                        .semantics { contentDescription = "Inbox Actor Avatar ${item.id}" },
                    contentAlignment = Alignment.Center,
                ) {
                    Text(
                        text = inboxAvatarText(item),
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = 11.sp, lineHeight = 12.sp),
                        color = if (!item.read) MulticaColors.Accent else MulticaColors.Muted,
                        maxLines = 1,
                        overflow = TextOverflow.Clip,
                    )
                }
                androidx.compose.foundation.layout.Spacer(modifier = Modifier.width(10.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Row(
                            modifier = Modifier.weight(1f),
                            horizontalArrangement = Arrangement.spacedBy(5.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            if (!item.read) {
                                Box(
                                    modifier = Modifier
                                        .size(6.dp)
                                        .clip(RoundedCornerShape(999.dp))
                                        .background(MulticaColors.Accent)
                                )
                            }
                            Text(
                                text = inboxDisplayTitle(item),
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = if (!item.read) FontWeight.SemiBold else FontWeight.Medium,
                                    fontSize = 15.sp,
                                    lineHeight = 19.sp,
                                ),
                                color = if (!item.read) MulticaColors.TextPrimary else MulticaColors.Muted,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.weight(1f, fill = false),
                            )
                        }
                        if (item.issueStatus.isNotBlank()) {
                            Icon(
                                imageVector = issueStatusIcon(item.issueStatus),
                                contentDescription = null,
                                tint = MulticaColors.Muted.copy(alpha = if (!item.read) 0.84f else 0.54f),
                                modifier = Modifier.size(15.dp),
                            )
                        }
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 2.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            text = inboxDetailLabel(item, zh),
                            style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                            color = MulticaColors.Muted.copy(alpha = if (!item.read) 0.92f else 0.62f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f),
                        )
                        val createdAt = relativeDate(item.createdAt, zh)
                        if (createdAt.isNotBlank()) {
                            Text(
                                text = createdAt,
                                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                                color = MulticaColors.Muted.copy(alpha = if (!item.read) 0.92f else 0.62f),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                        }
                    }
                }
            }
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(1.dp)
                .background(MulticaColors.Border)
        )
    }
}

private fun inboxDisplayTitle(item: Models.InboxItem): String {
    val title = clean(item.issueTitle)
    if (title.isBlank()) return clean(item.issueIdentifier).ifBlank { clean(item.type).replace('_', ' ') }
    val identifier = clean(item.issueIdentifier)
    if (identifier.isNotBlank()) {
        val exactPrefix = Regex("^Created\\s+${Regex.escape(identifier)}:\\s*", RegexOption.IGNORE_CASE)
        val stripped = title.replace(exactPrefix, "").trim()
        if (stripped != title) return stripped
    }
    return title.replace(Regex("^Created\\s+[A-Z][A-Z0-9]*-\\d+:\\s*", RegexOption.IGNORE_CASE), "").trim()
        .ifBlank { title }
}

private fun inboxDetailLabel(item: Models.InboxItem, zh: Boolean): String {
    val body = clean(item.body)
    if (body.isNotBlank()) return body
    return listOfNotNull(
        clean(item.issueIdentifier).takeIf { it.isNotBlank() && it != item.issueId },
        clean(item.type).replace('_', ' ').takeIf { it.isNotBlank() },
        clean(item.issueStatus).takeIf { it.isNotBlank() }?.let { Models.statusLabel(it, zh) },
    ).joinToString(" · ").ifBlank { Models.statusLabel(item.issueStatus, zh).ifBlank { if (zh) "通知" else "Notification" } }
}

private fun inboxAvatarText(item: Models.InboxItem): String {
    val source = clean(item.issueIdentifier).ifBlank { clean(item.type) }.ifBlank { "M" }
    return source.firstOrNull { it.isLetterOrDigit() }?.uppercaseChar()?.toString() ?: "M"
}

@Composable
private fun InlineInboxAction(
    text: String,
    contentDescription: String,
    emphasized: Boolean,
    icon: ImageVector? = null,
    iconOnly: Boolean = false,
    onClick: () -> Unit,
) {
    val foreground = if (emphasized) androidx.compose.ui.graphics.Color(0xFF7DB1FF) else MulticaColors.Muted
    val background = if (iconOnly) {
        if (emphasized) MulticaColors.AccentSoft.copy(alpha = 0.10f) else androidx.compose.ui.graphics.Color.Transparent
    } else if (emphasized) {
        MulticaColors.AccentSoft.copy(alpha = 0.58f)
    } else {
        androidx.compose.ui.graphics.Color.Transparent
    }
    val borderColor = if (emphasized) {
        MulticaColors.Accent.copy(alpha = if (iconOnly) 0.22f else 0.45f)
    } else {
        MulticaColors.Border.copy(alpha = if (iconOnly) 0.58f else 1f)
    }
    if (iconOnly) {
        Box(
            modifier = Modifier
                .width(44.dp)
                .height(34.dp)
                .clickable { onClick() }
                .semantics { this.contentDescription = contentDescription },
            contentAlignment = Alignment.Center,
        ) {
            Box(
                modifier = Modifier
                    .width(28.dp)
                    .height(28.dp)
                    .clip(RoundedCornerShape(999.dp))
                    .background(background)
                    .border(0.75.dp, borderColor, RoundedCornerShape(999.dp)),
                contentAlignment = Alignment.Center,
            ) {
                if (icon != null) {
                    Icon(
                        imageVector = icon,
                        contentDescription = null,
                        tint = foreground,
                        modifier = Modifier.width(15.dp).height(15.dp),
                    )
                }
            }
        }
        return
    }
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(999.dp))
            .background(background)
            .border(1.dp, borderColor, RoundedCornerShape(999.dp))
            .clickable { onClick() }
            .semantics { this.contentDescription = contentDescription }
            .padding(horizontal = 8.dp, vertical = 4.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (icon != null) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = foreground,
                modifier = Modifier.width(13.dp).height(13.dp),
            )
        }
        Text(
            text = text,
            style = MaterialTheme.typography.labelMedium.copy(fontSize = 11.sp, lineHeight = 13.sp),
            color = foreground,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
    }
}

