        showAllSessions -> if (zh) "新建对话后会显示在这里。" else "New chats will appear here."
        else -> if (zh) "归档会话可在全部会话中查看。" else "Archived chats are available from All Sessions."
    }

    Box(
        modifier = Modifier.semantics {
            contentDescription = "Chat Sessions Web Empty State $WEB_SSOT_CHAT_WINDOW"
        },
    ) {
        MulticaEmptyState(
            title = title,
            description = description,
        )
    }
}

