@Composable
private fun PilotChatMessages(
    api: ApiClient,
    workspaceId: String,
    session: Models.ChatSession,
    zh: Boolean,
    onBack: () -> Unit,
    onArchived: () -> Unit,
) {
    var state by remember(session.id) { mutableStateOf<Result<PilotChatMessagesData>?>(null) }
    var refresh by remember(session.id) { mutableIntStateOf(0) }
    var draft by remember(session.id) { mutableStateOf("") }
    var sending by remember(session.id) { mutableStateOf(false) }
    var locallyPending by remember(session.id) { mutableStateOf(false) }
    var sendError by remember(session.id) { mutableStateOf<String?>(null) }
    var archiving by remember(session.id) { mutableStateOf(false) }
    var cancelling by remember(session.id) { mutableStateOf(false) }
    var headerMenuOpen by remember(session.id) { mutableStateOf(false) }
    var actionError by remember(session.id) { mutableStateOf<String?>(null) }
    val listState = rememberLazyListState()
    val scope = rememberCoroutineScope()
    val hazeState = rememberHazeState()
    val haptic = LocalHapticFeedback.current

    LaunchedEffect(session.id, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                val messages = api.chatMessages(workspaceId, session.id)
                val pending = runCatching { api.pendingChatTask(workspaceId, session.id) }
                    .getOrElse { Models.ChatPendingTask(org.json.JSONObject()) }
                runCatching { api.markChatSessionRead(workspaceId, session.id) }
                PilotChatMessagesData(messages, pending)
            }
        }
    }

    LaunchedEffect(sending, state?.getOrNull()?.pendingTask?.taskId) {
        val taskId = state?.getOrNull()?.pendingTask?.taskId.orEmpty()
        if (!sending && taskId.isBlank()) return@LaunchedEffect
        while (sending || taskId.isNotBlank()) {
            delay(5_000)
            refresh++
        }
    }

    LaunchedEffect(state?.getOrNull()?.messages?.size, state?.getOrNull()?.pendingTask?.taskId) {
        val loadedData = state?.getOrNull() ?: return@LaunchedEffect
        if (loadedData.pendingTask.taskId.isNotBlank() || loadedData.messages.isNotEmpty()) {
            locallyPending = false
        }
    }

    val loaded = state
    val pendingTask = loaded?.getOrNull()?.pendingTask
    val latestAnchor = remember(loaded, sending, locallyPending, pendingTask?.taskId) {
        val data = loaded?.getOrNull()
        listOf(
            data?.messages?.size?.toString().orEmpty(),
            data?.messages?.lastOrNull()?.id.orEmpty(),
            pendingTask?.taskId.orEmpty(),
            sending.toString(),
            locallyPending.toString(),
        ).joinToString("|")
    }

    LaunchedEffect(latestAnchor) {
        val data = loaded?.getOrNull() ?: return@LaunchedEffect
        val messageCount = data.messages.size
        val hasPending = sending || locallyPending || validChatTaskId(data.pendingTask.taskId)
        val emptyCount = if (messageCount == 0) 1 else 0
        val lastIndex = (messageCount + emptyCount + if (hasPending) 1 else 0) - 1
        if (lastIndex >= 0) {
            listState.animateScrollToItem(lastIndex)
        }
    }

    fun archiveSession() {
        if (archiving) return
        archiving = true
        headerMenuOpen = false
        actionError = null
        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.archiveChatSession(workspaceId, session.id) }
            }
            archiving = false
            result.onSuccess { onArchived() }
                .onFailure { actionError = "${if (zh) "归档失败" else "Archive failed"}: ${it.message ?: it.toString()}" }
        }
    }

    fun cancelPendingTask(task: Models.ChatPendingTask?) {
        if (task == null || task.taskId.isBlank() || cancelling) return
        cancelling = true
        headerMenuOpen = false
        actionError = null
        haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.cancelTaskById(workspaceId, task.taskId) }
            }
            cancelling = false
            result.onSuccess { refresh++ }
                .onFailure { actionError = "${if (zh) "取消失败" else "Cancel failed"}: ${it.message ?: it.toString()}" }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(MulticaColors.Background)
            .statusBarsPadding()
            .padding(top = 8.dp)
            .semantics { contentDescription = "Chat Detail Safe Area Container" },
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 18.dp)
                .semantics { contentDescription = "Chat Detail Header Safe Horizontal Insets" },
        ) {
            PilotPageHeader(
                title = session.title,
                leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
                trailing = {
                    MulticaIconPillButton(
                        icon = Icons.Outlined.MoreHoriz,
                        contentDescription = "Chat Header More Menu",
                        onClick = { headerMenuOpen = true },
                        tone = MulticaButtonTone.Ghost,
                    )
                    MulticaCupertinoActionSheet(
                        visible = headerMenuOpen,
                        title = if (zh) "会话操作" else "Session actions",
                        message = if (zh) "整理当前聊天会话。" else "Manage this chat session.",
                        items = listOf(
                            MulticaCupertinoActionSheetItem(
                                title = if (archiving) "..." else if (zh) "归档会话" else "Archive Session",
                                icon = Icons.Outlined.Archive,
                                enabled = !archiving,
                                contentDescription = "Chat Header Cupertino Action Sheet Archive Session",
                                onClick = { archiveSession() },
                            ),
                            MulticaCupertinoActionSheetItem(
                                title = if (cancelling) "..." else if (zh) "取消任务" else "Cancel Task",
                                icon = Icons.Outlined.Close,
                                enabled = pendingTask?.taskId?.isNotBlank() == true && !cancelling,
                                contentDescription = "Chat Header Cupertino Action Sheet Cancel Task",
                                destructive = true,
                                onClick = { cancelPendingTask(pendingTask) },
                            ),
                        ),
                        cancelText = if (zh) "取消" else "Cancel",
                        onDismissRequest = { headerMenuOpen = false },
                    )
                },
            )
        }
        Text(
            text = "${if (zh) "会话状态" else "Status"} · ${session.status}",
            style = MaterialTheme.typography.bodyMedium,
            color = MulticaColors.Muted,
            modifier = Modifier.padding(horizontal = 18.dp),
        )
        if (pendingTask != null && pendingTask.taskId.isNotBlank()) {
            Text(
                text = "${if (zh) "任务" else "Task"} · ${pendingTask.status.ifBlank { Models.shortId(pendingTask.taskId) }}",
                style = MaterialTheme.typography.bodyMedium,
                color = MulticaColors.Muted,
                modifier = Modifier.padding(horizontal = 18.dp),
            )
        }
        if (!actionError.isNullOrBlank()) {
            PilotInlineResultState(
                message = actionError.orEmpty(),
                isError = true,
                contentDescription = "Chat Action Result Web Banner",
                modifier = Modifier.padding(horizontal = 18.dp),
            )
        }
        when {
            loaded == null -> Box(
                modifier = Modifier
                    .weight(1f)
                    .hazeSource(hazeState),
                contentAlignment = Alignment.Center,
            ) {
                ChatMessagesInlineLoadingIndicator(zh = zh)
            }
            loaded.isFailure -> Box(
                modifier = Modifier
                    .weight(1f)
                    .hazeSource(hazeState),
                contentAlignment = Alignment.Center,
            ) {
                MulticaErrorState(
                    message = "${if (zh) "消息加载失败" else "Messages failed"}\n${loaded.exceptionOrNull()?.message.orEmpty()}",
                    onRetry = { refresh++ },
                )
            }
            else -> LazyColumn(
                modifier = Modifier
                    .weight(1f)
                    .hazeSource(hazeState),
                state = listState,
                contentPadding = PaddingValues(horizontal = 18.dp, vertical = 12.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                val messages = loaded.getOrThrow().messages
                val activePending = loaded.getOrThrow().pendingTask
                if (messages.isEmpty()) {
                    item {
                        ChatWindowWebEmptyState(
                            zh = zh,
                            onPromptClick = { prompt -> draft = prompt },
                        )
                    }
                }
                items(messages) { message ->
                    ChatMessageBubble(message = message, zh = zh)
                    if (validChatTaskId(message.taskId)) {
                        ChatTaskTimeline(
                            api = api,
                            workspaceId = workspaceId,
                            taskId = message.taskId,
                            zh = zh,
                        )
                    }
                }
                if (sending || locallyPending || validChatTaskId(activePending.taskId)) {
                    item(key = "chat-latest-progress") {
                        ChatPendingTimelineCard(
                            api = api,
                            workspaceId = workspaceId,
                            taskId = activePending.taskId,
                            status = activePending.status.ifBlank { if (sending || locallyPending) "queued" else "" },
                            zh = zh,
                        )
                    }
                }
            }
        }
        PilotGlassBottomSlot(hazeState) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics(mergeDescendants = false) { contentDescription = "Chat Glass Bottom Composer" },
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                if (!sendError.isNullOrBlank()) {
                    PilotInlineResultState(
                        message = sendError.orEmpty(),
                        isError = true,
                        contentDescription = "Chat Send Result Web Banner",
                        modifier = Modifier.padding(horizontal = 18.dp),
                    )
                }
                // Chat Cupertino Composer: focus-within-style composer equivalent from Web chat-input.tsx.
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 18.dp, vertical = 10.dp),
                    shape = RoundedCornerShape(14.dp),
                    color = MulticaColors.Surface.copy(alpha = 0.94f),
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                    border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.86f)),
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(start = 10.dp, top = 8.dp, end = 8.dp, bottom = 8.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.Bottom,
                    ) {
                        MulticaTextField(
                            value = draft,
                            onValueChange = { draft = it },
                            modifier = Modifier.weight(1f),
                            label = if (zh) "发送 Markdown 消息..." else "Send a Markdown message...",
                            contentDescription = "Chat Message Input",
                            minLines = 1,
                            maxLines = 4,
                        )
                        MulticaIconPillButton(
                            icon = Icons.AutoMirrored.Outlined.Send,
                            contentDescription = if (zh) "发送消息" else "Send Message",
                            enabled = !sending && draft.trim().isNotEmpty(),
                            onClick = {
                                val content = draft.trim()
                                if (content.isEmpty() || sending) return@MulticaIconPillButton
                                sending = true
                                locallyPending = true
                                sendError = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) {
                                        runCatching { api.sendChatMessage(workspaceId, session.id, content) }
                                    }
                                    sending = false
                                    result.onSuccess {
                                        draft = ""
                                        refresh++
                                    }.onFailure {
                                        locallyPending = false
                                        sendError = "${if (zh) "发送失败" else "Send failed"}: ${it.message ?: it.toString()}"
                                    }
                                }
                            },
                            tone = if (!sending && draft.trim().isNotEmpty()) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                        )
                    }
                }
            }
        }
    }
}

@Composable
