}

@Composable
private fun ChatMessageBubble(
    message: Models.ChatMessage,
    zh: Boolean,
) {
    val context = LocalContext.current
    val haptic = LocalHapticFeedback.current
    var moreOpen by remember(message.id) { mutableStateOf(false) }
    val normalizedRole = clean(message.role).lowercase()
    val isUser = normalizedRole == "user"
    val failure = clean(message.failureReason)
    val meta = if (failure.isNotBlank()) {
        failure
    } else {
        listOf(roleLabel(message.role, zh), shortDate(message.createdAt))
            .filter { it.isNotBlank() }
            .joinToString(" · ")
    }
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = if (isUser) Arrangement.End else Arrangement.Start,
    ) {
        Surface(
            modifier = Modifier
                .fillMaxWidth(0.84f)
                .semantics { contentDescription = "Chat Message Bubble ${if (isUser) "user" else "assistant"}" },
            shape = RoundedCornerShape(12.dp),
            color = if (isUser) MulticaColors.Accent.copy(alpha = 0.14f) else MulticaColors.Surface,
            tonalElevation = 0.dp,
            shadowElevation = 0.dp,
        ) {
            Column(
                modifier = Modifier
                    .border(
                        1.dp,
                        if (isUser) MulticaColors.Accent.copy(alpha = 0.20f) else MulticaColors.Border,
                        RoundedCornerShape(12.dp),
                    )
                    .padding(horizontal = 10.dp, vertical = 9.dp),
                verticalArrangement = Arrangement.spacedBy(5.dp),
                horizontalAlignment = if (isUser) Alignment.End else Alignment.Start,
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalAlignment = Alignment.Top,
                ) {
                    Box(modifier = Modifier.weight(1f)) {
                        MarkdownBlock(message.content)
                    }
                    MulticaIconPillButton(
                        icon = Icons.Outlined.MoreHoriz,
                        contentDescription = "Chat Message More Menu",
                        onClick = { moreOpen = true },
                        tone = MulticaButtonTone.Ghost,
                    )
                    MulticaCupertinoActionSheet(
                        visible = moreOpen,
                        title = if (zh) "消息操作" else "Message actions",
                        items = listOf(
                            MulticaCupertinoActionSheetItem(
                                title = if (zh) "复制" else "Copy",
                                icon = Icons.Outlined.ContentCopy,
                                contentDescription = "Chat Message Cupertino Action Sheet Copy",
                                onClick = {
                                    val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
                                    clipboard.setPrimaryClip(ClipData.newPlainText("Multica chat message", message.content))
                                    haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                },
                            ),
                        ),
                        cancelText = if (zh) "取消" else "Cancel",
                        onDismissRequest = { moreOpen = false },
                    )
                }
                if (meta.isNotBlank()) {
                    Text(
                        text = meta,
                        style = MaterialTheme.typography.labelSmall,
                        color = if (failure.isNotBlank()) MulticaColors.Danger else MulticaColors.Muted,
                        textAlign = if (isUser) TextAlign.End else TextAlign.Start,
                    )
                }
            }
        }
    }
}

