@Composable
private fun ChatTaskTimeline(
    api: ApiClient,
    workspaceId: String,
    taskId: String,
    zh: Boolean,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Chat Task Timeline $taskId" },
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        ChatTaskWebLiveBanner(
            title = if (zh) "Agent 执行过程" else "Agent timeline",
            subtitle = Models.shortId(taskId),
            active = false,
        )
        ChatTaskTimelineRows(api = api, workspaceId = workspaceId, taskId = taskId, zh = zh)
    }
}

@Composable
private fun ChatTaskTimelineRows(
    api: ApiClient,
    workspaceId: String,
    taskId: String,
    zh: Boolean,
) {
    var state by remember(taskId, workspaceId) { mutableStateOf<Result<List<Models.TaskMessage>>?>(null) }
    LaunchedEffect(taskId, workspaceId) {
        state = withContext(Dispatchers.IO) { runCatching { api.runMessages(taskId, workspaceId) } }
    }
    when (val loaded = state) {
        null -> ChatTaskWebEmptyRow(
            title = if (zh) "加载执行过程..." else "Loading timeline...",
            subtitle = if (zh) "正在拉取 Agent transcript" else "Fetching the agent transcript",
        )
        else -> loaded.fold(
            onSuccess = { messages ->
                if (messages.isEmpty()) {
                    ChatTaskWebEmptyRow(
                        title = if (zh) "暂无执行消息" else "No task messages yet",
                        subtitle = if (zh) "Agent 开始输出后会显示在这里" else "Thinking, tools, output, and errors will appear here",
                    )
                } else {
                    messages.take(8).forEachIndexed { index, message ->
                        ChatTaskWebTimelineRow(
                            message = message,
                            zh = zh,
                            showDivider = index < messages.take(8).lastIndex || messages.size > 8,
                        )
                    }
                    if (messages.size > 8) {
                        ChatTaskWebEmptyRow(
                            title = if (zh) "还有 ${messages.size - 8} 条执行消息" else "${messages.size - 8} more task messages",
                            subtitle = null,
                        )
                    }
                }
            },
            onFailure = {
                ChatTaskWebErrorRow(
                    title = if (zh) "执行过程加载失败" else "Timeline failed",
                    subtitle = it.message ?: it.toString(),
                )
            },
        )
    }
}

private fun validChatTaskId(taskId: String?): Boolean {
    val value = clean(taskId)
    return value.isNotBlank() && !value.equals("null", ignoreCase = true)
}

