@Composable
private fun ChatTaskWebTimelineRow(
    message: Models.TaskMessage,
    zh: Boolean,
    showDivider: Boolean,
) {
    val tone = taskMessageTone(message)
    val accentColor = when (tone) {
        "danger" -> MulticaColors.Danger
        "accent" -> MulticaColors.Accent
        else -> MulticaColors.Muted
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Chat Task Web Timeline Row ${message.id}" },
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 2.dp, vertical = 8.dp),
            verticalAlignment = Alignment.Top,
            horizontalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Surface(
                modifier = Modifier.size(22.dp),
                shape = RoundedCornerShape(7.dp),
                color = accentColor.copy(alpha = 0.11f),
                tonalElevation = 0.dp,
                shadowElevation = 0.dp,
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Text(
                        text = "#${message.seq}",
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 9.sp, lineHeight = 11.sp, fontWeight = FontWeight.SemiBold),
                        color = accentColor,
                        textAlign = TextAlign.Center,
                    )
                }
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    Text(
                        text = taskMessageKindLabel(message, zh),
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 13.sp, lineHeight = 17.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.TextPrimary,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    val tool = clean(message.tool)
                    if (tool.isNotBlank()) {
                        Text(
                            text = tool,
                            style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 15.sp, fontFamily = FontFamily.Monospace),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                preview(messageSummary(message))?.let { summary ->
                    Text(
                        text = summary,
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 17.sp),
                        color = if (tone == "danger") MulticaColors.Danger else MulticaColors.Muted,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
        }
        if (showDivider) {
            Box(
                modifier = Modifier
                    .padding(start = 33.dp)
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border.copy(alpha = 0.65f)),
            )
        }
    }
}

