@Composable
private fun ChatTaskWebStateRow(
    contentDescription: String,
    title: String,
    subtitle: String?,
    tone: String,
) {
    val accentColor = if (tone == "danger") MulticaColors.Danger else MulticaColors.Muted
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { this.contentDescription = contentDescription },
        shape = RoundedCornerShape(10.dp),
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .border(1.dp, MulticaColors.Border, RoundedCornerShape(10.dp))
                .padding(horizontal = 11.dp, vertical = 9.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Icon(
                imageVector = if (tone == "danger") Icons.Outlined.Close else Icons.Outlined.RadioButtonUnchecked,
                contentDescription = null,
                modifier = Modifier.size(15.dp),
                tint = accentColor,
            )
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 13.sp, lineHeight = 17.sp, fontWeight = FontWeight.Medium),
                    color = if (tone == "danger") MulticaColors.Danger else MulticaColors.TextPrimary,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                if (!subtitle.isNullOrBlank()) {
                    Text(
                        text = subtitle,
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                        color = MulticaColors.Muted,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
        }
    }
}

private fun taskMessageTitle(message: Models.TaskMessage, zh: Boolean): String {
    val tool = clean(message.tool)
    return listOf("#${message.seq}", taskMessageKindLabel(message, zh), tool).filter { it.isNotBlank() }.joinToString(" · ")
}

private fun taskMessageKindLabel(message: Models.TaskMessage, zh: Boolean): String {
    val type = clean(message.type).lowercase()
    return when {
        type.contains("tool") && type.contains("result") -> if (zh) "工具结果" else "Tool result"
        type.contains("tool") -> if (zh) "工具调用" else "Tool call"
        type.contains("thinking") -> if (zh) "思考" else "Thinking"
        type.contains("error") -> if (zh) "错误" else "Error"
        type.contains("text") || type.contains("message") -> if (zh) "输出" else "Output"
        else -> clean(message.type).ifBlank { if (zh) "执行消息" else "Task message" }
    }
}

private fun taskMessageTone(message: Models.TaskMessage): String {
    val type = clean(message.type).lowercase()
    return when {
        type.contains("error") -> "danger"
        type.contains("tool") || type.contains("thinking") -> "accent"
        else -> "muted"
    }
}

