private val ISSUE_SORT_OPTIONS = listOf(
    IssueSortOption.Position,
    IssueSortOption.Number,
    IssueSortOption.Priority,
    IssueSortOption.Updated,
    IssueSortOption.Created,
    IssueSortOption.Title,
)

private fun issueSortLabel(option: IssueSortOption, zh: Boolean): String = when (option) {
    IssueSortOption.Position -> if (zh) "默认" else "Default"
    IssueSortOption.Number -> if (zh) "编号" else "Number"
    IssueSortOption.Priority -> if (zh) "优先级" else "Priority"
    IssueSortOption.Updated -> if (zh) "更新时间" else "Updated"
    IssueSortOption.Created -> if (zh) "创建时间" else "Created"
    IssueSortOption.Title -> if (zh) "标题" else "Title"
}

private fun issuePriorityRank(priority: String?): Int = when (priority) {
    "urgent" -> 0
    "high" -> 1
    "medium" -> 2
    "low" -> 3
    "none", "no_priority" -> 4
    else -> 5
}

