private fun issueStatusIcon(status: String?): ImageVector = when (status) {
    "todo" -> Icons.Outlined.RadioButtonUnchecked
    "in_progress" -> Icons.Outlined.Bolt
    "in_review" -> Icons.Outlined.Flag
    "done" -> Icons.Outlined.CheckCircle
    "blocked", "cancelled" -> Icons.Outlined.Delete
    else -> Icons.Outlined.Archive
}

private fun sortIssues(
    issues: List<Models.Issue>,
    option: IssueSortOption,
    descending: Boolean,
): List<Models.Issue> {
    val sorted = when (option) {
        IssueSortOption.Position -> issues.sortedWith(
            compareBy<Models.Issue> {
                Models.STATUS_VALUES.indexOf(it.status).let { index -> if (index >= 0) index else Int.MAX_VALUE }
            }.thenBy { it.number }
        )
        IssueSortOption.Number -> issues.sortedWith(compareBy<Models.Issue> { it.number }.thenByDescending { clean(it.updatedAt) })
        IssueSortOption.Priority -> issues.sortedWith(compareBy<Models.Issue> { issuePriorityRank(it.priority) }.thenByDescending { clean(it.updatedAt) })
        IssueSortOption.Updated -> issues.sortedBy { clean(it.updatedAt) }
        IssueSortOption.Created -> issues.sortedBy { clean(it.createdAt) }
        IssueSortOption.Title -> issues.sortedBy { clean(it.title).lowercase() }
    }
    return if (descending) sorted.asReversed() else sorted
}

