@Composable
private fun IssueMaterialListRow(
    issue: Models.Issue,
    metadata: String,
    childProgressMetadata: String,
    labelsMetadata: String,
    projectMetadata: String,
    dueDateMetadata: String,
    zh: Boolean,
    onClick: () -> Unit,
    rowSelectionDescription: String? = null,
    onRowSelectionClick: (() -> Unit)? = null,
    trailing: @Composable () -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .semantics(mergeDescendants = false) {
                if (rowSelectionDescription != null) {
                    contentDescription = rowSelectionDescription
                    if (onRowSelectionClick != null) {
                        semanticsOnClick(label = rowSelectionDescription) {
                            onRowSelectionClick()
                            true
                        }
                    }
                }
            },
        color = MulticaColors.Background,
        tonalElevation = 0.dp,
    ) {
        Column(modifier = Modifier.fillMaxWidth()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "Issue Web Dense Row ${issue.identifier}" }
                    .padding(vertical = 7.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(5.dp),
            ) {
                Box(
                    modifier = Modifier.size(24.dp),
                    contentAlignment = Alignment.Center,
                ) {
                    Icon(
                        imageVector = issueStatusIcon(issue.status),
                        contentDescription = null,
                        tint = when (issue.status) {
                            "done" -> MulticaColors.Success
                            "in_progress" -> MulticaColors.Accent
                            "in_review" -> MulticaColors.Warning
                            "blocked", "cancelled" -> MulticaColors.Danger
                            else -> MulticaColors.Muted
                        },
                        modifier = Modifier.size(16.dp),
                    )
                }
                Text(
                    text = issue.identifier,
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.widthIn(min = 44.dp, max = 54.dp),
                )
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    SelectionContainer {
                        Text(
                            text = issue.title,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Medium,
                                fontSize = 15.sp,
                                lineHeight = 19.sp,
                            ),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    val rowMetadata = listOf(
                        Models.priorityLabel(issue.priority, zh),
                        metadata,
                        childProgressMetadata,
                        labelsMetadata,
                        projectMetadata,
                        dueDateMetadata,
                    ).filter { it.isNotBlank() }
                    Text(
                        text = rowMetadata.joinToString(" · "),
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                        color = if (issue.priority == "urgent" || issue.priority == "high") {
                            MulticaColors.Warning.copy(alpha = 0.92f)
                        } else {
                            MulticaColors.Muted.copy(alpha = 0.72f)
                        },
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.semantics {
                            contentDescription = listOf(
                                "Issue Child Progress Metadata $childProgressMetadata",
                                "Issue Labels Metadata $labelsMetadata",
                                "Issue Project Metadata $projectMetadata",
                                "Issue Due Date Metadata $dueDateMetadata",
                            ).joinToString(" ")
                        },
                    )
                }
                trailing()
            }
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border.copy(alpha = 0.74f))
            )
        }
    }
}

