@Composable
private fun PilotIssues(
    api: ApiClient,
    workspaceId: String,
    workspaceName: String,
    issues: List<Models.Issue>,
    currentUser: Models.User,
    personal: Boolean,
    loading: Boolean,
    selectedIds: Set<String>,
    zh: Boolean,
    onSelectedIdsChange: (Set<String>) -> Unit,
    onIssueClick: (String) -> Unit,
    onNewIssueClick: () -> Unit,
    onRefresh: () -> Unit,
) {
    val WEB_SSOT_MY_ISSUES_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/my-issues/components/my-issues-page.tsx"
    val WEB_SSOT_MY_ISSUES_HEADER = "/Users/park0er/coding/multica-web-source/packages/views/my-issues/components/my-issues-header.tsx"
    var boardMode by remember(personal) { mutableStateOf(false) }
    var sortOption by remember(personal) { mutableStateOf(IssueSortOption.Position) }
    var descending by remember(personal) { mutableStateOf(false) }
    var assigneeScope by remember(personal, workspaceId) { mutableStateOf(IssueAssigneeScope.All) }
    var myIssueScope by remember(personal, workspaceId) { mutableStateOf(MyIssueScope.Assigned) }
    var personalScopedIssues by remember(personal, workspaceId) { mutableStateOf<List<Models.Issue>?>(null) }
    var personalScopeLoading by remember(personal, workspaceId) { mutableStateOf(false) }
    var personalScopeError by remember(personal, workspaceId) { mutableStateOf<String?>(null) }
    var priorityFilter by remember(personal, workspaceId) { mutableStateOf<String?>(null) }
    var statusFilter by remember(personal, workspaceId) { mutableStateOf<String?>(null) }
    var collapsedStatusSections by remember(personal, workspaceId) { mutableStateOf<Set<String>>(emptySet()) }
    var issueQuery by remember(personal, workspaceId) { mutableStateOf("") }
    var selectionModeEnabled by remember(personal, workspaceId) { mutableStateOf(false) }
    var showFilterPanel by remember(personal, workspaceId) { mutableStateOf(false) }
    var batchMutating by remember(personal, workspaceId) { mutableStateOf(false) }
    var batchMessage by remember(personal, workspaceId) { mutableStateOf<String?>(null) }
    var confirmBatchDelete by remember(personal, workspaceId) { mutableStateOf(false) }
    var quickCreateOpen by remember(personal, workspaceId) { mutableStateOf(false) }
    var movingBoardIssueId by remember(personal, workspaceId) { mutableStateOf<String?>(null) }
    var assigneeMembers by remember(workspaceId) { mutableStateOf<List<Models.Member>>(emptyList()) }
    var assigneeAgents by remember(workspaceId) { mutableStateOf<List<Models.Agent>>(emptyList()) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(personal, myIssueScope, issues) {
        if (personal && myIssueScope == MyIssueScope.Assigned) {
            personalScopedIssues = issues
            personalScopeLoading = false
            personalScopeError = null
        }
    }
    LaunchedEffect(personal, myIssueScope, workspaceId, currentUser.id, assigneeAgents) {
        if (!personal || myIssueScope == MyIssueScope.Assigned) return@LaunchedEffect
        val myAgentIds = assigneeAgents
            .filter { it.ownerId == currentUser.id }
            .map { it.id }
            .filter { it.isNotBlank() }
            .sorted()
        if (myIssueScope == MyIssueScope.Agents && myAgentIds.isEmpty()) {
            personalScopedIssues = emptyList()
            personalScopeLoading = false
            personalScopeError = null
            return@LaunchedEffect
        }
        personalScopeLoading = true
        personalScopeError = null
        val result = withContext(Dispatchers.IO) {
            runCatching {
                IssueBuckets.loadAllConcurrent(
                    { status, limit, offset ->
                        when (myIssueScope) {
                            MyIssueScope.Assigned -> api.issuesFiltered(workspaceId, limit, offset, currentUser.id, status, null, emptyList())
                            MyIssueScope.Created -> {
                                val creatorId = currentUser.id
                                api.issuesFiltered(workspaceId, limit, offset, null, status, creatorId, emptyList())
                            }
                            MyIssueScope.Agents -> {
                                val assigneeIds = myAgentIds
                                api.issuesFiltered(workspaceId, limit, offset, null, status, null, assigneeIds)
                            }
                        }
                    },
                    100,
                )
            }
        }
        personalScopeLoading = false
        result.onSuccess {
            personalScopedIssues = it
        }.onFailure {
            personalScopeError = it.message ?: it.toString()
            personalScopedIssues = emptyList()
        }
    }

    val effectiveIssues = if (personal) personalScopedIssues ?: issues else issues
    val effectiveLoading = loading || (personal && personalScopeLoading)
    val childCountByParent = remember(effectiveIssues) {
        effectiveIssues.mapNotNull { issue ->
            issue.parentIssueId?.takeIf { it.isNotBlank() }
        }.groupingBy { it }.eachCount()
    }
    val visibleIssues = remember(effectiveIssues, issueQuery, assigneeScope, priorityFilter, statusFilter, sortOption, descending, zh) {
        val query = issueQuery.trim()
        val filtered = effectiveIssues
            .asSequence()
            .filter { issue ->
                personal || when (assigneeScope) {
                    IssueAssigneeScope.All -> true
                    IssueAssigneeScope.Members -> issue.assigneeType == "member"
                    IssueAssigneeScope.Agents -> issue.assigneeType == "agent" || issue.assigneeType == "squad"
                }
            }
            .filter { issue -> priorityFilter == null || issue.priority == priorityFilter }
            .filter { issue -> statusFilter == null || issue.status == statusFilter }
            .filter { issue ->
                query.isBlank()
                    || issue.identifier.contains(query, ignoreCase = true)
                    || issue.title.contains(query, ignoreCase = true)
                    || clean(issue.description).contains(query, ignoreCase = true)
                    || Models.statusLabel(issue.status, zh).contains(query, ignoreCase = true)
                    || Models.priorityLabel(issue.priority, zh).contains(query, ignoreCase = true)
            }
            .toList()
        sortIssues(filtered, sortOption, descending)
    }
    val grouped = remember(visibleIssues) { visibleIssues.groupBy { it.status } }
    val activeFilterCount = listOf(
        issueQuery.isNotBlank(),
        !personal && assigneeScope != IssueAssigneeScope.All,
        personal && myIssueScope != MyIssueScope.Assigned,
        priorityFilter != null,
        statusFilter != null,
        sortOption != IssueSortOption.Position || descending,
    ).count { it }
    val issueListUnfilteredEmpty = effectiveIssues.isEmpty() && activeFilterCount == 0
    val issueIds = remember(effectiveIssues) { effectiveIssues.map { it.id }.toSet() }
    LaunchedEffect(issueIds, effectiveLoading) {
        if (!effectiveLoading) {
            val filtered = selectedIds.filter { it in issueIds }.toSet()
            if (filtered != selectedIds) onSelectedIdsChange(filtered)
        }
    }
    LaunchedEffect(workspaceId) {
        withContext(Dispatchers.IO) {
            runCatching {
                val members = api.members(workspaceId)
                val agents = api.agents(workspaceId)
                members to agents
            }
        }.onSuccess { (members, agents) ->
            assigneeMembers = members
            assigneeAgents = agents
        }
    }

    fun runBatchAction(action: suspend (List<String>) -> Int, success: (Int) -> String, clearSelection: Boolean) {
        val ids = selectedIds.toList()
        if (ids.isEmpty() || batchMutating) return
        batchMutating = true
        batchMessage = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { action(ids) } }
            batchMutating = false
            result.onSuccess { count ->
                batchMessage = success(count)
                if (clearSelection) onSelectedIdsChange(emptySet())
                confirmBatchDelete = false
                onRefresh()
            }.onFailure {
                batchMessage = "${if (zh) "批量操作失败" else "Batch action failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun moveBoardIssue(issue: Models.Issue, direction: Int) {
        if (movingBoardIssueId != null || direction == 0) return
        val currentIndex = Models.STATUS_VALUES.indexOf(issue.status).takeIf { it >= 0 } ?: return
        val targetIndex = (currentIndex + direction).coerceIn(0, Models.STATUS_VALUES.lastIndex)
        if (targetIndex == currentIndex) return
        val targetStatus = Models.STATUS_VALUES[targetIndex]
        movingBoardIssueId = issue.id
        batchMessage = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.updateIssueStatus(workspaceId, issue.id, targetStatus) }
            }
            movingBoardIssueId = null
            result.onSuccess {
                batchMessage = if (zh) {
                    "已移动 ${issue.identifier} 到 ${Models.statusLabel(targetStatus, true)}"
                } else {
                    "Moved ${issue.identifier} to ${Models.statusLabel(targetStatus, false)}"
                }
                onRefresh()
            }.onFailure {
                batchMessage = "${if (zh) "移动失败" else "Move failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    val issueTitleActions: @Composable () -> Unit = {
        Row(
            modifier = Modifier.semantics { contentDescription = "Issue Compact Title Toolbar" },
            horizontalArrangement = Arrangement.spacedBy(7.dp, Alignment.End),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            IssueToolbarIconPill(
                icon = if (selectionModeEnabled || selectedIds.isNotEmpty()) Icons.Outlined.CheckCircle else Icons.Outlined.RadioButtonUnchecked,
                contentDescription = "Issue Selection Toggle",
                selected = selectionModeEnabled || selectedIds.isNotEmpty(),
                onClick = {
                    selectionModeEnabled = !selectionModeEnabled
                    if (!selectionModeEnabled) {
                        onSelectedIdsChange(emptySet())
                        confirmBatchDelete = false
                    } else {
                        boardMode = false
                    }
                },
            )
            IssueToolbarIconPill(
                icon = Icons.Outlined.Tune,
                contentDescription = "IssueFilterToggle",
                selected = showFilterPanel || activeFilterCount > 0,
                onClick = { showFilterPanel = !showFilterPanel },
            )
            IssueSortIconMenu(
                sortOption = sortOption,
                descending = descending,
                zh = zh,
                onSortOptionChange = { sortOption = it },
                onDirectionChange = { descending = it },
            )
            IssueToolbarIconPill(
                icon = if (boardMode) Icons.Outlined.ViewList else Icons.Outlined.Dashboard,
                contentDescription = if (boardMode) {
                    if (zh) "切换到列表" else "Switch to list"
                } else {
                    if (zh) "切换到看板" else "Switch to board"
                },
                selected = boardMode,
                onClick = { boardMode = !boardMode },
            )
            IssueCreateMenuButton(
                zh = zh,
                onManualCreate = onNewIssueClick,
                onAgentQuickCreate = {
                    if (!personal) quickCreateOpen = !quickCreateOpen else onNewIssueClick()
                },
            )
        }
    }

    val issuePinnedHeader: @Composable () -> Unit = {
        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            IssueWebContextCaption(workspaceName = workspaceName, personal = personal, zh = zh)
            if (personal) {
                Box(
                    modifier = Modifier.semantics {
                        contentDescription = "My Issues Web SSOT $WEB_SSOT_MY_ISSUES_PAGE $WEB_SSOT_MY_ISSUES_HEADER"
                    },
                ) {
                    MyIssuesScopeSegmentedControl(
                        selected = myIssueScope,
                        zh = zh,
                        onSelected = {
                            myIssueScope = it
                            onSelectedIdsChange(emptySet())
                            confirmBatchDelete = false
                        },
                    )
                }
            } else {
                IssueScopeSegmentedControl(
                    selected = assigneeScope,
                    zh = zh,
                    onSelected = {
                        assigneeScope = it
                        onSelectedIdsChange(emptySet())
                        confirmBatchDelete = false
                    },
                )
            }
        }
    }

    PilotListPage(
        title = if (personal) {
            if (zh) "我的 Issues" else "My Issues"
        } else {
            "Issues"
        },
        trailing = issueTitleActions,
        pinnedHeader = issuePinnedHeader,
        bottomContent = if (selectedIds.isNotEmpty()) {
            {
                IssueBatchActionBar(
                    selectedCount = selectedIds.size,
                    members = assigneeMembers,
                    agents = assigneeAgents,
                    batchMutating = batchMutating,
                    confirmingDelete = confirmBatchDelete,
                    zh = zh,
                    onStatus = { status ->
                        runBatchAction(
                            action = { ids -> api.batchUpdateIssues(workspaceId, ids, status, null) },
                            success = { count -> if (zh) "已更新 $count 个 Issue" else "Updated $count issues" },
                            clearSelection = true,
                        )
                    },
                    onPriority = { priority ->
                        runBatchAction(
                            action = { ids -> api.batchUpdateIssues(workspaceId, ids, null, priority) },
                            success = { count -> if (zh) "已更新 $count 个 Issue" else "Updated $count issues" },
                            clearSelection = true,
                        )
                    },
                    onAssignee = { type, id ->
                        runBatchAction(
                            action = { ids -> api.batchUpdateIssues(workspaceId, ids, null, null, type, id) },
                            success = { count -> if (zh) "已分配 $count 个 Issue" else "Assigned $count issues" },
                            clearSelection = true,
                        )
                    },
                        onClear = {
                            onSelectedIdsChange(emptySet())
                            selectionModeEnabled = false
                            confirmBatchDelete = false
                        },
                    onDelete = { confirmBatchDelete = true },
                    onCancelDelete = { confirmBatchDelete = false },
                    onConfirmDelete = {
                        runBatchAction(
                            action = { ids -> api.batchDeleteIssues(workspaceId, ids) },
                            success = { count -> if (zh) "已删除 $count 个 Issue" else "Deleted $count issues" },
                            clearSelection = true,
                        )
                    },
                )
            }
        } else {
            null
        },
    ) {
        if (showFilterPanel || activeFilterCount > 0) {
            item {
                IssueListControls(
                    query = issueQuery,
                    onQueryChange = { issueQuery = it },
                    sortOption = sortOption,
                    descending = descending,
                    priorityFilter = priorityFilter,
                    statusFilter = statusFilter,
                    selectedCount = selectedIds.size,
                    zh = zh,
                    onSortOptionChange = { sortOption = it },
                    onDirectionChange = { descending = it },
                    onPriorityChange = { priorityFilter = it },
                    onStatusChange = { statusFilter = it },
                    onClear = {
                        issueQuery = ""
                        assigneeScope = IssueAssigneeScope.All
                        myIssueScope = MyIssueScope.Assigned
                        priorityFilter = null
                        statusFilter = null
                        sortOption = IssueSortOption.Position
                        descending = false
                        showFilterPanel = false
                    },
                )
            }
        }
        if (issueQuery.isBlank() && selectedIds.isEmpty()) {
            item {
                IssueListSummaryPanel(
                    total = effectiveIssues.size,
                    visible = visibleIssues.size,
                    groupedCount = grouped.values.count { it.isNotEmpty() },
                    activeFilters = activeFilterCount,
                    personal = personal,
                    zh = zh,
                )
            }
        }
        if (quickCreateOpen && !personal) {
            item {
                PilotQuickCreateCard(
                    api = api,
                    workspaceId = workspaceId,
                    zh = zh,
                    onClose = { quickCreateOpen = false },
                )
            }
        }
        if (!batchMessage.isNullOrBlank()) {
            item {
                PilotInlineResultState(
                    message = batchMessage.orEmpty(),
                    isError = pilotInlineResultIsError(batchMessage.orEmpty()),
                    contentDescription = "Issue Batch Result Web Banner",
                )
            }
        }
        if (!personalScopeError.isNullOrBlank()) {
            item {
                PilotInlineResultState(
                    message = "${if (zh) "加载我的 Issues 失败" else "Failed to load My Issues"}: ${personalScopeError.orEmpty()}",
                    isError = true,
                    contentDescription = "My Issues Scope Result Web Banner",
                )
            }
        }
        if (effectiveLoading) {
            item {
                MulticaLoadingState(
                    if (personal) {
                        if (zh) "正在加载我的 Issues..." else "Loading my issues..."
                    } else {
                        if (zh) "正在加载 Issues..." else "Loading issues..."
                    },
                )
            }
        } else if (boardMode) {
            item {
                PilotIssueBoard(
                    grouped = grouped,
                    zh = zh,
                    movingIssueId = movingBoardIssueId,
                    onMoveIssue = ::moveBoardIssue,
                    onIssueClick = onIssueClick,
                )
            }
        } else {
            if (visibleIssues.isEmpty()) {
                item {
                    IssueListWebEmptyState(
                        personal = personal,
                        unfilteredEmpty = issueListUnfilteredEmpty,
                        zh = zh,
                    )
                }
            } else {
                Models.STATUS_VALUES.forEach { status ->
                    val bucket = grouped[status].orEmpty()
                    if (bucket.isEmpty()) return@forEach
                    val collapsed = status in collapsedStatusSections
                    item {
                        IssueStatusGroupHeader(
                            status = status,
                            count = bucket.size,
                            collapsed = collapsed,
                            zh = zh,
                            onClick = {
                                collapsedStatusSections = if (collapsed) {
                                    collapsedStatusSections - status
                                } else {
                                    collapsedStatusSections + status
                                }
                            },
                        )
                    }
                    if (!collapsed) {
                        items(bucket, key = { it.id }) { issue ->
                            val selected = issue.id in selectedIds
                            val selectionMode = selectionModeEnabled || selectedIds.isNotEmpty() || issueQuery.isNotBlank()
                            fun toggleIssueSelection() {
                                onSelectedIdsChange(if (selected) {
                                    selectedIds - issue.id
                                } else {
                                    selectedIds + issue.id
                                })
                                confirmBatchDelete = false
                            }
                            IssueMaterialListRow(
                        issue = issue,
                        metadata = buildString {
                            if (issue.createdAt.isNotBlank()) {
                                append(if (zh) "创建 " else "Created ")
                                append(shortDate(issue.createdAt))
                                    }
                                    if (!issue.assigneeId.isNullOrBlank()) {
                                        val assigneeName = Models.issueAssigneeDisplayName(
                                            issue,
                                            assigneeMembers,
                                            assigneeAgents,
                                            currentUser,
                                        )
                                        if (isNotBlank()) append(" · ")
                                        append(assigneeName.ifBlank { Models.shortId(issue.assigneeId) })
                                    }
                                },
                                childProgressMetadata = childCountByParent[issue.id]?.takeIf { it > 0 }?.let {
                                    if (zh) "$it 个子 Issue" else "$it child issues"
                                }.orEmpty(),
                                labelsMetadata = issue.labels.take(2).joinToString(", ") { it.name },
                                projectMetadata = issue.projectId?.takeIf { it.isNotBlank() }?.let {
                                    if (zh) "项目 ${Models.shortId(it)}" else "Project ${Models.shortId(it)}"
                                }.orEmpty(),
                                dueDateMetadata = issue.dueDate.takeIf { it.isNotBlank() }?.let {
                                    if (zh) "截止 ${shortDate(it)}" else "Due ${shortDate(it)}"
                                }.orEmpty(),
                                onClick = {
                                    if (selectedIds.isNotEmpty() || issueQuery.isNotBlank()) {
                                        toggleIssueSelection()
                                    } else {
                                        onIssueClick(issue.id)
                                    }
                                },
                                rowSelectionDescription = if (!selectionMode) {
                                    "Open Issue ${issue.identifier}"
                                } else if (selected) {
                                    if (zh) "已选择 ${issue.identifier}" else "Selected ${issue.identifier}"
                                } else {
                                    if (zh) "选择 ${issue.identifier}" else "Select ${issue.identifier}"
                                },
                                onRowSelectionClick = {
                                    if (selectionMode) toggleIssueSelection() else onIssueClick(issue.id)
                                },
                                zh = zh,
                                trailing = {
                                    if (selectionMode) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(2.dp),
                                        ) {
                                            if (selected) {
                                                Text(
                                                    text = if (zh) "已选择 ${selectedIds.size}" else "${selectedIds.size} selected",
                                                    style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.SemiBold),
                                                    color = MulticaColors.Accent,
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis,
                                                )
                                            }
                                            MulticaIconPillButton(
                                                icon = if (selected) Icons.Outlined.CheckCircle else Icons.Outlined.RadioButtonUnchecked,
                                                contentDescription = if (selected) {
                                                    if (zh) "已选择 ${issue.identifier}" else "Selected ${issue.identifier}"
                                                } else {
                                                    if (zh) "选择 ${issue.identifier}" else "Select ${issue.identifier}"
                                                },
                                                onClick = { toggleIssueSelection() },
                                                tone = if (selected) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                                                modifier = Modifier
                                                    .size(44.dp)
                                                    .semantics(mergeDescendants = true) {
                                                        contentDescription = if (selected) {
                                                            if (zh) "已选择 ${issue.identifier}" else "Selected ${issue.identifier}"
                                                        } else {
                                                            if (zh) "选择 ${issue.identifier}" else "Select ${issue.identifier}"
                                                        }
                                                    },
                                            )
                                        }
                                    } else {
                                        Icon(
                                            imageVector = Icons.Outlined.KeyboardArrowRight,
                                            contentDescription = null,
                                            tint = MulticaColors.Muted,
                                            modifier = Modifier
                                                .size(22.dp)
                                                .semantics { contentDescription = "Open Issue ${issue.identifier}" },
                                        )
                                    }
                                },
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun PilotQuickCreateCard(
    api: ApiClient,
    workspaceId: String,
    zh: Boolean,
    onClose: () -> Unit,
) {
    var agentsState by remember(workspaceId) { mutableStateOf<Result<List<Models.Agent>>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var prompt by remember(workspaceId) { mutableStateOf("") }
    var agentIndex by remember(workspaceId) { mutableIntStateOf(0) }
    var submitting by remember(workspaceId) { mutableStateOf(false) }
    var resultText by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, refresh) {
        agentsState = null
        agentsState = withContext(Dispatchers.IO) {
            runCatching {
                api.agents(workspaceId)
                    .filter { it.archivedAt.isBlank() }
                    .sortedBy { it.name.lowercase() }
            }
        }
        agentIndex = 0
    }

    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Quick Create Web Agent Panel" },
        shape = RoundedCornerShape(12.dp),
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.66f), RoundedCornerShape(12.dp))
                .padding(horizontal = 12.dp, vertical = 11.dp),
            verticalArrangement = Arrangement.spacedBy(11.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        if (zh) "工作区 › Agent Issue" else "Workspace › Agent Issue",
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 14.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.TextTertiary,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        if (zh) "快速创建 Issue" else "Quick Create Issue",
                        style = MaterialTheme.typography.titleSmall.copy(fontSize = 15.sp, lineHeight = 19.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                    )
                }
                MulticaIconPillButton(
                    icon = Icons.Outlined.Close,
                    contentDescription = "Quick Create Close",
                    onClick = onClose,
                    tone = MulticaButtonTone.Ghost,
                )
            }
            when (val loaded = agentsState) {
                null -> MulticaLoadingState(if (zh) "正在加载 Agent..." else "Loading agents...")
                else -> loaded.fold(
                    onSuccess = { agents ->
                        val selectedAgent = agents.getOrNull(agentIndex.coerceIn(0, (agents.size - 1).coerceAtLeast(0)))
                        QuickCreateAgentPickerRow(
                            agents = agents,
                            selectedAgent = selectedAgent,
                            zh = zh,
                            onSelect = { index ->
                                agentIndex = index
                                resultText = null
                            },
                        )
                        MulticaTextField(
                            value = prompt,
                            onValueChange = {
                                prompt = it
                                resultText = null
                            },
                            label = if (zh) "告诉 Agent 要创建什么 Issue" else "Tell the agent what issue to create",
                            contentDescription = "Quick Create Prompt Field",
                            minLines = 4,
                            maxLines = 8,
                        )
                        if (!resultText.isNullOrBlank()) {
                            val isError = resultText!!.contains("failed", true) ||
                                resultText!!.contains("失败") ||
                                resultText!!.contains("请选择")
                            if (isError) {
                                PilotInlineResultState(
                                    message = resultText.orEmpty(),
                                    isError = true,
                                    contentDescription = "Quick Create Result Web Banner",
                                )
                            } else {
                                MulticaSuccessState(resultText.orEmpty())
                            }
                        }
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .border(1.dp, MulticaColors.Border.copy(alpha = 0.45f), RoundedCornerShape(10.dp))
                                .padding(horizontal = 10.dp, vertical = 9.dp),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Text(
                                if (zh) "Agent 会根据提示创建任务并回写 Issue。" else "The agent creates a task and files the issue from your prompt.",
                                modifier = Modifier.weight(1f),
                                style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                                color = MulticaColors.Muted,
                            )
                            MulticaPillButton(
                                text = if (submitting) "..." else if (zh) "发送" else "Send",
                                icon = Icons.AutoMirrored.Outlined.Send,
                                contentDescription = "Quick Create Send",
                                onClick = {
                                    val agent = selectedAgent
                                    val promptText = prompt.trim()
                                    if (agent == null || promptText.isBlank() || submitting) {
                                        resultText = if (zh) "请选择 Agent 并填写提示词" else "Select an agent and enter a prompt"
                                        return@MulticaPillButton
                                    }
                                    submitting = true
                                    resultText = null
                                    scope.launch {
                                        val result = withContext(Dispatchers.IO) {
                                            runCatching { api.quickCreateIssue(workspaceId, agent.id, promptText) }
                                        }
                                        submitting = false
                                        result.onSuccess {
                                            prompt = ""
                                            resultText = if (zh) "已创建任务 ${it.taskId}" else "Task created ${it.taskId}"
                                        }.onFailure {
                                            resultText = "${if (zh) "快速创建失败" else "Quick create failed"}: ${it.message ?: it.toString()}"
                                        }
                                    }
                                },
                                tone = MulticaButtonTone.Primary,
                            )
                        }
                    },
                    onFailure = {
                        MulticaErrorState(
                            message = "${if (zh) "Agent 加载失败" else "Agents failed"}\n${it.message ?: it.toString()}",
                            onRetry = { refresh++ },
                        )
                    },
                )
            }
        }
    }
}

@Composable
private fun QuickCreateAgentPickerRow(
    agents: List<Models.Agent>,
    selectedAgent: Models.Agent?,
    zh: Boolean,
    onSelect: (Int) -> Unit,
) {
    var expanded by remember { mutableStateOf(false) }
    val items = remember(agents, selectedAgent, zh) {
        if (agents.isEmpty()) {
            listOf(
                MulticaCupertinoActionSheetItem(
                    title = if (zh) "没有可用 Agent" else "No agent available",
                    icon = Icons.Outlined.Person,
                    contentDescription = "Quick Create Agent Empty",
                    enabled = false,
                    onClick = {},
                )
            )
        } else {
            agents.mapIndexed { index, agent ->
                MulticaCupertinoActionSheetItem(
                    title = agent.name,
                    subtitle = agent.visibility.takeIf { it.isNotBlank() },
                    icon = Icons.Outlined.Person,
                    selected = agent.id == selectedAgent?.id,
                    contentDescription = "Quick Create Agent ${agent.name}",
                    onClick = { onSelect(index) },
                )
            }
        }
    }
    Box {
        Surface(
            modifier = Modifier
                .fillMaxWidth()
                .semantics { contentDescription = "Quick Create Actor Picker" }
                .clickable(enabled = agents.isNotEmpty()) { expanded = true },
            shape = RoundedCornerShape(9.dp),
            color = MulticaColors.Background,
            tonalElevation = 0.dp,
            shadowElevation = 0.dp,
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .border(1.dp, MulticaColors.Border.copy(alpha = 0.58f), RoundedCornerShape(9.dp))
                    .padding(horizontal = 11.dp, vertical = 9.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(Icons.Outlined.Person, contentDescription = null, tint = MulticaColors.Muted, modifier = Modifier.size(17.dp))
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        if (zh) "Created by" else "Created by",
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.TextTertiary,
                    )
                    Text(
                        selectedAgent?.name ?: if (zh) "没有可用 Agent" else "No agent available",
                        style = MaterialTheme.typography.titleSmall.copy(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    selectedAgent?.visibility?.takeIf { it.isNotBlank() }?.let {
                        Text(
                            it,
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                Icon(Icons.Outlined.KeyboardArrowDown, contentDescription = null, tint = MulticaColors.Muted, modifier = Modifier.size(18.dp))
            }
        }
        MulticaCupertinoActionSheet(
            visible = expanded,
            title = if (zh) "选择 Agent" else "Choose agent",
            items = items,
            cancelText = if (zh) "取消" else "Cancel",
            onDismissRequest = { expanded = false },
        )
    }
}

@Composable
private fun IssueListWebEmptyState(
    personal: Boolean,
    unfilteredEmpty: Boolean,
    zh: Boolean,
) {
    val WEB_SSOT_ISSUES_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/issues/components/issues-page.tsx"
    val WEB_SSOT_MY_ISSUES_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/my-issues/components/my-issues-page.tsx"
    val sourcePath = if (personal) WEB_SSOT_MY_ISSUES_PAGE else WEB_SSOT_ISSUES_PAGE
    val title = if (unfilteredEmpty) {
        if (personal) {
            if (zh) "没有分配给你的 issue" else "No issues assigned to you"
        } else {
            if (zh) "还没有 issue" else "No issues yet"
        }
    } else {
        if (zh) "没有匹配的 Issue" else "No matching issues"
    }
    val description = if (unfilteredEmpty) {
        if (personal) {
            if (zh) "你创建或被分配到的 issue 会显示在这里。" else "Issues you create or are assigned to will appear here."
        } else {
            if (zh) "创建一个 issue 开始使用。" else "Create an issue to get started."
        }
    } else {
        if (zh) "清除搜索或筛选后再试。" else "Clear search or filters and try again."
    }

    Box(
        modifier = Modifier.semantics {
            contentDescription = "Issue List Web Empty State $sourcePath"
        },
    ) {
        MulticaEmptyState(
            title = title,
            description = description,
        )
    }
}

@Composable
private fun PilotIssueBoard(
    grouped: Map<String, List<Models.Issue>>,
    zh: Boolean,
    movingIssueId: String?,
    onMoveIssue: (Models.Issue, Int) -> Unit,
    onIssueClick: (String) -> Unit,
) {
    LazyRow(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 8.dp),
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        items(Models.STATUS_VALUES) { status ->
            val bucket = grouped[status].orEmpty()
            Surface(
                modifier = Modifier
                    .width(236.dp)
                    .semantics { contentDescription = "Issue Web Board Column $status" },
                shape = RoundedCornerShape(10.dp),
                color = MulticaColors.Surface,
                tonalElevation = 0.dp,
                shadowElevation = 0.dp,
                border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.74f)),
            ) {
                Column(modifier = Modifier.padding(horizontal = 10.dp, vertical = 10.dp)) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 8.dp),
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            imageVector = issueStatusIcon(status),
                            contentDescription = null,
                            tint = MulticaColors.Muted,
                            modifier = Modifier.size(15.dp),
                        )
                        Text(
                            text = Models.statusLabel(status, zh),
                            style = MaterialTheme.typography.labelLarge.copy(fontWeight = FontWeight.SemiBold),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f),
                        )
                        Text(
                            text = bucket.size.toString(),
                            style = MaterialTheme.typography.labelMedium.copy(fontSize = 11.sp, lineHeight = 13.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                        )
                    }
                    if (bucket.isEmpty()) {
                        Text(
                            text = if (zh) "暂无问题" else "No issues",
                            style = MaterialTheme.typography.labelMedium,
                            color = MulticaColors.Muted,
                            modifier = Modifier.padding(vertical = 14.dp),
                        )
                    }
                    bucket.take(20).forEachIndexed { index, issue ->
                        var horizontalDrag by remember(issue.id) { mutableStateOf(0f) }
                        val isMoving = movingIssueId == issue.id
                        Surface(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics {
                                    contentDescription = "Board Issue ${issue.identifier}"
                                }
                                .graphicsLayer {
                                    translationX = horizontalDrag.coerceIn(-44f, 44f)
                                }
                                .pointerInput(issue.id, issue.status, movingIssueId) {
                                    detectHorizontalDragGestures(
                                        onDragCancel = { horizontalDrag = 0f },
                                        onDragEnd = {
                                            val direction = when {
                                                horizontalDrag > 92f -> 1
                                                horizontalDrag < -92f -> -1
                                                else -> 0
                                            }
                                            horizontalDrag = 0f
                                            if (!isMoving && direction != 0) onMoveIssue(issue, direction)
                                        },
                                        onHorizontalDrag = { change, dragAmount ->
                                            if (!isMoving) {
                                                horizontalDrag += dragAmount
                                                change.consume()
                                            }
                                        },
                                    )
                                }
                                .clickable(enabled = !isMoving) { onIssueClick(issue.id) },
                            shape = RoundedCornerShape(8.dp),
                            color = if (isMoving) MulticaColors.Accent.copy(alpha = 0.10f) else MulticaColors.Background,
                            tonalElevation = 0.dp,
                            shadowElevation = 0.dp,
                            border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.52f)),
                        ) {
                            Column(modifier = Modifier.padding(horizontal = 9.dp, vertical = 8.dp)) {
                                Text(
                                    text = issue.title,
                                    style = MaterialTheme.typography.bodyMedium.copy(
                                        fontWeight = FontWeight.Medium,
                                        fontSize = 14.sp,
                                        lineHeight = 18.sp,
                                    ),
                                    color = MulticaColors.Text,
                                    maxLines = 2,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                Text(
                                    text = listOf(
                                        issue.identifier,
                                        Models.priorityLabel(issue.priority, zh),
                                        if (isMoving) if (zh) "移动中..." else "Moving..." else "",
                                    ).filter { it.isNotBlank() }.joinToString(" · "),
                                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                                    color = MulticaColors.Muted,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                        if (index < bucket.lastIndex && index < 19) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(1.dp)
                                    .background(MulticaColors.Border)
                            )
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
