@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun IssueFormWebRow(
    eyebrow: String,
    title: String,
    subtitle: String?,
    contentDescription: String,
    onClick: (() -> Unit)? = null,
    trailingIcon: ImageVector? = null,
) {
    val haptic = LocalHapticFeedback.current
    val clickableModifier = if (onClick == null) {
        Modifier
    } else {
        Modifier.clickable {
            haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
            onClick()
        }
    }
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .then(clickableModifier)
            .semantics(mergeDescendants = true) {
                this.contentDescription = contentDescription
            },
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = 64.dp)
                .padding(horizontal = 6.dp, vertical = 11.dp),
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Text(
                    text = eyebrow,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = MulticaTypeScale.Caption, lineHeight = 15.sp, fontWeight = FontWeight.SemiBold),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodyMedium.copy(fontSize = MulticaTypeScale.FormRowTitle, lineHeight = 20.sp, fontWeight = FontWeight.Medium),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                if (!subtitle.isNullOrBlank()) {
                    Text(
                        text = subtitle,
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = MulticaTypeScale.DetailMeta, lineHeight = 17.sp),
                        color = MulticaColors.Muted.copy(alpha = 0.72f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
            if (trailingIcon != null) {
                Icon(
                    imageVector = trailingIcon,
                    contentDescription = null,
                    tint = MulticaColors.Muted,
                    modifier = Modifier.size(18.dp),
                )
            }
        }
    }
}

@Composable
private fun IssueFormMenuRow(
    eyebrow: String,
    title: String,
    subtitle: String?,
    contentDescription: String,
    options: List<IssueFormMenuOption>,
) {
    var expanded by remember { mutableStateOf(false) }
    Box {
        IssueFormWebRow(
            eyebrow = eyebrow,
            title = title,
            subtitle = subtitle,
            contentDescription = "$contentDescription Issue Form Web Menu Row",
            onClick = { expanded = true },
            trailingIcon = Icons.Outlined.KeyboardArrowRight,
        )
        MulticaCupertinoActionSheet(
            visible = expanded,
            title = eyebrow,
            message = title,
            items = options.map { option ->
                MulticaCupertinoActionSheetItem(
                    title = option.label,
                    contentDescription = "$contentDescription ${option.label}",
                    selected = option.selected,
                    onClick = option.onClick,
                )
            },
            cancelText = "Cancel",
            onDismissRequest = { expanded = false },
        )
    }
}

private data class IssueFormMenuOption(
    val label: String,
    val selected: Boolean,
    val onClick: () -> Unit,
)

private data class PickedIssueAttachment(
    val uri: Uri,
    val filename: String,
    val contentType: String,
    val image: Boolean,
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun PilotIssueForm(
    api: ApiClient,
    session: PilotSession,
    issue: Models.Issue?,
    parentIssueId: String?,
    parentIssueIdentifier: String?,
    zh: Boolean,
    onCancel: () -> Unit,
    onSaved: (Models.Issue) -> Unit,
) {
    val editing = issue != null
    var optionsState by remember(session.workspace.id) { mutableStateOf<Result<PilotIssueFormOptions>?>(null) }
    var optionsRefresh by remember(session.workspace.id) { mutableIntStateOf(0) }
    var saveError by remember(issue?.id) { mutableStateOf<String?>(null) }
    var saving by remember(issue?.id) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    LaunchedEffect(session.workspace.id, optionsRefresh) {
        optionsState = null
        optionsState = withContext(Dispatchers.IO) {
            runCatching {
                PilotIssueFormOptions(
                    projects = api.projects(session.workspace.id, 500, 0).items,
                    members = api.members(session.workspace.id),
                    agents = api.agents(session.workspace.id),
                )
            }
        }
    }

    val loaded = optionsState
    when {
        loaded == null -> MulticaLoadingState(if (zh) "正在加载表单..." else "Loading form...")
        loaded.isFailure -> MulticaErrorState(
            message = "${if (zh) "表单加载失败" else "Form failed"}\n${loaded.exceptionOrNull()?.message.orEmpty()}",
            onRetry = { optionsRefresh++ },
        )
        else -> {
            val options = loaded.getOrThrow()
            val assignees = Models.issueAssignees(
                true,
                if (zh) "未分配" else "Unassigned",
                session.user,
                options.members,
                options.agents,
            ).map { PilotAssigneeOption(it.id, it.type, it.name) }
            var title by remember(issue?.id) { mutableStateOf(issue?.title.orEmpty()) }
            var description by remember(issue?.id) { mutableStateOf(issue?.description.orEmpty()) }
            var dueDate by remember(issue?.id) { mutableStateOf(issue?.dueDate.orEmpty()) }
            var dueDateEnabled by remember(issue?.id) { mutableStateOf(issue?.dueDate?.isNotBlank() == true) }
            var showDueDatePicker by remember(issue?.id) { mutableStateOf(false) }
            var projectIndex by remember(issue?.id, options.projects.size) {
                mutableIntStateOf((options.projects.indexOfFirst { it.id == issue?.projectId } + 1).coerceAtLeast(0))
            }
            var statusIndex by remember(issue?.id) {
                mutableIntStateOf(Models.STATUS_VALUES.indexOf(issue?.status ?: "todo").coerceAtLeast(0))
            }
            var priorityIndex by remember(issue?.id) {
                mutableIntStateOf(Models.PRIORITY_VALUES.indexOf(issue?.priority ?: "medium").coerceAtLeast(0))
            }
            var assigneeIndex by remember(issue?.id, assignees.size) {
                mutableIntStateOf(assignees.indexOfFirst {
                    it.id == issue?.assigneeId && (issue?.assigneeType == null || it.type == issue.assigneeType)
                }.coerceAtLeast(0))
            }
            val agentCreateOptions = options.agents
                .filter { it.archivedAt.isBlank() }
                .sortedBy { it.name.lowercase() }
            var agentCreateIndex by remember(issue?.id, agentCreateOptions.size) { mutableIntStateOf(0) }
            var agentCreatePrompt by remember(issue?.id) { mutableStateOf("") }
            var agentCreateSubmitting by remember(issue?.id) { mutableStateOf(false) }
            var agentCreateResult by remember(issue?.id) { mutableStateOf<String?>(null) }
            var pendingIssueAttachments by remember(issue?.id) { mutableStateOf<List<PickedIssueAttachment>>(emptyList()) }
            val selectedCreateAgent = agentCreateOptions.getOrNull(
                agentCreateIndex.coerceIn(0, (agentCreateOptions.size - 1).coerceAtLeast(0))
            )
            val fileAttachmentLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
                if (uri == null) return@rememberLauncherForActivityResult
                pendingIssueAttachments = pendingIssueAttachments + PickedIssueAttachment(
                    uri = uri,
                    filename = displayNameForUri(context, uri),
                    contentType = context.contentResolver.getType(uri) ?: "application/octet-stream",
                    image = false,
                )
            }
            val imageAttachmentLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
                if (uri == null) return@rememberLauncherForActivityResult
                pendingIssueAttachments = pendingIssueAttachments + PickedIssueAttachment(
                    uri = uri,
                    filename = displayNameForUri(context, uri),
                    contentType = context.contentResolver.getType(uri) ?: "image/*",
                    image = true,
                )
            }

            fun cycleProject() {
                projectIndex = (projectIndex + 1) % (options.projects.size + 1)
            }

            fun cycleStatus() {
                statusIndex = (statusIndex + 1) % Models.STATUS_VALUES.size
            }

            fun cyclePriority() {
                priorityIndex = (priorityIndex + 1) % Models.PRIORITY_VALUES.size
            }

            fun cycleAssignee() {
                assigneeIndex = (assigneeIndex + 1) % assignees.size
            }

            fun cycleCreateAgent() {
                if (agentCreateOptions.isNotEmpty()) {
                    agentCreateIndex = (agentCreateIndex + 1) % agentCreateOptions.size
                }
            }

            fun ensureDueDateValue() {
                if (dueDate.isBlank()) {
                    dueDate = formatDueDateMillis(System.currentTimeMillis())
                }
            }

            fun agentCreatePromptText(): String {
                val customPrompt = agentCreatePrompt.trim()
                if (customPrompt.isNotEmpty()) return customPrompt
                val titleText = title.trim()
                val descriptionText = description.trim()
                return listOf(
                    titleText.takeIf { it.isNotEmpty() }?.let { "Title: $it" },
                    descriptionText.takeIf { it.isNotEmpty() }?.let { "Description: $it" },
                ).filterNotNull().joinToString("\n")
            }

            fun saveIssue() {
                val titleText = title.trim()
                if (titleText.isEmpty() || saving) {
                    saveError = if (zh) "标题不能为空" else "Title is required"
                    return
                }
                val projectId = if (projectIndex == 0) null else options.projects[projectIndex - 1].id
                val dueDateText = if (dueDateEnabled) dueDate.trim() else ""
                val status = Models.STATUS_VALUES[statusIndex]
                val priority = Models.PRIORITY_VALUES[priorityIndex]
                val selectedAssignee = assignees[assigneeIndex]
                val assignee = if (selectedAssignee.id == null) null else {
                    Models.Assignee(selectedAssignee.id, selectedAssignee.type, selectedAssignee.name)
                }
                saving = true
                saveError = null
                scope.launch {
                    val result = withContext(Dispatchers.IO) {
                        runCatching {
                            val saved = if (issue == null) {
                                api.createIssue(titleText, description, session.workspace.id, projectId, status, priority, assignee, dueDateText, parentIssueId)
                            } else {
                                api.updateIssue(issue, titleText, description, projectId, status, priority, assignee, dueDateText)
                            }
                            pendingIssueAttachments.forEach { attachment ->
                                val bytes = context.contentResolver.openInputStream(attachment.uri)?.use { it.readBytes() } ?: ByteArray(0)
                                api.uploadIssueAttachment(
                                    session.workspace.id,
                                    saved.id,
                                    attachment.filename,
                                    attachment.contentType,
                                    bytes,
                                )
                            }
                            saved
                        }
                    }
                    saving = false
                    result.onSuccess {
                        pendingIssueAttachments = emptyList()
                        onSaved(it)
                    }.onFailure {
                        saveError = "${if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
                    }
                }
            }

            MulticaCupertinoActionSheet(
                visible = showDueDatePicker,
                title = if (zh) "设置到期时间" else "Set due date",
                message = if (zh) "也可以在下方直接输入日期值" else "You can also type a date value below",
                items = listOf(
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "今天" else "Today",
                        icon = Icons.Outlined.CalendarMonth,
                        contentDescription = "Issue Due Date Today",
                        onClick = {
                            dueDate = formatDueDateMillis(System.currentTimeMillis())
                            dueDateEnabled = true
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "明天" else "Tomorrow",
                        icon = Icons.Outlined.CalendarMonth,
                        contentDescription = "Issue Due Date Tomorrow",
                        onClick = {
                            dueDate = formatDueDateMillis(System.currentTimeMillis() + 86_400_000L)
                            dueDateEnabled = true
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "下周" else "Next week",
                        icon = Icons.Outlined.CalendarMonth,
                        contentDescription = "Issue Due Date Next Week",
                        onClick = {
                            dueDate = formatDueDateMillis(System.currentTimeMillis() + 7 * 86_400_000L)
                            dueDateEnabled = true
                        },
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "清除截止日期" else "Clear due date",
                        icon = Icons.Outlined.Delete,
                        destructive = true,
                        contentDescription = "Issue Due Date Clear",
                        onClick = {
                            dueDate = ""
                            dueDateEnabled = false
                        },
                    ),
                ),
                cancelText = if (zh) "取消" else "Cancel",
                onDismissRequest = { showDueDatePicker = false },
            )

            val WEB_SSOT_CREATE_ISSUE = "/Users/park0er/coding/multica-web-source/packages/views/modals/create-issue.tsx"
            val WEB_SSOT_CREATE_ISSUE_DIALOG = "/Users/park0er/coding/multica-web-source/packages/views/modals/create-issue-dialog.tsx"
            val WEB_SSOT_ISSUE_PROPERTY_PICKER = "/Users/park0er/coding/multica-web-source/packages/views/issues/components/pickers/property-picker.tsx"
            val formTitle = if (editing) {
                if (zh) "编辑 Issue" else "Edit Issue"
            } else if (!parentIssueId.isNullOrBlank()) {
                if (zh) "新建子 Issue" else "New Child Issue"
            } else {
                if (zh) "新建 Issue" else "New Issue"
            }

            PilotListPage(
                title = formTitle,
                compactHeader = true,
                leading = {
                    MulticaIconPillButton(
                        icon = Icons.AutoMirrored.Outlined.ArrowBack,
                        contentDescription = if (zh) "返回" else "Back",
                        onClick = onCancel,
                        tone = MulticaButtonTone.Secondary,
                    )
                },
                bottomContent = {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Issue Form Bottom Haze Save Bar $WEB_SSOT_CREATE_ISSUE $WEB_SSOT_CREATE_ISSUE_DIALOG $WEB_SSOT_ISSUE_PROPERTY_PICKER" }
                            .padding(horizontal = 16.dp, vertical = 12.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        MulticaPillButton(
                            text = if (zh) "取消" else "Cancel",
                            onClick = onCancel,
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Secondary,
                        )
                        MulticaPillButton(
                            text = if (saving) "..." else if (editing) {
                                if (zh) "保存" else "Save"
                            } else {
                                if (zh) "创建" else "Create"
                            },
                            onClick = { saveIssue() },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Primary,
                        )
                    }
                },
            ) {
                if (!saveError.isNullOrBlank()) {
                    item {
                        PilotInlineResultState(
                            message = saveError.orEmpty(),
                            isError = true,
                            contentDescription = "Issue Form Save Result Web Banner",
                        )
                    }
                }
                if (!parentIssueId.isNullOrBlank()) {
                    item {
                        Surface(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = "Issue Form Parent Context Capsule" },
                            shape = RoundedCornerShape(999.dp),
                            color = MulticaColors.AccentSoft,
                            tonalElevation = 0.dp,
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Icon(
                                    imageVector = Icons.Outlined.ArrowUpward,
                                    contentDescription = null,
                                    tint = MulticaColors.Accent,
                                    modifier = Modifier.size(16.dp),
                                )
                                Text(
                                    text = if (zh) {
                                        "子 Issue of ${parentIssueIdentifier ?: Models.shortId(parentIssueId)}"
                                    } else {
                                        "Sub-issue of ${parentIssueIdentifier ?: Models.shortId(parentIssueId)}"
                                    },
                                    style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.Accent,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                    }
                }
                item {
                    MulticaTextField(
                        value = title,
                        onValueChange = { title = it },
                        label = if (zh) "标题" else "Title",
                        contentDescription = "Issue Form Title Field",
                        singleLine = true,
                    )
                }
                item {
                    MulticaTextField(
                        value = description,
                        onValueChange = { description = it },
                        label = if (zh) "描述" else "Description",
                        contentDescription = "Issue Form Description Field",
                        minLines = 4,
                        maxLines = 8,
                    )
                }
                item {
                    IssueFormAttachmentPickerPanel(
                        attachments = pendingIssueAttachments,
                        zh = zh,
                        onPickFile = { fileAttachmentLauncher.launch("*/*") },
                        onPickImage = { imageAttachmentLauncher.launch("image/*") },
                        onRemove = { removeIndex ->
                            pendingIssueAttachments = pendingIssueAttachments.filterIndexed { index, _ -> index != removeIndex }
                        },
                    )
                }
                item {
                    SectionHeader(if (zh) "详情" else "Details")
                }
                item {
                    IssueFormDetailsWebPanel(
                        modifier = Modifier.semantics { contentDescription = "Issue Form Details Web Panel" },
                    ) {
                        IssueFormMenuRow(
                            eyebrow = if (zh) "项目" else "Project",
                            title = if (projectIndex == 0) {
                                if (zh) "不关联项目" else "No project"
                            } else {
                                options.projects[projectIndex - 1].name
                            },
                            subtitle = null,
                            contentDescription = "Issue Form Project",
                            options = listOf(
                                IssueFormMenuOption(
                                    label = if (zh) "不关联项目" else "No project",
                                    selected = projectIndex == 0,
                                    onClick = { projectIndex = 0 },
                                )
                            ) + options.projects.mapIndexed { index, project ->
                                IssueFormMenuOption(
                                    label = project.name,
                                    selected = projectIndex == index + 1,
                                    onClick = { projectIndex = index + 1 },
                                )
                            },
                        )
                        IssueFormMenuRow(
                            eyebrow = if (zh) "负责人" else "Assignee",
                            title = assignees[assigneeIndex].name,
                            subtitle = null,
                            contentDescription = "Issue Form Assignee",
                            options = assignees.mapIndexed { index, assignee ->
                                IssueFormMenuOption(
                                    label = assignee.name,
                                    selected = assigneeIndex == index,
                                    onClick = { assigneeIndex = index },
                                )
                            },
                        )
                        IssueFormMenuRow(
                            eyebrow = if (zh) "优先级" else "Priority",
                            title = Models.priorityLabel(Models.PRIORITY_VALUES[priorityIndex], zh),
                            subtitle = null,
                            contentDescription = "Issue Form Priority",
                            options = Models.PRIORITY_VALUES.mapIndexed { index, priority ->
                                IssueFormMenuOption(
                                    label = Models.priorityLabel(priority, zh),
                                    selected = priorityIndex == index,
                                    onClick = { priorityIndex = index },
                                )
                            },
                        )
                        IssueFormMenuRow(
                            eyebrow = if (zh) "状态" else "Status",
                            title = Models.statusLabel(Models.STATUS_VALUES[statusIndex], zh),
                            subtitle = null,
                            contentDescription = "Issue Form Status",
                            options = Models.STATUS_VALUES.mapIndexed { index, status ->
                                IssueFormMenuOption(
                                    label = Models.statusLabel(status, zh),
                                    selected = statusIndex == index,
                                    onClick = { statusIndex = index },
                                )
                            },
                        )
                        IssueFormWebRow(
                            eyebrow = if (zh) "标签" else "Labels",
                            title = issue?.labels?.takeIf { it.isNotEmpty() }?.joinToString(", ") { it.name }
                                ?: if (zh) "不设置标签" else "No labels",
                            subtitle = if (zh) "标签选择器稍后接入" else "Label picker coming soon",
                            contentDescription = "Issue Form Labels Web Row",
                            trailingIcon = Icons.Outlined.Label,
                        )
                        IssueFormWebRow(
                            eyebrow = if (zh) "截止日期" else "Due Date",
                            title = if (dueDateEnabled) shortDate(dueDate) else if (zh) "不设置截止日期" else "No due date",
                            subtitle = if (dueDateEnabled) dueDate else null,
                            contentDescription = "Issue Form Due Date Toggle Issue Form Due Date Web Row",
                            onClick = {
                                dueDateEnabled = !dueDateEnabled
                                if (dueDateEnabled) ensureDueDateValue()
                            },
                            trailingIcon = Icons.Outlined.KeyboardArrowRight,
                        )
                        if (dueDateEnabled) {
                            Column(
                                modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp),
                            ) {
                                Row(horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth()) {
                                    MulticaPillButton(
                                        text = if (zh) "选择日期" else "Select Date",
                                        onClick = {
                                            ensureDueDateValue()
                                            showDueDatePicker = true
                                        },
                                        modifier = Modifier.weight(1f),
                                        tone = MulticaButtonTone.Secondary,
                                    )
                                    MulticaPillButton(
                                        text = if (zh) "清除" else "Clear",
                                        onClick = {
                                            dueDateEnabled = false
                                            dueDate = ""
                                        },
                                        modifier = Modifier.weight(1f),
                                        tone = MulticaButtonTone.Ghost,
                                    )
                                }
                                MulticaTextField(
                                    value = dueDate,
                                    onValueChange = {
                                        dueDate = it
                                        dueDateEnabled = it.isNotBlank()
                                    },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .semantics { contentDescription = "Issue Form Web Due Date Field" },
                                    label = if (zh) "截止日期值" else "Due date value",
                                    contentDescription = "Issue Form Due Date Value",
                                    singleLine = true,
                                )
                            }
                        }
                    }
                }
                if (!editing) {
                    item {
                        SectionHeader(if (zh) "使用 Agent 创建" else "Create with Agent")
                    }
                    item {
                        IssueFormAgentCreatePanel(
                            agents = agentCreateOptions,
                            selectedAgent = selectedCreateAgent,
                            selectedAgentIndex = agentCreateIndex,
                            prompt = agentCreatePrompt,
                            agentCreateResult = agentCreateResult,
                            submitting = agentCreateSubmitting,
                            zh = zh,
                            onAgentSelected = {
                                agentCreateIndex = it
                                agentCreateResult = null
                            },
                            onPromptChange = {
                                agentCreatePrompt = it
                                agentCreateResult = null
                            },
                            onSend = {
                                val agent = selectedCreateAgent
                                val promptText = agentCreatePromptText()
                                if (agent == null || promptText.isBlank() || agentCreateSubmitting) {
                                    agentCreateResult = if (zh) "请选择 Agent，并填写标题、描述或提示词" else "Select an agent and enter a title, description, or prompt"
                                    return@IssueFormAgentCreatePanel
                                }
                                agentCreateSubmitting = true
                                agentCreateResult = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) {
                                        runCatching { api.quickCreateIssue(session.workspace.id, agent.id, promptText) }
                                    }
                                    agentCreateSubmitting = false
                                    result.onSuccess {
                                        agentCreatePrompt = ""
                                        agentCreateResult = if (zh) "已创建任务 ${it.taskId}" else "Task created ${it.taskId}"
                                    }.onFailure {
                                        agentCreateResult = "${if (zh) "发送给 Agent 失败" else "Send to Agent failed"}: ${it.message ?: it.toString()}"
                                    }
                                }
                            },
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun IssueFormAttachmentPickerPanel(
    attachments: List<PickedIssueAttachment>,
    zh: Boolean,
    onPickFile: () -> Unit,
    onPickImage: () -> Unit,
    onRemove: (Int) -> Unit,
) {
    CompactInfoPanel(
        modifier = Modifier.semantics(mergeDescendants = false) {
            contentDescription = "Issue Form Image And File Attachment Picker"
        },
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    text = if (zh) "附件" else "Attachments",
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = MulticaTypeScale.SectionTitle, lineHeight = 19.sp, fontWeight = FontWeight.SemiBold),
                    color = MulticaColors.Text,
                    maxLines = 1,
                )
                Text(
                    text = if (zh) "支持从相册选择图片，也保留通用文件上传" else "Pick images from Photos or attach any file",
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                    color = MulticaColors.Muted,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            MulticaPillButton(
                text = if (zh) "图片" else "Image",
                onClick = onPickImage,
                tone = MulticaButtonTone.Secondary,
                contentDescription = "Issue Form Pick Image",
            )
            MulticaPillButton(
                text = if (zh) "文件" else "File",
                onClick = onPickFile,
                tone = MulticaButtonTone.Ghost,
                contentDescription = "Issue Form Pick File",
            )
        }
        if (attachments.isEmpty()) {
            CompactIssueRow(
                eyebrow = if (zh) "待上传" else "Pending",
                title = if (zh) "尚未选择附件" else "No attachments selected",
            )
        } else {
            attachments.forEachIndexed { index, attachment ->
                CompactIssueRow(
                    eyebrow = if (attachment.image) if (zh) "图片" else "Image" else if (zh) "文件" else "File",
                    title = attachment.filename,
                    trailing = attachment.contentType,
                    showDivider = index < attachments.lastIndex,
                    contentDescription = "Issue Form Pending Attachment ${attachment.filename}",
                    onClick = { onRemove(index) },
                )
            }
        }
    }
}

@Composable
private fun IssueDetailWebPropertyPill(
    text: String,
    icon: ImageVector,
    selected: Boolean,
    enabled: Boolean,
    contentDescription: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val haptic = LocalHapticFeedback.current
    val shape = RoundedCornerShape(10.dp)
    Surface(
        modifier = modifier
            .heightIn(min = 32.dp)
            .widthIn(min = 86.dp)
            .clip(shape)
            .clickable(enabled = enabled) {
                haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                onClick()
            }
            .semantics(mergeDescendants = true) {
                this.contentDescription = "$contentDescription Issue Detail Web Property Pill"
            },
        shape = shape,
        color = when {
            !enabled -> MulticaColors.Surface
            selected -> MulticaColors.AccentSoft
            else -> MulticaColors.SurfaceElevated
        },
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .border(
                    width = 1.dp,
                    color = if (selected) MulticaColors.Accent.copy(alpha = 0.24f) else MulticaColors.Border,
                    shape = shape,
                )
                .padding(horizontal = 9.dp, vertical = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center,
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = when {
                    !enabled -> MulticaColors.Muted.copy(alpha = 0.54f)
                    selected -> MulticaColors.Accent
                    else -> MulticaColors.Muted
                },
                modifier = Modifier.size(14.dp),
            )
            Spacer(modifier = Modifier.width(6.dp))
            Text(
                text = text,
                style = MaterialTheme.typography.bodySmall.copy(
                    fontSize = 13.sp,
                    lineHeight = 17.sp,
                    fontWeight = FontWeight.SemiBold,
                ),
                color = if (enabled) MulticaColors.TextPrimary else MulticaColors.Muted,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.semantics { this.contentDescription = "Issue Detail Web Property Text" },
            )
        }
    }
}

@Composable
private fun IssueFormAgentCreatePanel(
    agents: List<Models.Agent>,
    selectedAgent: Models.Agent?,
    selectedAgentIndex: Int,
    prompt: String,
    agentCreateResult: String?,
    submitting: Boolean,
    zh: Boolean,
    onAgentSelected: (Int) -> Unit,
    onPromptChange: (String) -> Unit,
    onSend: () -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Issue Form Web Agent Panel" },
        shape = RoundedCornerShape(12.dp),
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.66f), RoundedCornerShape(12.dp))
                .padding(horizontal = 12.dp, vertical = 11.dp),
            verticalArrangement = Arrangement.spacedBy(11.dp),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Box(
                    modifier = Modifier
                        .size(34.dp)
                        .clip(RoundedCornerShape(9.dp))
                        .background(MulticaColors.AccentSoft.copy(alpha = 0.58f)),
                    contentAlignment = Alignment.Center,
                ) {
                    Icon(Icons.AutoMirrored.Outlined.Send, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(17.dp))
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        if (zh) "切换到 Agent 创建" else "Switch to agent create",
                        style = MaterialTheme.typography.titleSmall.copy(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                    )
                    Text(
                        if (zh) "沿用上方标题/描述，也可补充 Agent 提示词。" else "Use the title/description above, or add an agent prompt.",
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                        color = MulticaColors.Muted,
                    )
                }
            }
            QuickCreateAgentPickerRow(
                agents = agents,
                selectedAgent = selectedAgent,
                zh = zh,
                onSelect = onAgentSelected,
            )
            MulticaTextField(
                value = prompt,
                onValueChange = onPromptChange,
                label = if (zh) "Agent 提示词" else "Agent prompt",
                contentDescription = "Issue Form Agent Prompt Field",
                minLines = 3,
                maxLines = 6,
            )
            if (!agentCreateResult.isNullOrBlank()) {
                val isError = agentCreateResult.contains("failed", true) ||
                    agentCreateResult.contains("失败") ||
                    agentCreateResult.contains("请选择")
                if (isError) {
                    PilotInlineResultState(
                        message = agentCreateResult,
                        isError = true,
                        contentDescription = "Issue Form Agent Result Web Banner",
                    )
                } else {
                    MulticaSuccessState(agentCreateResult.orEmpty())
                }
            }
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .border(1.dp, MulticaColors.Border.copy(alpha = 0.45f), RoundedCornerShape(10.dp))
                    .padding(horizontal = 10.dp, vertical = 9.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    selectedAgent?.name?.let {
                        if (zh) "将发送给 $it" else "Will send to $it"
                    } ?: if (zh) "请选择 Agent" else "Select an agent",
                    modifier = Modifier.weight(1f),
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                    color = MulticaColors.Muted,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
                MulticaPillButton(
                    text = if (submitting) "..." else if (zh) "发送" else "Send",
                    icon = Icons.AutoMirrored.Outlined.Send,
                    contentDescription = "Issue Form Send to Agent",
                    onClick = onSend,
                    tone = MulticaButtonTone.Primary,
                )
            }
        }
    }
}

@Composable
private fun IssueDetailStatusMenu(
