@Composable
private fun CompactIssueRow(
    eyebrow: String,
    title: String,
    trailing: String? = null,
    showDivider: Boolean = false,
    contentDescription: String? = null,
    onClick: (() -> Unit)? = null,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .then(if (onClick == null) Modifier else Modifier.clickable(onClick = onClick))
            .then(if (contentDescription == null) Modifier else Modifier.semantics(mergeDescendants = true) {
                this.contentDescription = contentDescription
                if (onClick != null) {
                    semanticsOnClick(label = title) {
                        onClick()
                        true
                    }
                }
            }),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = MulticaVisualTokens.RowMinHeight)
                .padding(vertical = 8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Text(
                    text = eyebrow,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = MulticaTypeScale.Meta, lineHeight = 13.sp),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodySmall.copy(
                        fontSize = MulticaTypeScale.RowTitle,
                        lineHeight = 19.sp,
                        fontWeight = FontWeight.Medium,
                    ),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            if (!trailing.isNullOrBlank()) {
                Text(
                    text = trailing,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = MulticaTypeScale.Caption, lineHeight = 15.sp),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            if (onClick != null) {
                Icon(
                    imageVector = Icons.Outlined.KeyboardArrowRight,
                    contentDescription = null,
                    tint = MulticaColors.Muted,
                    modifier = Modifier.size(16.dp),
                )
            }
        }
        if (showDivider) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border)
            )
        }
    }
}

@Composable
private fun CompactUsageMetric(
    label: String,
    value: String,
    modifier: Modifier = Modifier,
) {
