@Composable
private fun IssueDetailSubIssuesCompactList(
    children: List<Models.Issue>,
    zh: Boolean,
    onOpenIssue: (String) -> Unit,
    onCreateChildIssue: () -> Unit,
) {
    val doneChildren = children.count { it.status == "done" }
    var subIssuesExpanded by remember(children.joinToString("|") { it.id }) { mutableStateOf(false) }
    CompactInfoPanel(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = false) { contentDescription = "Issue Sub Issues Integrated Panel" },
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                text = if (zh) "子 Issue" else "Sub-issues",
                style = MaterialTheme.typography.labelMedium.copy(
                    fontSize = MulticaTypeScale.SectionTitle,
                    lineHeight = 19.sp,
                    fontWeight = FontWeight.SemiBold,
                ),
                color = MulticaColors.Muted,
                modifier = Modifier.weight(1f),
            )
            Text(
                text = if (zh) "$doneChildren/${children.size} 完成" else "$doneChildren/${children.size} done",
                style = MaterialTheme.typography.labelSmall.copy(fontSize = MulticaTypeScale.DetailMeta, lineHeight = 16.sp, fontWeight = FontWeight.SemiBold),
                color = MulticaColors.Muted,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = "Issue Sub Issues Header Create Child Button",
                onClick = onCreateChildIssue,
                tone = MulticaButtonTone.Primary,
                modifier = Modifier
                    .size(44.dp)
                    .semantics { contentDescription = "Issue Sub Issues Header Create Child Button" },
            )
        }
        if (children.isEmpty()) {
            CompactIssueRow(
                eyebrow = if (zh) "空列表" else "Empty",
                title = if (zh) "暂无子 Issue" else "No sub-issues",
            )
        } else {
            val visibleChildren = if (subIssuesExpanded) children else children.take(4)
            visibleChildren.forEachIndexed { index, child ->
                CompactIssueRow(
                    eyebrow = listOf(child.identifier, Models.statusLabel(child.status, zh)).joinToString(" · "),
                    title = child.title,
                    trailing = if (child.assigneeType == "agent") "Agent" else null,
                    showDivider = index < visibleChildren.lastIndex || children.size > visibleChildren.size,
                    contentDescription = "Issue Detail Child ${child.id}",
                    onClick = { onOpenIssue(child.id) },
                )
            }
            if (!subIssuesExpanded && children.size > visibleChildren.size) {
                MulticaPillButton(
                    text = if (zh) "展开全部 ${children.size} 个子 Issue" else "Show all ${children.size} sub-issues",
                    onClick = { subIssuesExpanded = true },
                    tone = MulticaButtonTone.Secondary,
                    modifier = Modifier.fillMaxWidth(),
                    contentDescription = "Issue Sub Issues Show More",
                )
            } else if (subIssuesExpanded && children.size > 4) {
                MulticaPillButton(
                    text = if (zh) "收起子 Issue" else "Collapse sub-issues",
                    onClick = { subIssuesExpanded = false },
                    tone = MulticaButtonTone.Ghost,
                    modifier = Modifier.fillMaxWidth(),
                    contentDescription = "Issue Sub Issues Collapse",
                )
            }
        }
    }
}

@Composable
private fun IssueDetailSubscribersCompact(
    subscribers: List<Models.IssueSubscriber>,
    members: List<Models.Member>,
    agents: List<Models.Agent>,
    currentUser: Models.User,
    mutating: Boolean,
    zh: Boolean,
    onToggleSelf: (Boolean) -> Unit,
) {
    val currentMemberSubscribed = subscribers.any { it.userType == "member" && it.userId == currentUser.id }
    val subscriberNames = subscribers.take(5).joinToString(" · ") {
        Models.issueSubscriberDisplayName(it, members, agents, currentUser)
    }
    CompactInfoPanel {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 1.dp),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    text = if (subscribers.isEmpty()) {
                        if (zh) "暂无订阅者" else "No subscribers"
                    } else {
                        if (zh) "${subscribers.size} 个订阅者" else "${subscribers.size} subscribers"
                    },
                    style = MaterialTheme.typography.labelMedium.copy(
                        fontSize = 12.sp,
                        lineHeight = 14.sp,
                        fontWeight = FontWeight.SemiBold,
                    ),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = if (subscribers.isEmpty()) {
                        if (zh) "点右侧小按钮订阅" else "Use the small action to subscribe"
                    } else {
                        subscriberNames
                    },
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
                    color = MulticaColors.Muted,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            MulticaIconPillButton(
                icon = if (currentMemberSubscribed) Icons.Outlined.CheckCircle else Icons.Outlined.Add,
                contentDescription = "Issue Detail Subscriber Compact Action",
                onClick = { onToggleSelf(currentMemberSubscribed) },
                enabled = !mutating,
                tone = if (currentMemberSubscribed) MulticaButtonTone.Primary else MulticaButtonTone.Secondary,
                modifier = Modifier
                    .size(36.dp)
                    .semantics { contentDescription = "Issue Detail Subscriber Compact Action" },
            )
        }
    }
}

@Composable
private fun IssueDetailUsageCompact(usage: Models.IssueUsage?, zh: Boolean) {
    CompactInfoPanel(
        modifier = Modifier.semantics(mergeDescendants = false) {
            contentDescription = "Issue Detail Compact Usage"
        },
    ) {
        if (usage == null) {
            CompactIssueRow(
                eyebrow = "Usage",
                title = if (zh) "用量暂不可用" else "Usage unavailable",
                contentDescription = "Issue Usage Unavailable",
            )
        } else if (usage.taskCount <= 0) {
            CompactIssueRow(
                eyebrow = "Usage",
                title = if (zh) "暂无用量" else "No usage yet",
                contentDescription = "Issue Usage Empty State",
            )
        } else {
            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                CompactUsageMetric(
                    label = if (zh) "总 Tokens" else "Tokens",
                    value = usage.totalTokens().toString(),
                    modifier = Modifier
                        .weight(1f)
                        .semantics { contentDescription = "Issue Usage Tokens" },
                )
                CompactUsageMetric(
                    label = if (zh) "运行次数" else "Runs",
                    value = usage.taskCount.toString(),
                    modifier = Modifier.weight(1f),
                )
            }
            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                CompactUsageMetric(
                    label = if (zh) "输入" else "Input",
                    value = usage.inputTokens.toString(),
                    modifier = Modifier.weight(1f),
                )
                CompactUsageMetric(
                    label = if (zh) "输出" else "Output",
                    value = usage.outputTokens.toString(),
                    modifier = Modifier.weight(1f),
                )
            }
            if (usage.cacheReadTokens > 0 || usage.cacheWriteTokens > 0) {
                CompactIssueRow(
                    eyebrow = if (zh) "缓存" else "Cache",
                    title = if (zh) {
                        "读 ${usage.cacheReadTokens} · 写 ${usage.cacheWriteTokens}"
                    } else {
                        "read ${usage.cacheReadTokens} · write ${usage.cacheWriteTokens}"
                    },
                )
            }
        }
    }
}

