@Composable
private fun MulticaRemoteAvatarImage(
    avatarUrl: String,
    size: Dp,
    shape: RoundedCornerShape = RoundedCornerShape(999.dp),
    contentDescription: String? = null,
) {
    if (avatarUrl.isNotBlank()) {
        val context = LocalContext.current
        val cookieHeader = remember(context) { AuthStore(context.applicationContext).cloudFrontCookieHeader() }
        val imageRequest = remember(context, avatarUrl, cookieHeader) {
            ImageRequest.Builder(context)
                .data(avatarUrl)
                .crossfade(true)
                .apply {
                    if (cookieHeader.isNotBlank() && avatarUrl.contains("static.multica.ai")) {
                        addHeader("Cookie", cookieHeader)
                    }
                }
                .build()
        }
        AsyncImage(
            model = imageRequest,
            contentDescription = contentDescription,
            contentScale = ContentScale.Crop,
            modifier = Modifier
                .size(size)
                .clip(shape),
        )
    }
}

@Composable
private fun IssueActorAvatar(
    actorName: String,
    avatarUrl: String,
    actorType: String,
    agentStatus: String?,
    modifier: Modifier = Modifier,
    size: Dp = MulticaVisualTokens.AvatarMedium,
) {
    val isAgent = actorType == "agent"
    val initials = actorInitials(actorName, actorType)
    Box(
        modifier = modifier.size(size),
        contentAlignment = Alignment.Center,
    ) {
        Box(
            modifier = Modifier
                .size(size)
                .clip(RoundedCornerShape(999.dp))
                .background(if (isAgent) MulticaColors.Accent.copy(alpha = 0.13f) else MulticaColors.SurfaceElevated)
                .border(0.75.dp, MulticaColors.Border.copy(alpha = 0.68f), RoundedCornerShape(999.dp)),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = initials,
                style = MaterialTheme.typography.labelMedium.copy(
                    fontSize = MulticaTypeScale.AvatarInitials,
                    lineHeight = 14.sp,
                    fontWeight = FontWeight.SemiBold,
                ),
                color = if (isAgent) MulticaColors.Accent else MulticaColors.Text,
                maxLines = 1,
            )
            MulticaRemoteAvatarImage(
                avatarUrl = avatarUrl,
                size = size,
                contentDescription = if (isAgent) "Agent Remote Avatar" else "Member Remote Avatar",
            )
        }
        if (isAgent) {
            val dotColor = when (agentStatus.orEmpty().lowercase()) {
                "online", "running", "active", "available", "ready" -> MulticaColors.Success
                "busy", "working" -> MulticaColors.Accent
                "paused", "archived", "offline" -> MulticaColors.Muted
                else -> MulticaColors.Accent
            }
            Box(
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .size(8.dp)
                    .clip(RoundedCornerShape(999.dp))
                    .background(dotColor)
                    .border(1.dp, MulticaColors.Surface, RoundedCornerShape(999.dp)),
            )
        }
    }
}

private fun actorInitials(actorName: String, actorType: String): String {
    val cleaned = actorName.trim()
    if (cleaned.isEmpty()) return if (actorType == "agent") "A" else "M"
    val parts = cleaned.split(Regex("\\s+")).filter { it.isNotBlank() }
    val initials = if (parts.size >= 2) {
        "${parts[0].first()}${parts[1].first()}"
    } else {
        cleaned.take(2)
    }
    return initials.uppercase(Locale.getDefault())
}

private fun commentAuthorAgentStatus(comment: Models.Comment, agents: List<Models.Agent>): String? {
    if (comment.authorType != "agent") return null
    return agents.firstOrNull { it.id == comment.authorId }?.status
}

@Composable
private fun IssueCommentCard(
    comment: Models.Comment,
    authorName: String,
    authorAvatarUrl: String = "",
    authorAgentStatus: String? = null,
    expandedActions: Boolean,
    contentExpanded: Boolean,
    highlighted: Boolean,
    zh: Boolean,
    onToggleActions: () -> Unit,
    onToggleContent: () -> Unit,
    onReplyAction: () -> Unit,
    onEditAction: () -> Unit,
    onDeleteAction: () -> Unit,
) {
    val content = clean(comment.content)
    val collapseContent = shouldCollapseIssueComment(content)
    val renderedContent = if (collapseContent && !contentExpanded) {
        issueCommentPreview(comment.content)
    } else {
        comment.content
    }
    val shape = RoundedCornerShape(MulticaVisualTokens.CardRadius)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 10.dp)
            .semantics(mergeDescendants = false) {
                contentDescription = if (highlighted) {
                    "Issue Comment Web Highlighted ${comment.id}"
                } else {
                    "Issue Comment Web Thread Row ${comment.id}"
                }
            },
        shape = shape,
        color = MulticaColors.Surface.copy(alpha = if (highlighted) 0.88f else 0.74f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        border = androidx.compose.foundation.BorderStroke(
            width = if (highlighted) 1.dp else 0.75.dp,
            color = if (highlighted) MulticaColors.Border.copy(alpha = 0.86f) else MulticaColors.Border.copy(alpha = 0.52f),
        ),
    ) {
        Column(
            modifier = Modifier.padding(horizontal = 14.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(9.dp),
                verticalAlignment = Alignment.Top,
            ) {
                IssueActorAvatar(
                    actorName = authorName.ifBlank { comment.authorType },
                    avatarUrl = authorAvatarUrl,
                    actorType = comment.authorType,
                    agentStatus = authorAgentStatus,
                    modifier = Modifier.semantics { contentDescription = "Issue Comment Actor Avatar ${comment.id}" },
                )
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(7.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            text = authorName.ifBlank { if (zh) "评论者" else "Commenter" },
                            style = MaterialTheme.typography.labelLarge.copy(
                                fontWeight = FontWeight.SemiBold,
                                fontSize = MulticaTypeScale.RowTitle,
                                lineHeight = 19.sp,
                            ),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f, fill = false),
                        )
                        Text(
                            text = shortDate(comment.createdAt),
                            style = MaterialTheme.typography.labelSmall.copy(fontSize = MulticaTypeScale.Caption, lineHeight = 15.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    if (content.isBlank()) {
                        Text(
                            text = if (zh) "空评论" else "Empty comment",
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = MulticaTypeScale.Body, lineHeight = 20.sp),
                            color = MulticaColors.Muted,
                        )
                    } else {
                        MarkdownBlock(renderedContent)
                        if (collapseContent) {
                            MulticaPillButton(
                                text = if (contentExpanded) {
                                    if (zh) "收起" else "Collapse"
                                } else {
                                    if (zh) "展开" else "Expand"
                                },
                                onClick = onToggleContent,
                                modifier = Modifier.heightIn(min = 30.dp),
                                tone = MulticaButtonTone.Ghost,
                            )
                        }
                    }
                }
                IssueCommentWebActionsMenu(
                    commentId = comment.id,
                    expanded = expandedActions,
                    zh = zh,
                    onToggle = onToggleActions,
                    onReply = onReplyAction,
                    onEdit = onEditAction,
                    onDelete = onDeleteAction,
                ) {
                }
            }
        }
    }
}

