private fun shouldCollapseIssueComment(content: String): Boolean {
    if (content.contains("```")) return false
    if (content.lines().any { it.trim().startsWith("|") && it.trim().endsWith("|") }) return false
    if (content.length > 420) return true
    return content.count { it == '\n' } > 6
}

private fun issueCommentPreview(markdown: String): String {
    val lineLimited = markdown
        .lines()
        .take(6)
        .joinToString("\n")
        .trimEnd()
    val charLimited = if (lineLimited.length > 420) lineLimited.take(420).trimEnd() else lineLimited
    return "$charLimited\n\n..."
}

@Composable
private fun PilotIssueDetail(
    api: ApiClient,
    workspaceId: String,
    workspaceSlug: String,
    issueId: String,
    currentUser: Models.User,
    zh: Boolean,
    onBack: () -> Unit,
    onOpenIssue: (String) -> Unit,
    onEditIssue: (Models.Issue) -> Unit,
    onCreateChildIssue: (Models.Issue) -> Unit,
    onDeleted: () -> Unit,
    highlightCommentId: String? = null,
    inboxItemId: String? = null,
    inboxNextIssueId: String? = null,
    onInboxDone: ((String?) -> Unit)? = null,
) {
    var state by remember(issueId) { mutableStateOf<Result<PilotIssueDetailData>?>(null) }
    var detailRefresh by remember(issueId) { mutableIntStateOf(0) }
    var showRuns by remember(issueId) { mutableStateOf(false) }
    var selectedRun by remember(issueId) { mutableStateOf<Models.AgentTask?>(null) }
    var editingCommentId by remember(issueId) { mutableStateOf<String?>(null) }
    var editingCommentContent by remember(issueId) { mutableStateOf("") }
    var pendingDeleteComment by remember(issueId) { mutableStateOf<Models.Comment?>(null) }
    var replyingCommentId by remember(issueId) { mutableStateOf<String?>(null) }
    var replyDraft by remember(issueId) { mutableStateOf("") }
    var pendingReplyAttachments by remember(issueId) { mutableStateOf<List<Models.Attachment>>(emptyList()) }
    var uploadingReplyAttachment by remember(issueId) { mutableStateOf(false) }
    var sendingReply by remember(issueId) { mutableStateOf(false) }
    var replyMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var mutatingComment by remember(issueId) { mutableStateOf(false) }
    var commentMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var expandedCommentActionsId by remember(issueId) { mutableStateOf<String?>(null) }
    var expandedCommentContentIds by remember(issueId) { mutableStateOf<Set<String>>(emptySet()) }
    var showExpandedCommentHistory by remember(issueId) { mutableStateOf(false) }
    var commentsDescending by remember(issueId) { mutableStateOf(true) }
    var mutatingSubscriber by remember(issueId) { mutableStateOf(false) }
    var subscriberMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var uploadingAttachment by remember(issueId) { mutableStateOf(false) }
    var deletingAttachmentId by remember(issueId) { mutableStateOf<String?>(null) }
    var attachmentMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var confirmingDeleteIssue by remember(issueId) { mutableStateOf(false) }
    var deletingIssue by remember(issueId) { mutableStateOf(false) }
    var issueMutationMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var updatingIssueField by remember(issueId) { mutableStateOf<String?>(null) }
    var copyLinkMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var issueMoreMenuOpen by remember(issueId) { mutableStateOf(false) }
    var newCommentDraft by remember(issueId) { mutableStateOf("") }
    var pendingCommentAttachments by remember(issueId) { mutableStateOf<List<Models.Attachment>>(emptyList()) }
    var uploadingCommentAttachment by remember(issueId) { mutableStateOf(false) }
    var sendingNewComment by remember(issueId) { mutableStateOf(false) }
    var newCommentMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var olderTimelineEntries by remember(issueId) { mutableStateOf<List<Models.TimelineEntry>>(emptyList()) }
    var timelineNextCursor by remember(issueId) { mutableStateOf("") }
    var timelineHasMoreBefore by remember(issueId) { mutableStateOf(false) }
    var timelineInitialized by remember(issueId) { mutableStateOf(false) }
    var loadingOlderTimeline by remember(issueId) { mutableStateOf(false) }
    var timelineMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var cancellingIssueTaskId by remember(issueId) { mutableStateOf<String?>(null) }
    var pendingTerminateTask by remember(issueId) { mutableStateOf<Models.AgentTask?>(null) }
    var issueTaskMessage by remember(issueId) { mutableStateOf<String?>(null) }
    var showPullRequestsSection by remember(issueId) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    val activeRun = selectedRun
    if (activeRun != null) {
        PilotAgentTranscript(
            api = api,
            workspaceId = workspaceId,
            run = activeRun,
            zh = zh,
            onBack = { selectedRun = null },
        )
        return
    }

    LaunchedEffect(issueId, workspaceId, highlightCommentId, detailRefresh) {
        state = null
        val coreResult = withContext(Dispatchers.IO) {
            runCatching {
                IssueDetailLoader.load(issueId, workspaceId, object : IssueDetailLoader.Fetcher {
                    override fun issue(requestedIssueId: String, requestedWorkspaceId: String): Models.Issue {
                        return api.issue(requestedIssueId, requestedWorkspaceId)
                    }

                    override fun comments(requestedIssueId: String, requestedWorkspaceId: String): List<Models.Comment> {
                        return api.comments(requestedIssueId, requestedWorkspaceId, 100, 0).items
                    }

                    override fun runs(requestedIssueId: String, requestedWorkspaceId: String): List<Models.AgentTask> {
                        return api.agentRuns(requestedIssueId, requestedWorkspaceId)
                    }

                    override fun projects(): List<Models.Project> = emptyList()

                    override fun members(): List<Models.Member> = api.members(workspaceId)

                    override fun agents(): List<Models.Agent> = api.agents(workspaceId)
                }, 5)
            }
        }
        val core = coreResult.getOrElse { error ->
            state = Result.failure(error)
            return@LaunchedEffect
        }
        val initialData = PilotIssueDetailData(
            core.issue,
            core.comments,
            core.runs,
            core.members,
            core.agents,
            issueLabels = emptyList(),
            allLabels = emptyList(),
            subscribers = emptyList(),
            attachments = emptyList(),
            children = emptyList(),
            usage = null,
            timeline = null,
            activeTasks = emptyList(),
        )
        state = Result.success(initialData)
        val secondaryData = withContext(Dispatchers.IO) {
            val issueLabels = runCatching { api.issueLabels(workspaceId, issueId) }.getOrElse { emptyList() }
            val allLabels = runCatching { api.labels(workspaceId) }.getOrElse { emptyList() }
            val subscribers = runCatching { api.issueSubscribers(workspaceId, issueId) }.getOrElse { emptyList() }
            val attachments = runCatching { api.issueAttachments(workspaceId, issueId) }.getOrElse { emptyList() }
            val children = runCatching { api.childIssues(workspaceId, issueId) }.getOrElse { emptyList() }
            val usage = runCatching { api.issueUsage(workspaceId, issueId) }.getOrNull()
            val timelineAnchor = highlightCommentId ?: core.comments.lastOrNull()?.id
            val timeline = runCatching { api.issueTimeline(workspaceId, issueId, 10, null, null, timelineAnchor) }.getOrNull()
            val activeTasks = runCatching { api.activeIssueTasks(workspaceId, issueId) }.getOrElse { emptyList() }
            initialData.copy(
                issueLabels = issueLabels,
                allLabels = allLabels,
                subscribers = subscribers,
                attachments = attachments,
                children = children,
                usage = usage,
                timeline = timeline,
                activeTasks = activeTasks,
            )
        }
        state = Result.success(secondaryData)
    }

    val loaded = state
    when {
        loaded == null -> MulticaLoadingState(if (zh) "正在加载详情..." else "Loading issue...")
        loaded.isFailure -> MulticaErrorState(
            message = "${if (zh) "加载失败" else "Load failed"}\n${loaded.exceptionOrNull()?.message.orEmpty()}",
            onRetry = { detailRefresh++ },
        )
        else -> {
            val data = loaded.getOrThrow()
            LaunchedEffect(issueId, workspaceId, data.issue.id) {
                while (true) {
                    delay(2500)
                    val activeTasks = withContext(Dispatchers.IO) {
                        runCatching { api.activeIssueTasks(workspaceId, issueId) }.getOrNull()
                    } ?: continue
                    state = state?.map { current -> current.copy(activeTasks = activeTasks) }
                }
            }
            LaunchedEffect(data.timeline) {
                val timeline = data.timeline ?: return@LaunchedEffect
                if (!timelineInitialized) {
                    timelineNextCursor = timeline.nextCursor
                    timelineHasMoreBefore = timeline.hasMoreBefore
                    timelineInitialized = true
                }
            }

            fun loadOlderTimeline() {
                val cursor = timelineNextCursor
                if (cursor.isBlank() || loadingOlderTimeline) return
                loadingOlderTimeline = true
                timelineMessage = null
                scope.launch {
                    val result = withContext(Dispatchers.IO) {
                        runCatching { api.issueTimeline(workspaceId, issueId, 10, cursor, null) }
                    }
                    result.onSuccess { page ->
                        olderTimelineEntries = olderTimelineEntries + page.entries
                        timelineNextCursor = page.nextCursor
                        timelineHasMoreBefore = page.hasMoreBefore
                    }.onFailure { error ->
                        timelineMessage = if (zh) "加载更早时间线失败：${error.message}" else "Load older timeline failed: ${error.message}"
                    }
                    loadingOlderTimeline = false
                }
            }

            fun runCommentMutation(action: suspend () -> Unit) {
                if (mutatingComment) return
                mutatingComment = true
                commentMessage = null
                scope.launch {
                    val result = withContext(Dispatchers.IO) { runCatching { action() } }
                    mutatingComment = false
                    result.onSuccess {
                        editingCommentId = null
                        editingCommentContent = ""
                        pendingDeleteComment = null
                        commentMessage = if (zh) "评论已更新" else "Comment updated"
                        detailRefresh++
                    }.onFailure {
                        commentMessage = "${if (zh) "评论操作失败" else "Comment action failed"}: ${it.message ?: it.toString()}"
                    }
                }
            }

            fun runSubscriberMutation(successMessage: String, action: suspend () -> Unit) {
                if (mutatingSubscriber) return
                mutatingSubscriber = true
