            fun sendNewComment() {
                val content = newCommentDraft.trim()
                if (sendingNewComment || content.isEmpty() && pendingCommentAttachments.isEmpty()) return
                sendingNewComment = true
                newCommentMessage = null
                val attachmentIds = pendingCommentAttachments.map { it.id }
                scope.launch {
                    val result = withContext(Dispatchers.IO) {
                        runCatching { api.addComment(issueId, workspaceId, content, attachmentIds) }
                    }
                    sendingNewComment = false
                    result.onSuccess {
                        newCommentDraft = ""
                        pendingCommentAttachments = emptyList()
                        newCommentMessage = if (zh) "评论已发送" else "Comment sent"
                        detailRefresh++
                    }.onFailure {
                        newCommentMessage = "${if (zh) "评论发送失败" else "Comment send failed"}: ${it.message ?: it.toString()}"
                    }
                }
            }

            fun sendReply(parentId: String) {
                val content = replyDraft.trim()
                if (sendingReply || (content.isEmpty() && pendingReplyAttachments.isEmpty())) return
                sendingReply = true
                replyMessage = null
                val attachmentIds = pendingReplyAttachments.map { it.id }
                scope.launch {
                    val result = withContext(Dispatchers.IO) {
                        runCatching { api.addComment(issueId, workspaceId, content, attachmentIds, parentId) }
                    }
                    sendingReply = false
                    result.onSuccess {
                        replyDraft = ""
                        pendingReplyAttachments = emptyList()
                        replyingCommentId = null
                        replyMessage = if (zh) "回复已发送" else "Reply sent"
                        detailRefresh++
                    }.onFailure {
                        replyMessage = "${if (zh) "回复发送失败" else "Reply send failed"}: ${it.message ?: it.toString()}"
                    }
                }
            }

