private suspend fun attachIssueLabelWithRetry(
    api: ApiClient,
    workspaceId: String,
    issueId: String,
    labelId: String,
): List<Models.IssueLabel> {
    var lastError: Throwable? = null
    repeat(4) { attempt ->
        try {
            return api.attachIssueLabel(workspaceId, issueId, labelId)
        } catch (error: Throwable) {
            lastError = error
            if (attempt < 3) delay(650L * (attempt + 1))
        }
    }
    throw lastError ?: IllegalStateException("Label attach failed")
}

@Composable
private fun IssueCommentReplyBox(
    parentId: String,
    draft: String,
    pendingAttachments: List<Models.Attachment>,
    agents: List<Models.Agent>,
    uploadingAttachment: Boolean,
    sending: Boolean,
    zh: Boolean,
    onDraftChange: (String) -> Unit,
    onAttach: () -> Unit,
    onAttachImage: () -> Unit,
    onRemoveAttachment: (Int) -> Unit,
    onCancel: () -> Unit,
    onSend: () -> Unit,
) {
    var mentionPickerOpen by remember(parentId) { mutableStateOf(false) }
    var mentionQuery by remember(parentId) { mutableStateOf("") }
    val focusRequester = remember(parentId) { FocusRequester() }
    val keyboard = LocalSoftwareKeyboardController.current
    val focusManager = LocalFocusManager.current
    val mentionAgents = remember(agents, mentionQuery) {
        val query = mentionQuery.trim().lowercase()
        agents
            .filter { it.archivedAt.isBlank() }
            .filter { agent ->
                query.isBlank() ||
                    agent.name.lowercase().contains(query) ||
                    agent.description.lowercase().contains(query) ||
                    agent.id.lowercase().contains(query)
            }
            .sortedBy { it.name.lowercase() }
            .take(8)
    }
    LaunchedEffect(parentId) {
        delay(180)
        focusRequester.requestFocus()
        keyboard?.show()
    }

    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 38.dp, bottom = 8.dp)
            .semantics(mergeDescendants = false) { contentDescription = "Issue Comment Web Reply Editor $parentId" },
        shape = RoundedCornerShape(14.dp),
        color = MulticaColors.Surface.copy(alpha = 0.82f),
        border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.76f)),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 10.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Text(
                text = if (zh) "回复评论" else "Reply to comment",
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp, fontWeight = FontWeight.SemiBold),
                color = MulticaColors.Muted,
            )
            MulticaTextField(
                value = draft,
                onValueChange = onDraftChange,
                modifier = Modifier
                    .fillMaxWidth()
                    .focusRequester(focusRequester)
                    .semantics(mergeDescendants = true) { contentDescription = "Issue Comment Reply Input $parentId" },
                label = if (zh) "写回复..." else "Write a reply...",
                minLines = 2,
                maxLines = 5,
            )
            if (pendingAttachments.isNotEmpty()) {
                Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    pendingAttachments.forEachIndexed { index, attachment ->
                        CompactIssueRow(
                            eyebrow = if (zh) "待发送附件" else "Pending attachment",
                            title = attachment.filename.ifBlank { Models.shortId(attachment.id) },
                            trailing = attachment.contentType,
                            contentDescription = "Issue Comment Reply Pending Attachment ${attachment.id}",
                            onClick = { onRemoveAttachment(index) },
                        )
                    }
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MulticaPillButton(
                    text = if (uploadingAttachment) "..." else if (zh) "图片" else "Image",
                    onClick = onAttachImage,
                    tone = MulticaButtonTone.Secondary,
                    contentDescription = "Issue Comment Reply Attach Image",
                    enabled = !uploadingAttachment,
                )
                MulticaPillButton(
                    text = "+",
                    onClick = onAttach,
                    tone = MulticaButtonTone.Ghost,
                    contentDescription = "Issue Comment Reply Attach",
                    enabled = !uploadingAttachment,
                )
                MulticaPillButton(
                    text = "@",
                    onClick = { mentionPickerOpen = !mentionPickerOpen },
                    tone = if (mentionPickerOpen) MulticaButtonTone.Primary else MulticaButtonTone.Secondary,
                    contentDescription = "Issue Comment Reply Agent Mention",
                )
                MulticaPillButton(
                    text = if (zh) "取消" else "Cancel",
                    onClick = {
                        focusManager.clearFocus(force = true)
                        keyboard?.hide()
                        onCancel()
                    },
                    tone = MulticaButtonTone.Ghost,
                    modifier = Modifier.weight(1f),
                )
                MulticaPillButton(
                    text = if (sending) "..." else if (zh) "发送回复" else "Send Reply",
                    onClick = onSend,
                    tone = MulticaButtonTone.Primary,
                    enabled = !sending && (draft.trim().isNotEmpty() || pendingAttachments.isNotEmpty()),
                    modifier = Modifier.weight(1f),
                )
            }
            if (mentionPickerOpen) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Issue Comment Reply Mention Web Picker" },
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Text(
                        text = if (zh) "选择 Agent" else "Mention agent",
                        modifier = Modifier.semantics { contentDescription = "Issue Comment Mention Web Header" },
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                    )
                    MulticaTextField(
                        value = mentionQuery,
                        onValueChange = { mentionQuery = it },
                        modifier = Modifier.fillMaxWidth(),
                        contentDescription = "Issue Comment Reply Mention Search",
                        label = if (zh) "搜索 Agent" else "Search agents",
                        maxLines = 1,
                    )
                    if (mentionAgents.isEmpty()) {
                        Text(
                            text = if (zh) "没有可提及的 Agent" else "No agents available",
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                            color = MulticaColors.Muted,
                        )
                    } else {
                        mentionAgents.forEach { agent ->
                            IssueMentionAgentWebRow(
                                agent = agent,
                                contentDescription = "Issue Comment Reply Mention Agent Row ${agent.id}",
                                onClick = {
                                    val insertion = AgentMentionMarkdown.markdown(agent.name, agent.id)
                                    val separator = if (draft.isBlank() || draft.endsWith(" ") || draft.endsWith("\n")) "" else " "
                                    onDraftChange(draft + separator + insertion + " ")
                                    mentionPickerOpen = false
                                    mentionQuery = ""
                                },
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun IssueMentionAgentWebRow(
    agent: Models.Agent,
    contentDescription: String,
    onClick: () -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .semantics(mergeDescendants = true) {
                this.contentDescription = contentDescription
                semanticsOnClick(label = agent.name.ifBlank { Models.shortId(agent.id) }) {
                    onClick()
                    true
                }
            },
        shape = RoundedCornerShape(8.dp),
        color = MulticaColors.SurfaceElevated.copy(alpha = 0.78f),
