@Composable
private fun MarkdownBlock(markdown: String) {
    val textColor = MulticaColors.Text.toArgb()
    val mutedColor = MulticaColors.Muted.toArgb()
    val borderColor = MulticaColors.Border.toArgb()
    SelectionContainer(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Selectable Markdown Block" },
    ) {
        AndroidView(
            modifier = Modifier.fillMaxWidth(),
            factory = { context ->
                LinearLayout(context).apply { orientation = LinearLayout.VERTICAL }
            },
            update = { view ->
                view.removeAllViews()
                MarkdownRenderer.render(
                    view.context,
                    view,
                    markdown,
                    textColor,
                    mutedColor,
                    borderColor,
                )
            },
        )
    }
}

@Composable
private fun SectionHeader(title: String) {
    Text(
        text = title,
        style = MaterialTheme.typography.labelLarge.copy(
            fontWeight = FontWeight.SemiBold,
            fontSize = 15.sp,
            lineHeight = 20.sp,
        ),
        color = MulticaColors.Muted,
        modifier = Modifier.padding(top = MulticaVisualTokens.SectionTop, bottom = MulticaVisualTokens.SectionBottom),
    )
}

private fun projectProgressLabel(project: Models.Project, zh: Boolean): String {
    val done = project.doneCount.coerceAtLeast(0)
    val total = project.issueCount.coerceAtLeast(0)
    return if (zh) "$done/$total 完成" else "$done/$total Done"
}

private fun projectLeadLabel(project: Models.Project, zh: Boolean): String? {
    val type = project.leadType
    val id = project.leadId
    if (type.isBlank() || id.isBlank()) return null
    val label = when (type) {
        "member" -> if (zh) "成员" else "Member"
        "agent" -> "Agent"
        else -> type.replaceFirstChar { it.uppercaseChar() }
    }
    return "$label ${Models.shortId(id)}"
}

@Composable
private fun PilotProjectDetail(
    api: ApiClient,
    workspaceId: String,
    project: Models.Project,
    zh: Boolean,
    onBack: () -> Unit,
    onIssueClick: (String) -> Unit,
) {
    var state by remember(project.id, workspaceId) { mutableStateOf<Result<PilotProjectDetailData>?>(null) }
    var refresh by remember(project.id, workspaceId) { mutableIntStateOf(0) }
    var resourceUrl by remember(project.id, workspaceId) { mutableStateOf("") }
    var addResourceOpen by remember(project.id, workspaceId) { mutableStateOf(false) }
    var expandedResourceActionsId by remember(project.id, workspaceId) { mutableStateOf<String?>(null) }
    var pendingDeleteResource by remember(project.id, workspaceId) { mutableStateOf<Models.ProjectResource?>(null) }
    var mutatingResource by remember(project.id, workspaceId) { mutableStateOf(false) }
    var resourceResult by remember(project.id, workspaceId) { mutableStateOf<String?>(null) }
    var mutatingPin by remember(project.id, workspaceId) { mutableStateOf(false) }
    var pinResult by remember(project.id, workspaceId) { mutableStateOf<String?>(null) }
    var currentPinned by remember(project.id, workspaceId) { mutableStateOf<Boolean?>(null) }
    var projectActionsOpen by remember(project.id, workspaceId) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    LaunchedEffect(project.id, workspaceId, refresh) {
        state = null
        val loaded = withContext(Dispatchers.IO) {
            runCatching {
                val projectIssues = Models.STATUS_VALUES.flatMap { status ->
                    api.projectIssues(workspaceId, project.id, status, 80, 0).items
                }.distinctBy { it.id }
                val resources = api.projectResources(workspaceId, project.id).items.sortedBy { it.position }
                val pinned = api.pins(workspaceId).any { it.itemType == "project" && it.itemId == project.id }
                PilotProjectDetailData(project, projectIssues, resources, pinned)
            }
        }
        state = loaded
        loaded.onSuccess { currentPinned = it.isPinned }
    }

    fun toggleProjectPin(isPinned: Boolean) {
        if (mutatingPin) return
        mutatingPin = true
        pinResult = null
        val nextPinned = !isPinned
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                if (nextPinned) runCatching { api.createPin(workspaceId, "project", project.id) }
                else runCatching { api.deletePin(workspaceId, "project", project.id) }
            }
            mutatingPin = false
            result.onSuccess {
                currentPinned = nextPinned
                refresh++
                pinResult = if (nextPinned) {
                    if (zh) "项目已置顶" else "Project pinned"
                } else {
                    if (zh) "项目已取消置顶" else "Project unpinned"
                }
            }.onFailure {
                pinResult = "${if (zh) "置顶操作失败" else "Pin failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun copyProjectLink() {
        val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        clipboard.setPrimaryClip(ClipData.newPlainText("Multica project link", "multica://projects/${project.id}"))
        pinResult = if (zh) "项目链接已复制" else "Project link copied"
    }

    fun deleteProjectResource(resource: Models.ProjectResource) {
        if (mutatingResource) return
        mutatingResource = true
        resourceResult = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.deleteProjectResource(workspaceId, project.id, resource.id) }
            }
            mutatingResource = false
            result.onSuccess {
                pendingDeleteResource = null
                resourceResult = if (zh) "资源已删除" else "Resource deleted"
                refresh++
            }.onFailure {
                resourceResult = "${if (zh) "删除失败" else "Delete failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    val loadedData = state?.getOrNull()
    val headerPinned = currentPinned ?: loadedData?.isPinned ?: false

    PilotListPage(
        title = project.name.ifBlank { if (zh) "项目" else "Project" },
        leading = {
            MulticaIconPillButton(
                icon = Icons.Outlined.ArrowBack,
                contentDescription = if (zh) "返回" else "Back",
                onClick = onBack,
                tone = MulticaButtonTone.Ghost,
            )
        },
        trailing = {
            Box(modifier = Modifier.semantics { contentDescription = "Project Detail Cupertino More Menu" }) {
                MulticaIconPillButton(
                    icon = Icons.Outlined.MoreHoriz,
                    contentDescription = "Project Detail More Actions",
                    onClick = { projectActionsOpen = true },
                    tone = MulticaButtonTone.Ghost,
                )
                MulticaCupertinoActionSheet(
                    visible = projectActionsOpen,
                    title = project.name.ifBlank { if (zh) "项目" else "Project" },
                    message = if (zh) "项目操作" else "Project actions",
                    cancelText = if (zh) "取消" else "Cancel",
                    onDismissRequest = { projectActionsOpen = false },
                    items = listOf(
                        MulticaCupertinoActionSheetItem(
                            title = if (headerPinned) {
                                if (zh) "取消置顶项目" else "Unpin Project"
                            } else {
                                if (zh) "置顶项目" else "Pin Project"
                            },
                            subtitle = if (zh) "保存到工作区置顶项" else "Save this project in pinned workspace items",
                            contentDescription = "Project Detail More Pin Action ${project.name}",
                            selected = headerPinned,
                            onClick = {
                                projectActionsOpen = false
                                toggleProjectPin(headerPinned)
                            },
                        ),
                        MulticaCupertinoActionSheetItem(
                            title = if (zh) "复制项目链接" else "Copy Project Link",
                            subtitle = if (zh) "复制可回到此项目的链接" else "Copy a link back to this project",
                            contentDescription = "Project Detail More Copy Link Action ${project.name}",
                            onClick = {
                                projectActionsOpen = false
                                copyProjectLink()
                            },
                        ),
                    ),
                )
            }
        },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载项目..." else "Loading project...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "项目加载失败" else "Project failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { data ->
                    item {
                        ProjectDetailWebHero(
                            project = data.project,
                            issueCount = data.issues.size,
                            resourceCount = data.resources.size,
                            isPinned = headerPinned,
                            zh = zh,
                        )
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "属性" else "Properties",
                            subtitle = if (zh) "状态、优先级、负责人" else "Status, priority, and lead",
                            contentDescription = "Project Detail Web Properties",
                        ) {
                            ProjectPropertyWebRow(
                                label = if (zh) "状态" else "Status",
                                value = Models.projectStatusLabel(data.project.status, zh),
                                icon = Icons.Outlined.CheckCircle,
                            )
                            ProjectPropertyWebRow(
                                label = if (zh) "优先级" else "Priority",
                                value = Models.priorityLabel(data.project.priority, zh),
                                icon = Icons.Outlined.Flag,
                            )
                            ProjectPropertyWebRow(
                                label = if (zh) "负责人" else "Lead",
                                value = projectLeadLabel(data.project, zh) ?: if (zh) "未设置" else "No lead",
                                icon = Icons.Outlined.Person,
                            )
                            ProjectPropertyWebRow(
                                label = if (zh) "创建时间" else "Created",
                                value = shortDate(data.project.createdAt).ifBlank { Models.shortId(data.project.id) },
                                icon = Icons.Outlined.CalendarMonth,
                            )
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "进度" else "Progress",
                            subtitle = projectProgressLabel(data.project, zh),
                            contentDescription = "Project Detail Web Progress",
                        ) {
                            ProjectProgressWebRow(data.project, data.issues.size, zh)
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "描述" else "Description",
                            subtitle = if (data.project.description.isBlank()) {
                                if (zh) "暂无项目描述" else "No project description"
                            } else {
                                preview(data.project.description).orEmpty()
                            },
                            contentDescription = "Project Detail Web Description",
                        ) {
                            SelectionContainer {
                                Text(
                                    text = preview(data.project.description)
                                        ?: if (zh) "暂无项目描述" else "No project description",
                                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 17.sp),
                                    color = if (data.project.description.isBlank()) MulticaColors.Muted else MulticaColors.Text,
                                )
                            }
                        }
                    }
                    if (!pinResult.isNullOrBlank()) {
                        item {
                            PilotInlineResultState(
                                message = pinResult.orEmpty(),
                                isError = pilotInlineResultIsError(pinResult.orEmpty()),
                                contentDescription = "Project Pin Result Web Banner",
                            )
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "资源 (${data.resources.size})" else "Resources (${data.resources.size})",
                            subtitle = if (zh) "GitHub 仓库引用与补充上下文" else "GitHub repository references and project context",
                            contentDescription = "Project Detail Web Resources",
                        ) {
                            ProjectResourceWebAddRow(
                                expanded = addResourceOpen,
                                zh = zh,
                                onClick = { addResourceOpen = !addResourceOpen },
                            )
                            if (addResourceOpen) {
                                Column(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp),
                                ) {
                                    MulticaTextField(
                                        value = resourceUrl,
                                        onValueChange = { resourceUrl = it },
                                        label = if (zh) "GitHub 资源 URL" else "Resource URL",
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .semantics(mergeDescendants = true) {
                                                contentDescription = "Project Resource URL Field"
                                            },
                                        singleLine = true,
                                    )
                                    val canAddResource = resourceUrl.trim().isNotEmpty() && !mutatingResource
                                    MulticaPillButton(
                                        text = if (mutatingResource) "..." else if (zh) "添加资源" else "Add Resource",
                                        onClick = {
                                            val url = resourceUrl.trim()
                                            if (url.isEmpty() || mutatingResource) return@MulticaPillButton
                                            mutatingResource = true
                                            resourceResult = null
                                            scope.launch {
                                                val result = withContext(Dispatchers.IO) {
                                                    runCatching { api.createProjectResource(workspaceId, project.id, "github_repo", url) }
                                                }
                                                mutatingResource = false
                                                result.onSuccess {
                                                    resourceUrl = ""
                                                    addResourceOpen = false
                                                    resourceResult = if (zh) "资源已添加" else "Resource added"
                                                    refresh++
                                                }.onFailure {
                                                    resourceResult = "${if (zh) "添加失败" else "Add failed"}: ${it.message ?: it.toString()}"
                                                }
                                            }
                                        },
                                        tone = MulticaButtonTone.Primary,
                                        enabled = canAddResource,
                                        contentDescription = "Project Resource Add Button",
                                    )
                                }
                            }
                        }
                    }
                    if (!resourceResult.isNullOrBlank()) {
                        item {
                            PilotInlineResultState(
                                message = resourceResult.orEmpty(),
                                isError = pilotInlineResultIsError(resourceResult.orEmpty()),
                                contentDescription = "Project Resource Result Web Banner",
                            )
                        }
                    }
                    if (data.resources.isEmpty()) {
                        item {
                            ProjectDetailWebEmptyState(
                                type = ProjectDetailEmptyStateType.Resources,
                                zh = zh,
                            )
                        }
                    } else {
                        items(data.resources) { resource ->
                            Column(modifier = Modifier.fillMaxWidth()) {
                                ProjectResourceWebDenseRow(
                                    resource = resource,
                                    expanded = expandedResourceActionsId == resource.id,
                                    zh = zh,
                                    onToggleActions = {
                                        expandedResourceActionsId = if (expandedResourceActionsId == resource.id) null else resource.id
                                        pendingDeleteResource = null
                                    },
                                    onDelete = {
                                        pendingDeleteResource = resource
                                        expandedResourceActionsId = null
                                    },
                                )
                                if (pendingDeleteResource?.id == resource.id) {
                                    ProjectResourceDeleteConfirmWebPanel(
                                        resource = resource,
                                        zh = zh,
                                        isDeleting = mutatingResource,
                                        onCancel = { pendingDeleteResource = null },
                                        onConfirm = { deleteProjectResource(resource) },
                                    )
                                    Spacer(modifier = Modifier.height(10.dp))
                                }
                            }
                        }
                    }
                    item { SectionHeader(if (zh) "Issues (${data.issues.size})" else "Issues (${data.issues.size})") }
                    if (data.issues.isEmpty()) {
                        item {
                            ProjectDetailWebEmptyState(
                                type = ProjectDetailEmptyStateType.Issues,
                                zh = zh,
                            )
                        }
                    } else {
                        items(data.issues) { issue ->
                            ProjectDetailIssueWebDenseRow(
                                issue = issue,
                                zh = zh,
                                onClick = { onIssueClick(issue.id) },
                            )
                        }
                    }
                }
            }
        }
    }
}

private enum class ProjectDetailEmptyStateType {
    Resources,
    Issues,
}

@Composable
private fun ProjectDetailWebEmptyState(
    type: ProjectDetailEmptyStateType,
    zh: Boolean,
) {
    val WEB_SSOT_PROJECT_DETAIL = "/Users/park0er/coding/multica-web-source/packages/views/projects/components/project-detail.tsx"
    val WEB_SSOT_PROJECT_RESOURCES_SECTION = "/Users/park0er/coding/multica-web-source/packages/views/projects/components/project-resources-section.tsx"
    val title = when (type) {
        ProjectDetailEmptyStateType.Resources -> if (zh) "还没有关联资源。" else "No resources attached."
        ProjectDetailEmptyStateType.Issues -> if (zh) "还没有关联的 issue" else "No issues linked"
    }
    val description = when (type) {
        ProjectDetailEmptyStateType.Resources -> null
        ProjectDetailEmptyStateType.Issues -> if (zh) "新建一个 issue，或把已有的 issue 关联到这个项目。" else "Create a new issue or assign existing ones to this project."
    }
    val marker = when (type) {
        ProjectDetailEmptyStateType.Resources -> "Project Detail Resource Empty State $WEB_SSOT_PROJECT_RESOURCES_SECTION"
        ProjectDetailEmptyStateType.Issues -> "Project Detail Issues Empty State $WEB_SSOT_PROJECT_DETAIL"
    }

    Box(
        modifier = Modifier.semantics {
            contentDescription = marker
        },
    ) {
        MulticaEmptyState(
            title = title,
            description = description,
        )
    }
}

@Composable
private fun ProjectDetailWebHero(
    project: Models.Project,
    issueCount: Int,
    resourceCount: Int,
    isPinned: Boolean,
    zh: Boolean,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Project Detail Web Hero" },
        shape = RoundedCornerShape(16.dp),
        color = MulticaColors.Surface.copy(alpha = 0.9f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
