@Composable
private fun ProjectProgressWebRow(
    project: Models.Project,
    loadedIssueCount: Int,
    zh: Boolean,
) {
    val total = project.issueCount.coerceAtLeast(loadedIssueCount).coerceAtLeast(0)
    val done = project.doneCount.coerceIn(0, total.coerceAtLeast(project.doneCount))
    val progress = if (total > 0) (done.toFloat() / total.toFloat()).coerceIn(0f, 1f) else 0f
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Project Detail Web Progress" },
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Box(
                modifier = Modifier
                    .weight(1f)
                    .height(6.dp)
                    .clip(RoundedCornerShape(999.dp))
                    .background(MulticaColors.Border.copy(alpha = 0.72f))
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth(progress)
                        .height(6.dp)
                        .clip(RoundedCornerShape(999.dp))
                        .background(MulticaColors.Success)
                )
            }
            Text(
                text = if (total > 0) "$done/$total" else "--",
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp, fontWeight = FontWeight.SemiBold),
                color = MulticaColors.Muted,
                maxLines = 1,
            )
        }
        Text(
            text = if (zh) "完成度会随项目 Issue 变化自动更新" else "Completion follows project issue status",
            style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp),
            color = MulticaColors.TextTertiary,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
    }
}

