@Composable
private fun PilotProjects(
    api: ApiClient,
    workspaceId: String,
    workspace: Models.Workspace,
    projects: List<Models.Project>,
    zh: Boolean,
    onProjectClick: (Models.Project) -> Unit,
    onRefresh: () -> Unit,
) {
    val scope = rememberCoroutineScope()
    var editingProject by remember(workspaceId) { mutableStateOf<Models.Project?>(null) }
    var formOpen by remember(workspaceId) { mutableStateOf(false) }
    var title by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf(editingProject?.name.orEmpty()) }
    var description by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf(editingProject?.description.orEmpty()) }
    var icon by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf(editingProject?.icon.orEmpty()) }
    var status by remember(workspaceId, editingProject?.id, formOpen) {
        mutableStateOf(editingProject?.status?.takeIf { it.isNotBlank() } ?: "planned")
    }
    var priority by remember(workspaceId, editingProject?.id, formOpen) {
        mutableStateOf(editingProject?.priority?.takeIf { it.isNotBlank() } ?: "none")
    }
    var leadType by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf(editingProject?.leadType.orEmpty()) }
    var leadId by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf(editingProject?.leadId.orEmpty()) }
    var selectedResourceUrls by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf<Set<String>>(emptySet()) }
    var resourceUrlsText by remember(workspaceId, editingProject?.id, formOpen) { mutableStateOf("") }
    var projectMembers by remember(workspaceId) { mutableStateOf<List<Models.Member>>(emptyList()) }
    var projectAgents by remember(workspaceId) { mutableStateOf<List<Models.Agent>>(emptyList()) }
    var loadingProjectOptions by remember(workspaceId) { mutableStateOf(false) }
    var saving by remember(workspaceId) { mutableStateOf(false) }
    var pendingDelete by remember(workspaceId) { mutableStateOf<Models.Project?>(null) }
    var deleting by remember(workspaceId) { mutableStateOf(false) }
    var resultText by remember(workspaceId) { mutableStateOf<String?>(null) }
    var expandedProjectActionsId by remember(workspaceId) { mutableStateOf<String?>(null) }
    var projectQuery by remember(workspaceId) { mutableStateOf("") }
    val visibleProjects = remember(projects, projectQuery, zh) {
        val query = projectQuery.trim()
        if (query.isBlank()) {
            projects
        } else {
            projects.filter { project ->
                project.name.contains(query, ignoreCase = true)
                    || project.description.contains(query, ignoreCase = true)
                    || project.icon.contains(query, ignoreCase = true)
                    || Models.projectStatusLabel(project.status, zh).contains(query, ignoreCase = true)
                    || Models.priorityLabel(project.priority, zh).contains(query, ignoreCase = true)
            }
        }
    }

    fun openForm(project: Models.Project?) {
        projectQuery = ""
        editingProject = project
        title = project?.name.orEmpty()
        description = project?.description.orEmpty()
        icon = project?.icon.orEmpty()
        status = project?.status?.takeIf { it.isNotBlank() } ?: "planned"
        priority = project?.priority?.takeIf { it.isNotBlank() } ?: "none"
        leadType = project?.leadType.orEmpty()
        leadId = project?.leadId.orEmpty()
        selectedResourceUrls = emptySet()
        resourceUrlsText = ""
        formOpen = true
        pendingDelete = null
        expandedProjectActionsId = null
        resultText = null
    }

    fun saveProject() {
        val titleText = title.trim()
        if (titleText.isEmpty() || saving) {
            resultText = if (zh) "项目标题不能为空" else "Project title is required"
            return
        }
        val project = editingProject
        saving = true
        resultText = null
        val iconText = icon.trim()
        val resourceUrls = (selectedResourceUrls + resourceUrlsText
            .lineSequence()
            .map { it.trim() }
            .filter { it.isNotBlank() })
            .distinct()
            .sorted()
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    if (project == null) {
                        api.createProject(workspaceId, titleText, description, status, priority, iconText, leadType, leadId, resourceUrls)
                    } else {
                        api.updateProject(workspaceId, project, titleText, description, status, priority, iconText, leadType, leadId)
                    }
                }
            }
            saving = false
            result.onSuccess {
                formOpen = false
                editingProject = null
                projectQuery = ""
                resultText = it.name
                onRefresh()
            }.onFailure {
                resultText = "${if (zh) "项目保存失败" else "Project save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun deleteProject(project: Models.Project) {
        if (deleting) return
        deleting = true
        resultText = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.deleteProject(workspaceId, project.id) }
            }
            deleting = false
            result.onSuccess {
                pendingDelete = null
                resultText = if (zh) "项目已删除" else "Project deleted"
                onRefresh()
            }.onFailure {
                resultText = "${if (zh) "项目删除失败" else "Project delete failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    LaunchedEffect(formOpen, workspaceId) {
        if (!formOpen || projectMembers.isNotEmpty() || projectAgents.isNotEmpty() || loadingProjectOptions) return@LaunchedEffect
        loadingProjectOptions = true
        withContext(Dispatchers.IO) {
            runCatching { api.members(workspaceId) to api.agents(workspaceId) }
        }.onSuccess { (members, agents) ->
            projectMembers = members
            projectAgents = agents.filter { it.archivedAt.isBlank() }
        }.onFailure {
            resultText = "${if (zh) "项目选项加载失败" else "Project options failed"}: ${it.message ?: it.toString()}"
        }
        loadingProjectOptions = false
    }

    val selectedLeadLabel = remember(leadType, leadId, projectMembers, projectAgents, zh) {
        when (leadType) {
            "member" -> projectMembers.firstOrNull { it.userId == leadId || it.id == leadId }?.let { member ->
                member.displayName.ifBlank { member.email }
            } ?: Models.shortId(leadId)
            "agent" -> projectAgents.firstOrNull { it.id == leadId }?.name ?: Models.shortId(leadId)
            else -> if (zh) "无负责人" else "No Lead"
        }
    }

    if (formOpen) {
        BackHandler(enabled = true) {
            formOpen = false
            editingProject = null
            resultText = null
        }
        PilotListPage(
            title = if (editingProject == null) {
                if (zh) "新建项目" else "New Project"
            } else {
                if (zh) "编辑项目" else "Edit Project"
            },
            leading = {
                MulticaIconPillButton(
                    icon = Icons.Outlined.ArrowBack,
                    contentDescription = if (zh) "返回项目列表" else "Back to Projects",
                    onClick = {
                        formOpen = false
                        editingProject = null
                        resultText = null
                    },
                    tone = MulticaButtonTone.Ghost,
                )
            },
            trailing = {
                MulticaPillButton(
                    text = if (saving) "..." else if (zh) "保存" else "Save",
                    onClick = { saveProject() },
                    tone = MulticaButtonTone.Primary,
                    enabled = title.trim().isNotEmpty() && !saving,
                    contentDescription = "Project Save Button",
                )
            },
            bottomContent = {
                MulticaHazeBottomBar(
                    hazeState = rememberHazeState(),
                    contentDescription = "Project Form Bottom Haze Save Bar",
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 26.dp, vertical = 14.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaPillButton(
                            text = if (zh) "取消" else "Cancel",
                            onClick = {
                                formOpen = false
                                editingProject = null
                            },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Ghost,
                        )
                        MulticaPillButton(
                            text = if (saving) "..." else if (editingProject == null) {
                                if (zh) "创建项目" else "Create Project"
                            } else {
                                if (zh) "保存项目" else "Save Project"
                            },
                            onClick = { saveProject() },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Primary,
                            enabled = title.trim().isNotEmpty() && !saving,
                            contentDescription = "Project Form Bottom Save",
                        )
                    }
                }
            },
        ) {
            if (!resultText.isNullOrBlank()) {
                item {
                    val isError = resultText!!.contains("failed", true) || resultText!!.contains("失败")
                    PilotInlineResultState(
                        message = resultText.orEmpty(),
                        isError = isError,
                        contentDescription = "Project Form Result Web Banner",
                    )
                }
            }
            item {
                SettingsSectionLabel(if (zh) "项目" else "Project")
                ProjectFormWebPanel(contentDescription = "Project Form Identity Web Panel") {
                    MulticaTextField(
                        value = title,
                        onValueChange = { title = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Project Form Web Title Editor" },
                        label = if (zh) "项目标题" else "Project title",
                        contentDescription = "Project Title Field",
                        singleLine = true,
                    )
                    MulticaTextField(
                        value = icon,
                        onValueChange = { icon = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Project Form Web Icon Editor" },
                        label = if (zh) "图标" else "Icon",
                        contentDescription = "Project Icon Field",
                        singleLine = true,
                    )
                    MulticaTextField(
                        value = description,
                        onValueChange = { description = it },
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Project Form Web Description Editor" },
                        label = if (zh) "项目描述" else "Project description",
                        contentDescription = "Project Description Field",
                        minLines = 4,
                    )
                }
            }
            item {
                SettingsSectionLabel(if (zh) "详情" else "Details")
                ProjectFormWebPanel(contentDescription = "Project Form Details Web Panel") {
                    IssueFormMenuRow(
                        eyebrow = if (zh) "状态" else "Status",
                        title = Models.projectStatusLabel(status, zh),
                        subtitle = null,
                        contentDescription = "Project Status Picker",
                        options = Models.PROJECT_STATUS_VALUES.map { value ->
                            IssueFormMenuOption(
                                label = Models.projectStatusLabel(value, zh),
                                selected = value == status,
                                onClick = { status = value },
                            )
                        },
                    )
                    IssueFormMenuRow(
                        eyebrow = if (zh) "优先级" else "Priority",
                        title = Models.priorityLabel(priority, zh),
                        subtitle = null,
                        contentDescription = "Project Priority Picker",
                        options = Models.PRIORITY_VALUES.map { value ->
                            IssueFormMenuOption(
                                label = Models.priorityLabel(value, zh),
                                selected = value == priority,
                                onClick = { priority = value },
                            )
                        },
                    )
                    IssueFormMenuRow(
                        eyebrow = if (zh) "负责人" else "Lead",
                        title = selectedLeadLabel,
                        subtitle = if (loadingProjectOptions) {
                            if (zh) "正在加载成员和 Agent" else "Loading members and agents"
                        } else {
                            null
                        },
                        contentDescription = "Project Lead Picker",
                        options = listOf(
                            IssueFormMenuOption(
                                label = if (zh) "无负责人" else "No Lead",
                                selected = leadType.isBlank() || leadId.isBlank(),
                                onClick = {
                                    leadType = ""
                                    leadId = ""
                                },
                            )
                        ) + projectMembers.map { member ->
                            val assigneeId = member.userId.ifBlank { member.id }
                            IssueFormMenuOption(
                                label = listOf(member.displayName.ifBlank { member.email }, if (zh) "成员" else "Member")
                                    .filter { it.isNotBlank() }
                                    .joinToString(" · "),
                                selected = leadType == "member" && (leadId == assigneeId || leadId == member.id),
                                onClick = {
                                    leadType = "member"
                                    leadId = assigneeId
                                },
                            )
                        } + projectAgents.map { agent ->
                            IssueFormMenuOption(
                                label = listOf(agent.name, "Agent").filter { it.isNotBlank() }.joinToString(" · "),
                                selected = leadType == "agent" && leadId == agent.id,
                                onClick = {
                                    leadType = "agent"
                                    leadId = agent.id
                                },
                            )
                        },
                    )
                }
            }
            if (editingProject == null) {
                item {
                    SettingsSectionLabel(if (zh) "资源" else "Resources")
                    ProjectFormWebPanel(contentDescription = "Project Form Resources Web Panel") {
                        workspace.repos
                            .map { it.url }
                            .filter { it.isNotBlank() }
                            .distinct()
                            .forEachIndexed { index, repoUrl ->
                                ProjectFormRepoOptionRow(
                                    repoUrl = repoUrl,
                                    selected = selectedResourceUrls.contains(repoUrl),
                                    zh = zh,
                                    onClick = {
                                        selectedResourceUrls = if (selectedResourceUrls.contains(repoUrl)) {
                                            selectedResourceUrls - repoUrl
                                        } else {
                                            selectedResourceUrls + repoUrl
                                        }
                                    },
                                    rowContentDescription = "Project Repository Option ${index + 1}",
                                )
                            }
                        Column(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            MulticaTextField(
                                value = resourceUrlsText,
                                onValueChange = { resourceUrlsText = it },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics { contentDescription = "Project Form Web Resource URLs" },
                                label = if (zh) "自定义 GitHub URLs" else "Custom GitHub URLs",
                                contentDescription = "Project Resource URLs Field",
                                minLines = 3,
                            )
                            Text(
                                text = if (zh) "每行添加一个 GitHub repo URL。" else "Add one GitHub repo URL per line.",
                                style = MaterialTheme.typography.bodySmall,
                                color = MulticaColors.Muted,
                            )
                        }
                    }
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "项目" else "Projects",
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = if (zh) "新建项目" else "New Project",
                onClick = { openForm(null) },
                tone = MulticaButtonTone.Primary,
            )
        },
    ) {
        item {
            MulticaTextField(
                value = projectQuery,
                onValueChange = { projectQuery = it },
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 2.dp, bottom = 8.dp),
                label = if (zh) "搜索项目" else "Search projects",
                contentDescription = "Project List Search",
                singleLine = true,
            )
        }
        if (!resultText.isNullOrBlank()) {
            item {
                val isError = resultText!!.contains("failed", true) || resultText!!.contains("失败")
                PilotInlineResultState(
                    message = resultText.orEmpty(),
                    isError = isError,
                    contentDescription = "Project List Result Web Banner",
                )
            }
        }
        if (visibleProjects.isEmpty()) {
            item {
                ProjectsWebEmptyState(
                    zh = zh,
                    onCreateProject = { openForm(null) },
                )
            }
        }
        items(visibleProjects) { project ->
            Column(modifier = Modifier.fillMaxWidth()) {
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { onProjectClick(project) }
                        .semantics { contentDescription = "Open Project ${project.name}" },
                    color = MulticaColors.Background,
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics { contentDescription = "Project Web Dense Row ${project.name}" }
                            .padding(vertical = 8.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Box(
                            modifier = Modifier
                                .size(28.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(MulticaColors.AccentSoft.copy(alpha = 0.22f)),
                            contentAlignment = Alignment.Center,
                        ) {
                            Text(
                                text = clean(project.icon).ifBlank { project.name.take(1).uppercase() },
                                modifier = Modifier.semantics { contentDescription = "Project Web Row Icon" },
                                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 14.sp),
                                color = MulticaColors.Accent,
                                maxLines = 1,
                                overflow = TextOverflow.Clip,
                            )
                        }
                        Column(
                            modifier = Modifier.weight(1f),
                            verticalArrangement = Arrangement.spacedBy(4.dp),
                        ) {
                            val descriptionText = clean(project.description).ifBlank {
                                projectLeadLabel(project, zh) ?: if (zh) "暂无描述" else "No description"
                            }
                            val total = project.issueCount.coerceAtLeast(0)
                            val done = project.doneCount.coerceIn(0, total.coerceAtLeast(project.doneCount))
                            val resourceHint = if (workspace.repos.isNotEmpty()) {
                                if (zh) "${workspace.repos.size} 个工作区 repo" else "${workspace.repos.size} workspace repos"
                            } else {
                                if (zh) "详情页关联资源" else "Resources in detail"
                            }
                            Text(
                                text = project.name,
                                modifier = Modifier.semantics { contentDescription = "Project Web Row Title" },
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = FontWeight.Medium,
                                    fontSize = 15.sp,
                                    lineHeight = 19.sp,
                                ),
                                color = MulticaColors.Text,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            Text(
                                text = descriptionText,
                                modifier = Modifier.semantics { contentDescription = "Project Web Row Description" },
                                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 14.sp),
                                color = MulticaColors.Muted,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            LazyRow(
                                horizontalArrangement = Arrangement.spacedBy(5.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                item {
                                    ProjectMetricCapsule(
                                        text = Models.priorityLabel(project.priority, zh),
                                        icon = Icons.Outlined.Flag,
                                        contentDescription = "Project Priority Capsule ${project.name}",
                                        tone = if (project.priority == "urgent" || project.priority == "high") MulticaColors.Warning else MulticaColors.Muted,
                                    )
                                }
                                item {
                                    ProjectMetricCapsule(
                                        text = Models.projectStatusLabel(project.status, zh),
                                        icon = Icons.Outlined.CheckCircle,
                                        contentDescription = "Project Status Capsule ${project.name}",
                                        tone = MulticaColors.Accent,
                                    )
                                }
                                item {
                                    ProjectMetricCapsule(
                                        text = if (total > 0) "$done/$total" else "--",
                                        icon = Icons.Outlined.CheckCircle,
                                        contentDescription = "Project Issue Metrics Capsule ${project.name}",
                                        tone = MulticaColors.Success,
                                        showProgress = total > 0,
                                        progress = if (total > 0) (done.toFloat() / total.toFloat()).coerceIn(0f, 1f) else 0f,
                                    )
                                }
                                item {
                                    ProjectMetricCapsule(
                                        text = resourceHint,
                                        icon = Icons.Outlined.Link,
                                        contentDescription = "Project Resource Hint Capsule ${project.name}",
                                        tone = MulticaColors.Muted,
                                    )
                                }
                                item {
                                    ProjectMetricCapsule(
                                        text = shortDate(project.createdAt).ifBlank { Models.shortId(project.id) },
                                        icon = Icons.Outlined.CalendarMonth,
                                        contentDescription = "Project Created Capsule ${project.name}",
                                        tone = MulticaColors.TextTertiary,
                                    )
                                }
                            }
                        }
                        MulticaIconPillButton(
                            icon = Icons.Outlined.MoreHoriz,
                            contentDescription = "Project Actions ${project.name}",
                            onClick = {
                                expandedProjectActionsId = if (expandedProjectActionsId == project.id) null else project.id
                                pendingDelete = null
                                formOpen = false
                                editingProject = null
                                resultText = null
                            },
                            tone = if (expandedProjectActionsId == project.id) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                            modifier = Modifier
                                .size(36.dp)
                                .semantics(mergeDescendants = true) {
                                    contentDescription = "Project Actions ${project.name}"
                                },
                        )
                    }
                }
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(MulticaColors.Border.copy(alpha = 0.74f))
                )
                if (expandedProjectActionsId == project.id) {
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 10.dp)) {
                        MulticaPillButton(
                            text = "${if (zh) "编辑项目" else "Edit Project"} ${project.name}",
                            onClick = { openForm(project) },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Secondary,
                        )
                        MulticaPillButton(
                            text = "${if (zh) "删除项目" else "Delete Project"} ${project.name}",
                            onClick = {
                                pendingDelete = project
                                formOpen = false
                                editingProject = null
                                expandedProjectActionsId = null
                                resultText = null
                            },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Destructive,
                        )
                    }
                }
                if (pendingDelete?.id == project.id) {
                    ProjectDeleteConfirmWebPanel(
                        project = project,
                        zh = zh,
                        isDeleting = deleting,
                        onCancel = { pendingDelete = null },
                        onConfirm = { deleteProject(project) },
                    )
                    Spacer(modifier = Modifier.height(10.dp))
                }
            }
        }
    }
}

@Composable
private fun ProjectMetricCapsule(
    text: String,
    icon: ImageVector,
    contentDescription: String,
    tone: Color,
    modifier: Modifier = Modifier,
    showProgress: Boolean = false,
    progress: Float = 0f,
) {
    Surface(
        modifier = modifier
            .semantics(mergeDescendants = true) {
                this.contentDescription = contentDescription
            },
        shape = RoundedCornerShape(999.dp),
        color = MulticaColors.SurfaceElevated.copy(alpha = 0.72f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.62f)),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 7.dp, vertical = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(4.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = tone,
                modifier = Modifier.size(11.dp),
            )
            if (showProgress) {
                Box(
                    modifier = Modifier
                        .width(26.dp)
                        .height(4.dp)
                        .clip(RoundedCornerShape(999.dp))
                        .background(MulticaColors.Border.copy(alpha = 0.72f))
                        .semantics { this.contentDescription = "Project Progress Track" },
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(progress)
                            .height(4.dp)
                            .clip(RoundedCornerShape(999.dp))
                            .background(MulticaColors.Success),
                    )
                }
            }
            Text(
                text = text,
                modifier = Modifier.weight(1f),
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.Medium),
                color = MulticaColors.Muted,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

