@Composable
private fun ProjectSkeletonBlock(
    modifier: Modifier = Modifier,
    width: Dp? = null,
    height: Dp,
) {
    Box(
        modifier = modifier
            .then(if (width != null) Modifier.width(width) else Modifier)
            .height(height)
            .clip(RoundedCornerShape(999.dp))
            .background(MulticaColors.Border.copy(alpha = 0.42f)),
    )
}

