@Composable
private fun PilotInlineResultState(
    message: String,
    isError: Boolean,
    contentDescription: String,
    modifier: Modifier = Modifier,
) {
    val tone = if (isError) MulticaColors.Danger else MulticaColors.Success
    val icon = if (isError) Icons.Outlined.Close else Icons.Outlined.CheckCircle
    Surface(
        modifier = modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) { this.contentDescription = contentDescription },
        shape = RoundedCornerShape(12.dp),
        color = tone.copy(alpha = 0.08f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, tone.copy(alpha = 0.20f), RoundedCornerShape(12.dp))
                .padding(horizontal = 11.dp, vertical = 9.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(icon, contentDescription = null, tint = tone, modifier = Modifier.size(17.dp))
            Text(
                text = message,
                style = MaterialTheme.typography.bodySmall.copy(fontSize = 13.sp, lineHeight = 17.sp, fontWeight = FontWeight.SemiBold),
                color = tone,
                maxLines = 3,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

private fun pilotInlineResultIsError(message: String): Boolean =
    message.contains("failed", ignoreCase = true) ||
        message.contains("失败") ||
        message.contains("请选择") ||
        message.contains("请输入") ||
        message.startsWith("Enter ", ignoreCase = true) ||
        message.contains("没有可关联")

