@Composable
private fun PilotSettings(
    api: ApiClient,
    session: PilotSession,
    zh: Boolean,
    authStore: AuthStore,
    profileOpen: Boolean,
    onProfileOpenChange: (Boolean) -> Unit,
    onOpenSettingsPage: (PilotSettingsPage) -> Unit,
    onReloadSession: () -> Unit,
    onSessionUpdated: (PilotSession) -> Unit,
) {
    var profileName by remember(session.user.id, session.user.name) { mutableStateOf(session.user.name) }
    var profileAvatar by remember(session.user.id, session.user.avatarUrl) { mutableStateOf(session.user.avatarUrl) }
    var profileSaving by remember(session.user.id) { mutableStateOf(false) }
    var profileUploadingAvatar by remember(session.user.id) { mutableStateOf(false) }
    var profileMessage by remember(session.user.id) { mutableStateOf<String?>(null) }
    var settingsHomeStatusSummary by remember(session.user.id, session.workspace.id) {
        mutableStateOf(SettingsHomeStatusSummary(null, null, null, null))
    }
    var confirmingLogout by remember(session.user.id) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    LaunchedEffect(session.user.id, session.workspace.id, zh) {
        settingsHomeStatusSummary = withContext(Dispatchers.IO) {
            val pending = runCatching { api.myInvitations().size }.getOrNull()
            val tokens = runCatching { api.personalAccessTokens().size }.getOrNull()
            val runtimes = runCatching { api.runtimes(session.workspace.id) }.getOrNull()
            val runtimeHint = runtimes?.let { list ->
                val updateRelated = list.count { runtime ->
                    runtime.status.contains("update", ignoreCase = true) ||
                        runtime.status.contains("outdated", ignoreCase = true)
                }
                if (updateRelated > 0) {
                    if (zh) "$updateRelated 个更新提示" else "$updateRelated update hints"
                } else {
                    if (zh) "详情页检查更新" else "Check updates in detail"
                }
            }
            SettingsHomeStatusSummary(
                pendingInvitationCount = pending,
                tokenCount = tokens,
                runtimeCount = runtimes?.size,
                runtimeUpdateHint = runtimeHint,
            )
        }
    }
    val profileAvatarLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        if (uri == null || profileUploadingAvatar) return@rememberLauncherForActivityResult
        profileUploadingAvatar = true
        profileMessage = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() } ?: ByteArray(0)
                    api.uploadFile(
                        session.workspace.id,
                        displayNameForUri(context, uri),
                        context.contentResolver.getType(uri) ?: "application/octet-stream",
                        bytes,
                    )
                }
            }
            profileUploadingAvatar = false
            result.onSuccess { uploadedUrl ->
                profileAvatar = uploadedUrl
                profileMessage = if (zh) "头像已上传，请保存资料" else "Avatar uploaded. Save profile to apply."
            }.onFailure {
                profileMessage = "${if (zh) "头像上传失败" else "Avatar upload failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun saveProfile() {
        val name = profileName.trim()
        if (name.isBlank() || profileSaving) return
        profileSaving = true
        profileMessage = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    api.updateMe(
                        name,
                        profileAvatar.trim(),
                        null,
                    )
                }
            }
            profileSaving = false
            result.onSuccess { updatedUser ->
                onProfileOpenChange(false)
                profileMessage = if (zh) "账号资料已保存" else "Profile saved"
                onSessionUpdated(session.copy(user = updatedUser))
            }.onFailure {
                profileMessage = "${if (zh) "保存账号资料失败" else "Profile save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun switchLanguage() {
        val nextChinese = !zh
        val nextLanguage = if (nextChinese) "zh-Hans" else "en"
        authStore.setChinese(nextChinese)
        scope.launch {
            withContext(Dispatchers.IO) {
                runCatching { api.updateMe(null, null, nextLanguage) }
            }
            onReloadSession()
        }
    }
    val WEB_SSOT_SETTINGS_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/settings/components/settings-page.tsx"
    val WEB_SSOT_SETTINGS_LOCALE = "/Users/park0er/coding/multica-web-source/packages/views/locales/en/settings.json"

    if (profileOpen) {
        PilotListPage(
            title = if (zh) "账号资料" else "Account Profile",
            leading = {
                MulticaIconPillButton(
                    icon = Icons.Outlined.ArrowBack,
                    contentDescription = if (zh) "返回设置" else "Back to Settings",
                    onClick = { onProfileOpenChange(false) },
                    tone = MulticaButtonTone.Ghost,
                )
            },
            trailing = {
                MulticaPillButton(
                    text = if (profileSaving) "..." else if (zh) "保存" else "Save",
                    onClick = { saveProfile() },
                    tone = MulticaButtonTone.Primary,
                    enabled = profileName.trim().isNotBlank() && !profileSaving,
                    contentDescription = "Account Profile Save",
                )
            },
            bottomContent = {
                MulticaHazeBottomBar(
                    hazeState = rememberHazeState(),
                    contentDescription = "Account Profile Bottom Haze Save Bar",
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 26.dp, vertical = 14.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaPillButton(
                            text = if (zh) "取消" else "Cancel",
                            onClick = { onProfileOpenChange(false) },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Ghost,
                        )
                        MulticaPillButton(
                            text = if (profileSaving) "..." else if (zh) "保存资料" else "Save Profile",
                            onClick = { saveProfile() },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Primary,
                            enabled = profileName.trim().isNotBlank() && !profileSaving,
                            contentDescription = "Account Profile Bottom Save",
                        )
                    }
                }
            },
        ) {
            if (!profileMessage.isNullOrBlank()) {
                item {
                    PilotInlineResultState(
                        message = profileMessage.orEmpty(),
                        isError = pilotInlineResultIsError(profileMessage.orEmpty()),
                        contentDescription = "Account Profile Result Web Banner",
                    )
                }
            }
            item {
                AccountProfileWebEditor(
                    name = profileName,
                    avatarUrl = profileAvatar,
                    uploadingAvatar = profileUploadingAvatar,
                    zh = zh,
                    onNameChange = { profileName = it },
                    onAvatarUrlChange = { profileAvatar = it },
                    onUploadAvatar = { if (!profileUploadingAvatar) profileAvatarLauncher.launch("image/*") },
                )
            }
        }
        return
    }

    PilotListPage(title = if (zh) "设置" else "Settings") {
        item {
            Box(
                modifier = Modifier.semantics(mergeDescendants = false) {
                    contentDescription = "Settings Home Web SSOT $WEB_SSOT_SETTINGS_PAGE $WEB_SSOT_SETTINGS_LOCALE"
                },
            ) {
                SettingsWebAccountHeader(
