@Composable
private fun PilotSettingsSubpage(
    page: PilotSettingsPage,
    api: ApiClient,
    workspaceId: String,
    currentUserId: String,
    zh: Boolean,
    onReloadSession: () -> Unit,
    onSwitchWorkspace: (String) -> Unit,
    onBack: () -> Unit,
) {
    when (page) {
        PilotSettingsPage.WorkspaceDetails -> PilotWorkspaceSettings(api, workspaceId, currentUserId, zh, onBack, onReloadSession, onSwitchWorkspace)
        PilotSettingsPage.MyInvitations -> PilotMyInvitationsSettings(api, zh, onBack, onReloadSession)
        PilotSettingsPage.Members -> PilotMembersSettings(api, workspaceId, currentUserId, zh, onBack)
        PilotSettingsPage.Notifications -> PilotNotificationSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.ApiTokens -> PilotApiTokensSettings(api, zh, onBack)
        PilotSettingsPage.Agents -> PilotAgentsSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.Autopilots -> PilotAutopilotsSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.Runtimes -> PilotRuntimesSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.Labels -> PilotLabelsSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.Skills -> PilotSkillsSettings(api, workspaceId, zh, onBack)
        PilotSettingsPage.Feedback -> PilotFeedbackSettings(api, workspaceId, zh, onBack)
    }
}

@Composable
private fun PilotMyInvitationsSettings(
    api: ApiClient,
    zh: Boolean,
    onBack: () -> Unit,
    onReloadSession: () -> Unit,
) {
    val WEB_SSOT_INVITATIONS_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/invitations/invitations-page.tsx"
    val WEB_SSOT_INVITE_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/invite/invite-page.tsx"
    var refresh by remember { mutableIntStateOf(0) }
    var state by remember { mutableStateOf<Result<PilotMyInvitationsSettingsData>?>(null) }
    var mutatingId by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching { PilotMyInvitationsSettingsData(api.myInvitations()) }
        }
    }

    fun mutate(invitation: Models.Invitation, accept: Boolean) {
        if (invitation.id.isBlank() || mutatingId != null) return
        mutatingId = invitation.id
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    if (accept) api.acceptInvitation(invitation.id) else api.declineInvitation(invitation.id)
                }
            }
            mutatingId = null
            result.onSuccess {
                message = if (accept) {
                    if (zh) "邀请已接受" else "Invitation accepted"
                } else {
                    if (zh) "邀请已拒绝" else "Invitation declined"
                }
                refresh++
                if (accept) onReloadSession()
            }.onFailure {
                message = "${if (accept) {
                    if (zh) "接受邀请失败" else "Accept invitation failed"
                } else {
                    if (zh) "拒绝邀请失败" else "Decline invitation failed"
                }}: ${it.message ?: it.toString()}"
            }
        }
    }

    PilotListPage(
        title = if (zh) "我的邀请" else "My Invitations",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        if (!message.isNullOrBlank()) {
            item {
                PilotInlineResultState(
                    message = message.orEmpty(),
                    isError = pilotInlineResultIsError(message.orEmpty()),
                    contentDescription = "My Invitations Result Web Banner",
                    modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
                )
            }
        }
        val loaded = state
        when {
            loaded == null -> item { MulticaLoadingState(if (zh) "正在加载邀请..." else "Loading invitations...") }
            loaded.isFailure -> item {
                MulticaErrorState(
                    message = "${if (zh) "邀请加载失败" else "Invitations failed"}\n${loaded.exceptionOrNull()?.message ?: loaded.exceptionOrNull().toString()}",
                    onRetry = { refresh++ },
                )
            }
            else -> {
                val invitations = loaded.getOrThrow().invitations
                item { SettingsSectionLabel(if (zh) "待处理邀请" else "Pending Invitations") }
                if (invitations.isEmpty()) {
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "待处理邀请" else "Pending Invitations",
                            subtitle = if (zh) "新的 workspace 邀请会显示在这里" else "New workspace invitations appear here.",
                            contentDescription = "My Invitations Web Empty Group $WEB_SSOT_INVITATIONS_PAGE $WEB_SSOT_INVITE_PAGE",
                        ) {
                            MulticaCupertinoListRow(
                                title = if (zh) "暂无待处理邀请" else "No pending invitations",
                                subtitle = if (zh) "新的 workspace 邀请会显示在这里" else "New workspace invitations appear here.",
                                leadingIcon = Icons.Outlined.Link,
                                contentDescription = "My Invitations Compact Empty State",
                                onClick = {},
                            )
                        }
                    }
                } else {
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "待处理邀请" else "Pending Invitations",
                            subtitle = if (zh) "${invitations.size} 个待处理 workspace 邀请" else "${invitations.size} pending workspace invitations",
                            contentDescription = "My Invitations Web List Group $WEB_SSOT_INVITATIONS_PAGE $WEB_SSOT_INVITE_PAGE",
                        ) {
                            invitations.forEachIndexed { index, invitation ->
                                MyInvitationWebDenseRow(
                                    invitation = invitation,
                                    busy = mutatingId == invitation.id,
                                    zh = zh,
                                    showDivider = index < invitations.lastIndex,
                                    onAccept = { mutate(invitation, true) },
                                    onDecline = { mutate(invitation, false) },
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun MyInvitationWebDenseRow(
    invitation: Models.Invitation,
    busy: Boolean,
    zh: Boolean,
    showDivider: Boolean,
    onAccept: () -> Unit,
    onDecline: () -> Unit,
) {
    val WEB_SSOT_INVITATIONS_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/invitations/invitations-page.tsx"
    val WEB_SSOT_INVITE_PAGE = "/Users/park0er/coding/multica-web-source/packages/views/invite/invite-page.tsx"
    var actionsOpen by remember { mutableStateOf(false) }
    val workspaceTitle = invitation.workspaceName.ifBlank { Models.shortId(invitation.workspaceId) }
    val inviter = invitation.inviterName.ifBlank {
        invitation.inviterEmail.ifBlank { if (zh) "未知邀请人" else "Unknown inviter" }
    }
    val role = invitation.role.ifBlank { "member" }
    val status = invitation.status.ifBlank { "pending" }
    val created = invitation.createdAt.ifBlank { invitation.updatedAt }
    val createdText = if (created.isBlank()) {
        if (zh) "创建时间未知" else "Created date unavailable"
    } else {
        "${if (zh) "创建" else "Created"} ${shortDate(created)}"
    }
    val inviterText = if (zh) "邀请人：$inviter" else "Invited by $inviter"
    val roleText = when (role.lowercase(Locale.getDefault())) {
        "admin" -> if (zh) "管理员" else "Admin"
        "owner" -> if (zh) "所有者" else "Owner"
        else -> if (zh) "成员" else "Member"
    }
    val statusText = when (status.lowercase(Locale.getDefault())) {
        "accepted" -> if (zh) "已接受" else "Accepted"
        "declined" -> if (zh) "已拒绝" else "Declined"
        else -> if (zh) "待处理" else "Pending"
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = false) {
                contentDescription = "My Invitation Web Dense Row ${invitation.id} $WEB_SSOT_INVITATIONS_PAGE $WEB_SSOT_INVITE_PAGE"
            },
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 10.dp),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.Top,
        ) {
            Surface(
                modifier = Modifier
                    .size(34.dp)
                    .padding(top = 2.dp),
                shape = RoundedCornerShape(999.dp),
                color = MulticaColors.Border.copy(alpha = 0.42f),
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Icon(Icons.Outlined.Link, contentDescription = null, tint = MulticaColors.Muted, modifier = Modifier.size(15.dp))
                }
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                Text(
                    text = workspaceTitle,
                    modifier = Modifier.semantics {
                        contentDescription = "My Invitation Workspace Name ${invitation.id}"
                    },
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 13.sp, lineHeight = 16.sp, fontWeight = FontWeight.Medium),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = inviterText,
                    modifier = Modifier.semantics {
                        contentDescription = "My Invitation Inviter Metadata ${invitation.id}"
                    },
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically) {
                    InvitationMetadataCapsule(
                        text = roleText,
                        contentDescription = "My Invitation Role Capsule ${invitation.id}",
                        tone = MulticaColors.Accent,
                    )
                    InvitationMetadataCapsule(
                        text = statusText,
                        contentDescription = "My Invitation Status Capsule ${invitation.id}",
                        tone = MulticaColors.Warning,
                    )
                    InvitationMetadataCapsule(
                        text = createdText,
                        contentDescription = "My Invitation Created Metadata ${invitation.id}",
                        tone = MulticaColors.Muted,
                    )
                }
            }
            MulticaIconPillButton(
                icon = Icons.Outlined.MoreHoriz,
                contentDescription = "My Invitation Actions Menu ${invitation.id}",
                enabled = !busy,
                onClick = { actionsOpen = true },
                tone = MulticaButtonTone.Ghost,
                modifier = Modifier
                    .size(34.dp)
                    .semantics { contentDescription = "My Invitation Actions Menu ${invitation.id}" },
            )
        }
        if (showDivider) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border)
            )
        }
        if (actionsOpen) {
            Spacer(
                modifier = Modifier
                    .size(1.dp)
                    .semantics { contentDescription = "My Invitation Actions Sheet ${invitation.id}" },
            )
        }
        MulticaCupertinoActionSheet(
            visible = actionsOpen,
            title = if (zh) "邀请操作" else "Invitation actions",
            message = "$workspaceTitle · $roleText · $createdText",
            items = listOf(
                MulticaCupertinoActionSheetItem(
                    title = if (busy) "..." else if (zh) "接受邀请" else "Accept invitation",
                    subtitle = if (zh) "加入 $workspaceTitle 并刷新工作区" else "Join $workspaceTitle and refresh workspace",
                    contentDescription = "My Invitation Accept Action ${invitation.id}",
                    enabled = !busy,
                    selected = false,
                    onClick = onAccept,
                ),
                MulticaCupertinoActionSheetItem(
                    title = if (busy) "..." else if (zh) "拒绝邀请" else "Decline invitation",
                    subtitle = if (zh) "保留当前 workspace，并移除此邀请" else "Keep your current workspace and remove this invitation",
                    contentDescription = "My Invitation Decline Action ${invitation.id}",
                    destructive = true,
                    enabled = !busy,
                    onClick = onDecline,
                ),
            ),
            cancelText = if (zh) "取消" else "Cancel",
            onDismissRequest = { actionsOpen = false },
        )
    }
}

@Composable
private fun InvitationMetadataCapsule(
    text: String,
    contentDescription: String,
    tone: Color,
) {
    Surface(
        modifier = Modifier.semantics(mergeDescendants = true) {
            this.contentDescription = contentDescription
        },
        shape = RoundedCornerShape(999.dp),
        color = MulticaColors.SurfaceElevated.copy(alpha = 0.78f),
        border = androidx.compose.foundation.BorderStroke(1.dp, MulticaColors.Border.copy(alpha = 0.68f)),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Text(
            text = text,
            style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.Medium),
            color = tone,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.padding(horizontal = 7.dp, vertical = 4.dp),
        )
    }
}

