private fun notificationPreferencesWithValues(
    workspaceId: String,
    values: Map<String, String>,
): Models.NotificationPreferences {
    val preferences = JSONObject()
    values.forEach { (key, value) ->
        if (value.isNotBlank() && value != "all") {
            preferences.put(key, value)
        }
    }
    return Models.NotificationPreferences(
        JSONObject()
            .put("workspace_id", workspaceId)
            .put("preferences", preferences)
    )
}

private enum class MemberSettingsMode { List, Invite }

@Composable
private fun PilotMembersSettings(
    api: ApiClient,
    workspaceId: String,
    currentUserId: String,
    zh: Boolean,
    onBack: () -> Unit,
) {
    var state by remember(workspaceId) { mutableStateOf<Result<PilotMembersSettingsData>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var memberSettingsMode by remember(workspaceId) { mutableStateOf(MemberSettingsMode.List) }
    var email by remember(workspaceId) { mutableStateOf("") }
    var inviteRole by remember(workspaceId) { mutableStateOf("member") }
    var saving by remember(workspaceId) { mutableStateOf(false) }
    var revokingId by remember(workspaceId) { mutableStateOf<String?>(null) }
    var memberActionId by remember(workspaceId) { mutableStateOf<String?>(null) }
    var pendingRemove by remember(workspaceId) { mutableStateOf<Models.Member?>(null) }
    var pendingRevoke by remember(workspaceId) { mutableStateOf<Models.Invitation?>(null) }
    var memberMenu by remember(workspaceId) { mutableStateOf<Models.Member?>(null) }
    var rolePickerMember by remember(workspaceId) { mutableStateOf<Models.Member?>(null) }
    var message by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                PilotMembersSettingsData(
                    members = api.members(workspaceId),
                    invitations = api.workspaceInvitations(workspaceId),
                )
            }
        }
    }

    BackHandler(enabled = memberSettingsMode != MemberSettingsMode.List) {
        memberSettingsMode = MemberSettingsMode.List
    }

    fun invite() {
        val value = email.trim()
        if (value.isBlank() || saving) return
        saving = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.createMemberInvitation(workspaceId, value, inviteRole) }
            }
            saving = false
            result.onSuccess {
                email = ""
                inviteRole = "member"
                message = if (zh) "邀请已发送" else "Invitation sent"
                memberSettingsMode = MemberSettingsMode.List
                refresh++
            }.onFailure {
                message = "${if (zh) "邀请失败" else "Invite failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun updateRole(member: Models.Member, role: String) {
        if (memberActionId != null || role == member.role) return
        memberActionId = member.id
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.updateMemberRole(workspaceId, member.id, role) }
            }
            memberActionId = null
            result.onSuccess {
                message = if (zh) "成员角色已更新" else "Member role updated"
                refresh++
            }.onFailure {
                message = "${if (zh) "角色更新失败" else "Role update failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun removeMember(member: Models.Member) {
        if (memberActionId != null) return
        memberActionId = member.id
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.deleteMember(workspaceId, member.id) }
            }
            memberActionId = null
            result.onSuccess {
                pendingRemove = null
                message = if (zh) "成员已移除" else "Member removed"
                refresh++
            }.onFailure {
                message = "${if (zh) "移除成员失败" else "Remove member failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun revoke(invitation: Models.Invitation) {
        if (revokingId != null) return
        revokingId = invitation.id
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.revokeInvitation(workspaceId, invitation.id) }
            }
            revokingId = null
            result.onSuccess {
                pendingRevoke = null
                message = if (zh) "邀请已撤销" else "Invitation revoked"
                refresh++
            }.onFailure {
                message = "${if (zh) "撤销失败" else "Revoke failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (memberSettingsMode == MemberSettingsMode.Invite) {
        PilotListPage(
            title = if (zh) "邀请成员" else "Invite Member",
            trailing = {
                MulticaPillButton(
                    text = if (zh) "成员" else "Members",
                    onClick = { memberSettingsMode = MemberSettingsMode.List },
                    tone = MulticaButtonTone.Secondary,
                    contentDescription = "Back to Members",
                )
            },
            bottomContent = {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MulticaColors.Surface)
                        .padding(horizontal = 20.dp, vertical = 14.dp)
                        .imePadding(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    MulticaPillButton(
                        text = if (zh) "取消" else "Cancel",
                        onClick = { memberSettingsMode = MemberSettingsMode.List },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Secondary,
                    )
                    MulticaPillButton(
                        text = if (saving) "..." else if (zh) "发送邀请" else "Send Invite",
                        onClick = { invite() },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Primary,
                    )
                }
            },
        ) {
            item {
                SettingsSectionLabel(if (zh) "成员邀请" else "Member Invitation")
                MulticaTextField(
                    value = email,
                    onValueChange = { email = it },
                    label = if (zh) "邮箱地址" else "Email address",
                    singleLine = true,
                    contentDescription = "Member Invite Form Email",
                    modifier = Modifier.padding(bottom = 12.dp),
                )
                MemberInviteRolePicker(
                    selectedRole = inviteRole,
                    zh = zh,
                    onRoleChange = { inviteRole = it },
                )
            }
            if (!message.isNullOrBlank()) {
                item {
                    PilotInlineResultState(
                        message = message.orEmpty(),
                        isError = pilotInlineResultIsError(message.orEmpty()),
                        contentDescription = "Members Result Web Banner",
                        modifier = Modifier.padding(top = 12.dp),
                    )
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "成员" else "Members",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载成员..." else "Loading members...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "成员加载失败" else "Members failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { data ->
                    val currentMember = data.members.firstOrNull { it.userId == currentUserId }
                    val canManage = currentMember?.role == "owner" || currentMember?.role == "admin"
                    val canManageOwners = currentMember?.role == "owner"
                    val ownerCount = data.members.count { it.role == "owner" }
                    if (canManage) {
                        item {
                            SettingsWebTabGroup(
                                title = if (zh) "管理" else "Manage",
                                subtitle = if (zh) "邀请成员并指定 workspace role" else "Invite members and assign workspace roles",
                                contentDescription = "Members Web Invite Entry Member Invite Entry",
                            ) {
                                SettingsWebTabRow(
                                    title = if (zh) "邀请成员" else "Invite Member",
                                    subtitle = if (zh) "发送邮件邀请并指定成员角色" else "Send an email invite and choose a workspace role",
                                    icon = Icons.Outlined.Add,
                                    onClick = { memberSettingsMode = MemberSettingsMode.Invite },
                                    contentDescription = "Members Web Invite Entry Row",
                                )
                            }
                        }
                    }
                    if (!message.isNullOrBlank()) {
                        item {
                            PilotInlineResultState(
                                message = message.orEmpty(),
                                isError = pilotInlineResultIsError(message.orEmpty()),
                                contentDescription = "Members Result Web Banner",
                            )
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "当前成员" else "Current Members",
                            subtitle = if (zh) "${data.members.size} 个 workspace 成员" else "${data.members.size} workspace members",
                        ) {
                            if (data.members.isEmpty()) {
                                CompactIssueRow(
                                    eyebrow = if (zh) "空" else "Empty",
                                    title = if (zh) "暂无成员" else "No members",
                                    trailing = null,
                                )
                            } else {
                                data.members.forEachIndexed { index, member ->
                                    val isSelf = member.userId == currentUserId
                                    val isLastOwner = member.role == "owner" && ownerCount <= 1
                                    val canEditRole = canManage && !isSelf && !isLastOwner && (member.role != "owner" || canManageOwners)
                                    val canRemove = canManage && !isSelf && !isLastOwner && (member.role != "owner" || canManageOwners)
                                    val roleOptions = buildList {
                                        add("member")
                                        add("admin")
                                        if (canManageOwners) add("owner")
                                    }
                                    MemberWebDenseRow(
                                        member = member,
                                        isSelf = isSelf,
                                        busy = memberActionId == member.id,
                                        canEditRole = canEditRole && roleOptions.isNotEmpty(),
                                        canRemove = canRemove,
                                        canManage = canManage,
                                        isLastOwner = isLastOwner,
                                        zh = zh,
                                        showDivider = index < data.members.lastIndex,
                                        onOpenMenu = { memberMenu = member },
                                        onRemove = { pendingRemove = member },
                                    )
                                }
                            }
                        }
                    }
                    memberMenu?.let { member ->
                        item {
                            MemberMoreActionSheet(
                                member = member,
                                zh = zh,
                                canEditRole = canManage && member.userId != currentUserId && !(member.role == "owner" && ownerCount <= 1) && (member.role != "owner" || canManageOwners),
                                canRemove = canManage && member.userId != currentUserId && !(member.role == "owner" && ownerCount <= 1) && (member.role != "owner" || canManageOwners),
                                onDismiss = { memberMenu = null },
                                onChangeRole = {
                                    rolePickerMember = member
                                    memberMenu = null
                                },
                                onRemove = {
                                    pendingRemove = member
                                    memberMenu = null
                                },
                            )
                        }
                    }
                    rolePickerMember?.let { member ->
                        item {
                            MemberRolePickerActionSheet(
                                member = member,
                                canManageOwners = canManageOwners,
                                zh = zh,
                                onDismiss = { rolePickerMember = null },
                                onRoleChange = { role ->
                                    rolePickerMember = null
                                    updateRole(member, role)
                                },
                            )
                        }
                    }
                    pendingRemove?.let { member ->
                        item {
                            MulticaCupertinoAlertDialog(
                                visible = true,
                                title = if (zh) "移除成员？" else "Remove member?",
                                message = if (zh) {
                                    "${member.displayName} 会从当前 workspace 移除；已创建内容会保留。"
                                } else {
                                    "${member.displayName} will be removed from this workspace. Existing authored content remains."
                                },
                                cancelText = if (zh) "取消" else "Cancel",
                                confirmText = if (memberActionId == member.id) "..." else if (zh) "移除" else "Remove",
                                destructive = true,
                                contentDescription = "Member Remove Cupertino Alert ${member.id}",
                                onDismissRequest = { pendingRemove = null },
                                onConfirm = { removeMember(member) },
                            )
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "待处理邀请" else "Pending Invitations",
                            subtitle = if (zh) "${data.invitations.size} 个待处理邀请" else "${data.invitations.size} pending invitations",
                        ) {
                            if (data.invitations.isEmpty()) {
                                CompactIssueRow(
                                    eyebrow = if (zh) "空" else "Empty",
                                    title = if (zh) "暂无邀请" else "No pending invitations",
                                )
                            } else {
                                data.invitations.forEachIndexed { index, invitation ->
                                    MemberInvitationWebDenseRow(
                                        invitation = invitation,
                                        busy = revokingId == invitation.id,
                                        canManage = canManage,
                                        zh = zh,
                                        showDivider = index < data.invitations.lastIndex,
                                        onRevoke = { pendingRevoke = invitation },
                                    )
                                }
                            }
                        }
                    }
                    pendingRevoke?.let { invitation ->
                        item {
                            MulticaCupertinoAlertDialog(
                                visible = true,
                                title = if (zh) "撤销邀请？" else "Revoke invitation?",
                                message = if (zh) {
                                    "${invitation.inviteeEmail.ifBlank { Models.shortId(invitation.id) }} 将不再能通过此邀请加入 workspace。"
                                } else {
                                    "${invitation.inviteeEmail.ifBlank { Models.shortId(invitation.id) }} will no longer be able to join from this invitation."
                                },
                                cancelText = if (zh) "取消" else "Cancel",
                                confirmText = if (revokingId == invitation.id) "..." else if (zh) "撤销" else "Revoke",
                                destructive = true,
                                contentDescription = "Members Invitation Revoke Cupertino Alert ${invitation.id}",
                                onDismissRequest = { pendingRevoke = null },
                                onConfirm = { revoke(invitation) },
                            )
                        }
                    }
                }
            }
        }
    }
}

