@Composable
private fun MemberRolePickerActionSheet(
    member: Models.Member,
    canManageOwners: Boolean,
    zh: Boolean,
    onDismiss: () -> Unit,
    onRoleChange: (String) -> Unit,
) {
    val roles = listOf("owner", "admin", "member")
    MulticaCupertinoActionSheet(
        visible = true,
        title = if (zh) "选择角色" else "Choose role",
        message = if (zh) "成员角色会影响 workspace 管理权限" else "Member roles control workspace management access",
        items = roles.map { role ->
            val ownerDisabled = role == "owner" && !canManageOwners
            MulticaCupertinoActionSheetItem(
                title = memberRoleLabel(role, zh),
                subtitle = memberRoleDescription(role, ownerDisabled, zh),
                icon = memberRoleIcon(role),
                contentDescription = when (role) {
                    "owner" -> "Member Role Option Owner"
                    "admin" -> "Member Role Option Admin"
                    else -> "Member Role Option Member"
                },
                selected = member.role == role,
                enabled = !ownerDisabled,
                onClick = { onRoleChange(role) },
            )
        },
        cancelText = if (zh) "取消" else "Cancel",
        onDismissRequest = onDismiss,
    )
}

private fun memberRoleLabel(role: String, zh: Boolean): String = when (role) {
    "owner" -> if (zh) "所有者" else "Owner"
    "admin" -> if (zh) "管理员" else "Admin"
    else -> if (zh) "成员" else "Member"
}

private fun memberRoleDescription(role: String, disabledOwner: Boolean, zh: Boolean): String = when {
    disabledOwner -> if (zh) "只有 owner 可以授予 owner" else "Only owners can grant owner"
    role == "owner" -> if (zh) "完整管理权限，包括 owner 管理" else "Full access, including owner management"
    role == "admin" -> if (zh) "管理成员与 workspace 设置" else "Manage members and workspace settings"
    else -> if (zh) "参与协作，无管理权限" else "Collaborate without admin access"
}

private fun memberRoleIcon(role: String): ImageVector = when (role) {
    "owner" -> Icons.Outlined.Key
    "admin" -> Icons.Outlined.CheckCircle
    else -> Icons.Outlined.Person
}

