@Composable
private fun PilotNotificationSettings(
    api: ApiClient,
    workspaceId: String,
    zh: Boolean,
    onBack: () -> Unit,
) {
    var state by remember(workspaceId) { mutableStateOf<Result<Models.NotificationPreferences>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var mutatingKey by remember(workspaceId) { mutableStateOf<String?>(null) }
    var message by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching { api.notificationPreferences(workspaceId) }
        }
    }

    fun toggle(preferences: Models.NotificationPreferences, key: String) {
        if (mutatingKey != null) return
        val previousState = state
        val next = if (preferences.value(key) == "muted") "all" else "muted"
        val updated = LinkedHashMap<String, String>(preferences.values)
        if (next == "all") updated.remove(key) else updated[key] = next
        val optimisticPreferences = notificationPreferencesWithValues(
            preferences.workspaceId.ifBlank { workspaceId },
            updated,
        )
        state = Result.success(optimisticPreferences)
        mutatingKey = key
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.updateNotificationPreferences(workspaceId, updated) }
            }
            mutatingKey = null
            result.onSuccess {
                state = Result.success(it)
                message = if (zh) "通知偏好已更新" else "Notification preferences updated"
            }.onFailure {
                state = previousState
                message = "${if (zh) "通知偏好更新失败" else "Notification update failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    PilotListPage(
        title = if (zh) "通知" else "Notifications",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载通知偏好..." else "Loading notification preferences...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "通知加载失败" else "Notifications failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { preferences ->
                    item {
                        // NotificationWebSwitchRow owns CupertinoSwitch( so this page stays Cupertino-first.
                        SettingsWebTabGroup(
                            title = if (zh) "收件箱通知" else "Inbox Notifications",
                            subtitle = notificationInboxFooter(zh),
                            contentDescription = "Notifications Web Inbox Group $WEB_SSOT_NOTIFICATIONS_TAB",
                        ) {
                            notificationInboxPreferenceKeys.forEachIndexed { index, key ->
                                val value = preferences.value(key)
                                NotificationWebSwitchRow(
                                    title = notificationPreferenceLabel(key, zh),
                                    subtitle = notificationPreferenceDescription(key, zh),
                                    checked = value != "muted",
                                    saving = mutatingKey == key,
                                    showDivider = index < notificationInboxPreferenceKeys.lastIndex,
                                    contentDescription = "Notification ${key} Cupertino Switch",
                                    onClick = { toggle(preferences, key) },
                                )
                            }
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "系统通知" else "System notifications",
                            subtitle = notificationSystemFooter(zh),
                            contentDescription = "Notifications Web System Group $WEB_SSOT_NOTIFICATIONS_TAB $WEB_SSOT_NOTIFICATIONS_LOCALE_EN $WEB_SSOT_NOTIFICATIONS_LOCALE_ZH",
                        ) {
                            val key = "system_notifications"
                            val value = preferences.value(key)
                            NotificationWebSwitchRow(
                                title = if (zh) "显示系统通知" else "Show system notifications",
                                subtitle = notificationPreferenceDescription(key, zh),
                                checked = value != "muted",
                                saving = mutatingKey == key,
                                contentDescription = "Notification ${key} Cupertino Switch",
                                onClick = { toggle(preferences, key) },
                            )
                        }
                    }
                    if (!message.isNullOrBlank()) {
                        item {
                            PilotInlineResultState(
                                message = message.orEmpty(),
                                isError = pilotInlineResultIsError(message.orEmpty()),
                                contentDescription = "Notifications Result Web Banner",
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun PilotNotificationSettingsPreview() {
    var preferences by remember {
        mutableStateOf(
            notificationPreferencesWithValues(
                workspaceId = "preview-workspace",
                values = linkedMapOf("comments" to "muted", "system_notifications" to "muted"),
            )
        )
    }
    var mutatingKey by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }

    fun togglePreview(key: String) {
        if (mutatingKey != null) return
        val next = if (preferences.value(key) == "muted") "all" else "muted"
        val updated = LinkedHashMap<String, String>(preferences.values)
        if (next == "all") updated.remove(key) else updated[key] = next
        mutatingKey = key
        preferences = notificationPreferencesWithValues(preferences.workspaceId, updated)
        message = if (next == "all") "Notification enabled" else "Notification muted"
        mutatingKey = null
    }

    PilotListPage(
        title = "Notifications",
        leading = { PilotSecondaryBackButton(zh = false, onBack = {}) },
    ) {
        item {
            SettingsWebTabGroup(
                title = "Inbox Notifications",
                subtitle = notificationInboxFooter(zh = false),
                contentDescription = "Notifications Web Inbox Group Preview $WEB_SSOT_NOTIFICATIONS_TAB",
            ) {
                notificationInboxPreferenceKeys.forEachIndexed { index, key ->
                    NotificationWebSwitchRow(
                        title = notificationPreferenceLabel(key, zh = false),
                        subtitle = notificationPreferenceDescription(key, zh = false),
                        checked = preferences.value(key) != "muted",
                        saving = mutatingKey == key,
                        showDivider = index < notificationInboxPreferenceKeys.lastIndex,
                        contentDescription = "Notification ${key} Cupertino Switch Preview",
                        onClick = { togglePreview(key) },
                    )
                }
            }
        }
        item {
            SettingsWebTabGroup(
                title = "System notifications",
                subtitle = notificationSystemFooter(zh = false),
                contentDescription = "Notifications Web System Group Preview $WEB_SSOT_NOTIFICATIONS_TAB",
            ) {
                val key = "system_notifications"
                NotificationWebSwitchRow(
                    title = "Show system notifications",
                    subtitle = notificationPreferenceDescription(key, zh = false),
                    checked = preferences.value(key) != "muted",
                    saving = mutatingKey == key,
                    contentDescription = "Notification ${key} Cupertino Switch Preview",
                    onClick = { togglePreview(key) },
                )
            }
        }
        if (!message.isNullOrBlank()) {
            item {
                PilotInlineResultState(
                    message = message.orEmpty(),
                    isError = false,
                    contentDescription = "Notifications Result Web Banner Preview",
                )
            }
        }
    }
}

@Composable
private fun PilotWorkspaceSettings(
    api: ApiClient,
    workspaceId: String,
    currentUserId: String,
    zh: Boolean,
    onBack: () -> Unit,
    onReloadSession: () -> Unit,
    onSwitchWorkspace: (String) -> Unit,
) {
    var state by remember(workspaceId) { mutableStateOf<Result<PilotWorkspaceSettingsData>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var formOpen by remember(workspaceId) { mutableStateOf(false) }
    var editingWorkspace by remember(workspaceId) { mutableStateOf<Models.Workspace?>(null) }
    var name by remember(workspaceId) { mutableStateOf("") }
    var slug by remember(workspaceId) { mutableStateOf("") }
    var description by remember(workspaceId) { mutableStateOf("") }
    var context by remember(workspaceId) { mutableStateOf("") }
    var saving by remember(workspaceId) { mutableStateOf(false) }
    var pendingDelete by remember(workspaceId) { mutableStateOf<Models.Workspace?>(null) }
    var deleting by remember(workspaceId) { mutableStateOf(false) }
    var pendingLeave by remember(workspaceId) { mutableStateOf<Models.Workspace?>(null) }
    var leaving by remember(workspaceId) { mutableStateOf(false) }
    var repoRows by remember(workspaceId) { mutableStateOf<List<String>>(emptyList()) }
    var savingRepos by remember(workspaceId) { mutableStateOf(false) }
    var coAuthoredByEnabled by remember(workspaceId) { mutableStateOf(true) }
    var savingLabs by remember(workspaceId) { mutableStateOf(false) }
    var message by remember(workspaceId) { mutableStateOf<String?>(null) }
    var expandedWorkspaceActionsId by remember(workspaceId) { mutableStateOf<String?>(null) }
    var workspaceSwitcherOpen by remember(workspaceId) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, refresh) {
        state = null
        val result = withContext(Dispatchers.IO) {
            runCatching {
                PilotWorkspaceSettingsData(
                    current = api.workspace(workspaceId),
                    workspaces = api.workspaces(),
                    members = api.members(workspaceId),
                )
            }
        }
        result.onSuccess {
            repoRows = it.current.repos.map { repo -> repo.url }
            coAuthoredByEnabled = it.current.coAuthoredByEnabled()
        }
        state = result
    }

    fun openCreate() {
        editingWorkspace = null
        name = ""
        slug = ""
        description = ""
        context = ""
        pendingDelete = null
        pendingLeave = null
        message = null
        formOpen = true
    }

    fun openEdit(workspace: Models.Workspace) {
        editingWorkspace = workspace
        name = workspace.name
        slug = workspace.slug
        description = workspace.description
        context = workspace.context
        pendingDelete = null
        pendingLeave = null
        message = null
        formOpen = true
    }

    fun saveWorkspace() {
        val trimmedName = name.trim()
        val trimmedSlug = slug.trim()
        if (trimmedName.isBlank() || (editingWorkspace == null && trimmedSlug.isBlank()) || saving) return
        saving = true
        message = null
        val editing = editingWorkspace
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    if (editing == null) {
                        api.createWorkspace(trimmedName, trimmedSlug, description.trim(), context.trim())
                    } else {
                        api.updateWorkspace(editing.id, trimmedName, description.trim(), context.trim())
                    }
                }
            }
            saving = false
            result.onSuccess { saved ->
                formOpen = false
                editingWorkspace = null
                message = "${if (zh) "工作区已保存" else "Workspace saved"}: ${saved.name}"
                refresh++
                if (saved.id == workspaceId) onReloadSession()
            }.onFailure {
                message = "${if (zh) "工作区保存失败" else "Workspace save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun deleteWorkspace(workspace: Models.Workspace) {
        if (deleting) return
        deleting = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.deleteWorkspace(workspace.id) } }
            deleting = false
            result.onSuccess {
                pendingDelete = null
                message = "${if (zh) "工作区已删除" else "Workspace deleted"}: ${workspace.name}"
                refresh++
                if (workspace.id == workspaceId) {
                    onBack()
                    onReloadSession()
                }
            }.onFailure {
                message = "${if (zh) "工作区删除失败" else "Workspace delete failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun leaveWorkspace(workspace: Models.Workspace) {
        if (leaving) return
        leaving = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.leaveWorkspace(workspace.id) } }
            leaving = false
            result.onSuccess {
                pendingLeave = null
                message = "${if (zh) "已离开工作区" else "Workspace left"}: ${workspace.name}"
                refresh++
                if (workspace.id == workspaceId) {
                    onBack()
                    onReloadSession()
                }
            }.onFailure {
                message = "${if (zh) "离开工作区失败" else "Workspace leave failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun saveRepositories() {
        if (savingRepos) return
        savingRepos = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.updateWorkspaceRepos(workspaceId, repoRows) } }
            savingRepos = false
            result.onSuccess { saved ->
                repoRows = saved.repos.map { repo -> repo.url }
                message = if (zh) "仓库已保存" else "Repositories saved"
                refresh++
            }.onFailure {
                message = "${if (zh) "仓库保存失败" else "Repository save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun toggleCoAuthoredBy(enabled: Boolean) {
        if (savingLabs) return
        savingLabs = true
        message = null
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.updateWorkspaceCoAuthoredBy(workspaceId, enabled) } }
            savingLabs = false
            result.onSuccess { saved ->
                coAuthoredByEnabled = saved.coAuthoredByEnabled()
                message = if (zh) "实验功能已保存" else "Labs saved"
                refresh++
            }.onFailure {
                message = "${if (zh) "实验功能保存失败" else "Labs save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (formOpen) {
        PilotListPage(
            title = if (editingWorkspace == null) {
                if (zh) "创建工作区" else "Create Workspace"
            } else {
                if (zh) "编辑工作区" else "Edit Workspace"
            },
            leading = {
                MulticaIconPillButton(
                    icon = Icons.Outlined.ArrowBack,
                    contentDescription = if (zh) "返回工作区设置" else "Back to Workspace Settings",
                    onClick = {
                        formOpen = false
                        editingWorkspace = null
                    },
                    tone = MulticaButtonTone.Ghost,
                )
            },
            trailing = {
                MulticaPillButton(
                    text = if (saving) "..." else if (zh) "保存" else "Save",
                    onClick = { saveWorkspace() },
                    tone = MulticaButtonTone.Primary,
                    enabled = name.trim().isNotBlank() && (editingWorkspace != null || slug.trim().isNotBlank()) && !saving,
                    contentDescription = "Workspace Save Button",
                )
            },
            bottomContent = {
                MulticaHazeBottomBar(
                    hazeState = rememberHazeState(),
                    contentDescription = "Workspace Form Bottom Haze Save Bar",
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 26.dp, vertical = 14.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaPillButton(
                            text = if (zh) "取消" else "Cancel",
                            onClick = {
                                formOpen = false
                                editingWorkspace = null
                            },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Ghost,
                        )
                        MulticaPillButton(
                            text = if (saving) "..." else if (editingWorkspace == null) {
                                if (zh) "创建工作区" else "Create Workspace"
                            } else {
                                if (zh) "保存工作区" else "Save Workspace"
                            },
                            onClick = { saveWorkspace() },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Primary,
                            enabled = name.trim().isNotBlank() && (editingWorkspace != null || slug.trim().isNotBlank()) && !saving,
                            contentDescription = "Workspace Form Bottom Save",
                        )
                    }
                }
            },
        ) {
            if (!message.isNullOrBlank()) {
                item {
                    PilotInlineResultState(
                        message = message.orEmpty(),
                        isError = pilotInlineResultIsError(message.orEmpty()),
                        contentDescription = "Workspace Result Web Banner",
                    )
                }
            }
            item {
                WorkspaceFormWebPanel(
                    title = if (editingWorkspace == null) {
                        if (zh) "创建工作区" else "Create Workspace"
                    } else {
                        if (zh) "编辑工作区" else "Edit Workspace"
                    },
                    subtitle = if (editingWorkspace == null) {
                        if (zh) "名称、slug、描述和上下文" else "Name, slug, description, and context"
                    } else {
                        if (zh) "名称、描述和上下文" else "Name, description, and context"
                    },
                    zh = zh,
                ) {
                    MulticaTextField(
                        value = name,
                        onValueChange = { name = it },
                        label = if (zh) "工作区名称" else "Workspace name",
                        contentDescription = "Workspace Form Name Field",
                        singleLine = true,
                    )
                    MulticaTextField(
                        value = slug,
                        onValueChange = { slug = it },
                        enabled = editingWorkspace == null,
                        label = if (zh) "工作区 slug" else "Workspace slug",
                        contentDescription = "Workspace Form Slug Field",
                        singleLine = true,
                    )
                    MulticaTextField(
                        value = description,
                        onValueChange = { description = it },
                        label = if (zh) "工作区描述" else "Workspace description",
                        contentDescription = "Workspace Form Description Field",
                        minLines = 3,
                    )
                    MulticaTextField(
                        value = context,
                        onValueChange = { context = it },
                        label = if (zh) "工作区上下文" else "Workspace context",
                        contentDescription = "Workspace Form Context Field",
                        minLines = 4,
                    )
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "工作区详情" else "Workspace Details",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载工作区..." else "Loading workspaces...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "工作区加载失败" else "Workspace load failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { data ->
                    val currentMember = data.members.firstOrNull { it.userId == currentUserId }
                    val canManageWorkspace = currentMember?.role == "owner" || currentMember?.role == "admin"
                    item {
                        WorkspaceIdentitySummaryCard(
                            workspace = data.current,
                            role = currentMember?.role.orEmpty(),
                            zh = zh,
                            canManageWorkspace = canManageWorkspace,
                            onEdit = { if (canManageWorkspace) openEdit(data.current) },
                        )
                    }
                    if (!canManageWorkspace) {
                        item {
                            PilotInlineResultState(
                                message = if (zh) {
                                    "你可以查看 workspace 详情；只有 owner 和 admin 可以修改设置。"
                                } else {
                                    "You can review workspace details. Only owners and admins can change settings."
                                },
                                isError = false,
                                contentDescription = "Workspace Permission Read Only",
                            )
                        }
                    }
                    item {
                        WorkspaceDetailWebGeneralForm(
                            workspace = data.current,
                            zh = zh,
                            onEdit = { if (canManageWorkspace) openEdit(data.current) },
                        )
                    }
                    if (canManageWorkspace) item {
                        SettingsWebTabGroup(
                            title = if (zh) "管理工作区" else "Manage Workspaces",
                            subtitle = if (zh) "创建新 workspace，或在底部切换已有 workspace" else "Create a new workspace or switch below",
                        ) {
                            SettingsWebTabRow(
                                title = if (zh) "创建工作区" else "Create Workspace",
                                subtitle = if (zh) "创建一个新的独立 workspace" else "Create a new standalone workspace",
                                icon = Icons.Outlined.Add,
                                onClick = { openCreate() },
                            )
                        }
                    }
                    if (formOpen) {
                        item {
                            WorkspaceFormWebPanel(
                                title = if (editingWorkspace == null) {
                                    if (zh) "创建工作区" else "Create Workspace"
                                } else {
                                    if (zh) "编辑工作区" else "Edit Workspace"
                                },
                                subtitle = if (editingWorkspace == null) {
                                    if (zh) "名称、slug、描述和上下文" else "Name, slug, description, and context"
                                } else {
                                    if (zh) "名称、描述和上下文" else "Name, description, and context"
                                },
                                zh = zh,
                            ) {
                                    MulticaTextField(
                                        value = name,
                                        onValueChange = { name = it },
                                        label = if (zh) "工作区名称" else "Workspace name",
                                        contentDescription = "Workspace Form Name Field",
                                        singleLine = true,
                                    )
                                    MulticaTextField(
                                        value = slug,
                                        onValueChange = { slug = it },
                                        enabled = editingWorkspace == null,
                                        label = if (zh) "工作区 slug" else "Workspace slug",
                                        contentDescription = "Workspace Form Slug Field",
                                        singleLine = true,
                                    )
                                    MulticaTextField(
                                        value = description,
                                        onValueChange = { description = it },
                                        label = if (zh) "工作区描述" else "Workspace description",
                                        contentDescription = "Workspace Form Description Field",
                                        minLines = 2,
                                    )
                                    MulticaTextField(
                                        value = context,
                                        onValueChange = { context = it },
                                        label = if (zh) "工作区上下文" else "Workspace context",
                                        contentDescription = "Workspace Form Context Field",
                                        minLines = 3,
                                    )
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        modifier = Modifier.fillMaxWidth(),
                                    ) {
                                        MulticaPillButton(
                                            text = if (zh) "取消" else "Cancel",
                                            onClick = {
                                                formOpen = false
                                                editingWorkspace = null
                                            },
                                            modifier = Modifier.weight(1f),
                                            tone = MulticaButtonTone.Secondary,
                                        )
                                        MulticaPillButton(
                                            text = if (saving) "..." else if (zh) "保存工作区" else "Save Workspace",
                                            onClick = { saveWorkspace() },
                                            modifier = Modifier.weight(1f),
                                            tone = MulticaButtonTone.Primary,
                                        )
                                    }
                            }
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "切换工作区" else "Switch Workspace",
                            subtitle = if (zh) "从列表中切换当前 workspace" else "Switch the current workspace from this list",
                            contentDescription = "Workspace Switcher Cupertino Picker",
                        ) {
                            SettingsWebTabRow(
                                title = data.current.name,
                                subtitle = data.current.slug.ifBlank { if (zh) "当前 workspace" else "Current workspace" },
                                value = if (zh) "当前" else "Current",
                                icon = Icons.Outlined.Folder,
                                onClick = { workspaceSwitcherOpen = true },
                                contentDescription = "Workspace Switcher Open Picker",
                            )
                        }
                    }
                    if (workspaceSwitcherOpen) {
                        item {
                            MulticaCupertinoActionSheet(
                                visible = true,
                                title = if (zh) "切换工作区" else "Switch Workspace",
                                message = if (zh) "当前 workspace 会立即切换" else "The current workspace changes immediately",
                                items = data.workspaces.map { workspace ->
                                    MulticaCupertinoActionSheetItem(
                                        title = workspace.name,
                                        subtitle = workspace.slug,
                                        icon = Icons.Outlined.Folder,
                                        selected = workspace.id == workspaceId,
                                        contentDescription = "Workspace Switcher Option ${workspace.id}",
                                        onClick = {
                                            workspaceSwitcherOpen = false
                                            if (workspace.id != workspaceId) onSwitchWorkspace(workspace.id)
                                        },
                                    )
                                },
                                cancelText = if (zh) "取消" else "Cancel",
                                onDismissRequest = { workspaceSwitcherOpen = false },
                            )
                        }
                    }
                    if (canManageWorkspace) item {
                        SettingsWebTabGroup(
                            title = if (zh) "代码仓库" else "Repositories",
                            subtitle = if (zh) "这些 GitHub 仓库会出现在项目资源选择器里" else "These GitHub repositories appear in project resource pickers",
                        ) {
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(6.dp),
                            ) {
                                if (repoRows.isEmpty()) {
                                    Text(
                                        text = if (zh) "暂无仓库" else "No repositories",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = MulticaColors.Muted,
                                        modifier = Modifier.padding(vertical = 7.dp),
                                    )
                                }
                                repoRows.forEachIndexed { index, value ->
                                    WorkspaceDetailRepoDenseRow(
                                        value = value,
                                        index = index,
                                        zh = zh,
                                        showDivider = index < repoRows.lastIndex,
                                        onValueChange = { next ->
                                            repoRows = repoRows.toMutableList().also { it[index] = next }
                                        },
                                        onRemove = {
                                            repoRows = repoRows.filterIndexed { rowIndex, _ -> rowIndex != index }
                                        },
                                    )
                                }
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                ) {
                                    MulticaPillButton(
                                        text = if (zh) "添加仓库" else "Add Repository",
                                        onClick = { repoRows = repoRows + "" },
                                        modifier = Modifier.weight(1f),
                                        tone = MulticaButtonTone.Secondary,
                                    )
                                    MulticaPillButton(
                                        text = if (savingRepos) "..." else if (zh) "保存仓库" else "Save Repositories",
                                        onClick = { saveRepositories() },
                                        modifier = Modifier.weight(1f),
                                        tone = MulticaButtonTone.Primary,
                                    )
                                }
                            }
                        }
                    }
                    if (canManageWorkspace) item {
                        SettingsWebTabGroup(
                            title = if (zh) "实验功能" else "Labs",
                            subtitle = if (zh) "和 Web Labs tab 保持一致的轻量开关" else "Lightweight toggles mirrored from the web Labs tab",
                        ) {
                            WorkspaceDetailLabsRow(
                                enabled = coAuthoredByEnabled,
                                saving = savingLabs,
                                zh = zh,
                                onToggle = { toggleCoAuthoredBy(it) },
                            )
                        }
                    }
                    item {
                        SettingsWebTabGroup(
                            title = if (zh) "危险操作" else "Danger Zone",
                            subtitle = if (zh) "离开或删除当前工作区" else "Leave or delete the current workspace",
                        ) {
                            WorkspaceDetailDangerRow(
                                title = if (zh) "离开工作区" else "Leave workspace",
                                subtitle = if (zh) "从当前 workspace 移除自己的成员关系" else "Remove your membership from this workspace",
                                zh = zh,
                                destructive = false,
                                showDivider = true,
                                onClick = {
                                    pendingLeave = data.current
                                    pendingDelete = null
                                },
                            )
                            WorkspaceDetailDangerRow(
                                title = if (zh) "删除工作区" else "Delete workspace",
                                subtitle = if (zh) "删除 workspace 及其协作上下文" else "Delete the workspace and its collaboration context",
                                zh = zh,
                                destructive = true,
                                enabled = canManageWorkspace,
                                onClick = {
                                    if (canManageWorkspace) {
                                        pendingDelete = data.current
                                        pendingLeave = null
                                    }
                                },
                            )
                        }
                    }
                    pendingLeave?.let { workspace ->
                        item {
                            MulticaCupertinoAlertDialog(
                                visible = true,
                                title = if (zh) "离开工作区？" else "Leave workspace?",
                                message = if (zh) {
                                    "这会从 ${workspace.name} 移除你的成员关系。你需要重新受邀才能回来。"
                                } else {
                                    "This removes your membership from ${workspace.name}. You will need a new invitation to return."
                                },
                                cancelText = if (zh) "取消" else "Cancel",
                                confirmText = if (leaving) "..." else if (zh) "离开" else "Leave",
                                destructive = true,
                                contentDescription = "Workspace Leave Cupertino Alert ${workspace.id}",
                                onDismissRequest = { pendingLeave = null },
                                onConfirm = { leaveWorkspace(workspace) },
                            )
                        }
                    }
                    pendingDelete?.let { workspace ->
                        item {
                            MulticaCupertinoAlertDialog(
                                visible = true,
                                title = if (zh) "删除工作区？" else "Delete workspace?",
                                message = if (zh) {
                                    "这会删除 ${workspace.name} 及其协作上下文。请确认你已经不再需要它。"
                                } else {
                                    "This deletes ${workspace.name} and its collaboration context. Confirm you no longer need it."
                                },
                                cancelText = if (zh) "取消" else "Cancel",
                                confirmText = if (deleting) "..." else if (zh) "删除" else "Delete",
                                destructive = true,
                                contentDescription = "Workspace Delete Cupertino Alert ${workspace.id}",
                                onDismissRequest = { pendingDelete = null },
                                onConfirm = { deleteWorkspace(workspace) },
                            )
                        }
                    }
                    if (!message.isNullOrBlank()) {
                        item {
                            PilotInlineResultState(
                                message = message.orEmpty(),
                                isError = pilotInlineResultIsError(message.orEmpty()),
                                contentDescription = "Workspace Result Web Banner",
                            )
                        }
                    }
                    item { SettingsSectionLabel(if (zh) "所有工作区" else "All Workspaces") }
                    items(data.workspaces) { workspace ->
                        WorkspaceWebDenseRow(
                            workspace = workspace,
                            current = workspace.id == workspaceId,
                            zh = zh,
                            expanded = expandedWorkspaceActionsId == workspace.id,
                            onExpandedChange = { expandedWorkspaceActionsId = if (it) workspace.id else null },
                            onEdit = {
                                expandedWorkspaceActionsId = null
                                openEdit(workspace)
                            },
                            onDelete = {
                                expandedWorkspaceActionsId = null
                                pendingDelete = workspace
                                pendingLeave = null
                                formOpen = false
                                editingWorkspace = null
                                message = null
                            },
                            onLeave = {
                                expandedWorkspaceActionsId = null
                                pendingLeave = workspace
                                pendingDelete = null
                                formOpen = false
                                editingWorkspace = null
                                message = null
                            },
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun PilotWorkspaceSettingsPreview() {
    val workspaces = remember {
        listOf(
            Models.Workspace(
                JSONObject()
                    .put("id", "preview-workspace")
                    .put("name", "Multica Design Lab")
                    .put("slug", "design-lab")
                    .put("description", "Mobile design QA and product polish")
                    .put("context", "iOS-inspired Android workspace for visual system work.")
                    .put("issue_prefix", "MUL")
                    .put("created_at", "2026-05-14T09:30:00Z")
            ),
            Models.Workspace(
                JSONObject()
                    .put("id", "preview-ops")
                    .put("name", "Automation Ops")
                    .put("slug", "automation-ops")
                    .put("description", "Agent automation operations")
                    .put("issue_prefix", "OPS")
                    .put("created_at", "2026-04-21T12:00:00Z")
            ),
        )
    }
    val workspace = workspaces.first()
    var editOpen by remember { mutableStateOf(false) }
    var switcherOpen by remember { mutableStateOf(false) }
    var pendingLeave by remember { mutableStateOf<Models.Workspace?>(null) }
    var pendingDelete by remember { mutableStateOf<Models.Workspace?>(null) }
    var name by remember { mutableStateOf(workspace.name) }
    var slug by remember { mutableStateOf(workspace.slug) }
    var description by remember { mutableStateOf(workspace.description) }
    var context by remember { mutableStateOf(workspace.context) }

    if (editOpen) {
        PilotListPage(
            title = "Edit Workspace",
            leading = {
                MulticaIconPillButton(
                    icon = Icons.Outlined.ArrowBack,
                    contentDescription = "Back to Workspace Settings",
                    onClick = { editOpen = false },
                    tone = MulticaButtonTone.Ghost,
                )
            },
            bottomContent = {
                MulticaHazeBottomBar(
                    hazeState = rememberHazeState(),
                    contentDescription = "Workspace Form Bottom Haze Save Bar Preview",
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 26.dp, vertical = 14.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaPillButton(
                            text = "Cancel",
                            onClick = { editOpen = false },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Ghost,
                        )
                        MulticaPillButton(
                            text = "Save Workspace",
                            onClick = { editOpen = false },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Primary,
                            contentDescription = "Workspace Form Bottom Save Preview",
                        )
                    }
                }
            },
        ) {
            item {
                WorkspaceFormWebPanel(
                    title = "Edit Workspace",
                    subtitle = "Name, description, and context",
                    zh = false,
                ) {
                    MulticaTextField(value = name, onValueChange = { name = it }, label = "Workspace name", contentDescription = "Workspace Form Name Field Preview", singleLine = true)
                    MulticaTextField(value = slug, onValueChange = { slug = it }, enabled = false, label = "Workspace slug", contentDescription = "Workspace Form Slug Field Preview", singleLine = true)
                    MulticaTextField(value = description, onValueChange = { description = it }, label = "Workspace description", contentDescription = "Workspace Form Description Field Preview", minLines = 3)
                    MulticaTextField(value = context, onValueChange = { context = it }, label = "Workspace context", contentDescription = "Workspace Form Context Field Preview", minLines = 4)
                }
            }
        }
        return
    }

    PilotListPage(
        title = "Workspace Details",
        leading = { PilotSecondaryBackButton(zh = false, onBack = {}) },
    ) {
        item {
            WorkspaceIdentitySummaryCard(
                workspace = workspace,
                role = "owner",
                zh = false,
                canManageWorkspace = true,
                onEdit = { editOpen = true },
            )
        }
        item {
            WorkspaceDetailWebGeneralForm(
                workspace = workspace,
                zh = false,
                onEdit = { editOpen = true },
            )
        }
        item {
            SettingsWebTabGroup(
                title = "Switch Workspace",
                subtitle = "Switch the current workspace from this list",
                contentDescription = "Workspace Switcher Cupertino Picker Preview",
            ) {
                SettingsWebTabRow(
                    title = workspace.name,
                    subtitle = workspace.slug,
                    value = "Current",
                    icon = Icons.Outlined.Folder,
                    onClick = { switcherOpen = true },
                    contentDescription = "Workspace Switcher Open Picker Preview",
                )
            }
        }
        if (switcherOpen) {
            item {
                MulticaCupertinoActionSheet(
                    visible = true,
                    title = "Switch Workspace",
                    message = "The current workspace changes immediately",
                    items = workspaces.map { item ->
                        MulticaCupertinoActionSheetItem(
                            title = item.name,
                            subtitle = item.slug,
                            icon = Icons.Outlined.Folder,
                            selected = item.id == workspace.id,
                            contentDescription = "Workspace Switcher Option Preview ${item.id}",
                            onClick = { switcherOpen = false },
                        )
                    },
                    cancelText = "Cancel",
                    onDismissRequest = { switcherOpen = false },
                )
            }
        }
        item {
            SettingsWebTabGroup(
                title = "Danger Zone",
                subtitle = "Leave or delete the current workspace",
            ) {
                WorkspaceDetailDangerRow(
                    title = "Leave workspace",
                    subtitle = "Remove your membership from this workspace",
                    zh = false,
                    destructive = false,
                    showDivider = true,
                    onClick = {
                        pendingLeave = workspace
                        pendingDelete = null
                    },
                )
                WorkspaceDetailDangerRow(
                    title = "Delete workspace",
                    subtitle = "Delete the workspace and its collaboration context",
                    zh = false,
                    destructive = true,
                    onClick = {
                        pendingDelete = workspace
                        pendingLeave = null
                    },
                )
            }
        }
        pendingLeave?.let {
            item {
                MulticaCupertinoAlertDialog(
                    visible = true,
                    title = "Leave workspace?",
                    message = "This removes your membership from ${it.name}. You will need a new invitation to return.",
                    cancelText = "Cancel",
                    confirmText = "Leave",
                    destructive = true,
                    contentDescription = "Workspace Leave Cupertino Alert Preview ${it.id}",
                    onDismissRequest = { pendingLeave = null },
                    onConfirm = { pendingLeave = null },
                )
            }
        }
        pendingDelete?.let {
            item {
                MulticaCupertinoAlertDialog(
                    visible = true,
                    title = "Delete workspace?",
                    message = "This deletes ${it.name} and its collaboration context. Confirm you no longer need it.",
                    cancelText = "Cancel",
                    confirmText = "Delete",
                    destructive = true,
                    contentDescription = "Workspace Delete Cupertino Alert Preview ${it.id}",
                    onDismissRequest = { pendingDelete = null },
                    onConfirm = { pendingDelete = null },
                )
            }
        }
    }
}

@Composable
private fun WorkspaceIdentitySummaryCard(
    workspace: Models.Workspace,
    role: String,
    zh: Boolean,
    canManageWorkspace: Boolean,
    onEdit: () -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = false) { contentDescription = "Workspace Summary Hero ${workspace.id}" },
        shape = RoundedCornerShape(16.dp),
        color = MulticaColors.Surface.copy(alpha = 0.94f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        border = androidx.compose.foundation.BorderStroke(0.5.dp, MulticaColors.Border.copy(alpha = 0.70f)),
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(
                    modifier = Modifier.size(48.dp),
                    shape = RoundedCornerShape(14.dp),
                    color = MulticaColors.Accent.copy(alpha = 0.12f),
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        Text(
                            text = workspace.name.firstOrNull()?.uppercaseChar()?.toString() ?: "W",
                            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                            color = MulticaColors.Accent,
                        )
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(
                        text = workspace.name,
                        modifier = Modifier.semantics { contentDescription = "Workspace Summary Name ${workspace.id}" },
                        style = MaterialTheme.typography.titleMedium.copy(fontSize = 18.sp, lineHeight = 22.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        text = workspace.slug.ifBlank { Models.shortId(workspace.id) },
                        modifier = Modifier.semantics { contentDescription = "Workspace Summary Slug ${workspace.id}" },
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                        color = MulticaColors.Muted,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                if (canManageWorkspace) {
                    MulticaIconPillButton(
                        icon = Icons.Outlined.Edit,
                        contentDescription = "Workspace Summary Edit",
                        onClick = onEdit,
                        tone = MulticaButtonTone.Ghost,
                    )
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                WorkspaceSummaryChip(
                    title = if (zh) "角色" else "Role",
                    value = role.ifBlank { if (zh) "成员" else "member" },
                    contentDescription = "Workspace Summary Role ${workspace.id}",
                    modifier = Modifier.weight(1f),
                )
                WorkspaceSummaryChip(
                    title = if (zh) "创建" else "Created",
                    value = shortDate(workspace.createdAt).ifBlank { if (zh) "未知" else "Unknown" },
                    contentDescription = "Workspace Summary Created ${workspace.id}",
                    modifier = Modifier.weight(1f),
                )
            }
            if (workspace.description.isNotBlank() || workspace.context.isNotBlank()) {
                Text(
                    text = listOf(clean(workspace.description), clean(workspace.context)).filter { it.isNotBlank() }.joinToString("\n"),
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                    color = MulticaColors.Muted,
                    maxLines = 4,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
    }
}

