                tone = if (expanded) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                modifier = Modifier
                    .size(36.dp)
                    .semantics { contentDescription = "Workspace Actions ${workspace.name}" },
            )
            MulticaCupertinoActionSheet(
                visible = expanded,
                title = if (zh) "工作区操作" else "Workspace actions",
                message = workspace.name.ifBlank { workspace.slug },
                items = listOf(
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "编辑" else "Edit",
                        icon = Icons.Outlined.Edit,
                        contentDescription = "Workspace Edit ${workspace.name}",
                        onClick = onEdit,
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "离开" else "Leave",
                        icon = Icons.Outlined.Close,
                        destructive = true,
                        contentDescription = "Workspace Leave ${workspace.name}",
                        onClick = onLeave,
                    ),
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "删除" else "Delete",
                        icon = Icons.Outlined.Delete,
                        destructive = true,
                        contentDescription = "Workspace Delete ${workspace.name}",
                        onClick = onDelete,
                    ),
                ),
                cancelText = if (zh) "取消" else "Cancel",
                onDismissRequest = { onExpandedChange(false) },
            )
        }
    }
}

@Composable
private fun PilotTextWebRow(
