    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Pilot Text Web Row ${title.ifBlank { eyebrow }}" },
        shape = shape,
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.72f), shape)
                .padding(horizontal = 12.dp, vertical = 10.dp),
            verticalArrangement = Arrangement.spacedBy(3.dp),
        ) {
            if (eyebrow.isNotBlank()) {
                Text(
                    text = eyebrow,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp, fontWeight = FontWeight.SemiBold),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            Text(
                text = title,
                style = MaterialTheme.typography.bodyMedium.copy(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight.Medium),
                color = MulticaColors.Text,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            if (!subtitle.isNullOrBlank()) {
                Text(
                    text = subtitle,
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                    color = MulticaColors.Muted.copy(alpha = 0.72f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
    }
}

@Composable
private fun PilotTextRowsSettings(
    page: PilotSettingsPage,
    api: ApiClient,
    workspaceId: String,
    zh: Boolean,
    onBack: () -> Unit,
) {
    var state by remember(page, workspaceId) { mutableStateOf<Result<List<String>>?>(null) }
    var refresh by remember(page, workspaceId) { mutableIntStateOf(0) }
    val title = settingsPageTitle(page)

    LaunchedEffect(page, workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                when (page) {
                    PilotSettingsPage.WorkspaceDetails -> listOf(api.workspaceSummary(workspaceId))
                    PilotSettingsPage.Members -> api.memberSummaries(workspaceId)
                    PilotSettingsPage.Notifications -> api.notificationSummaries(workspaceId)
                    PilotSettingsPage.ApiTokens -> api.tokenSummaries()
                    PilotSettingsPage.Autopilots -> api.autopilots(workspaceId).map {
                        "${it.title}\n${clean(it.description)}\n${it.status}"
                    }
                    PilotSettingsPage.Runtimes -> api.runtimes(workspaceId).map {
                        "${it.name}\n${it.status}${if (it.version.isBlank()) "" else " · ${it.version}"}"
                    }
                    else -> emptyList()
                }
            }
        }
    }

    PilotListPage(
        title = title,
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载..." else "Loading...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { rows ->
                    if (rows.isEmpty()) item { SettingsTextRowsWebEmptyState(zh = zh) }
                    items(rows) { row ->
                        val parts = row.split('\n')
                        PilotTextWebRow(
                            eyebrow = parts.getOrNull(1).orEmpty(),
                            title = parts.firstOrNull().orEmpty().ifBlank { title },
                            subtitle = parts.drop(2).joinToString(" · ").ifBlank { null },
                        )
                    }
                }
            }
        }
    }
}

