private enum class ApiTokenSettingsMode { List, Create }

@Composable
private fun PilotApiTokensSettings(api: ApiClient, zh: Boolean, onBack: () -> Unit) {
    var state by remember { mutableStateOf<Result<List<Models.PersonalAccessToken>>?>(null) }
    var refresh by remember { mutableIntStateOf(0) }
    var apiTokenMode by remember { mutableStateOf(ApiTokenSettingsMode.List) }
    var name by remember { mutableStateOf("") }
    var expiryIndex by remember { mutableIntStateOf(1) }
    var saving by remember { mutableStateOf(false) }
    var pendingRevoke by remember { mutableStateOf<Models.PersonalAccessToken?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var createdSecret by remember { mutableStateOf<String?>(null) }
    var createdSecretCopied by remember { mutableStateOf(false) }
    var createdTokens by remember { mutableStateOf<List<Models.PersonalAccessToken>>(emptyList()) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current
    val expiryOptions = listOf(30 to "30 days", 90 to "90 days", 365 to "365 days", null to "Never")

    LaunchedEffect(refresh) {
        state = null
        state = withContext(Dispatchers.IO) { runCatching { api.personalAccessTokens() } }
    }

    fun resetCreateForm() {
        apiTokenMode = ApiTokenSettingsMode.List
        name = ""
        expiryIndex = 1
        createdSecretCopied = false
    }

    fun createToken() {
        val tokenName = name.trim()
        if (tokenName.isEmpty() || saving) return
        saving = true
        resultText = null
        createdSecret = null
        createdSecretCopied = false
        val expires = expiryOptions[expiryIndex.coerceAtMost(expiryOptions.lastIndex)].first
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.createPersonalAccessToken(tokenName, expires) }
            }
            saving = false
            result.onSuccess {
                createdTokens = listOf(it) + createdTokens.filter { token -> token.id != it.id }
                createdSecret = it.token
                createdSecretCopied = false
                resultText = if (zh) "API 令牌已创建，请立即复制保存。" else "API token created. Copy it now."
                resetCreateForm()
                refresh++
            }.onFailure {
                createdSecret = null
                createdSecretCopied = false
                resultText = "${if (zh) "创建失败" else "Create failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun copyCreatedToken(secret: String) {
        val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        clipboard.setPrimaryClip(ClipData.newPlainText("Multica API token", secret))
        createdSecretCopied = true
        resultText = if (zh) "API 令牌已复制" else "API token copied"
    }

    fun revokeToken(token: Models.PersonalAccessToken) {
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.revokePersonalAccessToken(token.id) }
            }
            result.onSuccess {
                createdTokens = createdTokens.filter { it.id != token.id }
                pendingRevoke = null
                resultText = if (zh) "API 令牌已撤销" else "API token revoked"
                refresh++
            }.onFailure {
                pendingRevoke = null
                resultText = "${if (zh) "撤销失败" else "Revoke failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (apiTokenMode == ApiTokenSettingsMode.Create) {
        PilotListPage(
            title = if (zh) "新建 API 令牌" else "New API Token",
            leading = {
                PilotSecondaryBackButton(
                    zh = zh,
                    onBack = {
                        resetCreateForm()
                        resultText = null
                        createdSecret = null
                        createdSecretCopied = false
                    },
                    contentDescription = if (zh) "返回 API Tokens" else "Back to API Tokens",
                )
            },
            bottomContent = {
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .imePadding(),
                    color = MulticaColors.Background,
                    tonalElevation = 0.dp,
                    shadowElevation = 0.dp,
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 26.dp, vertical = 14.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        MulticaPillButton(
                            text = if (zh) "取消" else "Cancel",
                            onClick = {
                                resetCreateForm()
                                resultText = null
                                createdSecret = null
                                createdSecretCopied = false
                            },
                            modifier = Modifier.weight(1f),
                            tone = MulticaButtonTone.Ghost,
                            contentDescription = "API Token Form Cancel",
                        )
                        MulticaPillButton(
                            text = if (saving) "..." else if (zh) "创建" else "Create",
                            onClick = { createToken() },
                            modifier = Modifier.weight(1.2f),
                            tone = MulticaButtonTone.Primary,
                            contentDescription = "API Token Form Bottom Create",
                        )
                    }
                }
            },
        ) {
            item {
                ApiTokenCreateIntroWebPanel(zh = zh)
            }
            item { SettingsSectionLabel(if (zh) "令牌信息" else "Token") }
            item {
                MulticaTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = if (zh) "令牌名称" else "Token name",
                    singleLine = true,
                    contentDescription = "API Token Form Name",
                )
            }
            item {
                val option = expiryOptions[expiryIndex.coerceAtMost(expiryOptions.lastIndex)]
                ApiTokenFormExpirationWebPicker(
                    options = expiryOptions,
                    selectedIndex = expiryIndex,
                    zh = zh,
                    onSelect = { expiryIndex = it },
                )
            }
            if (!resultText.isNullOrBlank()) {
                item {
                    if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                        PilotInlineResultState(
                            message = resultText.orEmpty(),
                            isError = true,
                            contentDescription = "API Token Create Result Web Banner",
                        )
                    } else {
                        MulticaSuccessState(resultText.orEmpty())
                    }
                }
            }
            item {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    MulticaPillButton(
                        text = if (zh) "取消" else "Cancel",
                        onClick = {
                            resetCreateForm()
                            resultText = null
                            createdSecret = null
                            createdSecretCopied = false
                        },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Ghost,
                    )
                    MulticaPillButton(
                        text = if (saving) "..." else if (zh) "创建" else "Create",
                        onClick = { createToken() },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Primary,
                        contentDescription = "API Token Form Create",
                    )
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "API 令牌" else "API Tokens",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = if (zh) "新建 API Token" else "New API Token",
                onClick = {
                    apiTokenMode = ApiTokenSettingsMode.Create
                    resultText = null
                    createdSecret = null
                    createdSecretCopied = false
                },
                tone = MulticaButtonTone.Primary,
            )
        },
    ) {
        item {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "API Token Create Entry" }
                    .clickable {
                        apiTokenMode = ApiTokenSettingsMode.Create
                        resultText = null
                        createdSecret = null
                        createdSecretCopied = false
                    },
                shape = RoundedCornerShape(8.dp),
                color = MulticaColors.AccentSoft.copy(alpha = 0.48f),
                tonalElevation = 0.dp,
                shadowElevation = 0.dp,
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(1.dp, MulticaColors.Accent.copy(alpha = 0.18f), RoundedCornerShape(8.dp))
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    Icon(Icons.Outlined.Add, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(18.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            if (zh) "新建 API 令牌" else "Create API Token",
                            style = MaterialTheme.typography.titleSmall.copy(fontSize = 14.sp, fontWeight = FontWeight.SemiBold),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                        Text(
                            if (zh) "设置名称与有效期，密钥只显示一次" else "Set name and expiration; secret is shown once",
                            style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    Icon(
                        Icons.Outlined.KeyboardArrowRight,
                        contentDescription = null,
                        tint = MulticaColors.Muted,
                        modifier = Modifier
                            .size(17.dp)
                            .semantics { contentDescription = "API Token Create Entry Arrow" },
                    )
                }
            }
        }
        if (!resultText.isNullOrBlank()) {
            item {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                        PilotInlineResultState(
                            message = resultText.orEmpty(),
                            isError = true,
                            contentDescription = "API Token List Result Web Banner",
                        )
                    } else {
                        MulticaSuccessState(resultText.orEmpty())
                    }
                }
            }
        }
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载令牌..." else "Loading tokens...") }
            else -> {
                loaded.onFailure { item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) } }
                loaded.onSuccess { tokens ->
                    val mergedTokens = (createdTokens + tokens).distinctBy { it.id }
                    if (mergedTokens.isEmpty()) item { ApiTokensWebEmptyState(zh = zh) }
                    if (mergedTokens.isNotEmpty()) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics { contentDescription = "API Token Web Table Header" }
                                    .padding(horizontal = 12.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    if (zh) "令牌" else "Token",
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                )
                                Text(
                                    if (zh) "前缀" else "Prefix",
                                    modifier = Modifier.width(82.dp),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                    textAlign = TextAlign.Center,
                                )
                                Spacer(Modifier.width(42.dp))
                            }
                        }
                    }
                    items(mergedTokens) { token ->
                        ApiTokenWebDenseRow(
                            token = token,
                            zh = zh,
                            onRevoke = { pendingRevoke = token },
                        )
                    }
                }
            }
        }
    }
    pendingRevoke?.let { token ->
        MulticaCupertinoAlertDialog(
            visible = true,
            title = if (zh) "撤销令牌？" else "Revoke token?",
            message = if (zh) {
                "令牌 ${token.name} 将立即失效，相关脚本需要重新配置。"
            } else {
                "${token.name} will stop working immediately. Connected scripts need a new token."
            },
            cancelText = if (zh) "取消" else "Cancel",
            confirmText = if (zh) "确认撤销" else "Revoke",
            destructive = true,
            contentDescription = "API Token Revoke Cupertino Alert",
            onDismissRequest = { pendingRevoke = null },
            onConfirm = { revokeToken(token) },
        )
    }
    createdSecret?.let { secret ->
        MulticaCupertinoSecretDialog(
            visible = true,
            title = if (zh) "API 令牌已创建" else "API token created",
            message = if (zh) {
                "这个密钥只会显示一次。请立即复制并保存到安全位置。"
            } else {
                "This secret is shown once. Copy it now and store it somewhere safe."
            },
            secret = secret,
            copied = createdSecretCopied,
            copyText = if (createdSecretCopied) {
                if (zh) "再次复制" else "Copy again"
            } else {
                if (zh) "复制" else "Copy"
            },
            doneText = if (zh) "完成" else "Done",
            copiedText = if (zh) "已复制" else "Copied",
            contentDescription = "API Token Created Secret Dialog",
            onDismissRequest = {
                createdSecret = null
                createdSecretCopied = false
            },
            onCopy = { copyCreatedToken(secret) },
        )
    }
}

