@Composable
private fun ApiTokenFormExpirationWebPicker(
    options: List<Pair<Int?, String>>,
    selectedIndex: Int,
    zh: Boolean,
    onSelect: (Int) -> Unit,
) {
    val safeIndex = selectedIndex.coerceIn(0, options.lastIndex)
    val selected = options[safeIndex]
    AgentFormWebMenuRow(
        eyebrow = if (zh) "有效期" else "Expiration",
        title = if (zh && selected.first == null) "永不过期" else selected.second,
        subtitle = if (zh) "选择令牌自动失效时间" else "Choose when this token expires",
        contentDescription = "API Token Form Expiration Web Picker",
        options = options.mapIndexed { index, option ->
            AgentFormMenuOption(
                label = if (zh && option.first == null) "永不过期" else option.second,
                detail = when (option.first) {
                    30 -> if (zh) "适合短期脚本和临时集成" else "Best for short-lived scripts"
                    90 -> if (zh) "默认安全周期" else "Default safety window"
                    365 -> if (zh) "适合长期但仍需轮换的集成" else "Long-lived but still rotates"
                    null -> if (zh) "仅用于明确需要长期访问的场景" else "Only for explicit long-term access"
                    else -> null
                },
                selected = index == safeIndex,
                onClick = { onSelect(index) },
            )
        },
    )
}

