                    token.name,
                    style = MaterialTheme.typography.titleSmall.copy(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight.SemiBold),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    listOf(
                        if (token.createdAt.isNotBlank()) "${if (zh) "创建" else "Created"} ${shortDate(token.createdAt)}" else "",
                        if (token.expiresAt.isNotBlank()) {
                            "${if (zh) "过期" else "Expires"} ${shortDate(token.expiresAt)}"
                        } else {
                            if (zh) "不过期" else "No expiration"
                        },
                        if (token.lastUsedAt.isNotBlank()) {
                            "${if (zh) "上次使用" else "Last used"} ${shortDate(token.lastUsedAt)}"
                        } else {
                            if (zh) "从未使用" else "Never used"
                        },
                    ).filter { it.isNotBlank() }.joinToString(" · "),
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            Text(
                prefix,
                modifier = Modifier
                    .width(82.dp)
                    .semantics { contentDescription = "API Token Prefix $prefix" },
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold, fontFamily = FontFamily.Monospace),
                color = MulticaColors.TextTertiary,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                textAlign = TextAlign.Center,
            )
            MulticaIconPillButton(
                icon = Icons.Outlined.Delete,
                contentDescription = "API Token Revoke ${token.name}",
                onClick = onRevoke,
                tone = MulticaButtonTone.Destructive,
                modifier = Modifier
                    .size(36.dp)
                    .semantics { contentDescription = "API Token Revoke ${token.name}" },
            )
        }
    }
}

