@Composable
private fun AutopilotTemplateChip(
    title: String,
    summary: String,
    icon: ImageVector,
    contentDescription: String,
    trailingContentDescription: String? = null,
    trailingIcon: ImageVector = Icons.Outlined.KeyboardArrowRight,
    onClick: () -> Unit,
) {
    val haptic = LocalHapticFeedback.current
    val shape = RoundedCornerShape(12.dp)
    Surface(
        modifier = Modifier
            .width(224.dp)
            .clip(shape)
            .clickable {
                haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                onClick()
            }
            .semantics(mergeDescendants = true) { this.contentDescription = contentDescription },
        shape = shape,
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.68f), shape)
                .padding(horizontal = 11.dp, vertical = 9.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box(
                modifier = Modifier
                    .size(28.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(MulticaColors.Accent.copy(alpha = 0.10f)),
                contentAlignment = Alignment.Center,
            ) {
                Icon(icon, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(15.dp))
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.labelMedium.copy(
                        fontSize = 13.sp,
                        lineHeight = 16.sp,
                        fontWeight = FontWeight.SemiBold,
                    ),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = summary,
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
                    color = MulticaColors.Muted,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            Icon(
                imageVector = trailingIcon,
                contentDescription = null,
                tint = MulticaColors.Muted,
                modifier = Modifier
                    .size(16.dp)
                    .then(
                        if (trailingContentDescription == null) {
                            Modifier
                        } else {
                            Modifier.semantics { this.contentDescription = trailingContentDescription }
                        }
                    ),
            )
        }
    }
}

private fun autopilotTemplateContentDescription(id: String): String {
    return when (id) {
        "daily_news" -> "Autopilot Template daily_news"
        "pr_review" -> "Autopilot Template pr_review"
        "bug_triage" -> "Autopilot Template bug_triage"
        else -> "Autopilot Template $id"
    }
}

private fun autopilotTemplateOptions(zh: Boolean): List<AutopilotTemplateOption> {
    return listOf(
        AutopilotTemplateOption(
            id = "daily_news",
            title = if (zh) "每日资讯" else "Daily news",
            summary = if (zh) "每天整理团队相关资讯" else "Daily digest for team-relevant news",
            prompt = "Search today's relevant news, summarize the key takeaways, and post a concise digest.",
            icon = Icons.Outlined.Search,
        ),
        AutopilotTemplateOption(
            id = "pr_review",
            title = if (zh) "PR 复查" else "PR review",
            summary = if (zh) "提醒长时间未 review 的 PR" else "Surface stale pull requests for review",
            prompt = "Find pull requests waiting for review, summarize their age and scope, and remind the team.",
            icon = Icons.Outlined.Flag,
        ),
        AutopilotTemplateOption(
            id = "bug_triage",
            title = if (zh) "Bug 分诊" else "Bug triage",
            summary = if (zh) "检查 backlog 并建议优先级" else "Review backlog issues and suggest priority",
            prompt = "Review untriaged issues, assess severity, assign priority, and explain the recommendation.",
            icon = Icons.Outlined.Bolt,
        ),
    )
}

