                Row(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        text = trigger.label.ifBlank { trigger.kind.ifBlank { if (zh) "定时触发器" else "Scheduled trigger" } },
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontSize = 14.sp,
                            lineHeight = 18.sp,
                            fontWeight = FontWeight.Medium,
                        ),
                        color = MulticaColors.Text,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    if (!trigger.enabled) {
                        Text(
                            text = if (zh) "停用" else "Disabled",
                            style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                        )
                    }
                }
                Text(
                    text = listOf(
                        if (trigger.enabled) if (zh) "已启用" else "enabled" else if (zh) "已停用" else "disabled",
                        clean(trigger.cronExpression),
                        clean(trigger.timezone),
                        clean(trigger.nextRunAt).takeIf { it.isNotBlank() }?.let { if (zh) "下次 $it" else "next $it" } ?: "",
                    ).filter { it.isNotBlank() }.joinToString(" · "),
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                    color = MulticaColors.Muted.copy(alpha = 0.72f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            MulticaIconPillButton(
                icon = Icons.Outlined.Edit,
                contentDescription = "Autopilot Trigger Update ${trigger.id}",
                onClick = onUpdate,
                tone = MulticaButtonTone.Ghost,
                modifier = Modifier
                    .size(34.dp)
                    .semantics { contentDescription = "Autopilot Trigger Update ${trigger.id}" },
            )
            MulticaIconPillButton(
                icon = Icons.Outlined.Delete,
                contentDescription = "Autopilot Trigger Delete ${trigger.id}",
                onClick = onDelete,
                tone = MulticaButtonTone.Destructive,
                modifier = Modifier
                    .size(34.dp)
                    .semantics { contentDescription = "Autopilot Trigger Delete ${trigger.id}" },
            )
        }
    }
}

@Composable
private fun AutopilotRunWebRow(run: Models.AutopilotRun, zh: Boolean) {
    val statusColor = when (run.status.lowercase(Locale.US)) {
        "completed", "issue_created" -> MulticaColors.Success
        "running", "queued" -> MulticaColors.Accent
        "failed" -> MulticaColors.Danger
        else -> MulticaColors.Muted
    }
    val shape = RoundedCornerShape(8.dp)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) { contentDescription = "Autopilot Run Web Row ${run.id}" },
        shape = shape,
        color = MulticaColors.Background,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.54f), shape)
                .padding(horizontal = 10.dp, vertical = 8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(Icons.Outlined.Bolt, contentDescription = null, tint = statusColor, modifier = Modifier.size(16.dp))
            Text(
                text = run.status.ifBlank { if (zh) "未知" else "unknown" },
                modifier = Modifier.width(84.dp),
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp, fontWeight = FontWeight.SemiBold),
                color = statusColor,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                text = run.source.ifBlank { if (zh) "manual" else "manual" },
                modifier = Modifier.width(70.dp),
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                color = MulticaColors.Muted,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                text = listOf(clean(run.issueId), clean(run.taskId), clean(run.failureReason)).filter { it.isNotBlank() }.joinToString(" · ").ifBlank {
                    if (zh) "无关联 Issue" else "No linked issue"
                },
                modifier = Modifier.weight(1f),
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                color = if (run.failureReason.isNotBlank()) MulticaColors.Danger else MulticaColors.Muted.copy(alpha = 0.72f),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                text = clean(run.triggeredAt).ifBlank { Models.shortId(run.id) },
                modifier = Modifier.width(90.dp),
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
                color = MulticaColors.TextTertiary,
                textAlign = TextAlign.End,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

@Composable
private fun PilotAutopilotsSettings(api: ApiClient, workspaceId: String, zh: Boolean, onBack: () -> Unit) {
    var state by remember(workspaceId) { mutableStateOf<Result<PilotAutopilotSettingsData>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var autopilotMode by remember(workspaceId) { mutableStateOf(AutopilotSettingsMode.List) }
    var title by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var template by remember { mutableStateOf("") }
    var agentIndex by remember { mutableIntStateOf(0) }
    var modeIndex by remember { mutableIntStateOf(0) }
    var statusIndex by remember { mutableIntStateOf(0) }
    var editing by remember { mutableStateOf<Models.Autopilot?>(null) }
    var pendingDelete by remember { mutableStateOf<Models.Autopilot?>(null) }
    var deletingAutopilotId by remember { mutableStateOf<String?>(null) }
    var updatingAutopilotStatusId by remember { mutableStateOf<String?>(null) }
    var autopilotActionMenuId by remember { mutableStateOf<String?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var saving by remember { mutableStateOf(false) }
    var triggerCron by remember { mutableStateOf("0 9 * * *") }
    var triggerTimezone by remember { mutableStateOf("Asia/Shanghai") }
    var triggerLabel by remember { mutableStateOf("") }
    var detailState by remember { mutableStateOf<Result<PilotAutopilotDetailData>?>(null) }
    val scope = rememberCoroutineScope()
    val modes = listOf("create_issue")
    val statuses = listOf("active", "paused", "archived")
    val editingId = editing?.id

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                val autopilots = api.autopilots(workspaceId)
                val agents = api.agents(workspaceId)
                val triggers = autopilots.flatMap { autopilot ->
                    runCatching { api.autopilotTriggers(workspaceId, autopilot.id) }.getOrDefault(emptyList())
                }
                PilotAutopilotSettingsData(autopilots, agents, triggers)
            }
        }
    }

    LaunchedEffect(workspaceId, editingId, refresh) {
        val id = editingId
        if (id == null) {
            detailState = null
        } else {
            detailState = null
            detailState = withContext(Dispatchers.IO) {
                runCatching { PilotAutopilotDetailData(api.autopilotTriggers(workspaceId, id), api.autopilotRuns(workspaceId, id)) }
            }
        }
    }

    fun resetForm() {
        autopilotMode = AutopilotSettingsMode.List
        editing = null
        title = ""
        description = ""
        template = ""
        agentIndex = 0
        modeIndex = 0
        statusIndex = 0
    }

    fun startCreate() {
        resetForm()
        autopilotMode = AutopilotSettingsMode.Create
        resultText = null
    }

    fun startCreateFromTemplate(templateOption: AutopilotTemplateOption) {
        startCreate()
        title = templateOption.title
        description = templateOption.prompt
        template = templateOption.title
    }

    fun startEdit(autopilot: Models.Autopilot, data: PilotAutopilotSettingsData) {
        autopilotMode = AutopilotSettingsMode.Edit
        editing = autopilot
        title = autopilot.title
        description = autopilot.description
        template = autopilot.issueTitleTemplate
        agentIndex = data.agents.indexOfFirst { it.id == autopilot.assigneeId }.takeIf { it >= 0 } ?: 0
        statusIndex = statuses.indexOf(autopilot.status).takeIf { it >= 0 } ?: 0
        modeIndex = modes.indexOf(autopilot.executionMode).takeIf { it >= 0 } ?: 0
        resultText = null
    }

    fun saveAutopilot(data: PilotAutopilotSettingsData) {
        val autopilotTitle = title.trim()
        if (autopilotTitle.isEmpty() || data.agents.isEmpty() || saving) return
        saving = true
        resultText = null
        val agent = data.agents[agentIndex.coerceAtMost(data.agents.lastIndex)]
        val mode = modes[modeIndex.coerceAtMost(modes.lastIndex)]
        val status = statuses[statusIndex.coerceAtMost(statuses.lastIndex)]
        val current = editing
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                if (current == null) {
                    runCatching {
                        val created = api.createAutopilot(workspaceId, autopilotTitle, description, agent.id, mode, template)
                        api.createAutopilotTrigger(workspaceId, created.id, "schedule", triggerCron, triggerTimezone, triggerLabel)
                        created
                    }
                } else {
                    runCatching { api.updateAutopilot(workspaceId, current, autopilotTitle, description, agent.id, status, mode, template) }
                }
            }
            saving = false
            result.onSuccess {
                resultText = if (zh) "已保存" else "Saved"
                resetForm()
                refresh++
            }.onFailure {
                resultText = "${if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun deleteAutopilot(autopilot: Models.Autopilot) {
        if (deletingAutopilotId != null) return
        deletingAutopilotId = autopilot.id
        resultText = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching { api.deleteAutopilot(workspaceId, autopilot.id) }
            }
            deletingAutopilotId = null
            result.onSuccess {
                if (editing?.id == autopilot.id) resetForm()
                pendingDelete = null
                resultText = if (zh) "Autopilot 已删除" else "Autopilot deleted"
                refresh++
            }.onFailure {
                resultText = "${if (zh) "删除失败" else "Delete failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun updateAutopilotStatus(autopilot: Models.Autopilot, nextStatus: String) {
        if (updatingAutopilotStatusId != null || autopilot.status == nextStatus) return
        updatingAutopilotStatusId = autopilot.id
        resultText = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    api.updateAutopilot(
                        workspaceId,
                        autopilot,
                        autopilot.title,
                        autopilot.description,
                        autopilot.assigneeId,
                        nextStatus,
                        autopilot.executionMode,
                        autopilot.issueTitleTemplate,
                    )
                }
            }
            updatingAutopilotStatusId = null
            result.onSuccess {
                resultText = if (nextStatus == "active") {
                    if (zh) "Autopilot 已恢复" else "Autopilot resumed"
                } else {
                    if (zh) "Autopilot 已暂停" else "Autopilot paused"
                }
                refresh++
            }.onFailure {
                resultText = "${if (zh) "状态更新失败" else "Status update failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (autopilotMode == AutopilotSettingsMode.Create || autopilotMode == AutopilotSettingsMode.Edit) {
        val editingAutopilot = editing
        PilotListPage(
            title = if (editingAutopilot == null) if (zh) "新建 Autopilot" else "New Autopilot" else if (zh) "编辑 Autopilot" else "Edit Autopilot",
            leading = {
                PilotSecondaryBackButton(
                    zh = zh,
                    onBack = { resetForm() },
                    contentDescription = if (zh) "返回 Autopilots" else "Back to Autopilots",
                )
            },
            bottomContent = {
                val data = state?.getOrNull()
                if (data != null && data.agents.isNotEmpty()) {
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth()
                            .imePadding(),
                        color = MulticaColors.Background,
                        tonalElevation = 0.dp,
                        shadowElevation = 0.dp,
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 26.dp, vertical = 14.dp),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                        ) {
                            MulticaPillButton(
                                text = if (zh) "取消" else "Cancel",
                                onClick = { resetForm() },
                                modifier = Modifier.weight(1f),
                                tone = MulticaButtonTone.Ghost,
                                contentDescription = "Autopilot Form Cancel",
                            )
                            MulticaPillButton(
                                text = if (saving) "..." else if (editingAutopilot == null) if (zh) "创建 Autopilot" else "Create Autopilot" else if (zh) "保存 Autopilot" else "Save Autopilot",
                                onClick = { saveAutopilot(data) },
                                modifier = Modifier.weight(1.2f),
                                tone = MulticaButtonTone.Primary,
                                contentDescription = if (editingAutopilot == null) "Autopilot Form Bottom Create" else "Autopilot Form Bottom Save",
                            )
                        }
                    }
                }
            },
        ) {
            val loaded = state
            when {
                loaded == null -> item { MulticaLoadingState(if (zh) "正在加载 Autopilots..." else "Loading autopilots...") }
                loaded.isFailure -> item {
                    MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${loaded.exceptionOrNull()?.message}", onRetry = { refresh++ })
                }
                else -> {
                    val data = loaded.getOrThrow()
                    item {
                        AutopilotFormWebHero(
                            title = if (editingAutopilot == null) {
                                if (zh) "新建 Autopilot" else "New Autopilot"
                            } else {
                                editingAutopilot.title
                            },
                            subtitle = if (editingAutopilot == null) {
                                if (zh) "创建一个定时或手动触发的 Agent 工作流" else "Create an agent workflow for scheduled or manual runs."
                            } else {
                                listOf(editingAutopilot.status, editingAutopilot.executionMode, editingAutopilot.lastRunAt)
                                    .filter { it.isNotBlank() }
                                    .joinToString(" · ")
                            },
                            editing = editingAutopilot != null,
                            zh = zh,
                        )
                    }
                    if (data.agents.isEmpty()) {
                        item {
                            MulticaErrorState(
                                if (zh) "没有可用 Agent，先创建 Agent 后再创建 Autopilot。" else "No agent is available. Create an agent before saving an autopilot.",
                                onRetry = { refresh++ },
                            )
                        }
                    }
                    item {
                        AutopilotFormTriggerConfigWebSection(
                            title = title,
                            onTitleChange = { title = it },
                            prompt = description,
                            onPromptChange = { description = it },
                            template = template,
                            onTemplateChange = { template = it },
                            cron = triggerCron,
                            onCronChange = { triggerCron = it },
                            timezone = triggerTimezone,
                            onTimezoneChange = { triggerTimezone = it },
                            label = triggerLabel,
                            onLabelChange = { triggerLabel = it },
                            zh = zh,
                        )
                    }
                    if (data.agents.isNotEmpty()) {
                        item {
                            val selectedAgentIndex = agentIndex.coerceAtMost(data.agents.lastIndex)
                            val selectedAgent = data.agents[selectedAgentIndex]
                            AutopilotFormWebMenuRow(
                                eyebrow = if (zh) "Assignee" else "Assignee",
                                title = selectedAgent.name,
                                subtitle = listOf(
                                    clean(selectedAgent.visibility),
                                    clean(selectedAgent.status),
                                    clean(selectedAgent.description),
                                ).filter { it.isNotBlank() }.joinToString(" · "),
                                contentDescription = "Autopilot Form Assignee Web Picker",
                                options = data.agents.mapIndexed { index, agent ->
                                    AutopilotFormMenuOption(
                                        label = agent.name,
                                        detail = listOf(
                                            clean(agent.visibility),
                                            clean(agent.status),
                                            clean(agent.description),
                                        ).filter { it.isNotBlank() }.joinToString(" · "),
                                        selected = index == selectedAgentIndex,
                                        onClick = { agentIndex = index },
                                    )
                                },
                            )
                        }
                    }
                    item {
                        val selectedModeIndex = modeIndex.coerceAtMost(modes.lastIndex)
                        val selectedMode = modes[selectedModeIndex]
                        AutopilotFormWebMenuRow(
                            eyebrow = if (zh) "模式" else "Mode",
                            title = selectedMode,
                            subtitle = if (selectedMode == "create_issue") {
                                if (zh) "每次运行创建 Issue" else "Create an issue from each run"
                            } else {
                                if (zh) "仅运行 Agent" else "Run agent without creating an issue"
                            },
                            contentDescription = "Autopilot Form Mode Web Picker",
                            options = modes.mapIndexed { index, mode ->
                                AutopilotFormMenuOption(
                                    label = mode,
                                    detail = if (mode == "create_issue") {
                                        if (zh) "每次运行创建 Issue" else "Create an issue from each run"
                                    } else {
                                        if (zh) "仅运行 Agent" else "Run agent without creating an issue"
                                    },
                                    selected = index == selectedModeIndex,
                                    onClick = { modeIndex = index },
                                )
                            },
                        )
                    }
                    item {
                        val selectedStatusIndex = statusIndex.coerceAtMost(statuses.lastIndex)
                        val selectedStatus = statuses[selectedStatusIndex]
                        AutopilotFormWebMenuRow(
                            eyebrow = if (zh) "状态" else "Status",
                            title = selectedStatus,
                            subtitle = if (editingAutopilot == null) {
                                if (zh) "新建后默认 active" else "New autopilots start active"
                            } else {
                                if (zh) "控制是否自动运行" else "Controls whether this workflow runs automatically"
                            },
                            contentDescription = "Autopilot Form Status Web Picker",
                            options = (if (editingAutopilot == null) listOf("active") else statuses).mapIndexed { index, status ->
                                val actualIndex = statuses.indexOf(status).takeIf { it >= 0 } ?: index
                                AutopilotFormMenuOption(
                                    label = status,
                                    detail = when (status) {
                                        "active" -> if (zh) "可按计划运行" else "Runs on schedule"
                                        "paused" -> if (zh) "暂停自动运行" else "Pauses scheduled runs"
                                        "archived" -> if (zh) "从活跃列表归档" else "Moves out of the active list"
                                        else -> null
                                    },
                                    selected = actualIndex == selectedStatusIndex,
                                    onClick = {
                                        if (editingAutopilot != null) statusIndex = actualIndex
                                    },
                                )
                            },
                        )
                    }
                    if (!resultText.isNullOrBlank()) {
                        item {
                            if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                                PilotInlineResultState(
                                    message = resultText.orEmpty(),
                                    isError = true,
                                    contentDescription = "Autopilot Form Result Web Banner",
                                )
                            } else {
                                MulticaSuccessState(resultText.orEmpty())
                            }
                        }
                    }
                    item {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            MulticaPillButton(if (zh) "取消" else "Cancel", onClick = { resetForm() }, modifier = Modifier.weight(1f), tone = MulticaButtonTone.Ghost)
                            MulticaPillButton(
                                text = if (saving) "..." else if (editingAutopilot == null) if (zh) "创建 Autopilot" else "Create Autopilot" else if (zh) "保存 Autopilot" else "Save Autopilot",
                                onClick = { saveAutopilot(data) },
                                modifier = Modifier.weight(1f),
                                tone = MulticaButtonTone.Primary,
                                contentDescription = if (editingAutopilot == null) "Autopilot Form Create" else "Autopilot Form Save",
                            )
                        }
                    }
                    editingAutopilot?.let { current ->
                        item { SettingsSectionLabel(if (zh) "触发器和运行历史" else "Triggers & Runs") }
                        item {
                            AutopilotTriggerComposerWebPanel(
                                cron = triggerCron,
                                onCronChange = { triggerCron = it },
                                timezone = triggerTimezone,
                                onTimezoneChange = { triggerTimezone = it },
                                label = triggerLabel,
                                onLabelChange = { triggerLabel = it },
                                zh = zh,
                                onAdd = {
                                    scope.launch {
                                        val result = withContext(Dispatchers.IO) {
                                            runCatching { api.createAutopilotTrigger(workspaceId, current.id, "cron", triggerCron, triggerTimezone, triggerLabel) }
                                        }
                                        result.onSuccess {
                                            triggerLabel = ""
                                            resultText = if (zh) "触发器已创建" else "Trigger created"
                                            refresh++
                                        }.onFailure {
                                            resultText = "${if (zh) "触发器创建失败" else "Trigger create failed"}: ${it.message ?: it.toString()}"
                                        }
                                    }
                                },
                            )
                        }
                        when (val detail = detailState) {
                            null -> item { MulticaLoadingState(if (zh) "正在加载详情..." else "Loading details...") }
                            else -> {
                                detail.onFailure {
                                    item { MulticaErrorState("${if (zh) "详情加载失败" else "Details failed"}\n${it.message}", onRetry = { refresh++ }) }
                                }.onSuccess { detail ->
                                    if (detail.triggers.isEmpty()) {
                                        item { AutopilotDetailTriggersWebEmptyState(zh = zh) }
                                    }
                                    items(detail.triggers) { trigger ->
                                        AutopilotTriggerWebRow(
                                            trigger = trigger,
                                            zh = zh,
                                            onUpdate = {
                                                scope.launch {
                                                    val result = withContext(Dispatchers.IO) {
                                                        runCatching {
                                                            api.updateAutopilotTrigger(
                                                                workspaceId,
                                                                current.id,
                                                                trigger.id,
                                                                trigger.enabled,
                                                                triggerCron,
                                                                triggerTimezone,
                                                                triggerLabel,
                                                            )
                                                        }
                                                    }
                                                    result.onSuccess {
                                                        resultText = if (zh) "触发器已更新" else "Trigger updated"
                                                        refresh++
                                                    }.onFailure {
                                                        resultText = "${if (zh) "更新触发器失败" else "Update trigger failed"}: ${it.message ?: it.toString()}"
                                                    }
                                                }
                                            },
                                            onDelete = {
                                                scope.launch {
                                                    val result = withContext(Dispatchers.IO) {
                                                        runCatching { api.deleteAutopilotTrigger(workspaceId, current.id, trigger.id) }
                                                    }
                                                    result.onSuccess {
                                                        resultText = if (zh) "触发器已删除" else "Trigger deleted"
                                                        refresh++
                                                    }.onFailure {
                                                        resultText = "${if (zh) "删除触发器失败" else "Delete trigger failed"}: ${it.message ?: it.toString()}"
                                                    }
                                                }
                                            },
                                        )
                                    }
                                    if (detail.runs.isEmpty()) {
                                        item { AutopilotDetailRunsWebEmptyState(zh = zh) }
                                    }
                                    items(detail.runs.take(8)) { run ->
                                        AutopilotRunWebRow(run = run, zh = zh)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "Autopilots" else "Autopilots",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = if (zh) "新建 Autopilot" else "New Autopilot",
                onClick = { startCreate() },
                tone = MulticaButtonTone.Primary,
            )
        },
    ) {
        val loaded = state
        if (loaded == null) {
            item { MulticaLoadingState(if (zh) "正在加载 Autopilots..." else "Loading autopilots...") }
        } else {
            loaded.onFailure { item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) } }
            loaded.onSuccess { data ->
                item {
                    AutopilotTemplateCompactStrip(
                        zh = zh,
                        onTemplateClick = { startCreateFromTemplate(it) },
                        onBlankClick = { startCreate() },
                        blankContentDescription = "Autopilot Create Entry",
                        blankArrowContentDescription = "Autopilot Create Entry Arrow",
                        blankTrailingIcon = Icons.Outlined.KeyboardArrowRight,
                    )
                }
                if (!resultText.isNullOrBlank()) {
                    item {
                        if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                            PilotInlineResultState(
                                message = resultText.orEmpty(),
                                isError = true,
                                contentDescription = "Autopilot List Result Web Banner",
                            )
                        } else {
                            MulticaSuccessState(resultText.orEmpty())
                        }
                    }
                }
                if (data.autopilots.isEmpty()) item { AutopilotsWebEmptyState(zh = zh) }
                if (data.autopilots.isNotEmpty()) {
                    item {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = "Autopilot Web Table Header" }
                                .padding(horizontal = 12.dp, vertical = 6.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Text(
                                if (zh) "工作流" else "Workflow",
                                modifier = Modifier.weight(1f),
                                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                color = MulticaColors.TextTertiary,
                            )
                            Text(
                                if (zh) "状态" else "State",
                                modifier = Modifier.width(72.dp),
                                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                color = MulticaColors.TextTertiary,
                                textAlign = TextAlign.Center,
                            )
                            Spacer(Modifier.width(42.dp))
                        }
                    }
                }
                items(data.autopilots) { autopilot ->
                    Column(modifier = Modifier.fillMaxWidth()) {
                        AutopilotWebDenseRow(
                            autopilot = autopilot,
                            agentName = data.agents.firstOrNull { it.id == autopilot.assigneeId }?.name ?: Models.shortId(autopilot.assigneeId),
                            triggerSummary = autopilotListTriggerSummary(
                                autopilot = autopilot,
                                triggers = data.triggers,
                                zh = zh,
                            ),
                            zh = zh,
                            actionsExpanded = autopilotActionMenuId == autopilot.id,
                            onActionsClick = {
                                autopilotActionMenuId = if (autopilotActionMenuId == autopilot.id) null else autopilot.id
                                pendingDelete = null
                                resultText = null
                            },
                            onEdit = {
                                autopilotActionMenuId = null
                                startEdit(autopilot, data)
                            },
                            onTrigger = {
                                autopilotActionMenuId = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) { runCatching { api.triggerAutopilot(workspaceId, autopilot.id) } }
                                    result.onSuccess { resultText = "${if (zh) "已触发" else "Triggered"}: ${it.status.ifBlank { Models.shortId(it.id) }}" }
                                        .onFailure { resultText = "${if (zh) "触发失败" else "Trigger failed"}: ${it.message ?: it.toString()}" }
                                }
                            },
                            onPauseResume = {
                                autopilotActionMenuId = null
                                val nextStatus = if (autopilot.status.equals("active", ignoreCase = true)) "paused" else "active"
                                updateAutopilotStatus(autopilot, nextStatus = nextStatus)
                            },
                            onDelete = {
                                autopilotActionMenuId = null
                                pendingDelete = autopilot
                            },
                        )
                        AutopilotRowCupertinoMoreMenu(
                            visible = autopilotActionMenuId == autopilot.id,
                            autopilot = autopilot,
                            isUpdatingStatus = updatingAutopilotStatusId == autopilot.id,
                            zh = zh,
                            onDismissRequest = { autopilotActionMenuId = null },
                            onEdit = {
                                autopilotActionMenuId = null
                                startEdit(autopilot, data)
                            },
                            onTrigger = {
                                autopilotActionMenuId = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) { runCatching { api.triggerAutopilot(workspaceId, autopilot.id) } }
                                    result.onSuccess { resultText = "${if (zh) "已触发" else "Triggered"}: ${it.status.ifBlank { Models.shortId(it.id) }}" }
                                        .onFailure { resultText = "${if (zh) "触发失败" else "Trigger failed"}: ${it.message ?: it.toString()}" }
                                }
                            },
                            onPauseResume = {
                                autopilotActionMenuId = null
                                val nextStatus = if (autopilot.status.equals("active", ignoreCase = true)) "paused" else "active"
                                updateAutopilotStatus(autopilot, nextStatus = nextStatus)
                            },
                            onDelete = {
                                autopilotActionMenuId = null
                                pendingDelete = autopilot
                            },
                        )
                    }
                }
            }
        }
    }
    pendingDelete?.let { autopilot ->
        MulticaCupertinoAlertDialog(
            visible = true,
            title = if (zh) "删除 Autopilot？" else "Delete autopilot?",
            message = if (zh) {
                "这会删除「${autopilot.title}」，并停止它后续的自动触发。"
            } else {
                "This deletes \"${autopilot.title}\" and stops its future automated triggers."
            },
            cancelText = if (zh) "取消" else "Cancel",
            confirmText = if (deletingAutopilotId == autopilot.id) "..." else if (zh) "删除" else "Delete",
            destructive = true,
            contentDescription = "Autopilot Delete Cupertino Alert ${autopilot.title}",
            onDismissRequest = {
                if (deletingAutopilotId == null) pendingDelete = null
            },
            onConfirm = { deleteAutopilot(autopilot) },
        )
    }
}

