private fun autopilotListTriggerSummary(
    autopilot: Models.Autopilot,
    triggers: List<Models.AutopilotTrigger>,
    zh: Boolean,
): String {
    val ownTriggers = triggers.filter { it.autopilotId == autopilot.id }
    if (ownTriggers.isEmpty()) return if (zh) "未配置触发器" else "No triggers configured"
    val enabledCount = ownTriggers.count { it.enabled }
    val primary = ownTriggers.firstOrNull { it.enabled } ?: ownTriggers.first()
    val label = clean(primary.label).ifBlank { clean(primary.kind).ifBlank { if (zh) "定时触发器" else "Scheduled trigger" } }
    val schedule = listOf(
        clean(primary.cronExpression),
        clean(primary.timezone),
        clean(primary.nextRunAt).takeIf { it.isNotBlank() }?.let { if (zh) "下次 $it" else "next $it" } ?: "",
    ).filter { it.isNotBlank() }.joinToString(" · ")
    val count = if (ownTriggers.size > 1) {
        if (zh) "$enabledCount/${ownTriggers.size} 已启用" else "$enabledCount/${ownTriggers.size} enabled"
    } else {
        if (primary.enabled) if (zh) "已启用" else "enabled" else if (zh) "已停用" else "disabled"
    }
    return listOf(label, count, schedule).filter { it.isNotBlank() }.joinToString(" · ")
}

