@Composable
private fun PilotRuntimesSettings(api: ApiClient, workspaceId: String, zh: Boolean, onBack: () -> Unit) {
    var state by remember(workspaceId) { mutableStateOf<Result<List<Models.Runtime>>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var pendingDelete by remember { mutableStateOf<Models.Runtime?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var selectedRuntime by remember(workspaceId) { mutableStateOf<Models.Runtime?>(null) }
    var runtimeSearch by remember(workspaceId) { mutableStateOf("") }
    var runtimeHealthFilter by remember(workspaceId) { mutableStateOf("all") }
    var expandedRuntimeActionsId by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    selectedRuntime?.let { runtime ->
        PilotRuntimeDetailSettings(
            api = api,
            workspaceId = workspaceId,
            runtime = runtime,
            zh = zh,
            onBack = { selectedRuntime = null },
        )
        return
    }

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) { runCatching { api.runtimes(workspaceId) } }
    }

    PilotListPage(
        title = if (zh) "Runtimes" else "Runtimes",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        if (!resultText.isNullOrBlank()) {
            item {
                if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                    PilotInlineResultState(
                        message = resultText.orEmpty(),
                        isError = true,
                        contentDescription = "Runtime List Result Web Banner",
                    )
                } else {
                    MulticaSuccessState(resultText.orEmpty())
                }
            }
        }
        pendingDelete?.let { runtime ->
            item {
                RuntimeDeleteConfirmWebPanel(
                    runtimeName = runtime.name,
                    zh = zh,
                    onCancel = { pendingDelete = null },
                    onConfirm = {
                        scope.launch {
                            val result = withContext(Dispatchers.IO) { runCatching { api.deleteRuntime(workspaceId, runtime.id) } }
                            result.onSuccess {
                                pendingDelete = null
                                resultText = if (zh) "Runtime 已删除" else "Runtime deleted"
                                refresh++
                            }.onFailure {
                                resultText = "${if (zh) "删除失败" else "Delete failed"}: ${it.message ?: it.toString()}"
                            }
                        }
                    },
                )
            }
        }
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载运行时..." else "Loading runtimes...") }
            else -> {
                loaded.onFailure { item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) } }
                loaded.onSuccess { runtimes ->
                    val healthOptions = listOf("all", "online", "recently_lost", "offline", "about_to_gc")
                    val filtered = runtimes.filter { runtime ->
                        val q = runtimeSearch.trim().lowercase(Locale.US)
                        val health = runtimeHealth(runtime)
                        val matchesHealth = runtimeHealthFilter == "all" || health == runtimeHealthFilter
                        val matchesQuery = q.isBlank() || listOf(runtime.name, runtime.provider, runtime.deviceInfo, runtime.version, runtime.runtimeMode)
                            .joinToString(" ")
                            .lowercase(Locale.US)
                            .contains(q)
                        matchesHealth && matchesQuery
                    }
                    item {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = "Runtime Web Filter Toolbar" },
                            verticalArrangement = Arrangement.spacedBy(10.dp),
                        ) {
                            MulticaTextField(
                                value = runtimeSearch,
                                onValueChange = { runtimeSearch = it },
                                label = if (zh) "搜索 Runtimes" else "Search runtimes",
                                singleLine = true,
                                contentDescription = "Runtime List Search",
                            )
                            LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                items(healthOptions) { option ->
                                    val count = if (option == "all") runtimes.size else runtimes.count { runtimeHealth(it) == option }
                                    SettingsWebFilterPill(
                                        text = "${runtimeHealthLabel(option, zh)} $count",
                                        selected = runtimeHealthFilter == option,
                                        onClick = { runtimeHealthFilter = option },
                                        contentDescription = "Runtime Health Filter ${runtimeHealthLabel(option, zh)}",
                                    )
                                }
                            }
                        }
                    }
                    if (runtimes.isEmpty()) item { RuntimesWebEmptyState(zh = zh) }
                    else if (filtered.isEmpty()) item {
                        RuntimesWebNoMatchesState(
                            zh = zh,
                            query = runtimeSearch.trim(),
                            filtered = runtimeHealthFilter != "all",
                        )
                    }
                    if (filtered.isNotEmpty()) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics { contentDescription = "Runtime Web Table Header" }
                                    .padding(horizontal = 12.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    if (zh) "Runtime" else "Runtime",
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                )
                                Text(
                                    if (zh) "健康" else "Health",
                                    modifier = Modifier.width(88.dp),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                    textAlign = TextAlign.Center,
                                )
                                Spacer(Modifier.width(42.dp))
                            }
                        }
                    }
                    items(filtered) { runtime ->
                        RuntimeWebDenseRow(
                            runtime = runtime,
                            zh = zh,
                            expanded = expandedRuntimeActionsId == runtime.id,
                            onExpandedChange = { expandedRuntimeActionsId = if (it) runtime.id else null },
                            onOpen = {
                                expandedRuntimeActionsId = null
                                selectedRuntime = runtime
                            },
                            onDelete = {
                                expandedRuntimeActionsId = null
                                pendingDelete = runtime
                            },
                        )
                    }
                }
            }
        }
    }
}

