@Composable
private fun RuntimeProviderMark(
    provider: String,
    runtimeMode: String,
    modifier: Modifier = Modifier,
) {
    val normalizedProvider = clean(provider).lowercase(Locale.US)
    val normalizedMode = clean(runtimeMode).lowercase(Locale.US)
    val label = clean(provider).ifBlank { clean(runtimeMode).ifBlank { "runtime" } }
    val initials = when (normalizedProvider) {
        "claude" -> "C"
        "codex" -> "O"
        "opencode" -> "OC"
        "openclaw" -> "CL"
        "hermes" -> "H"
        "pi" -> "PI"
        "copilot" -> "GH"
        "cursor" -> "CU"
        "kimi" -> "K"
        "kiro" -> "KI"
        else -> label.take(2).uppercase(Locale.US)
    }
    val tint = when {
        normalizedProvider == "claude" -> androidx.compose.ui.graphics.Color(0xFFD97757)
        normalizedProvider == "codex" -> MulticaColors.Text
        normalizedProvider == "cursor" -> androidx.compose.ui.graphics.Color(0xFF72716D)
        normalizedProvider == "kimi" -> androidx.compose.ui.graphics.Color(0xFF6D4BFF)
        normalizedProvider == "kiro" -> androidx.compose.ui.graphics.Color(0xFF9046FF)
        normalizedMode == "cloud" -> MulticaColors.Accent
        else -> MulticaColors.Muted
    }
    Box(
        modifier = modifier
            .size(34.dp)
            .clip(RoundedCornerShape(10.dp))
            .background(tint.copy(alpha = 0.11f))
            .semantics { contentDescription = "Runtime Provider Mark $label" },
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = initials.ifBlank { "R" },
            style = MaterialTheme.typography.labelSmall.copy(
                fontSize = if (initials.length > 1) 10.sp else 13.sp,
                lineHeight = 13.sp,
                fontWeight = FontWeight.Bold,
            ),
            color = tint,
            maxLines = 1,
        )
    }
}

