private fun splitRuntimeName(name: String): Pair<String, String?> {
    val trimmed = clean(name)
    val match = Regex("^(.+?)\\s+\\(([^)]+)\\)$").find(trimmed)
    return if (match != null) {
        match.groupValues[1] to match.groupValues[2]
    } else {
        trimmed to null
    }
}

private fun runtimeNeedsUpdate(runtime: Models.Runtime): Boolean {
    val status = clean(runtime.status).lowercase(Locale.US)
    return "update" in status || "upgrade" in status || "outdated" in status
}

private fun runtimeDisplayVersion(runtime: Models.Runtime): String {
    return clean(runtime.version)
        .ifBlank { extractRuntimeVersion(runtime.deviceInfo) }
        .ifBlank { Models.shortId(runtime.id) }
}

private fun extractRuntimeVersion(deviceInfo: String): String {
    val normalized = clean(deviceInfo)
    return Regex("""\d+(?:\.\d+){1,3}(?:[-+][A-Za-z0-9.]+)?""")
        .find(normalized)
        ?.value
        .orEmpty()
}

private fun runtimeUpdateLabel(runtime: Models.Runtime, zh: Boolean): String {
    val mode = clean(runtime.runtimeMode).lowercase(Locale.US)
    return when {
        runtimeNeedsUpdate(runtime) -> if (zh) "需更新" else "Update"
        mode == "cloud" -> if (zh) "托管" else "Managed"
        runtimeDisplayVersion(runtime) == Models.shortId(runtime.id) -> if (zh) "未知" else "Unknown"
        else -> if (zh) "检查" else "Check"
    }
}

private fun runtimeHealth(runtime: Models.Runtime): String {
    val status = clean(runtime.status).lowercase(Locale.US)
    return when {
        "about_to_gc" in status || "gc" in status -> "about_to_gc"
        "recent" in status || "lost" in status -> "recently_lost"
        "online" in status || "ready" in status || "connected" in status || "active" in status -> "online"
        else -> "offline"
    }
}

private fun runtimeHealthLabel(health: String, zh: Boolean): String = when (health) {
    "all" -> if (zh) "全部" else "All"
    "online" -> if (zh) "在线" else "Online"
    "recently_lost" -> if (zh) "刚离线" else "Lost"
    "about_to_gc" -> if (zh) "待回收" else "GC"
    else -> if (zh) "离线" else "Offline"
}

@Composable
private fun PilotRuntimeDetailSettings(
    api: ApiClient,
    workspaceId: String,
    runtime: Models.Runtime,
    zh: Boolean,
    onBack: () -> Unit,
) {
    var state by remember(workspaceId, runtime.id) { mutableStateOf<Result<PilotRuntimeDetailData>?>(null) }
    var refresh by remember(workspaceId, runtime.id) { mutableIntStateOf(0) }
    var targetVersion by remember { mutableStateOf("") }
    var updateRequest by remember { mutableStateOf<Models.RuntimeUpdate?>(null) }
    var modelList by remember { mutableStateOf<Models.RuntimeModelListRequest?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var capabilityResultText by remember { mutableStateOf<String?>(null) }
    var capabilityLoadingText by remember { mutableStateOf<String?>(null) }
    var loadingAction by remember { mutableStateOf(false) }
    var connectRemoteOpen by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    if (connectRemoteOpen) {
        PilotRuntimeConnectRemotePage(
            zh = zh,
            onBack = { connectRemoteOpen = false },
        )
        return
    }

    LaunchedEffect(workspaceId, runtime.id, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                val loadErrors = mutableListOf<String>()
                fun <T> loadRuntimeSection(label: String, fallback: T, block: () -> T): T {
                    return RuntimeSectionLoader.load(label, fallback, loadErrors) { block() }
                }
                PilotRuntimeDetailData(
                    usage = loadRuntimeSection("usage", emptyList()) { api.runtimeUsage(workspaceId, runtime.id, 30) },
                    activity = loadRuntimeSection("activity", emptyList()) { api.runtimeActivity(workspaceId, runtime.id) },
                    usageByAgent = loadRuntimeSection("usage by agent", emptyList()) { api.runtimeUsageByAgent(workspaceId, runtime.id, 30) },
                    usageByHour = loadRuntimeSection("usage by hour", emptyList()) { api.runtimeUsageByHour(workspaceId, runtime.id, 30) },
                    members = loadRuntimeSection("members", emptyList()) { api.members(workspaceId) },
                    agents = loadRuntimeSection("agents", emptyList()) { api.agents(workspaceId, true) },
                    loadErrors = loadErrors,
                )
            }
        }
    }

    fun setFailure(prefix: String, error: Throwable): String {
        val message = "$prefix: ${error.message ?: error.toString()}"
        resultText = message
        return message
    }

    fun scopedFailure(prefix: String, error: Throwable): String {
        return "$prefix: ${error.message ?: error.toString()}"
    }

    PilotListPage(
        title = if (zh) "Runtime 详情" else "Runtime Detail",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
    ) {
        item {
            CompactInfoPanel(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Hero" },
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Surface(
                        modifier = Modifier.size(34.dp),
                        shape = RoundedCornerShape(10.dp),
                        color = MulticaColors.Accent.copy(alpha = 0.10f),
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Icon(Icons.Outlined.Dashboard, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(18.dp))
                        }
                    }
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(
                            runtime.name,
                            style = MaterialTheme.typography.titleMedium.copy(fontSize = 16.sp, lineHeight = 20.sp, fontWeight = FontWeight.SemiBold),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                        Text(
                            listOf(runtime.status, runtime.provider, runtime.runtimeMode).filter { it.isNotBlank() }.joinToString(" · "),
                            style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
                            color = MulticaColors.Muted,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                    CompactMetaText(
                        label = if (zh) "设备" else "Device",
                        value = runtime.deviceInfo.ifBlank { if (zh) "未知" else "Unknown" },
                        modifier = Modifier.weight(1f),
                    )
                    CompactMetaText(
                        label = if (zh) "最后在线" else "Last Seen",
                        value = runtime.lastSeenAt.takeIf { it.isNotBlank() }?.let { shortDate(it) } ?: "-",
                        modifier = Modifier.weight(1f),
                    )
                }
                Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                    CompactMetaText(
                        label = "Daemon",
                        value = runtime.daemonId.ifBlank { "-" }.let { if (it == "-") it else Models.shortId(it) },
                        modifier = Modifier.weight(1f),
                    )
                    CompactMetaText(
                        label = if (zh) "版本" else "Version",
                        value = runtime.version.ifBlank { "-" },
                        modifier = Modifier.weight(1f),
                    )
                }
            }
        }
        if (!resultText.isNullOrBlank()) {
            item {
                if (resultText!!.contains("failed", true) || resultText!!.contains("失败")) {
                    PilotInlineResultState(
                        message = resultText.orEmpty(),
                        isError = true,
                        contentDescription = "Runtime Detail Result Web Banner",
                    )
                } else {
                    MulticaSuccessState(resultText.orEmpty())
                }
            }
        }
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载 Runtime 详情..." else "Loading runtime detail...") }
            else -> {
                loaded.onFailure { item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) } }
                loaded.onSuccess { data ->
                    val owner = data.members.firstOrNull { it.id == runtime.ownerId }?.displayName
                    val servingAgents = data.agents.filter { it.runtimeId == runtime.id }
                    val usageTotal = data.usage.sumOf { it.totalTokens() }
                    val inputTotal = data.usage.sumOf { it.inputTokens }
                    val outputTotal = data.usage.sumOf { it.outputTokens }

                    item { SettingsSectionLabel(if (zh) "用量 · 30 天" else "Usage · 30D") }
                    if (data.loadErrors.isNotEmpty()) {
                        item {
                            CompactInfoPanel(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Partial Error Row" },
                            ) {
                                RuntimeDetailWebDenseRow(
                                    eyebrow = if (zh) "部分数据不可用" else "Partial data unavailable",
                                    title = if (zh) "Runtime 详情仍可继续查看" else "Runtime detail is still available",
                                    subtitle = data.loadErrors.joinToString("\n"),
                                    icon = Icons.Outlined.Bolt,
                                    contentDescription = "Runtime Detail Web Partial Error Row",
                                )
                            }
                        }
                    }
                    item {
                        CompactInfoPanel(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Usage Metrics Runtime Usage Compact Metric Cards" },
                        ) {
                            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                                CompactMetaText(if (zh) "总 Tokens" else "Tokens", usageTotal.toString(), Modifier.weight(1f))
                                CompactMetaText("Input", inputTotal.toString(), Modifier.weight(1f))
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                                CompactMetaText("Output", outputTotal.toString(), Modifier.weight(1f))
                                CompactMetaText("Owner", owner ?: "-", Modifier.weight(1f))
                            }
                        }
                    }

                    if (data.activity.isNotEmpty()) {
                        item { SettingsSectionLabel(if (zh) "活动" else "Activity") }
                        item {
                            CompactInfoPanel(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Activity" },
                            ) {
                                val rows = data.activity.take(5)
                                rows.forEachIndexed { index, row ->
                                    RuntimeDetailWebDenseRow(
                                        eyebrow = if (zh) "小时" else "Hour",
                                        title = row.hour,
                                        subtitle = "${row.totalTasks} tasks",
                                        icon = Icons.Outlined.CalendarMonth,
                                        contentDescription = "Runtime Detail Web Dense Row Activity ${row.hour}",
                                        showDivider = index < rows.lastIndex,
                                    )
                                }
                            }
                        }
                    }

                    if (data.usageByHour.isNotEmpty()) {
                        item { SettingsSectionLabel(if (zh) "按小时用量" else "Usage by Hour") }
                        item {
                            CompactInfoPanel(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Usage By Hour" },
                            ) {
                                val rows = data.usageByHour.take(5)
                                RuntimeUsageHourMiniBars(rows = rows, zh = zh)
                                rows.forEachIndexed { index, row ->
                                    RuntimeDetailWebDenseRow(
                                        eyebrow = row.model,
                                        title = row.hour,
                                        subtitle = "${row.totalTokens()} tokens",
                                        icon = Icons.Outlined.Dashboard,
                                        contentDescription = "Runtime Detail Web Dense Row Usage Hour ${row.hour}",
                                        showDivider = index < rows.lastIndex,
                                    )
                                }
                            }
                        }
                    }

                    if (servingAgents.isNotEmpty()) {
                        item { SettingsSectionLabel(if (zh) "关联 Agents" else "Serving Agents") }
                        item {
                            CompactInfoPanel(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Serving Agents" },
                            ) {
                                val visibleAgents = servingAgents.take(4)
                                visibleAgents.forEachIndexed { index, agent ->
                                    RuntimeDetailWebDenseRow(
                                        eyebrow = agent.status.ifBlank { agent.visibility },
                                        title = agent.name,
                                        subtitle = agent.description.ifBlank { agent.visibility },
                                        icon = Icons.Outlined.Person,
                                        contentDescription = "Runtime Detail Web Dense Row Agent ${agent.id}",
                                        showDivider = index < visibleAgents.lastIndex || servingAgents.size > visibleAgents.size,
                                    )
                                }
                                if (servingAgents.size > visibleAgents.size) {
                                    RuntimeDetailWebDenseRow(
                                        eyebrow = if (zh) "更多" else "More",
                                        title = if (zh) "还有 ${servingAgents.size - visibleAgents.size} 个 Agent" else "${servingAgents.size - visibleAgents.size} more agents",
                                        subtitle = if (zh) "完整列表保留在 Web/runtime 详情中" else "Full list remains available in runtime detail",
                                        icon = Icons.Outlined.MoreHoriz,
                                        contentDescription = "Runtime Detail Web Dense Row More Agents",
                                    )
                                }
                            }
                        }
                    }

                    if (data.usageByAgent.isNotEmpty()) {
                        item { SettingsSectionLabel(if (zh) "按 Agent 用量" else "Usage by Agent") }
                        item {
                            CompactInfoPanel(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Usage By Agent" },
                            ) {
                                val rows = data.usageByAgent.sortedByDescending { it.totalTokens() }.take(5)
                                rows.forEachIndexed { index, row ->
                                    RuntimeDetailWebDenseRow(
                                        eyebrow = row.model.ifBlank { "${row.taskCount} tasks" },
                                        title = row.agentName.ifBlank { Models.shortId(row.agentId) },
                                        subtitle = "${row.totalTokens()} tokens",
                                        icon = Icons.Outlined.Bolt,
                                        contentDescription = "Runtime Detail Web Dense Row Usage Agent ${row.agentId}",
                                        showDivider = index < rows.lastIndex,
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        item { SettingsSectionLabel(if (zh) "Runtime Update" else "Runtime Update") }
        item {
            MulticaTextField(
                value = targetVersion,
                onValueChange = { targetVersion = it },
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "Runtime Detail Target Version" },
                label = if (zh) "目标版本" else "Target version",
                singleLine = true,
            )
        }
        item {
            Row(modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                MulticaPillButton(
                    if (loadingAction) "..." else if (zh) "发起更新" else "Update Runtime",
                    onClick = {
                        val version = targetVersion.trim()
                        if (version.isEmpty() || loadingAction) {
                            resultText = if (zh) "请先填写目标版本" else "Enter a target version first"
                            return@MulticaPillButton
                        }
                        scope.launch {
                            loadingAction = true
                            val result = withContext(Dispatchers.IO) { runCatching { api.initiateRuntimeUpdate(workspaceId, runtime.id, version) } }
                            loadingAction = false
                            result.onSuccess {
                                updateRequest = it
                                resultText = "${if (zh) "已发起更新" else "Update started"}: ${it.status}"
                            }.onFailure { setFailure(if (zh) "更新失败" else "Update failed", it) }
                        }
                    },
                    modifier = Modifier.weight(1f),
                    tone = MulticaButtonTone.Secondary,
                )
                MulticaPillButton(
                    if (zh) "刷新状态" else "Refresh Status",
                    onClick = {
                        val requestId = updateRequest?.id.orEmpty()
                        if (requestId.isBlank() || loadingAction) return@MulticaPillButton
                        scope.launch {
                            loadingAction = true
                            val result = withContext(Dispatchers.IO) { runCatching { api.runtimeUpdateResult(workspaceId, runtime.id, requestId) } }
                            loadingAction = false
                            result.onSuccess {
                                updateRequest = it
                                resultText = "${if (zh) "更新状态" else "Update status"}: ${it.status}"
                            }.onFailure { setFailure(if (zh) "刷新失败" else "Refresh failed", it) }
                        }
                    },
                    modifier = Modifier.weight(1f),
                    tone = MulticaButtonTone.Ghost,
                )
            }
        }
        updateRequest?.let { update ->
            item {
                CompactInfoPanel(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Update Result Row" },
                ) {
                    RuntimeDetailWebDenseRow(
                        eyebrow = update.targetVersion,
                        title = update.status,
                        subtitle = update.error.ifBlank { update.output.ifBlank { update.id } },
                        icon = Icons.Outlined.ArrowUpward,
                        contentDescription = "Runtime Detail Web Update Result Row",
                    )
                }
            }
        }

        item { SettingsSectionLabel(if (zh) "连接远程 Runtime" else "Connect Remote") }
        item {
            CompactInfoPanel(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics(mergeDescendants = false) { contentDescription = "Runtime Connect Remote Entry Panel" },
            ) {
                RuntimeDetailWebDenseRow(
                    eyebrow = if (zh) "独立页面" else "Independent page",
                    title = if (zh) "连接远程 Runtime" else "Connect remote runtime",
                    subtitle = if (zh) "安装、配置、登录和启动命令" else "Install, configure, login, and daemon commands",
                    icon = Icons.Outlined.Link,
                    contentDescription = "Runtime Connect Remote Entry",
                    onClick = { connectRemoteOpen = true },
                )
            }
        }

        item { SettingsSectionLabel(if (zh) "Runtime Capabilities" else "Runtime Capabilities") }
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 8.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                    MulticaPillButton(
                        if (loadingAction && capabilityLoadingText != null) {
                            capabilityLoadingText.orEmpty()
                        } else if (zh) "刷新模型" else "Refresh Models",
                        onClick = {
                            if (loadingAction) return@MulticaPillButton
                            val loadingMessage = if (zh) "正在刷新模型..." else "Refreshing models..."
                            capabilityResultText = loadingMessage
                            capabilityLoadingText = loadingMessage
                            scope.launch {
                                loadingAction = true
                                val result = runCatching {
                                    withTimeout(15000) {
                                        withContext(Dispatchers.IO) { api.initiateListRuntimeModels(workspaceId, runtime.id) }
                                    }
                                }
                                loadingAction = false
                                capabilityLoadingText = null
                                result.onSuccess {
                                    modelList = it
                                    val message = "${if (zh) "模型请求" else "Model request"}: ${it.status}"
                                    capabilityResultText = message
                                }.onFailure { capabilityResultText = scopedFailure(if (zh) "模型刷新失败" else "Refresh models failed", it) }
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        tone = MulticaButtonTone.Secondary,
                        contentDescription = "Runtime Refresh Models",
                    )
                if (!capabilityResultText.isNullOrBlank()) {
                    PilotInlineResultState(
                        message = capabilityResultText.orEmpty(),
                        isError = pilotInlineResultIsError(capabilityResultText.orEmpty()),
                        contentDescription = "Runtime Capability Result Web Banner",
                    )
                }
            }
        }
        modelList?.let { list ->
            item {
                MulticaPillButton(
                    if (loadingAction) "..." else if (zh) "检查模型结果" else "Check Models Result",
                    onClick = {
                        if (loadingAction || list.id.isBlank()) return@MulticaPillButton
                        capabilityResultText = if (zh) "正在检查模型结果..." else "Checking models result..."
                        scope.launch {
                            loadingAction = true
                            val result = runCatching {
                                withTimeout(15000) {
                                    withContext(Dispatchers.IO) {
                                        api.runtimeModelListResult(workspaceId, runtime.id, list.id)
                                    }
                                }
                            }
                            loadingAction = false
                            result.onSuccess {
                                modelList = it
                                capabilityResultText = "${if (zh) "模型结果" else "Models result"}: ${it.status}"
                            }.onFailure {
                                capabilityResultText = scopedFailure(if (zh) "模型结果失败" else "Models result failed", it)
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth(),
                    tone = MulticaButtonTone.Secondary,
                    contentDescription = "Runtime Check Models Result",
                )
            }
            item {
                CompactInfoPanel(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics(mergeDescendants = false) { contentDescription = "Runtime Detail Web Model Results" },
                ) {
                    val visibleModels = list.models.take(8)
                    RuntimeDetailWebDenseRow(
                        eyebrow = if (list.supported) "supported" else list.id.ifBlank { "models" },
                        title = "Models · ${list.status}",
                        subtitle = list.error.ifBlank { "${list.models.size} models" },
                        icon = Icons.Outlined.Dashboard,
                        contentDescription = "Runtime Detail Web Model Result Row",
                        showDivider = visibleModels.isNotEmpty(),
                    )
                    visibleModels.forEachIndexed { index, model ->
                        RuntimeDetailWebDenseRow(
                            eyebrow = model.provider.ifBlank { "model" },
                            title = model.name,
                            subtitle = model.id.ifBlank { null },
                            icon = Icons.Outlined.Bolt,
                            contentDescription = "Runtime Detail Web Model Row ${model.id.ifBlank { model.name }}",
                            showDivider = index < visibleModels.lastIndex,
                        )
                    }
                }
            }
        }
        item { Spacer(modifier = Modifier.height(120.dp)) }
    }
}

