@Composable
private fun RuntimeUsageHourMiniBars(
    rows: List<Models.RuntimeUsageByHour>,
    zh: Boolean,
    modifier: Modifier = Modifier,
) {
    val maxTokens = rows.maxOfOrNull { it.totalTokens() } ?: 0L
    Column(
        modifier = modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = false) { contentDescription = "Runtime Usage Hour Mini Bars" },
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        rows.forEach { row ->
            val total = row.totalTokens()
            val fraction = if (maxTokens <= 0L) 0.04f else (total.toFloat() / maxTokens.toFloat()).coerceIn(0.04f, 1f)
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "Runtime Usage Hour Mini Bar ${row.hour}" },
                verticalArrangement = Arrangement.spacedBy(4.dp),
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        text = if (zh) "${row.hour} 点" else "Hour ${row.hour}",
                        modifier = Modifier.weight(1f),
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        text = "${total} tokens",
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp, fontFamily = FontFamily.Monospace),
                        color = MulticaColors.TextTertiary,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(6.dp)
                        .clip(RoundedCornerShape(99.dp))
                        .background(MulticaColors.Border.copy(alpha = 0.55f)),
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(fraction)
                            .height(6.dp)
                            .clip(RoundedCornerShape(99.dp))
                            .background(MulticaColors.Accent.copy(alpha = 0.72f)),
                    )
                }
            }
        }
    }
}

@Composable
private fun RuntimeDetailWebDenseRow(
    eyebrow: String,
    title: String,
    subtitle: String?,
    icon: ImageVector,
    contentDescription: String,
    showDivider: Boolean = false,
    onClick: (() -> Unit)? = null,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) { this.contentDescription = contentDescription },
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .then(if (onClick == null) Modifier else Modifier.clickable(onClick = onClick))
                .padding(vertical = 7.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Surface(
                modifier = Modifier.size(26.dp),
                shape = RoundedCornerShape(999.dp),
                color = MulticaColors.Accent.copy(alpha = 0.10f),
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Icon(icon, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(14.dp))
                }
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    text = eyebrow.uppercase(),
                    style = MaterialTheme.typography.labelSmall.copy(
                        fontSize = 8.sp,
                        lineHeight = 10.sp,
                        fontWeight = FontWeight.SemiBold,
                    ),
                    color = MulticaColors.Muted,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodySmall.copy(
                        fontSize = 13.sp,
                        lineHeight = 16.sp,
                        fontWeight = FontWeight.Medium,
                    ),
                    color = MulticaColors.Text,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                if (!subtitle.isNullOrBlank()) {
                    Text(
                        text = subtitle,
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp),
                        color = MulticaColors.Muted,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
        }
        if (showDivider) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(1.dp)
                    .background(MulticaColors.Border)
            )
        }
    }
}

private enum class LabelSettingsMode { List, Create, Edit }

private data class PilotLabelsSettingsData(
    val labels: List<Models.IssueLabel>,
    val usageCounts: Map<String, Int>,
    val sampledIssueCount: Int,
    val usageHasMore: Boolean,
)

private val LABEL_COLOR_PALETTE = listOf(
    "#ef4444", "#f97316", "#eab308", "#22c55e", "#14b8a6",
    "#3b82f6", "#6366f1", "#a855f7", "#ec4899", "#64748b",
)

private const val WEB_SSOT_LABEL_CHIP = "/Users/park0er/coding/multica-web-source/packages/views/labels/label-chip.tsx"
private const val WEB_SSOT_LABELS_PANEL_PATH = "/Users/park0er/coding/multica-web-source/packages/views/issues/components/labels-panel.tsx"
private const val WEB_SSOT_LABEL_PICKER = "/Users/park0er/coding/multica-web-source/packages/views/issues/components/pickers/label-picker.tsx"

@Composable
private fun PilotLabelsSettings(api: ApiClient, workspaceId: String, zh: Boolean, onBack: () -> Unit) {
    var state by remember(workspaceId) { mutableStateOf<Result<PilotLabelsSettingsData>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var mode by remember(workspaceId) { mutableStateOf(LabelSettingsMode.List) }
    var formLabel by remember(workspaceId) { mutableStateOf<Models.IssueLabel?>(null) }
    var formName by remember(workspaceId) { mutableStateOf("") }
    var formColor by remember(workspaceId) { mutableStateOf("#3b82f6") }
    var saving by remember(workspaceId) { mutableStateOf(false) }
    var error by remember(workspaceId) { mutableStateOf<String?>(null) }
    var createdLabels by remember(workspaceId) { mutableStateOf<List<Models.IssueLabel>>(emptyList()) }
    var deletingLabel by remember(workspaceId) { mutableStateOf<Models.IssueLabel?>(null) }
    var mutatingLabelId by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                val labels = api.labels(workspaceId)
                val issuesPage = runCatching { api.issues(workspaceId, 250, 0) }.getOrNull()
                PilotLabelsSettingsData(
                    labels = labels,
                    usageCounts = labelUsageCounts(issuesPage?.items.orEmpty()),
                    sampledIssueCount = issuesPage?.items?.size ?: 0,
                    usageHasMore = issuesPage?.hasMore ?: false,
                )
            }
        }
    }

    fun openCreate() {
        mode = LabelSettingsMode.Create
        formLabel = null
        formName = ""
        formColor = "#3b82f6"
        deletingLabel = null
        error = null
    }

    fun openEdit(label: Models.IssueLabel) {
        mode = LabelSettingsMode.Edit
        formLabel = label
        formName = label.name
        formColor = normalizeLabelColor(label.color)
        deletingLabel = null
        error = null
    }

    fun closeForm() {
        mode = LabelSettingsMode.List
        formLabel = null
        formName = ""
        formColor = "#3b82f6"
    }

    fun saveForm() {
        val nextName = formName.trim()
        val nextColor = normalizeLabelColor(formColor)
        if (nextName.isBlank() || saving) return
        val editing = formLabel
        saving = true
        error = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    if (editing == null) {
                        api.createLabel(workspaceId, nextName, nextColor)
                    } else {
                        api.updateLabel(workspaceId, editing.id, nextName, nextColor)
                    }
                }
            }
            saving = false
            result.onSuccess { saved ->
                createdLabels = listOf(saved) + createdLabels.filter { it.id != saved.id }
                closeForm()
                refresh++
            }.onFailure {
                error = "${if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (mode != LabelSettingsMode.List) {
        LabelFormPage(
            mode = mode,
            label = formLabel,
            name = formName,
            color = formColor,
            saving = saving,
            error = error,
            zh = zh,
            onNameChange = { formName = it },
            onColorChange = { formColor = normalizeLabelColor(it) },
            onBack = { closeForm() },
            onSave = { saveForm() },
        )
        return
    }

    PilotListPage(
        title = if (zh) "Labels" else "Labels",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = "Label Header Create Button",
                onClick = { openCreate() },
                tone = MulticaButtonTone.Primary,
            )
        },
    ) {
        item {
            SettingsWebTabGroup(
                title = if (zh) "标签" else "Labels",
                subtitle = if (zh) {
                    "颜色标签用于跨列表、看板和详情页分类 issue"
                } else {
                    "Color labels classify issues across list, board, and detail surfaces"
                },
                contentDescription = "Label Management Web Intro /Users/park0er/coding/multica-web-source/packages/views/issues/components/labels-panel.tsx /Users/park0er/coding/multica-web-source/packages/views/issues/components/pickers/label-picker.tsx",
            ) {
                SettingsWebTabRow(
                    title = if (zh) "创建 Label" else "Create Label",
                    subtitle = if (zh) "使用 swatch palette 选择颜色" else "Choose from the swatch palette",
                    icon = Icons.Outlined.Add,
                    onClick = { openCreate() },
                    contentDescription = "Label Create Entry",
                )
            }
        }
        if (!error.isNullOrBlank()) item {
            PilotInlineResultState(
                message = error.orEmpty(),
                isError = true,
                contentDescription = "Label Result Web Banner",
            )
        }
        deletingLabel?.let { label ->
            item {
                MulticaCupertinoAlertDialog(
                    visible = true,
                    title = if (zh) "删除 Label？" else "Delete label?",
                    message = if (zh) {
                        "这会从整个工作区移除 ${label.name}。"
                    } else {
                        "This removes ${label.name} from the workspace."
                    },
                    cancelText = if (zh) "取消" else "Cancel",
                    confirmText = if (mutatingLabelId == label.id) "..." else if (zh) "删除" else "Delete",
                    destructive = true,
                    contentDescription = "Label Delete Cupertino Alert ${label.id}",
                    onDismissRequest = { deletingLabel = null },
                    onConfirm = {
                        if (mutatingLabelId != null) return@MulticaCupertinoAlertDialog
                        mutatingLabelId = label.id
                        error = null
                        scope.launch {
                            val result = withContext(Dispatchers.IO) {
                                runCatching { api.deleteLabel(workspaceId, label.id) }
                            }
                            mutatingLabelId = null
                            result.onSuccess {
                                deletingLabel = null
                                createdLabels = createdLabels.filter { it.id != label.id }
                                refresh++
                            }.onFailure {
                                error = "${if (zh) "删除失败" else "Delete failed"}: ${it.message ?: it.toString()}"
                            }
                        }
                    },
                )
            }
        }
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载 Labels..." else "Loading labels...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { data ->
                    val visibleLabels = createdLabels + data.labels.filter { label ->
                        createdLabels.none { it.id == label.id }
                    }
                    if (visibleLabels.isEmpty()) item { LabelsWebEmptyState(zh = zh) }
                    if (visibleLabels.isNotEmpty()) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics { contentDescription = "Label Web List Header" }
                                    .padding(horizontal = 12.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    if (zh) "标签" else "Label",
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                )
                                Text(
                                    if (zh) "使用情况" else "Usage",
                                    modifier = Modifier.width(108.dp),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                    textAlign = TextAlign.Center,
                                )
                                Spacer(Modifier.width(42.dp))
                            }
                        }
                    }
                    items(visibleLabels) { label ->
                        LabelWebDenseRow(
                            label = label,
                            usageCount = data.usageCounts[label.id] ?: 0,
                            usageApproximate = data.usageHasMore,
                            zh = zh,
                            onEdit = { openEdit(label) },
                            onDelete = { deletingLabel = label },
                        )
                    }
                }
            }
        }
    }
}

