private fun labelUsageCounts(issues: List<Models.Issue>): Map<String, Int> {
    val counts = LinkedHashMap<String, Int>()
    issues.forEach { issue ->
        issue.labels.forEach { label ->
            counts[label.id] = (counts[label.id] ?: 0) + 1
        }
    }
    return counts
}

private fun labelUsageText(count: Int, approximate: Boolean, zh: Boolean): String {
    val suffix = if (approximate && count > 0) "+" else ""
    return if (count == 0) {
        if (zh) "未使用" else "No usage"
    } else if (zh) {
        "$count$suffix 个 issue"
    } else {
        "$count$suffix ${if (count == 1) "issue" else "issues"}"
    }
}

private fun normalizeLabelColor(value: String): String {
    val trimmed = value.trim().ifBlank { "#3b82f6" }
    val withHash = if (trimmed.startsWith("#")) trimmed else "#$trimmed"
    return if (withHash.matches(Regex("^#[0-9a-fA-F]{6}$"))) {
        withHash.lowercase(Locale.US)
    } else {
        "#3b82f6"
    }
}

private fun labelContrastTextColor(hex: String): Color {
    val normalized = normalizeLabelColor(hex).removePrefix("#")
    val r = normalized.substring(0, 2).toInt(16) / 255f
    val g = normalized.substring(2, 4).toInt(16) / 255f
    val b = normalized.substring(4, 6).toInt(16) / 255f
    val luminance = 0.299f * r + 0.587f * g + 0.114f * b
    return if (luminance > 0.55f) Color(0xFF111827) else Color(0xFFF9FAFB)
}

private enum class SkillSettingsMode { List, Create, Edit, Import }

@Composable
private fun PilotSkillsSettings(api: ApiClient, workspaceId: String, zh: Boolean, onBack: () -> Unit) {
    var state by remember(workspaceId) { mutableStateOf<Result<List<Models.Skill>>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    var selectedSkill by remember(workspaceId) { mutableStateOf<Models.Skill?>(null) }
    var editing by remember(workspaceId) { mutableStateOf<Models.Skill?>(null) }
    var skillsMode by remember(workspaceId) { mutableStateOf(SkillSettingsMode.List) }
    var pendingDelete by remember(workspaceId) { mutableStateOf<Models.Skill?>(null) }
    var name by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var content by remember { mutableStateOf("") }
    var importUrl by remember { mutableStateOf("") }
    var importRuntimeId by remember { mutableStateOf("") }
    var importRuntimes by remember(workspaceId) { mutableStateOf<List<Models.Runtime>>(emptyList()) }
    var importRuntimeSkillsRequest by remember(workspaceId) { mutableStateOf<Models.RuntimeLocalSkillListRequest?>(null) }
    var importRuntimeSkillsLoading by remember(workspaceId) { mutableStateOf(false) }
    var importSelectedSkillKey by remember(workspaceId) { mutableStateOf("") }
    var importRuntimeRequest by remember(workspaceId) { mutableStateOf<Models.RuntimeLocalSkillImportRequest?>(null) }
    var saving by remember { mutableStateOf(false) }
    var error by remember { mutableStateOf<String?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var createdSkills by remember(workspaceId) { mutableStateOf<List<Models.Skill>>(emptyList()) }
    var deletedSkillIds by remember(workspaceId) { mutableStateOf<Set<String>>(emptySet()) }
    var skillQuery by remember(workspaceId) { mutableStateOf("") }
    var skillFilter by remember(workspaceId) { mutableStateOf("all") }
    var expandedSkillActionsId by remember(workspaceId) { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()

    fun resetForm() {
        editing = null
        skillsMode = SkillSettingsMode.List
        name = ""
        description = ""
        content = ""
    }

    fun startEdit(skill: Models.Skill) {
        selectedSkill = null
        editing = skill
        skillsMode = SkillSettingsMode.Edit
        name = skill.name
        description = clean(skill.description)
        content = clean(skill.content)
        error = null
        resultText = null
    }

    fun upsertVisible(skill: Models.Skill) {
        deletedSkillIds = deletedSkillIds - skill.id
        createdSkills = listOf(skill) + createdSkills.filter { it.id != skill.id }
    }

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) { runCatching { api.skills(workspaceId) } }
    }

    selectedSkill?.let { skill ->
        PilotSkillDetail(
            api = api,
            workspaceId = workspaceId,
            skill = skill,
            zh = zh,
            onBack = { selectedSkill = null },
            onEdit = { startEdit(it) },
        )
        return
    }

    if (skillsMode == SkillSettingsMode.Create || skillsMode == SkillSettingsMode.Edit) {
        val editingSkill = editing
        PilotListPage(
            title = if (editingSkill == null) {
                if (zh) "新建 Skill" else "New Skill"
            } else {
                if (zh) "编辑 Skill" else "Edit Skill"
            },
            leading = {
                PilotSecondaryBackButton(
                    zh = zh,
                    onBack = { resetForm() },
                    contentDescription = if (zh) "返回 Skills" else "Back to Skills",
                )
            },
        ) {
            item { SettingsSectionLabel(if (zh) "基础信息" else "Identity") }
            item {
                MulticaTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = if (zh) "名称" else "Name",
                    singleLine = true,
                    contentDescription = "Create Skill Form Name",
                )
            }
            item {
                MulticaTextField(
                    value = description,
                    onValueChange = { description = it },
                    label = if (zh) "描述" else "Description",
                    minLines = 2,
                    maxLines = 4,
                    contentDescription = "Create Skill Form Description",
                )
            }
            item { SettingsSectionLabel("SKILL.md") }
            item {
                MulticaTextField(
                    value = content,
                    onValueChange = { content = it },
                    label = if (zh) "内容" else "Content",
                    minLines = 8,
                    maxLines = 14,
                    contentDescription = "Create Skill Form Content",
                )
            }
            if (!error.isNullOrBlank()) item {
                PilotInlineResultState(
                    message = error.orEmpty(),
                    isError = true,
                    contentDescription = "Skill Form Result Web Banner",
                )
            }
            if (!resultText.isNullOrBlank()) item { MulticaSuccessState(resultText.orEmpty()) }
            item {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    MulticaPillButton(
                        text = if (zh) "取消" else "Cancel",
                        onClick = { resetForm() },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Ghost,
                    )
                    MulticaPillButton(
                        text = if (saving) "..." else if (editingSkill == null) if (zh) "创建" else "Create" else if (zh) "保存" else "Save",
                        onClick = {
                            val skillName = name.trim()
                            if (skillName.isEmpty() || saving) return@MulticaPillButton
                            saving = true
                            error = null
                            resultText = null
                            scope.launch {
                                val result = withContext(Dispatchers.IO) {
                                    if (editingSkill == null) {
                                        runCatching { api.createSkill(workspaceId, skillName, description, content) }
                                    } else {
                                        runCatching { api.updateSkill(workspaceId, editingSkill, skillName, description, content) }
                                    }
                                }
                                saving = false
                                result.onSuccess { created ->
                                    upsertVisible(created)
                                    resetForm()
                                    resultText = if (zh) "Skill 已保存" else "Skill saved"
                                    refresh++
                                }.onFailure {
                                    error = "${if (editingSkill == null) if (zh) "创建失败" else "Create failed" else if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
                                }
                            }
                        },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Primary,
                    )
                }
            }
        }
        return
    }

    if (skillsMode == SkillSettingsMode.Import) {
        val localImportRuntimes = importRuntimes.filter { runtime ->
            runtime.runtimeMode.equals("local", ignoreCase = true)
        }
        val selectedRuntime = localImportRuntimes.firstOrNull { it.id == importRuntimeId }
        val runtimeSkillRows = importRuntimeSkillsRequest?.skills.orEmpty()
        val selectedRuntimeSkill = runtimeSkillRows.firstOrNull { it.key == importSelectedSkillKey }

        LaunchedEffect(workspaceId, skillsMode) {
            if (skillsMode != SkillSettingsMode.Import) return@LaunchedEffect
            error = null
            val result = withContext(Dispatchers.IO) { runCatching { api.runtimes(workspaceId) } }
            result.onSuccess { runtimes ->
                importRuntimes = runtimes
                val local = runtimes.filter { it.runtimeMode.equals("local", ignoreCase = true) }
                if (importRuntimeId.isBlank() || local.none { it.id == importRuntimeId }) {
                    importRuntimeId = local.firstOrNull { it.status.equals("online", ignoreCase = true) }?.id
                        ?: local.firstOrNull()?.id.orEmpty()
                }
            }.onFailure {
                error = "${if (zh) "加载 Runtime 失败" else "Load runtimes failed"}: ${it.message ?: it.toString()}"
            }
        }

        LaunchedEffect(workspaceId, skillsMode, importRuntimeId, importRuntimes) {
            if (skillsMode != SkillSettingsMode.Import) return@LaunchedEffect
            importRuntimeSkillsRequest = null
            importSelectedSkillKey = ""
            val runtime = localImportRuntimes.firstOrNull { it.id == importRuntimeId }
            if (runtime == null || !runtime.status.equals("online", ignoreCase = true)) return@LaunchedEffect
            importRuntimeSkillsLoading = true
            error = null
            val result = withContext(Dispatchers.IO) {
                runCatching { resolveRuntimeLocalSkills(api, workspaceId, runtime.id) }
            }
            importRuntimeSkillsLoading = false
            result.onSuccess { request ->
                importRuntimeSkillsRequest = request
                importSelectedSkillKey = request.skills.firstOrNull()?.key.orEmpty()
            }.onFailure {
                error = "${if (zh) "加载本地 Skills 失败" else "Load local skills failed"}: ${it.message ?: it.toString()}"
            }
        }

        PilotListPage(
            title = if (zh) "导入 Skill" else "Import Skill",
            leading = {
                PilotSecondaryBackButton(
                    zh = zh,
                    onBack = {
                        skillsMode = SkillSettingsMode.List
                        importUrl = ""
                        importRuntimeId = ""
                        importRuntimeSkillsRequest = null
                        importSelectedSkillKey = ""
                        importRuntimeRequest = null
                        error = null
                        resultText = null
                    },
                    contentDescription = if (zh) "返回 Skills" else "Back to Skills",
                )
            },
        ) {
            item { SettingsSectionLabel(if (zh) "本地 Runtime" else "Runtime Local") }
            item {
                RuntimeLocalSkillImportPanel(
                    runtimes = localImportRuntimes,
                    selectedRuntimeId = importRuntimeId,
                    localSkillRequest = importRuntimeSkillsRequest,
                    selectedSkillKey = importSelectedSkillKey,
                    loadingSkills = importRuntimeSkillsLoading,
                    zh = zh,
                    onRuntimeSelected = { runtimeId ->
                        importRuntimeId = runtimeId
                        importRuntimeSkillsRequest = null
                        importSelectedSkillKey = ""
                        importRuntimeRequest = null
                    },
                    onSkillSelected = { skill ->
                        importSelectedSkillKey = skill.key
                        importRuntimeRequest = null
                    },
                    onImport = {
                        val runtimeId = importRuntimeId.trim()
                        val skill = selectedRuntimeSkill ?: return@RuntimeLocalSkillImportPanel
                        if (runtimeId.isBlank() || saving) return@RuntimeLocalSkillImportPanel
                        saving = true
                        error = null
                        resultText = null
                        scope.launch {
                            val result = withContext(Dispatchers.IO) {
                                runCatching { resolveRuntimeLocalSkillImport(api, workspaceId, runtimeId, skill) }
                            }
                            saving = false
                            result.onSuccess { request ->
                                importRuntimeRequest = request
                                request.skill?.let { imported ->
                                    upsertVisible(imported)
                                    skillsMode = SkillSettingsMode.List
                                    resultText = if (zh) "Runtime skill 已导入" else "Runtime skill imported"
                                    refresh++
                                }
                            }.onFailure {
                                error = "${if (zh) "Runtime 导入失败" else "Runtime import failed"}: ${it.message ?: it.toString()}"
                            }
                        }
                    },
                    importing = saving,
                )
            }
            item { SettingsSectionLabel(if (zh) "远程 URL" else "Remote URL") }
            item {
                MulticaTextField(
                    value = importUrl,
                    onValueChange = { importUrl = it },
                    label = if (zh) "导入 URL" else "Import URL",
                    singleLine = true,
                    contentDescription = "Import Skill Form URL",
                )
            }
            if (!error.isNullOrBlank()) item {
                PilotInlineResultState(
                    message = error.orEmpty(),
                    isError = true,
                    contentDescription = "Skill Import Result Web Banner",
                )
            }
            if (!resultText.isNullOrBlank()) item { MulticaSuccessState(resultText.orEmpty()) }
            item {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    MulticaPillButton(
                        text = if (zh) "取消" else "Cancel",
                        onClick = {
                            skillsMode = SkillSettingsMode.List
                            importUrl = ""
                            importRuntimeId = ""
                            importRuntimeSkillsRequest = null
                            importSelectedSkillKey = ""
                            importRuntimeRequest = null
                            error = null
                            resultText = null
                        },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Ghost,
                    )
                    MulticaPillButton(
                        text = if (saving) "..." else if (zh) "导入" else "Import",
                        onClick = {
                            val url = importUrl.trim()
                            if (url.isEmpty() || saving) return@MulticaPillButton
                            saving = true
                            error = null
                            resultText = null
                            scope.launch {
                                val result = withContext(Dispatchers.IO) {
                                    runCatching { api.importSkill(workspaceId, url) }
                                }
                                saving = false
                                result.onSuccess { imported ->
                                    importUrl = ""
                                    upsertVisible(imported)
                                    skillsMode = SkillSettingsMode.List
                                    resultText = if (zh) "Skill 已导入" else "Skill imported"
                                    refresh++
                                }.onFailure {
                                    error = "${if (zh) "导入失败" else "Import failed"}: ${it.message ?: it.toString()}"
                                }
                            }
                        },
                        modifier = Modifier.weight(1f),
                        tone = MulticaButtonTone.Primary,
                    )
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "Skills" else "Skills",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = if (zh) "新建 Skill" else "New Skill",
                onClick = {
                    resetForm()
                    skillsMode = SkillSettingsMode.Create
                    error = null
                    resultText = null
                },
                tone = MulticaButtonTone.Primary,
            )
        },
    ) {
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics {
                        contentDescription = "Skill Web Command Row /Users/park0er/coding/multica-web-source/packages/views/skills/components/skills-page.tsx /Users/park0er/coding/multica-web-source/packages/views/skills/components/skill-columns.tsx"
                    },
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp), modifier = Modifier.fillMaxWidth()) {
                    SkillCommandTile(
                        title = if (zh) "新建 Skill" else "Create Skill",
                        subtitle = if (zh) "编写名称、描述和 SKILL.md" else "Name, description, and SKILL.md",
                        icon = Icons.Outlined.Add,
                        modifier = Modifier.weight(1f),
                        contentDescription = "Skill Create Entry",
                        onClick = {
                            resetForm()
                            skillsMode = SkillSettingsMode.Create
                        },
                    )
                    SkillCommandTile(
                        title = if (zh) "导入" else "Import",
                        subtitle = if (zh) "本地 Runtime 或远程 URL" else "Local runtime or remote URL",
                        icon = Icons.Outlined.Link,
                        modifier = Modifier.weight(1f),
                        contentDescription = "Skill Import Entry",
                        onClick = {
                            skillsMode = SkillSettingsMode.Import
                            importUrl = ""
                            importRuntimeRequest = null
                            importRuntimeSkillsRequest = null
                            importSelectedSkillKey = ""
                            error = null
                            resultText = null
                        },
                    )
                }
                MulticaTextField(
                    value = skillQuery,
                    onValueChange = { skillQuery = it },
                    label = if (zh) "搜索 Skills" else "Search skills",
                    singleLine = true,
                    contentDescription = "Skill List Search",
                )
                LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    val filters = listOf("all", "manual", "imported", "with_files")
                    items(filters) { filter ->
                        SettingsWebFilterPill(
                            text = skillFilterLabel(filter, zh),
                            selected = skillFilter == filter,
                            onClick = { skillFilter = filter },
                            contentDescription = "Skill Scope Filter ${skillFilterLabel(filter, zh)}",
                        )
                    }
                }
            }
        }
        if (!error.isNullOrBlank()) item {
            PilotInlineResultState(
                message = error.orEmpty(),
                isError = true,
                contentDescription = "Skill List Result Web Banner",
            )
        }
        if (!resultText.isNullOrBlank()) item { MulticaSuccessState(resultText.orEmpty()) }
        pendingDelete?.let { skill ->
            item {
                SkillDeleteWebAlertPanel(
                    skill = skill,
                    zh = zh,
                    isDeleting = saving,
                    onCancel = { pendingDelete = null },
                    onConfirm = {
                        if (saving) return@SkillDeleteWebAlertPanel
                        saving = true
                        error = null
                        resultText = null
                        scope.launch {
                            val result = withContext(Dispatchers.IO) {
                                runCatching { api.deleteSkill(workspaceId, skill.id) }
                            }
                            saving = false
                            result.onSuccess {
                                if (editing?.id == skill.id) resetForm()
                                pendingDelete = null
                                deletedSkillIds = deletedSkillIds + skill.id
                                createdSkills = createdSkills.filter { it.id != skill.id }
                                resultText = if (zh) "Skill 已删除" else "Skill deleted"
                                refresh++
                            }.onFailure {
                                error = "${if (zh) "删除失败" else "Delete failed"}: ${it.message ?: it.toString()}"
                            }
                        }
                    },
                )
            }
        }
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载 Skills..." else "Loading skills...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) }
                }.onSuccess { skills ->
                    val visibleSkills = (createdSkills + skills.filter { skill ->
                        createdSkills.none { it.id == skill.id }
                    }).filter { it.id !in deletedSkillIds }
                    val filteredSkills = visibleSkills.filter { skill ->
                        val q = skillQuery.trim().lowercase(Locale.US)
                        val origin = skillOriginLabel(skill, zh).lowercase(Locale.US)
                        val matchesQuery = q.isBlank() || listOf(skill.name, skill.description, skill.content, origin)
                            .joinToString(" ")
                            .lowercase(Locale.US)
                            .contains(q)
                        val matchesFilter = when (skillFilter) {
                            "manual" -> skillOriginKey(skill) == "manual"
                            "imported" -> skillOriginKey(skill) != "manual"
                            "with_files" -> skillFileCount(skill) > 1
                            else -> true
                        }
                        matchesQuery && matchesFilter
                    }
                    if (visibleSkills.isEmpty()) item { SkillsWebEmptyState(zh = zh) }
                    else if (filteredSkills.isEmpty()) item {
                        SkillsWebNoMatchesState(
                            zh = zh,
                            query = skillQuery.trim(),
                            filtered = skillFilter != "all",
                        )
                    }
                    if (filteredSkills.isNotEmpty()) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .semantics { contentDescription = "Skill Web Table Header" }
                                    .padding(horizontal = 12.dp, vertical = 6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    if (zh) "Skill" else "Skill",
                                    modifier = Modifier.weight(1f),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                )
                                Text(
                                    if (zh) "来源" else "Source",
                                    modifier = Modifier.width(104.dp),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                    textAlign = TextAlign.Center,
                                )
                                Text(
                                    if (zh) "更新" else "Updated",
                                    modifier = Modifier.width(86.dp),
                                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.SemiBold),
                                    color = MulticaColors.TextTertiary,
                                    textAlign = TextAlign.Center,
                                )
                                Spacer(Modifier.width(42.dp))
                            }
                        }
                    }
                    items(filteredSkills) { skill ->
                        SkillWebDenseRow(
                            skill = skill,
                            zh = zh,
                            expanded = expandedSkillActionsId == skill.id,
                            onExpandedChange = { expandedSkillActionsId = if (it) skill.id else null },
                            onOpen = {
                                expandedSkillActionsId = null
                                selectedSkill = skill
                            },
                            onEdit = {
                                expandedSkillActionsId = null
                                startEdit(skill)
                            },
                            onDelete = {
                                expandedSkillActionsId = null
                                pendingDelete = skill
                            },
                        )
                    }
                }
            }
        }
    }
}

private suspend fun resolveRuntimeLocalSkills(
    api: ApiClient,
    workspaceId: String,
    runtimeId: String,
): Models.RuntimeLocalSkillListRequest {
    var current = api.initiateListRuntimeLocalSkills(workspaceId, runtimeId)
    val startedAt = System.currentTimeMillis()
    while (current.status == "pending" || current.status == "running") {
        if (System.currentTimeMillis() - startedAt > 30_000) {
            throw IllegalStateException("runtime local skill discovery timed out")
        }
        delay(500)
        current = api.runtimeLocalSkillListResult(workspaceId, runtimeId, current.id)
    }
    if (current.status == "failed" || current.status == "timeout") {
        throw IllegalStateException(current.error.ifBlank { "runtime local skill discovery failed" })
    }
    return current
}

private suspend fun resolveRuntimeLocalSkillImport(
    api: ApiClient,
    workspaceId: String,
    runtimeId: String,
    skill: Models.RuntimeLocalSkillInfo,
): Models.RuntimeLocalSkillImportRequest {
    var current = api.initiateImportRuntimeLocalSkill(
        workspaceId,
        runtimeId,
        skill.key,
        skill.name,
        skill.description,
    )
    val startedAt = System.currentTimeMillis()
    while (current.status == "pending" || current.status == "running") {
        if (System.currentTimeMillis() - startedAt > 30_000) {
            throw IllegalStateException("runtime local skill import timed out")
        }
        delay(500)
        current = api.runtimeLocalSkillImportResult(workspaceId, runtimeId, current.id)
    }
    if (current.status == "failed" || current.status == "timeout") {
        throw IllegalStateException(current.error.ifBlank { "runtime local skill import failed" })
    }
    if (current.skill == null) {
        throw IllegalStateException("runtime local skill import did not return a skill")
    }
    return current
}

@Composable
private fun RuntimeLocalSkillImportPanel(
    runtimes: List<Models.Runtime>,
    selectedRuntimeId: String,
    localSkillRequest: Models.RuntimeLocalSkillListRequest?,
    selectedSkillKey: String,
    loadingSkills: Boolean,
    zh: Boolean,
    onRuntimeSelected: (String) -> Unit,
    onSkillSelected: (Models.RuntimeLocalSkillInfo) -> Unit,
    onImport: () -> Unit,
    importing: Boolean,
) {
    val selectedRuntime = runtimes.firstOrNull { it.id == selectedRuntimeId }
    val localSkills = localSkillRequest?.skills.orEmpty()
    val selectedSkill = localSkills.firstOrNull { it.key == selectedSkillKey }
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics {
                contentDescription = "Runtime Local Skill Import Panel /Users/park0er/coding/multica-web-source/packages/views/skills/components/runtime-local-skill-import-panel.tsx"
            },
        shape = RoundedCornerShape(10.dp),
        color = MulticaColors.Surface.copy(alpha = 0.95f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        border = androidx.compose.foundation.BorderStroke(0.5.dp, MulticaColors.Border.copy(alpha = 0.70f)),
    ) {
        Column(
            modifier = Modifier.padding(13.dp),
            verticalArrangement = Arrangement.spacedBy(11.dp),
        ) {
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp), verticalAlignment = Alignment.CenterVertically) {
                Box(
                    modifier = Modifier
                        .size(34.dp)
                        .clip(RoundedCornerShape(9.dp))
                        .background(MulticaColors.AccentSoft.copy(alpha = 0.58f)),
                    contentAlignment = Alignment.Center,
                ) {
                    Icon(Icons.Outlined.Folder, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(18.dp))
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        if (zh) "从本地 Runtime 导入" else "Import from local runtime",
                        style = MaterialTheme.typography.titleSmall.copy(fontSize = 15.sp, lineHeight = 19.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                    )
                    Text(
                        if (zh) "选择一个在线 Runtime，系统会自动读取可导入的 Skills。" else "Choose an online runtime; available skills load automatically.",
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                        color = MulticaColors.Muted,
                    )
                }
            }
            CompactInfoPanel(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics(mergeDescendants = false) { contentDescription = "Skill Import Runtime Picker" },
            ) {
                if (runtimes.isEmpty()) {
                    RuntimeDetailWebDenseRow(
                        eyebrow = if (zh) "Runtime" else "Runtime",
                        title = if (zh) "没有本地 Runtime" else "No local runtimes",
                        subtitle = if (zh) "请先启动本地 Runtime 后再导入" else "Start a local runtime before importing",
                        icon = Icons.Outlined.Folder,
                        contentDescription = "Skill Import Runtime Empty",
                    )
                } else {
                    runtimes.forEachIndexed { index, runtime ->
                        RuntimeDetailWebDenseRow(
                            eyebrow = runtime.status.ifBlank { if (zh) "状态未知" else "Unknown" },
                            title = runtime.name.ifBlank { Models.shortId(runtime.id) },
                            subtitle = listOf(runtime.provider, runtime.deviceInfo, Models.shortId(runtime.id))
                                .filter { it.isNotBlank() }
                                .joinToString(" · "),
                            icon = if (runtime.id == selectedRuntimeId) Icons.Outlined.CheckCircle else Icons.Outlined.Folder,
                            contentDescription = "Skill Import Runtime Option ${runtime.id}",
                            showDivider = index < runtimes.lastIndex,
                            onClick = { onRuntimeSelected(runtime.id) },
                        )
                    }
                }
            }
            selectedRuntime?.let { runtime ->
                RuntimeDetailWebDenseRow(
                    eyebrow = if (zh) "已选择" else "Selected",
                    title = runtime.name.ifBlank { Models.shortId(runtime.id) },
                    subtitle = if (runtime.status.equals("online", ignoreCase = true)) {
                        if (zh) "在线，可以读取本地 Skills" else "Online; ready to load local skills"
                    } else {
                        if (zh) "该 Runtime 不在线，无法读取本地 Skills" else "This runtime is not online"
                    },
                    icon = Icons.Outlined.CheckCircle,
                    contentDescription = "Skill Import Runtime Selected Summary ${runtime.id}",
                )
            }
            CompactInfoPanel(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics(mergeDescendants = false) { contentDescription = "Skill Import Runtime Local Skills" },
            ) {
                when {
                    selectedRuntime == null -> {
                        RuntimeDetailWebDenseRow(
                            eyebrow = if (zh) "Skills" else "Skills",
                            title = if (zh) "请选择 Runtime" else "Choose a runtime",
                            subtitle = null,
                            icon = Icons.Outlined.Folder,
                            contentDescription = "Skill Import Runtime Local Skill Empty",
                        )
                    }
                    !selectedRuntime.status.equals("online", ignoreCase = true) -> {
                        RuntimeDetailWebDenseRow(
                            eyebrow = if (zh) "离线" else "Offline",
                            title = if (zh) "Runtime 需要在线" else "Runtime must be online",
                            subtitle = selectedRuntime.status,
                            icon = Icons.Outlined.Close,
                            contentDescription = "Skill Import Runtime Offline",
                        )
                    }
                    loadingSkills -> {
                        RuntimeDetailWebDenseRow(
                            eyebrow = if (zh) "读取中" else "Loading",
                            title = if (zh) "正在加载可导入 Skills..." else "Loading importable skills...",
                            subtitle = null,
                            icon = Icons.Outlined.Bolt,
                            contentDescription = "Skill Import Runtime Local Skill Loading",
                        )
                    }
                    localSkillRequest != null && !localSkillRequest.supported -> {
                        RuntimeDetailWebDenseRow(
                            eyebrow = if (zh) "不支持" else "Unsupported",
                            title = if (zh) "这个 Runtime 暂不支持本地 Skill 导入" else "This runtime does not support local skill import",
                            subtitle = localSkillRequest.error.ifBlank { null },
                            icon = Icons.Outlined.Close,
                            contentDescription = "Skill Import Runtime Unsupported",
                        )
                    }
                    localSkills.isEmpty() -> {
                        RuntimeDetailWebDenseRow(
                            eyebrow = if (zh) "Skills" else "Skills",
                            title = if (zh) "没有可导入的 Skill" else "No importable skills",
                            subtitle = if (zh) "Runtime 返回了空列表" else "The runtime returned an empty list",
                            icon = Icons.Outlined.Folder,
                            contentDescription = "Skill Import Runtime Local Skill Empty",
                        )
                    }
                    else -> {
                        localSkills.forEachIndexed { index, skill ->
                            RuntimeDetailWebDenseRow(
                                eyebrow = if (skill.key == selectedSkillKey) {
                                    if (zh) "已选择" else "Selected"
                                } else {
                                    skill.provider.ifBlank { if (zh) "本地" else "Local" }
                                },
                                title = skill.name.ifBlank { skill.key },
                                subtitle = skill.description.ifBlank { skill.path.ifBlank { skill.key } },
                                icon = if (skill.key == selectedSkillKey) Icons.Outlined.CheckCircle else Icons.Outlined.Link,
                                contentDescription = "Skill Import Runtime Local Skill Row ${skill.key}",
                                showDivider = index < localSkills.lastIndex,
                                onClick = { onSkillSelected(skill) },
                            )
                        }
                    }
                }
            }
            MulticaPillButton(
                text = if (importing) "..." else if (zh) "导入选中的 Skill" else "Import selected skill",
                onClick = onImport,
                modifier = Modifier.fillMaxWidth(),
                tone = MulticaButtonTone.Primary,
                enabled = selectedRuntime?.status.equals("online", ignoreCase = true) && selectedSkill != null && !importing,
                contentDescription = "Skill Import Runtime Action",
            )
        }
    }
}

@Composable
private fun SkillCommandTile(
    title: String,
    subtitle: String,
    icon: ImageVector,
    modifier: Modifier = Modifier,
    contentDescription: String,
    onClick: () -> Unit,
) {
    Surface(
        modifier = modifier
            .semantics { this.contentDescription = contentDescription }
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(8.dp),
        color = MulticaColors.AccentSoft.copy(alpha = 0.46f),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Accent.copy(alpha = 0.18f), RoundedCornerShape(8.dp))
                .padding(horizontal = 11.dp, vertical = 10.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(icon, contentDescription = null, tint = MulticaColors.Accent, modifier = Modifier.size(18.dp))
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(
                    title,
