private fun skillFilterLabel(filter: String, zh: Boolean): String = when (filter) {
    "manual" -> if (zh) "手动" else "Manual"
    "imported" -> if (zh) "导入" else "Imported"
    "with_files" -> if (zh) "多文件" else "Files"
    else -> if (zh) "全部" else "All"
}

private fun skillOriginKey(skill: Models.Skill): String {
    val origin = clean(skill.originType).lowercase(Locale.US)
    val url = clean(skill.originSourceUrl)
    return when {
        origin.isNotBlank() && origin != "manual" -> origin
        url.isNotBlank() -> "imported"
        else -> "manual"
    }
}

private fun skillOriginLabel(skill: Models.Skill, zh: Boolean): String = when (skillOriginKey(skill)) {
    "runtime_local" -> if (zh) "Runtime" else "Runtime"
    "clawhub" -> "Clawhub"
    "skills_sh" -> "skills.sh"
    "github" -> "GitHub"
    "imported" -> if (zh) "导入" else "Imported"
    else -> if (zh) "手动" else "Manual"
}

private fun skillCanEdit(skill: Models.Skill): Boolean {
    return skillOriginKey(skill) == "manual" || skill.originSourceUrl.isBlank()
}

private fun skillUpdatedLabel(skill: Models.Skill, zh: Boolean): String {
    val value = shortDate(skill.updatedAt.ifBlank { skill.createdAt })
    return value.ifBlank { if (zh) "未知" else "Unknown" }
}

private fun skillFileCount(skill: Models.Skill): Int {
    val base = if (clean(skill.content).isBlank()) 0 else 1
    return (base + skill.files.size).coerceAtLeast(1)
}

private fun validateSkillFilePath(path: String, existingPaths: List<String>): String? {
    val p = path.trim()
    return when {
        p.isBlank() -> "Path is required"
        p.startsWith("/") -> "Use a relative path"
        p.split("/").any { it == ".." } -> "Path cannot contain .."
        p == "SKILL.md" -> "SKILL.md is edited above"
        existingPaths.any { it == p } -> "File already exists"
        else -> null
    }
}

@Composable
private fun PilotSkillDetail(
    api: ApiClient,
    workspaceId: String,
    skill: Models.Skill,
    zh: Boolean,
    onBack: () -> Unit,
    onEdit: (Models.Skill) -> Unit,
) {
    var state by remember(workspaceId, skill.id) { mutableStateOf<Result<PilotSkillDetailData>?>(null) }
    var addFileOpen by remember(workspaceId, skill.id) { mutableStateOf(false) }
    var filePath by remember(workspaceId, skill.id) { mutableStateOf("") }
    var fileContent by remember(workspaceId, skill.id) { mutableStateOf("") }
    var fileSaving by remember(workspaceId, skill.id) { mutableStateOf(false) }
    var fileError by remember(workspaceId, skill.id) { mutableStateOf<String?>(null) }
    var selectedFilePath by remember(workspaceId, skill.id) { mutableStateOf("SKILL.md") }
    var viewerWrap by remember(workspaceId, skill.id) { mutableStateOf(true) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(workspaceId, skill.id) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                val detail = api.skill(workspaceId, skill.id)
                val files = runCatching { api.skillFiles(workspaceId, skill.id) }
                    .getOrElse { detail.files }
                    .ifEmpty { detail.files }
                PilotSkillDetailData(detail, files)
            }
        }
    }

    PilotListPage(
        title = if (zh) "Skill 详情" else "Skill Detail",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                MulticaPillButton(
                    text = if (zh) "编辑" else "Edit",
                    onClick = { onEdit(state?.getOrNull()?.skill ?: skill) },
                    tone = MulticaButtonTone.Secondary,
                )
            }
        },
    ) {
        when (val loaded = state) {
            null -> item { MulticaLoadingState(if (zh) "正在加载 Skill..." else "Loading skill...") }
            else -> {
                loaded.onFailure {
                    item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { state = null }) }
                }.onSuccess { data ->
                    val displayFiles = skillDisplayFilesSorted(data.skill, data.files)
                    val selectedFile = displayFiles.firstOrNull { it.path == selectedFilePath }
                        ?: displayFiles.firstOrNull()
                    item {
                        SkillDetailWebHero(
                            skill = data.skill,
                            fileCount = data.files.size,
                            originLabel = skillOriginLabel(data.skill, zh),
                            zh = zh,
                        )
                    }
                    item {
                        SkillDetailMobileFileBrowser(
                            files = displayFiles,
                            selectedPath = selectedFile?.path.orEmpty(),
                            wrap = viewerWrap,
                            zh = zh,
                            onSelect = { selectedFilePath = it },
                            onWrapChange = { viewerWrap = it },
                        )
                    }
                    item {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = "Skill Detail Web Add File Row" },
                            verticalArrangement = Arrangement.spacedBy(9.dp),
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                                    Text(
                                        if (zh) "文件" else "Files",
                                        style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.SemiBold),
                                        color = MulticaColors.TextTertiary,
                                    )
                                    Text(
                                        if (zh) "使用相对路径补充脚本、提示词或配置文件" else "Add scripts, prompts, or config with relative paths",
                                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 15.sp),
                                        color = MulticaColors.Muted,
                                        maxLines = 2,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                }
                                MulticaPillButton(
                                    text = if (addFileOpen) if (zh) "取消" else "Cancel" else if (zh) "添加文件" else "Add file",
                                    onClick = {
                                        addFileOpen = !addFileOpen
                                        fileError = null
                                    },
                                    tone = if (addFileOpen) MulticaButtonTone.Ghost else MulticaButtonTone.Secondary,
                                    icon = Icons.Outlined.Add,
                                    contentDescription = "Skill Detail Add File Toggle",
                                )
                            }
                            if (addFileOpen) {
                                Surface(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(8.dp),
                                    color = MulticaColors.Surface,
                                    tonalElevation = 0.dp,
                                    shadowElevation = 0.dp,
                                ) {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .border(1.dp, MulticaColors.Border.copy(alpha = 0.58f), RoundedCornerShape(8.dp))
                                            .padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(10.dp),
                                    ) {
                                        MulticaTextField(
                                            value = filePath,
                                            onValueChange = {
                                                filePath = it
                                                fileError = null
                                            },
                                            label = if (zh) "路径" else "Path",
                                            singleLine = true,
                                            contentDescription = "Skill Detail Add File Path",
                                        )
                                        MulticaTextField(
                                            value = fileContent,
                                            onValueChange = { fileContent = it },
                                            label = if (zh) "内容" else "Content",
                                            minLines = 4,
                                            maxLines = 8,
                                            contentDescription = "Skill Detail Add File Content",
                                        )
                                        if (!fileError.isNullOrBlank()) {
                                            Text(
                                                fileError.orEmpty(),
                                                style = MaterialTheme.typography.bodySmall,
                                                color = MulticaColors.Danger,
                                            )
                                        }
                                        MulticaPillButton(
                                            text = if (fileSaving) "..." else if (zh) "保存文件" else "Save file",
                                            onClick = {
                                                val nextPath = filePath.trim()
                                                val nextContent = fileContent
                                                val validation = validateSkillFilePath(nextPath, data.files.map { it.path })
                                                if (validation != null) {
                                                    fileError = validation
                                                    return@MulticaPillButton
                                                }
                                                if (fileSaving) return@MulticaPillButton
                                                fileSaving = true
                                                fileError = null
                                                scope.launch {
                                                    val result = withContext(Dispatchers.IO) {
                                                        runCatching { api.upsertSkillFile(workspaceId, data.skill.id, nextPath, nextContent) }
                                                    }
                                                    fileSaving = false
                                                    result.onSuccess { saved ->
                                                        val nextFiles = (data.files.filter { it.path != saved.path } + saved)
                                                            .sortedBy { it.path.lowercase(Locale.US) }
                                                        state = Result.success(data.copy(files = nextFiles))
                                                        filePath = ""
                                                        fileContent = ""
                                                        addFileOpen = false
                                                    }.onFailure {
                                                        fileError = "${if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
                                                    }
                                                }
                                            },
                                            modifier = Modifier.fillMaxWidth(),
                                            tone = MulticaButtonTone.Primary,
                                            contentDescription = "Skill Detail Add File Button",
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

