                    )
                }
                MulticaPillButton(
                    text = if (wrap) if (zh) "换行" else "Wrap" else if (zh) "横滚" else "Scroll",
                    onClick = { onWrapChange(!wrap) },
                    tone = MulticaButtonTone.Secondary,
                    contentDescription = "Skill Detail Viewer Wrap Toggle",
                )
            }
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "Skill Detail File Tree Panel" },
