) {
    val content = clean(file?.content).ifBlank { if (zh) "空文件" else "Empty file" }
    val isMarkdown = file?.path?.let { SkillFileTree.isMarkdownPath(it) } == true
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { contentDescription = "Skill Detail File Viewer Panel ${file?.path.orEmpty()}" },
        shape = RoundedCornerShape(8.dp),
        color = MulticaColors.Background,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        border = androidx.compose.foundation.BorderStroke(0.5.dp, MulticaColors.Border.copy(alpha = 0.62f)),
    ) {
        Column(
            modifier = Modifier.padding(10.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Text(
                file?.path ?: "SKILL.md",
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 14.sp, fontFamily = FontFamily.Monospace, fontWeight = FontWeight.SemiBold),
                color = MulticaColors.TextTertiary,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            if (isMarkdown) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Skill Detail Viewer Markdown ${file?.path.orEmpty()}" },
                ) {
                    MarkdownBlock(content)
                }
            } else {
                Text(
                    content,
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Skill Detail Viewer Monospace ${file?.path.orEmpty()}" },
                    style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp, fontFamily = FontFamily.Monospace),
                    color = MulticaColors.Text,
                    softWrap = wrap,
                    overflow = if (wrap) TextOverflow.Ellipsis else TextOverflow.Clip,
                )
            }
        }
    }
}

private fun skillDisplayFilesSorted(skill: Models.Skill, files: List<Models.SkillFile>): List<SkillDisplayFile> {
    val byPath = LinkedHashMap<String, SkillDisplayFile>()
    byPath["SKILL.md"] = SkillDisplayFile("SKILL.md", skill.content, isDirectory = false)
    val tree = SkillFileTree.build(files)
    SkillFileTree.flattenDisplayPaths(tree).forEach { path ->
        val file = files.firstOrNull { it.path == path }
        byPath[path] = SkillDisplayFile(path, file?.content.orEmpty(), isDirectory = path.endsWith("/"))
    }
    return byPath.values.sortedWith(
        compareBy<SkillDisplayFile> {
            skillDisplayFileSortBucket(path = it.path, isDirectory = it.isDirectory)
        }.thenBy { it.path.lowercase(Locale.US) }
    )
}

private fun skillDisplayFileSortBucket(path: String, isDirectory: Boolean): Int = when {
    path == "SKILL.md" -> 0
    isDirectory -> 1
    else -> 2
}

