@Composable
private fun PilotFeedbackSettingsContent(
    zh: Boolean,
    onBack: () -> Unit,
    initialTitle: String,
    initialType: String,
    initialMessage: String,
    initialContext: String,
    initialSubmitAttempted: Boolean,
    onSubmitFeedback: suspend (payload: String, context: String) -> Unit,
) {
    val WEB_SSOT_FEEDBACK_MODAL = "/Users/park0er/coding/multica-web-source/packages/views/modals/feedback.tsx"
    var feedbackTitle by remember { mutableStateOf(initialTitle) }
    var feedbackType by remember { mutableStateOf(initialType) }
    var message by remember { mutableStateOf(initialMessage) }
    var context by remember { mutableStateOf(initialContext) }
    var typePickerVisible by remember { mutableStateOf(false) }
    var submitAttempted by remember { mutableStateOf(initialSubmitAttempted) }
    var saving by remember { mutableStateOf(false) }
    var resultText by remember { mutableStateOf<String?>(null) }
    var resultIsError by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val haptic = LocalHapticFeedback.current
    val maxFeedbackLength = 10000
    val validationError = feedbackValidationError(feedbackTitle, message, maxFeedbackLength, zh)
    val canSubmit = validationError == null && !saving
    val selectedType = feedbackTypeOptions(zh).firstOrNull { it.key == feedbackType }
        ?: feedbackTypeOptions(zh).first()

    PilotListPage(
        title = if (zh) "Feedback" else "Feedback",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        bottomContent = {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .imePadding()
                    .semantics { contentDescription = "Feedback Web Bottom Bar" },
                color = MulticaColors.Background,
                tonalElevation = 0.dp,
                shadowElevation = 0.dp,
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(1.dp, MulticaColors.Border.copy(alpha = 0.45f), RoundedCornerShape(topStart = 8.dp, topEnd = 8.dp))
                        .padding(horizontal = 18.dp, vertical = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        "${message.length}/$maxFeedbackLength",
                        modifier = Modifier.weight(1f),
                        style = MaterialTheme.typography.labelSmall.copy(fontFamily = FontFamily.Monospace),
                        color = if (message.length > maxFeedbackLength) MulticaColors.Danger else MulticaColors.TextTertiary,
                    )
                    MulticaPillButton(
                        text = if (saving) "..." else if (zh) "发送" else "Send",
                        onClick = {
                            submitAttempted = true
                            val currentError = feedbackValidationError(feedbackTitle, message, maxFeedbackLength, zh)
                            if (currentError != null || saving) {
                                haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                resultText = null
                                return@MulticaPillButton
                            }
                            saving = true
                            resultText = null
                            resultIsError = false
                            val payload = feedbackPayloadMarkdown(
                                type = selectedType.label,
                                title = feedbackTitle,
                                message = message,
                                context = context,
                            )
                            val contextValue = context.trim()
                            scope.launch {
                                val result = runCatching { onSubmitFeedback(payload, contextValue) }
                                saving = false
                                result.onSuccess {
                                    haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                                    feedbackTitle = ""
                                    message = ""
                                    context = ""
                                    submitAttempted = false
                                    resultIsError = false
                                    resultText = if (zh) "反馈已提交" else "Feedback submitted"
                                }.onFailure {
                                    resultIsError = true
                                    resultText = "${if (zh) "提交失败" else "Submit failed"}: ${it.message ?: it.toString()}"
                                }
                            }
                        },
                        tone = if (canSubmit) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                        contentDescription = "Feedback Submit Bottom",
                        enabled = !saving,
                    )
                }
            }
        },
    ) {
        item {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentDescription = "Feedback Web Intro" },
                shape = RoundedCornerShape(8.dp),
                color = MulticaColors.Surface,
                tonalElevation = 0.dp,
                shadowElevation = 0.dp,
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .border(1.dp, MulticaColors.Border.copy(alpha = 0.58f), RoundedCornerShape(8.dp))
                        .padding(horizontal = 14.dp, vertical = 12.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp),
                ) {
                    Text(
                        if (zh) "告诉我们哪里卡住了，或者把你想要的体验直接写下来。" else "Tell us what feels rough, blocked, or missing.",
                        style = MaterialTheme.typography.titleSmall.copy(fontSize = 14.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                    )
                    Text(
                        if (zh) "Web 端使用富文本编辑器和附件；Android 当前先保持 Markdown 文本和当前 URL 上下文。" else "Web uses a rich editor and attachments; Android keeps Markdown text plus URL context for now.",
                        style = MaterialTheme.typography.bodySmall.copy(fontSize = 12.sp, lineHeight = 16.sp),
                        color = MulticaColors.Muted,
                    )
                }
            }
        }
        item {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics {
                        contentDescription = "Feedback Web Short Form $WEB_SSOT_FEEDBACK_MODAL"
                    },
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                MulticaTextField(
                    value = feedbackTitle,
                    onValueChange = {
                        feedbackTitle = it
                        resultText = null
                    },
                    modifier = Modifier.fillMaxWidth(),
                    label = if (zh) "标题" else "Title",
                    singleLine = true,
                    contentDescription = "Feedback Title Field",
                )
                FeedbackTypePickerRow(
                    selectedType = selectedType,
                    zh = zh,
                    onOpen = { typePickerVisible = true },
                )
                MulticaTextField(
                    value = message,
                    onValueChange = {
                        message = it
                        resultText = null
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Feedback Web Editor Feedback Message Cupertino Text Area" },
                    label = if (zh) "反馈内容" else "Message",
                    minLines = 7,
                    maxLines = 12,
                    contentDescription = "Feedback Message",
                )
                MulticaTextField(
                    value = context,
                    onValueChange = {
                        context = it
                        resultText = null
                    },
                    modifier = Modifier.fillMaxWidth(),
                    label = if (zh) "上下文 / URL" else "Context / URL",
                    minLines = 2,
                    maxLines = 3,
                    contentDescription = "Feedback Context Field",
                )
            }
        }
        if (submitAttempted && validationError != null) {
            item {
                PilotInlineResultState(
                    message = validationError,
                    isError = true,
                    contentDescription = "Feedback Inline Error",
                )
            }
        }
        if (!resultText.isNullOrBlank()) {
            item {
                if (resultIsError) {
                    PilotInlineResultState(
                        message = resultText.orEmpty(),
                        isError = true,
                        contentDescription = "Feedback Result Web Banner Feedback Inline Error",
                    )
                } else {
                    Box(modifier = Modifier.semantics { contentDescription = "Feedback Success Motion" }) {
                        MulticaSuccessState(resultText.orEmpty())
                    }
                }
            }
        }
    }
    MulticaCupertinoActionSheet(
        visible = typePickerVisible,
        title = if (zh) "反馈类型" else "Feedback type",
        message = if (zh) "选择最接近这条反馈的类别。" else "Choose the category closest to this note.",
        items = feedbackTypeOptions(zh).map { option ->
            MulticaCupertinoActionSheetItem(
                title = option.label,
                subtitle = option.detail,
                icon = option.icon,
                selected = option.key == feedbackType,
                contentDescription = "Feedback Type Action Sheet ${option.label}",
                onClick = {
                    feedbackType = option.key
                    resultText = null
                },
            )
        },
        cancelText = if (zh) "取消" else "Cancel",
        onDismissRequest = { typePickerVisible = false },
    )
}

