private data class FeedbackTypeOption(
    val key: String,
    val label: String,
    val detail: String,
    val icon: ImageVector,
)

private fun feedbackTypeOptions(zh: Boolean): List<FeedbackTypeOption> = listOf(
    FeedbackTypeOption(
        key = "bug",
        label = if (zh) "问题" else "Bug report",
        detail = if (zh) "有东西不工作或结果不对。" else "Something is broken or incorrect.",
        icon = Icons.Outlined.Flag,
    ),
    FeedbackTypeOption(
        key = "feature",
        label = if (zh) "功能建议" else "Feature request",
        detail = if (zh) "一个希望 Multica 支持的新能力。" else "A capability you want Multica to support.",
        icon = Icons.Outlined.Bolt,
    ),
    FeedbackTypeOption(
        key = "design",
        label = if (zh) "体验审美" else "Design feedback",
        detail = if (zh) "信息层级、动效、视觉或手感问题。" else "Hierarchy, motion, visuals, or interaction feel.",
        icon = Icons.Outlined.Tune,
    ),
    FeedbackTypeOption(
        key = "other",
        label = if (zh) "其他" else "Other",
        detail = if (zh) "不属于上面几类的反馈。" else "Anything that does not fit the other categories.",
        icon = Icons.Outlined.MoreHoriz,
    ),
)

private fun feedbackValidationError(title: String, message: String, maxFeedbackLength: Int, zh: Boolean): String? = when {
    title.trim().isEmpty() -> if (zh) "请填写标题。" else "Title is required."
    message.trim().isEmpty() -> if (zh) "请填写反馈内容。" else "Message is required."
    message.length > maxFeedbackLength -> if (zh) "反馈内容不能超过 $maxFeedbackLength 个字符。" else "Message must be $maxFeedbackLength characters or fewer."
    else -> null
}

private fun feedbackPayloadMarkdown(
    type: String,
    title: String,
    message: String,
    context: String,
): String {
    val cleanTitle = title.trim()
    val cleanMessage = message.trim()
    val cleanContext = context.trim()
    return buildString {
        appendLine("# $cleanTitle")
        appendLine()
        appendLine("- Type: $type")
        if (cleanContext.isNotEmpty()) {
            appendLine("- Context: $cleanContext")
        }
        appendLine()
        append(cleanMessage)
    }
}

@Composable
private fun AgentsOverviewPanel(data: PilotAgentSettingsData, zh: Boolean) {
    val total = data.agents.size
    val archived = data.agents.count { !it.archivedAt.isNullOrBlank() }
    val active = total - archived
    val activeTasks = data.taskSnapshot.count { it.status in setOf("queued", "dispatched", "running") }
    val runs30d = data.runCounts.sumOf { it.runCount }
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 44.dp)
            .padding(top = 2.dp, bottom = 8.dp)
            .semantics { contentDescription = "Agents Overview Compact Strip" },
        shape = RoundedCornerShape(12.dp),
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        LazyRow(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.66f), RoundedCornerShape(12.dp))
                .padding(horizontal = 8.dp, vertical = 7.dp),
            horizontalArrangement = Arrangement.spacedBy(7.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            item { AgentOverviewMetric(if (zh) "可用" else "Active", active.toString()) }
            item { AgentOverviewMetric(if (zh) "已归档" else "Archived", archived.toString()) }
            item { AgentOverviewMetric(if (zh) "活跃任务" else "Active tasks", activeTasks.toString()) }
            item { AgentOverviewMetric(if (zh) "30 天运行" else "Runs 30d", runs30d.toString()) }
        }
    }
}

