            .fillMaxWidth()
            .semantics {
                this.contentDescription = "$contentDescription $WEB_SSOT_AGENT_OVERVIEW_PANE $WEB_SSOT_AGENT_ACTIVITY_TAB"
            },
        verticalArrangement = Arrangement.spacedBy(0.dp),
    ) {
        AgentDetailWebSectionLabel(if (zh) "Activity" else "Activity", contentDescription)
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = shape,
            color = MulticaColors.Surface,
            tonalElevation = 0.dp,
            shadowElevation = 0.dp,
        ) {
