                    Text(
                        text = if (zh) "归档 Agent？" else "Archive agent?",
                        style = MaterialTheme.typography.bodyMedium.copy(fontSize = 14.sp, lineHeight = 18.sp, fontWeight = FontWeight.SemiBold),
                        color = MulticaColors.Text,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        text = if (zh) "归档 $agentName，可从 Archived 中恢复。" else "Archive $agentName. You can restore it from Archived.",
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 16.sp),
                        color = MulticaColors.Muted,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                MulticaPillButton(
                    text = if (zh) "取消" else "Cancel",
                    onClick = onCancel,
                    modifier = Modifier.weight(1f),
                    tone = MulticaButtonTone.Ghost,
                )
                MulticaPillButton(
                    text = if (archiving) "..." else if (zh) "归档" else "Archive",
                    onClick = onConfirm,
                    modifier = Modifier
                        .weight(1f)
                        .semantics { contentDescription = "Agent Archive Confirm Destructive $agentName" },
                    tone = MulticaButtonTone.Destructive,
                )
            }
        }
    }
}

@Composable
private fun AgentActionWebPanel(
    agentName: String,
    metricsSummary: String,
    recentTaskSummary: String?,
    archived: Boolean,
    tasksSummary: String,
    cancelResult: String?,
    cancelling: Boolean,
    restoring: Boolean,
    zh: Boolean,
    onEdit: () -> Unit,
    onArchive: () -> Unit,
    onCancelTasks: () -> Unit,
    onRestore: () -> Unit,
) {
    val shape = RoundedCornerShape(12.dp)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 6.dp)
            .semantics { contentDescription = "Agent Action Web Panel $agentName" },
        shape = shape,
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .border(1.dp, MulticaColors.Border.copy(alpha = 0.72f), shape)
                .padding(8.dp),
            verticalArrangement = Arrangement.spacedBy(2.dp),
        ) {
            AgentActionInfoRow(
                label = if (zh) "活动指标" else "Activity Metrics",
                value = metricsSummary,
                icon = Icons.Outlined.Dashboard,
                contentDescription = "Agent Action Metrics $agentName",
            )
            if (!recentTaskSummary.isNullOrBlank()) {
                AgentActionInfoRow(
                    label = if (zh) "最近任务" else "Recent Task",
                    value = recentTaskSummary,
                    icon = Icons.Outlined.DoneAll,
                    contentDescription = "Agent Action Recent Task $agentName",
                )
            }
            AgentActionCommandRow(
                title = if (zh) "编辑 Agent" else "Edit Agent",
                subtitle = agentName,
                icon = Icons.Outlined.Edit,
                contentDescription = "${if (zh) "编辑 Agent" else "Edit Agent"} $agentName",
                onClick = onEdit,
            )
            if (archived) {
                AgentActionCommandRow(
                    title = if (restoring) if (zh) "恢复中..." else "Restoring..." else if (zh) "恢复 Agent" else "Restore Agent",
                    subtitle = agentName,
                    icon = Icons.Outlined.Archive,
                    contentDescription = "${if (zh) "恢复 Agent" else "Restore Agent"} $agentName",
                    onClick = onRestore,
                )
            } else {
                AgentActionCommandRow(
                    title = if (zh) "归档 Agent" else "Archive Agent",
                    subtitle = agentName,
                    icon = Icons.Outlined.Archive,
                    destructive = true,
                    contentDescription = "${if (zh) "归档 Agent" else "Archive Agent"} $agentName",
                    onClick = onArchive,
                )
                AgentActionCommandRow(
                    title = if (cancelling) if (zh) "取消中..." else "Cancelling..." else if (zh) "取消任务" else "Cancel Tasks",
                    subtitle = tasksSummary,
                    icon = Icons.Outlined.Delete,
                    destructive = true,
                    contentDescription = "${if (zh) "取消任务" else "Cancel Tasks"} $agentName",
                    onClick = onCancelTasks,
                )
            }
            if (!cancelResult.isNullOrBlank()) {
                PilotInlineResultState(
                    message = cancelResult,
                    isError = false,
                    contentDescription = "Agent Action Result Web Banner",
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                )
            }
        }
    }
}

@Composable
private fun AgentActionInfoRow(
    label: String,
    value: String,
    icon: ImageVector,
    contentDescription: String,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .semantics { this.contentDescription = contentDescription }
            .padding(horizontal = 10.dp, vertical = 7.dp),
        horizontalArrangement = Arrangement.spacedBy(10.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(icon, contentDescription = null, tint = MulticaColors.Muted, modifier = Modifier.size(16.dp))
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
            Text(
                text = label,
                style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp, fontWeight = FontWeight.SemiBold),
                color = MulticaColors.Muted,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                text = value,
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                color = MulticaColors.Text,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

@Composable
private fun AgentActionCommandRow(
    title: String,
    subtitle: String,
    icon: ImageVector,
    contentDescription: String,
    onClick: () -> Unit,
    destructive: Boolean = false,
) {
    val haptic = LocalHapticFeedback.current
    val tint = if (destructive) MulticaColors.Danger else MulticaColors.Accent
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(8.dp))
            .clickable {
                haptic.performHapticFeedback(HapticFeedbackType.TextHandleMove)
                onClick()
            }
            .semantics(mergeDescendants = true) { this.contentDescription = contentDescription }
            .padding(horizontal = 10.dp, vertical = 9.dp),
        horizontalArrangement = Arrangement.spacedBy(10.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(icon, contentDescription = null, tint = tint, modifier = Modifier.size(16.dp))
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
            Text(
                text = title,
                style = MaterialTheme.typography.bodyMedium.copy(fontSize = 13.sp, lineHeight = 17.sp, fontWeight = FontWeight.SemiBold),
                color = if (destructive) MulticaColors.Danger else MulticaColors.Text,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                text = subtitle,
                style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                color = MulticaColors.Muted.copy(alpha = 0.72f),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
        Icon(Icons.Outlined.KeyboardArrowRight, contentDescription = null, tint = MulticaColors.Muted, modifier = Modifier.size(16.dp))
    }
}

@Composable
private fun PilotAgentsSettings(api: ApiClient, workspaceId: String, zh: Boolean, onBack: () -> Unit) {
    var state by remember(workspaceId) { mutableStateOf<Result<PilotAgentSettingsData>?>(null) }
    var refresh by remember(workspaceId) { mutableIntStateOf(0) }
    val listState = rememberLazyListState()
    val focusManager = LocalFocusManager.current
    var agentMode by remember(workspaceId) { mutableStateOf(AgentSettingsMode.List) }
    var editing by remember(workspaceId) { mutableStateOf<Models.Agent?>(null) }
    var name by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var instructions by remember { mutableStateOf("") }
    var model by remember { mutableStateOf("") }
    var avatarUrl by remember { mutableStateOf("") }
    var agentQuery by remember(workspaceId) { mutableStateOf("") }
    var agentArchiveView by remember(workspaceId) { mutableStateOf("active") }
    var agentActionMenuId by remember(workspaceId) { mutableStateOf<String?>(null) }
    var maxTasksText by remember { mutableStateOf("1") }
    var customEnvText by remember { mutableStateOf("") }
    var customEnvDirty by remember { mutableStateOf(false) }
    var customArgsText by remember { mutableStateOf("") }
    var runtimeIndex by remember { mutableIntStateOf(0) }
    var visibilityIndex by remember { mutableIntStateOf(0) }
    var selectedSkillIds by remember(workspaceId) { mutableStateOf<Set<String>>(emptySet()) }
    val selectedSkillGeneration = remember(workspaceId) { java.util.concurrent.atomic.AtomicInteger(0) }
    var saving by remember { mutableStateOf(false) }
    var uploadingAvatar by remember { mutableStateOf(false) }
    var archiving by remember { mutableStateOf(false) }
    var restoringAgentId by remember { mutableStateOf<String?>(null) }
    var pendingArchive by remember { mutableStateOf<Models.Agent?>(null) }
    var cancellingAgentTasks by remember { mutableStateOf<String?>(null) }
    var cancelTaskResults by remember(workspaceId) { mutableStateOf<Map<String, String>>(emptyMap()) }
    var error by remember { mutableStateOf<String?>(null) }
    var resultText by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current
    val visibilityOptions = listOf("private", "workspace", "public")
    val avatarLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        if (uri == null || uploadingAvatar) return@rememberLauncherForActivityResult
        uploadingAvatar = true
        error = null
        resultText = null
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() } ?: ByteArray(0)
                    api.uploadFile(
                        workspaceId,
                        displayNameForUri(context, uri),
                        context.contentResolver.getType(uri) ?: "application/octet-stream",
                        bytes,
                    )
                }
            }
            uploadingAvatar = false
            result.onSuccess { uploadedUrl ->
                avatarUrl = uploadedUrl
                resultText = if (zh) "头像已上传，请保存 Agent" else "Avatar uploaded. Save agent to apply."
            }.onFailure {
                error = "${if (zh) "头像上传失败" else "Avatar upload failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    fun resetForm() {
        focusManager.clearFocus(force = true)
        agentMode = AgentSettingsMode.List
        editing = null
        name = ""
        description = ""
        instructions = ""
        model = ""
        avatarUrl = ""
        maxTasksText = "1"
        customEnvText = ""
        customEnvDirty = false
        customArgsText = ""
        visibilityIndex = 0
        selectedSkillIds = emptySet()
        selectedSkillGeneration.incrementAndGet()
        agentActionMenuId = null
    }

    fun startCreate() {
        focusManager.clearFocus(force = true)
        agentMode = AgentSettingsMode.Create
        editing = null
        name = ""
        description = ""
        instructions = ""
        model = ""
        avatarUrl = ""
        maxTasksText = "1"
        customEnvText = ""
        customEnvDirty = true
        customArgsText = ""
        runtimeIndex = 0
        visibilityIndex = 0
        selectedSkillIds = emptySet()
        selectedSkillGeneration.incrementAndGet()
        error = null
        resultText = null
        agentActionMenuId = null
        scope.launch { listState.scrollToItem(0) }
    }

    fun startEdit(agent: Models.Agent, data: PilotAgentSettingsData) {
        focusManager.clearFocus(force = true)
        agentMode = AgentSettingsMode.Edit
        editing = agent
        name = agent.name
        description = clean(agent.description)
        instructions = clean(agent.instructions).ifBlank { clean(agent.description) }
        model = clean(agent.model)
        avatarUrl = clean(agent.avatarUrl)
        maxTasksText = agent.maxConcurrentTasks.coerceAtLeast(1).toString()
        customEnvText = agentCustomEnvPlaceholder(agent, zh)
        customEnvDirty = false
        customArgsText = agent.customArgs.joinToString("\n")
        runtimeIndex = data.runtimes.indexOfFirst { it.id == agent.runtimeId }.takeIf { it >= 0 } ?: 0
        visibilityIndex = visibilityOptions.indexOf(agent.visibility).takeIf { it >= 0 } ?: 0
        selectedSkillIds = emptySet()
        val loadGeneration = selectedSkillGeneration.incrementAndGet()
        error = null
        resultText = null
        agentActionMenuId = null
        scope.launch { listState.scrollToItem(0) }
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.agentSkills(workspaceId, agent.id) } }
            result.onSuccess { assigned ->
                if (editing?.id == agent.id && selectedSkillGeneration.get() == loadGeneration) {
                    selectedSkillIds = assigned.map { it.id }.toSet()
                }
            }
        }
    }

    fun startDuplicate(agent: Models.Agent, data: PilotAgentSettingsData) {
        focusManager.clearFocus(force = true)
        agentMode = AgentSettingsMode.Create
        editing = null
        name = if (zh) "${agent.name} 副本" else "Copy of ${agent.name}"
        description = clean(agent.description)
        instructions = clean(agent.instructions).ifBlank { clean(agent.description) }
        model = clean(agent.model)
        avatarUrl = clean(agent.avatarUrl)
        maxTasksText = agent.maxConcurrentTasks.coerceAtLeast(1).toString()
        customEnvText = ""
        customEnvDirty = true
        customArgsText = agent.customArgs.joinToString("\n")
        runtimeIndex = data.runtimes.indexOfFirst { it.id == agent.runtimeId }.takeIf { it >= 0 } ?: 0
        visibilityIndex = visibilityOptions.indexOf(agent.visibility).takeIf { it >= 0 } ?: 0
        selectedSkillIds = emptySet()
        val loadGeneration = selectedSkillGeneration.incrementAndGet()
        error = null
        resultText = null
        agentActionMenuId = null
        scope.launch { listState.scrollToItem(0) }
        scope.launch {
            val result = withContext(Dispatchers.IO) { runCatching { api.agentSkills(workspaceId, agent.id) } }
            result.onSuccess { assigned ->
                if (agentMode == AgentSettingsMode.Create && selectedSkillGeneration.get() == loadGeneration) {
                    selectedSkillIds = assigned.map { it.id }.toSet()
                }
            }
        }
    }

    LaunchedEffect(workspaceId, refresh) {
        state = null
        state = withContext(Dispatchers.IO) {
            runCatching {
                PilotAgentSettingsData(
                    agents = api.agents(workspaceId, true),
                    runtimes = api.runtimes(workspaceId),
                    skills = api.skills(workspaceId),
                    activity = runCatching { api.agentActivity30d(workspaceId) }.getOrDefault(emptyList()),
                    runCounts = runCatching { api.agentRunCounts30d(workspaceId) }.getOrDefault(emptyList()),
                    taskSnapshot = runCatching { api.agentTaskSnapshot(workspaceId) }.getOrDefault(emptyList()),
                )
            }
        }
    }

    fun submitAgentForm(data: PilotAgentSettingsData, editingAgent: Models.Agent?) {
        val agentName = name.trim()
        if (agentName.isEmpty() || saving || data.runtimes.isEmpty()) return
        focusManager.clearFocus(force = true)
        saving = true
        error = null
        resultText = null
        val runtime = data.runtimes[runtimeIndex.coerceAtMost(data.runtimes.lastIndex)]
        val visibility = visibilityOptions[visibilityIndex.coerceAtMost(visibilityOptions.lastIndex)]
        val maxTasks = maxTasksText.toIntOrNull()?.coerceAtLeast(1) ?: 1
        val customEnv = if (editingAgent != null && !customEnvDirty) editingAgent.customEnv else parseCustomEnvLines(customEnvText)
        val customArgs = parseCustomArgsLines(customArgsText)
        scope.launch {
            val result = withContext(Dispatchers.IO) {
                if (editingAgent == null) {
                    runCatching {
                        val created = api.createAgent(
                            workspaceId,
                            agentName,
                            description,
                            instructions,
                            runtime.id,
                            visibility,
                            maxTasks,
                            model,
                            avatarUrl,
                            customEnv,
                            customArgs,
                        )
                        if (selectedSkillIds.isNotEmpty()) {
                            api.setAgentSkills(workspaceId, created.id, selectedSkillIds.toList())
                        }
                        created
                    }
                } else {
                    runCatching {
                        val updated = api.updateAgent(
                            workspaceId,
                            editingAgent,
                            agentName,
                            description,
                            instructions,
                            runtime.id,
                            visibility,
                            maxTasks,
                            model,
                            avatarUrl,
                            customEnv,
                            customArgs,
                        )
                        api.setAgentSkills(workspaceId, updated.id, selectedSkillIds.toList())
                        updated
                    }
                }
            }
            saving = false
            result.onSuccess { saved ->
                state = state?.map { currentData ->
                    val updatedAgents = if (editingAgent == null) {
                        listOf(saved) + currentData.agents.filterNot { it.id == saved.id }
                    } else {
                        val replaced = currentData.agents.map { if (it.id == saved.id) saved else it }
                        if (replaced.any { it.id == saved.id }) replaced else listOf(saved) + replaced
                    }
                    currentData.copy(agents = updatedAgents)
                }
                resetForm()
                resultText = if (zh) "Agent 已保存" else "Agent saved"
                refresh++
            }.onFailure {
                error = "${if (editingAgent == null) if (zh) "创建失败" else "Create failed" else if (zh) "保存失败" else "Save failed"}: ${it.message ?: it.toString()}"
            }
        }
    }

    if (agentMode == AgentSettingsMode.Create || agentMode == AgentSettingsMode.Edit) {
        val editingAgent = editing
        PilotListPage(
            title = if (editingAgent == null) {
                if (zh) "新建 Agent" else "New Agent"
            } else {
                if (zh) "编辑 Agent" else "Edit Agent"
            },
            leading = {
                PilotSecondaryBackButton(
                    zh = zh,
                    onBack = { resetForm() },
                    contentDescription = if (zh) "返回 Agents" else "Back to Agents",
                )
            },
            listState = listState,
            bottomContent = {
                val data = state?.getOrNull()
                if (data != null && data.runtimes.isNotEmpty()) {
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth()
                            .imePadding(),
                        color = MulticaColors.Background,
                        tonalElevation = 0.dp,
                        shadowElevation = 0.dp,
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 26.dp, vertical = 14.dp),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                        ) {
                            MulticaPillButton(
                                text = if (zh) "取消" else "Cancel",
                                onClick = { resetForm() },
                                modifier = Modifier.weight(1f),
                                tone = MulticaButtonTone.Ghost,
                                contentDescription = "Agent Form Cancel",
                            )
                            MulticaPillButton(
                                text = if (saving) "..." else if (editingAgent == null) if (zh) "创建 Agent" else "Create Agent" else if (zh) "保存 Agent" else "Save Agent",
                                onClick = { submitAgentForm(data, editingAgent) },
                                modifier = Modifier.weight(1.2f),
                                tone = MulticaButtonTone.Primary,
                                contentDescription = if (editingAgent == null) "Agent Form Bottom Create" else "Agent Form Bottom Save",
                            )
                        }
                    }
                }
            },
        ) {
            val loaded = state
            when {
                loaded == null -> item { MulticaLoadingState(if (zh) "正在加载 Agents..." else "Loading agents...") }
                loaded.isFailure -> item {
                    MulticaErrorState(
                        "${if (zh) "加载失败" else "Load failed"}\n${loaded.exceptionOrNull()?.message}",
                        onRetry = { refresh++ },
                    )
                }
                else -> {
                    val data = loaded.getOrThrow()
                    if (editingAgent != null) {
                        item {
                            val editingRuntimeName = data.runtimes
                                .firstOrNull { it.id == editingAgent.runtimeId }
                                ?.name
                                ?: clean(editingAgent.runtimeId).ifBlank { if (zh) "未绑定 Runtime" else "No runtime" }
                            val detailParts = mutableListOf<String>()
                            clean(editingAgent.visibility).takeIf { it.isNotBlank() }?.let { detailParts += it }
                            clean(editingAgent.status).takeIf { it.isNotBlank() }?.let { detailParts += it }
                            detailParts += "${if (zh) "最大并发" else "Max tasks"} ${editingAgent.maxConcurrentTasks.coerceAtLeast(1)}"
                            val formSubtitle = listOf(
                                clean(editingAgent.description).ifBlank {
                                    clean(editingAgent.status).ifBlank { if (zh) "可编辑 Agent" else "Editable agent" }
                                },
                                editingRuntimeName,
                                detailParts.joinToString(" · ").ifBlank { agentTasksSummary(editingAgent, data, zh) },
                            ).filter { it.isNotBlank() }.joinToString(" · ")
                            AgentFormWebHero(
                                title = editingAgent.name,
                                subtitle = formSubtitle,
                                editing = true,
                                zh = zh,
                            )
                        }
                    } else {
                        item {
                            AgentFormWebHero(
                                title = if (zh) "新建 Agent" else "New Agent",
                                subtitle = if (zh) "填写名称、Runtime、可见性、模型与 Skills 后保存。" else "Fill in name, runtime, visibility, model, and skills before saving.",
                                editing = false,
                                zh = zh,
                            )
                        }
                    }
                    if (data.runtimes.isEmpty()) {
                        item {
                            MulticaErrorState(
                                if (zh) "没有可用 Runtime，先连接或创建 runtime 后再创建 Agent。" else "No runtime is available. Connect or create a runtime before saving an agent.",
                                onRetry = { refresh++ },
                            )
                        }
                    }
                    item { AgentDetailWebSectionLabel(if (zh) "Profile" else "Profile", "Agent Detail Web Profile Section") }
                    item {
                        MulticaTextField(
                            value = name,
                            onValueChange = { name = it },
                            label = if (zh) "名称" else "Name",
                            singleLine = true,
                            contentDescription = "Agent Form Name",
                        )
                    }
                    item {
                        MulticaTextField(
                            value = description,
                            onValueChange = { description = it },
                            label = if (zh) "描述" else "Description",
                            minLines = 2,
                            maxLines = 4,
                            contentDescription = "Agent Form Description",
                        )
                    }
                    item {
                        MulticaTextField(
                            value = avatarUrl,
                            onValueChange = { avatarUrl = it },
                            label = if (zh) "头像 URL" else "Avatar URL",
                            singleLine = true,
                            contentDescription = "Agent Form Avatar URL",
                        )
                    }
                    item {
                        MulticaPillButton(
                            text = if (uploadingAvatar) "..." else if (zh) "上传头像" else "Upload Avatar",
                            onClick = { if (!uploadingAvatar) avatarLauncher.launch("image/*") },
                            tone = MulticaButtonTone.Secondary,
                            contentDescription = "Agent Form Upload Avatar",
                        )
                    }
                    item { AgentDetailWebSectionLabel(if (zh) "Instructions" else "Instructions", "Agent Detail Web Instructions Section") }
                    item {
                        MulticaTextField(
                            value = instructions,
                            onValueChange = { instructions = it },
                            label = if (zh) "指令" else "Instructions",
                            minLines = 5,
                            maxLines = 12,
                            contentDescription = "Agent Detail Instructions Web Editor Agent Form Instructions",
                        )
                    }
                    item { AgentDetailWebSectionLabel(if (zh) "Runtime / Model" else "Runtime / Model", "Agent Detail Web Runtime Section") }
                    if (data.runtimes.isNotEmpty()) {
                        item {
                            val selectedRuntimeIndex = runtimeIndex.coerceAtMost(data.runtimes.lastIndex)
                            val selectedRuntime = data.runtimes[selectedRuntimeIndex]
                            AgentFormWebMenuRow(
                                eyebrow = if (zh) "Runtime" else "Runtime",
                                title = selectedRuntime.name,
                                subtitle = listOf(
                                    clean(selectedRuntime.status),
                                    clean(selectedRuntime.provider),
                                    clean(selectedRuntime.runtimeMode),
                                    clean(selectedRuntime.deviceInfo),
                                ).filter { it.isNotBlank() }.joinToString(" · "),
                                contentDescription = "Agent Form Runtime Web Picker",
                                options = data.runtimes.mapIndexed { index, runtime ->
                                    AgentFormMenuOption(
                                        label = runtime.name,
                                        detail = listOf(
                                            clean(runtime.status),
                                            clean(runtime.provider),
                                            clean(runtime.deviceInfo),
                                        ).filter { it.isNotBlank() }.joinToString(" · "),
                                        selected = index == selectedRuntimeIndex,
                                        onClick = { runtimeIndex = index },
                                    )
                                },
                            )
                        }
                    }
                    item {
                        AgentFormWebModelPicker(
                            model = model,
                            modelOptions = agentModelOptions(data, model, zh),
                            zh = zh,
                            onModelSelected = { model = it },
                        )
                    }
                    item {
                        val selectedVisibilityIndex = visibilityIndex.coerceAtMost(visibilityOptions.lastIndex)
                        val selectedVisibility = visibilityOptions[selectedVisibilityIndex]
                        AgentFormWebMenuRow(
                            eyebrow = if (zh) "可见性" else "Visibility",
                            title = selectedVisibility,
                            subtitle = when (selectedVisibility.lowercase()) {
                                "private" -> if (zh) "仅自己可见" else "Only you can access this agent"
                                else -> if (zh) "工作区成员可见" else "Visible to workspace members"
                            },
                            contentDescription = "Agent Form Visibility Web Picker",
                            options = visibilityOptions.mapIndexed { index, option ->
                                AgentFormMenuOption(
                                    label = option,
                                    detail = when (option.lowercase()) {
                                        "private" -> if (zh) "仅自己可见" else "Only you can access this agent"
                                        else -> if (zh) "工作区成员可见" else "Visible to workspace members"
                                    },
                                    selected = index == selectedVisibilityIndex,
                                    onClick = { visibilityIndex = index },
                                )
                            },
                        )
                    }
                    item {
                        AgentFormWebConcurrencyPicker(
                            maxTasksText = maxTasksText,
                            zh = zh,
                            onConcurrencySelected = { maxTasksText = it.coerceIn(1, 50).toString() },
                        )
                    }
                    if (data.skills.isNotEmpty()) {
                        item { AgentDetailWebSectionLabel(if (zh) "Skills" else "Skills", "Agent Detail Web Skills Section") }
                    }
                    item { AgentDetailWebSectionLabel(if (zh) "Environment" else "Environment", "Agent Detail Web Environment Section") }
                    item {
                        MulticaTextField(
                            value = customEnvText,
                            onValueChange = {
                                customEnvText = it
                                customEnvDirty = true
                            },
                            label = if (zh) "自定义环境变量" else "Custom Env",
                            minLines = 2,
                            maxLines = 5,
                            contentDescription = "Agent Form Custom Env",
                        )
                    }
                    item {
                        MulticaTextField(
                            value = customArgsText,
                            onValueChange = { customArgsText = it },
                            label = if (zh) "自定义参数" else "Custom Args",
                            minLines = 2,
                            maxLines = 5,
                            contentDescription = "Agent Form Custom Args",
                        )
                    }
                    if (editingAgent != null) {
                        item {
                            AgentDetailActivityWebSection(
                                agent = editingAgent,
                                data = data,
                                zh = zh,
                                contentDescription = "Agent Detail Web Activity Section",
                            )
                        }
                    }
                    if (data.skills.isNotEmpty()) {
                        item {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(top = 2.dp, bottom = 4.dp)
                                    .semantics { contentDescription = "Agent Form Web Skill Picker" },
                                verticalArrangement = Arrangement.spacedBy(3.dp),
                            ) {
                                Text(
                                    text = if (zh) "Agent Skills" else "Agent Skills",
                                    style = MaterialTheme.typography.labelSmall.copy(
                                        fontSize = 11.sp,
                                        lineHeight = 13.sp,
                                        fontWeight = FontWeight.SemiBold,
                                    ),
                                    color = MulticaColors.Muted,
                                    maxLines = 1,
                                )
                                Text(
                                    text = if (selectedSkillIds.isEmpty()) {
                                        if (zh) "选择要随 Agent 一起启用的 Skill" else "Select skills to enable with this agent"
                                    } else {
                                        if (zh) "已选择 ${selectedSkillIds.size} 个 Skill" else "${selectedSkillIds.size} skills selected"
                                    },
                                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                                    color = MulticaColors.Muted.copy(alpha = 0.72f),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                        items(data.skills) { skill ->
                            val attached = selectedSkillIds.contains(skill.id)
                            AgentSkillWebToggleRow(
                                skill = skill,
                                attached = attached,
                                zh = zh,
                                onToggle = {
                                    focusManager.clearFocus(force = true)
                                    selectedSkillGeneration.incrementAndGet()
                                    selectedSkillIds = if (attached) selectedSkillIds - skill.id else selectedSkillIds + skill.id
                                },
                            )
                        }
                    }
                    if (!error.isNullOrBlank()) item {
                        PilotInlineResultState(
                            message = error.orEmpty(),
                            isError = true,
                            contentDescription = "Agent Form Result Web Banner",
                        )
                    }
                    if (!resultText.isNullOrBlank()) item { MulticaSuccessState(resultText.orEmpty()) }
                    item {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            MulticaPillButton(
                                text = if (zh) "取消" else "Cancel",
                                onClick = { resetForm() },
                                modifier = Modifier.weight(1f),
                                tone = MulticaButtonTone.Ghost,
                            )
                            MulticaPillButton(
                                text = if (saving) "..." else if (editingAgent == null) if (zh) "创建 Agent" else "Create Agent" else if (zh) "保存 Agent" else "Save Agent",
                                onClick = { submitAgentForm(data, editingAgent) },
                                modifier = Modifier.weight(1f),
                                tone = MulticaButtonTone.Primary,
                                contentDescription = if (editingAgent == null) "Agent Form Create" else "Agent Form Save",
                            )
                        }
                    }
                }
            }
        }
        return
    }

    PilotListPage(
        title = if (zh) "Agents" else "Agents",
        leading = { PilotSecondaryBackButton(zh = zh, onBack = onBack) },
        trailing = {
            MulticaIconPillButton(
                icon = Icons.Outlined.Add,
                contentDescription = "Agent Header Create Button",
                onClick = { startCreate() },
                tone = MulticaButtonTone.Primary,
            )
        },
        listState = listState,
    ) {
        val loaded = state
        if (loaded == null) {
            item { MulticaLoadingState(if (zh) "正在加载 Agents..." else "Loading agents...") }
        } else {
            loaded.onFailure {
                item { MulticaErrorState("${if (zh) "加载失败" else "Load failed"}\n${it.message}", onRetry = { refresh++ }) }
            }.onSuccess { data ->
                item { AgentsOverviewPanel(data, zh) }
                item {
                    MulticaTextField(
                        value = agentQuery,
                        onValueChange = { agentQuery = it },
                        modifier = Modifier
                            .fillMaxWidth(),
                        label = if (zh) "搜索 Agents" else "Search agents",
                        contentDescription = "Agent List Search",
                        singleLine = true,
                    )
                }
                item {
                    val activeCount = data.agents.count { it.archivedAt.isNullOrBlank() }
                    val archivedCount = data.agents.count { !it.archivedAt.isNullOrBlank() }
                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 10.dp, bottom = 6.dp)
                            .semantics { contentDescription = "Agent Active Archived Filter" },
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        item {
                            SettingsWebFilterPill(
                                text = if (zh) "活跃 $activeCount" else "Active $activeCount",
                                selected = agentArchiveView == "active",
                                onClick = {
                                    agentArchiveView = "active"
                                    agentActionMenuId = null
                                },
                                contentDescription = "Agent Active Filter",
                            )
                        }
                        item {
                            SettingsWebFilterPill(
                                text = if (zh) "已归档 $archivedCount" else "Archived $archivedCount",
                                selected = agentArchiveView == "archived",
                                onClick = {
                                    agentArchiveView = "archived"
                                    agentActionMenuId = null
                                },
                                contentDescription = "Agent Archived Filter",
                            )
                        }
                    }
                }
                pendingArchive?.let { agent ->
                    item {
                        AgentArchiveConfirmWebPanel(
                            agentName = agent.name,
                            archiving = archiving,
                            zh = zh,
                            onCancel = { pendingArchive = null },
                            onConfirm = {
                                if (!archiving) {
                                    archiving = true
                                    error = null
                                    scope.launch {
                                        val result = withContext(Dispatchers.IO) {
                                            runCatching { api.archiveAgent(workspaceId, agent.id) }
                                        }
                                        archiving = false
                                        result.onSuccess {
                                            pendingArchive = null
                                            refresh++
                                        }.onFailure {
                                            error = "${if (zh) "归档失败" else "Archive failed"}: ${it.message ?: it.toString()}"
                                        }
                                    }
                                }
                            },
                        )
                    }
                }
                item {
                    if (!error.isNullOrBlank()) {
                        PilotInlineResultState(
                            message = error.orEmpty(),
                            isError = true,
                            contentDescription = "Agent List Result Web Banner",
                        )
                    }
                }
                if (!resultText.isNullOrBlank()) item { MulticaSuccessState(resultText.orEmpty()) }
                val normalizedAgentQuery = agentQuery.trim()
                val visibleAgents = data.agents
                    .asSequence()
                    .filter { agent ->
                        val archived = !agent.archivedAt.isNullOrBlank()
                        if (agentArchiveView == "archived") archived else !archived
                    }
                    .filter { agent ->
                        normalizedAgentQuery.isBlank() ||
                            clean(agent.name).contains(normalizedAgentQuery, ignoreCase = true) ||
                            clean(agent.description).contains(normalizedAgentQuery, ignoreCase = true) ||
                            clean(agent.status).contains(normalizedAgentQuery, ignoreCase = true)
                    }
                    .sortedWith(
                        compareByDescending<Models.Agent> { it.name },
                    )
                    .toList()
                if (visibleAgents.isEmpty()) item {
                    if (data.agents.isEmpty()) {
                        AgentsWebEmptyState(zh = zh)
                    } else {
                        AgentsWebNoMatchesState(
                            zh = zh,
                            query = normalizedAgentQuery,
                            archived = agentArchiveView == "archived",
                        )
                    }
                }
                items(visibleAgents) { agent ->
                    val archived = !agent.archivedAt.isNullOrBlank()
                    val tasksSummary = agentTasksSummary(agent, data, zh)
                    val activeTaskCount = data.taskSnapshot.count {
                        it.agentId == agent.id && it.status in setOf("queued", "dispatched", "running")
                    }
                    val compactTaskLabel = if (activeTaskCount > 0) {
                        if (zh) "$activeTaskCount 个活跃任务" else "$activeTaskCount active"
                    } else {
                        if (zh) "无活跃任务" else "No active tasks"
                    }
                    AgentRosterWebDenseRow(
                        agent = agent,
                        archived = archived,
                        statusLabel = if (archived) if (zh) "已归档" else "Archived" else clean(agent.status).ifBlank { if (zh) "Agent" else "Agent" },
                        runtimeLabel = agentRuntimeLabel(agent, data),
                        modelLabel = clean(agent.model).ifBlank { if (zh) "默认模型" else "Default model" },
                        recentTaskSummary = agentRecentTask(agent, data)?.let { agentTaskSummary(it, zh) }
                            ?: if (zh) "暂无最近任务" else "No recent task",
                        metricsSummary = agentMetricsSummary(agent, data, zh),
                        compactTaskLabel = compactTaskLabel,
                        actionsExpanded = agentActionMenuId == agent.id,
                        onClick = { startEdit(agent, data) },
                        onActionsClick = {
                            agentActionMenuId = if (agentActionMenuId == agent.id) null else agent.id
                            pendingArchive = null
                            error = null
                            resultText = null
                        },
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(1.dp)
                            .background(MulticaColors.Border.copy(alpha = 0.74f))
                    )
                    AgentRowCupertinoMoreMenu(
                        visible = agentActionMenuId == agent.id,
                        agentName = agent.name,
                        archived = archived,
                        hasActiveTasks = activeTaskCount > 0,
                        tasksSummary = tasksSummary,
                        cancelling = cancellingAgentTasks == agent.id,
                        restoring = restoringAgentId == agent.id,
                        zh = zh,
                        onDismissRequest = { agentActionMenuId = null },
                        onEdit = { startEdit(agent, data) },
                        onDuplicate = { startDuplicate(agent, data) },
                        onManageSkills = { startEdit(agent, data) },
                        onArchive = { pendingArchive = agent },
                        onCancelTasks = {
                            if (cancellingAgentTasks == null) {
                                cancellingAgentTasks = agent.id
                                cancelTaskResults = cancelTaskResults - agent.id
                                error = null
                                resultText = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) {
                                        runCatching { api.cancelAgentTasks(workspaceId, agent.id) }
                                    }
                                    cancellingAgentTasks = null
                                    result.onSuccess { count ->
                                        val message = if (zh) "已取消 $count 个任务" else "Cancelled tasks: $count"
                                        resultText = message
                                        cancelTaskResults = cancelTaskResults + (agent.id to message)
                                        refresh++
                                    }.onFailure {
                                        error = "${if (zh) "取消任务失败" else "Cancel tasks failed"}: ${it.message ?: it.toString()}"
                                    }
                                }
                            }
                        },
                        onRestore = {
                            if (restoringAgentId == null) {
                                restoringAgentId = agent.id
                                error = null
                                resultText = null
                                scope.launch {
                                    val result = withContext(Dispatchers.IO) {
                                        runCatching { api.restoreAgent(workspaceId, agent.id) }
                                    }
                                    restoringAgentId = null
                                    result.onSuccess { restored ->
                                        state = state?.map { currentData ->
                                            currentData.copy(
                                                agents = currentData.agents.map {
                                                    if (it.id == restored.id) restored else it
                                                }
                                            )
                                        }
                                        resultText = if (zh) "Agent 已恢复" else "Agent restored"
                                        refresh++
                                    }.onFailure {
                                        error = "${if (zh) "恢复失败" else "Restore failed"}: ${it.message ?: it.toString()}"
                                    }
                                }
                            }
                        },
                    )
                }
            }
        }
    }
}

@Composable
private fun AgentRowCupertinoMoreMenu(
    visible: Boolean,
    agentName: String,
    archived: Boolean,
    hasActiveTasks: Boolean,
    tasksSummary: String,
    cancelling: Boolean,
    restoring: Boolean,
    zh: Boolean,
    onDismissRequest: () -> Unit,
    onEdit: () -> Unit,
    onDuplicate: () -> Unit,
    onManageSkills: () -> Unit,
    onArchive: () -> Unit,
    onCancelTasks: () -> Unit,
    onRestore: () -> Unit,
) {
    Box(modifier = Modifier.semantics { contentDescription = "Agent Row Cupertino More Menu $agentName" }) {
        MulticaCupertinoActionSheet(
            visible = visible,
            title = agentName,
            message = if (zh) "选择 Agent 操作" else "Choose an agent action",
            cancelText = if (zh) "取消" else "Cancel",
            onDismissRequest = onDismissRequest,
            items = buildList {
                add(
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "编辑 Agent" else "Edit Agent",
                        subtitle = if (zh) "打开完整配置" else "Open full configuration",
                        contentDescription = "Agent Menu Edit $agentName",
                        onClick = onEdit,
                    )
                )
                add(
                    MulticaCupertinoActionSheetItem(
                        title = if (zh) "管理 Skills" else "Manage Agent Skills",
                        subtitle = if (zh) "编辑已绑定技能" else "Edit attached skills",
                        contentDescription = "Agent Menu Skills $agentName",
                        onClick = onManageSkills,
                    )
                )
                if (!archived) {
                    add(
                        MulticaCupertinoActionSheetItem(
                            title = if (zh) "复制 Agent" else "Duplicate Agent",
                            subtitle = if (zh) "用当前配置创建副本" else "Create from this configuration",
                            contentDescription = "Agent Menu Duplicate $agentName",
                            onClick = onDuplicate,
                        )
                    )
                }
                if (archived) {
                    add(
                        MulticaCupertinoActionSheetItem(
                            title = if (restoring) if (zh) "恢复中..." else "Restoring..." else if (zh) "恢复 Agent" else "Restore Agent",
                            subtitle = agentName,
                            contentDescription = "Agent Menu Restore $agentName",
                            enabled = !restoring,
                            onClick = onRestore,
                        )
                    )
                } else {
                    if (hasActiveTasks) {
                        add(
                            MulticaCupertinoActionSheetItem(
                                title = if (cancelling) if (zh) "取消中..." else "Cancelling..." else if (zh) "取消任务" else "Cancel Tasks",
                                subtitle = tasksSummary,
                                contentDescription = "Agent Menu Cancel Tasks $agentName",
                                destructive = true,
                                enabled = !cancelling,
                                onClick = onCancelTasks,
                            )
                        )
                    }
                    add(
                        MulticaCupertinoActionSheetItem(
                            title = if (zh) "归档 Agent" else "Archive Agent",
                            subtitle = agentName,
                            contentDescription = "Agent Menu Archive $agentName",
                            destructive = true,
                            onClick = onArchive,
                        )
                    )
                }
            },
        )
    }
}

@Composable
private fun AgentRosterWebDenseRow(
    agent: Models.Agent,
    archived: Boolean,
    statusLabel: String,
    runtimeLabel: String,
    modelLabel: String,
    recentTaskSummary: String,
    metricsSummary: String,
    compactTaskLabel: String,
    actionsExpanded: Boolean,
    onClick: () -> Unit,
    onActionsClick: () -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .semantics { contentDescription = "Agent ${agent.name}" },
        color = MulticaColors.Background,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .semantics { contentDescription = "Agent Roster Web Dense Row Agent Web Dense Row ${agent.name}" }
                .padding(vertical = 9.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.Top,
        ) {
            Box(
                modifier = Modifier
                    .padding(top = 1.dp)
                    .size(32.dp)
                    .clip(RoundedCornerShape(10.dp))
                    .background(MulticaColors.AccentSoft.copy(alpha = if (archived) 0.14f else 0.26f)),
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    text = clean(agent.name).take(1).uppercase().ifBlank { "A" },
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 14.sp),
                    color = if (archived) MulticaColors.Muted else MulticaColors.Accent,
                    maxLines = 1,
                )
                MulticaRemoteAvatarImage(
                    avatarUrl = agent.avatarUrl,
                    size = 32.dp,
                    shape = RoundedCornerShape(10.dp),
                    contentDescription = "Agent Row Remote Avatar ${agent.name}",
                )
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .size(8.dp)
                        .clip(RoundedCornerShape(999.dp))
                        .background(if (archived) MulticaColors.Muted else MulticaColors.Success)
                        .semantics { contentDescription = "Agent Availability Dot ${agent.name}" },
                )
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(7.dp)) {
                    SelectionContainer(modifier = Modifier.weight(1f)) {
                        Text(
                            text = agent.name,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Medium,
                                fontSize = 15.sp,
                                lineHeight = 19.sp,
                            ),
                            color = MulticaColors.Text,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    Text(
                        text = statusLabel,
                        style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp, fontWeight = FontWeight.SemiBold),
                        color = if (archived) MulticaColors.Muted else MulticaColors.Success,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                SelectionContainer {
                    Text(
                        text = clean(agent.description).ifBlank { compactTaskLabel },
                        style = MaterialTheme.typography.labelMedium.copy(fontSize = 12.sp, lineHeight = 15.sp),
                        color = MulticaColors.Muted.copy(alpha = 0.72f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics { contentDescription = "Agent Runtime Model Row ${agent.name}" },
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    AgentRosterMetaPill(
                        label = runtimeLabel,
                        contentDescription = "Agent Runtime Pill ${agent.name}",
                        modifier = Modifier.weight(1.12f),
                    )
                    AgentRosterMetaPill(
                        label = modelLabel,
                        contentDescription = "Agent Model Pill ${agent.name}",
                        modifier = Modifier.weight(0.88f),
                    )
                }
                Text(
                    text = recentTaskSummary,
                    modifier = Modifier.semantics { contentDescription = "Agent Recent Task ${agent.name}" },
                    style = MaterialTheme.typography.labelMedium.copy(fontSize = 11.sp, lineHeight = 14.sp),
                    color = MulticaColors.Muted.copy(alpha = 0.76f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = metricsSummary,
                    modifier = Modifier.semantics { contentDescription = "Agent Metrics Summary ${agent.name}" },
                    style = MaterialTheme.typography.labelSmall.copy(fontSize = 10.sp, lineHeight = 12.sp),
                    color = MulticaColors.Muted.copy(alpha = 0.62f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            MulticaIconPillButton(
                icon = Icons.Outlined.MoreHoriz,
                contentDescription = "Agent Actions ${agent.name}",
                onClick = onActionsClick,
                tone = if (actionsExpanded) MulticaButtonTone.Primary else MulticaButtonTone.Ghost,
                modifier = Modifier
                    .size(34.dp)
                    .semantics(mergeDescendants = true) {
                        contentDescription = "Agent Actions ${agent.name}"
                    },
            )
        }
    }
}

@Composable
private fun AgentRosterMetaPill(
    label: String,
    contentDescription: String,
    modifier: Modifier = Modifier,
) {
    Surface(
        shape = RoundedCornerShape(999.dp),
        color = MulticaColors.Surface,
        tonalElevation = 0.dp,
        shadowElevation = 0.dp,
        modifier = modifier
            .border(1.dp, MulticaColors.Border.copy(alpha = 0.62f), RoundedCornerShape(999.dp))
            .semantics { this.contentDescription = contentDescription },
    ) {
        Text(
            text = label,
            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
            style = MaterialTheme.typography.labelSmall.copy(fontSize = 11.sp, lineHeight = 13.sp),
            color = MulticaColors.Muted,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
    }
}

