@Composable
private fun PilotGlassTopSlot(
    hazeState: HazeState,
    content: @Composable () -> Unit,
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(bottomStart = 24.dp, bottomEnd = 24.dp))
            .hazeEffect(
                hazeState,
                style = HazeDefaults.style(
                    backgroundColor = MulticaColors.Background.copy(alpha = 0.78f),
                    blurRadius = 24.dp,
                    noiseFactor = 0.08f,
                ),
            )
            .background(MulticaColors.Background.copy(alpha = 0.78f))
            .semantics(mergeDescendants = false) { contentDescription = "Pilot Glass Pinned Header" },
    ) {
        content()
    }
}

@Composable
private fun PilotGlassBottomSlot(
    hazeState: HazeState,
    content: @Composable () -> Unit,
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp))
            .hazeEffect(
                hazeState,
                style = HazeDefaults.style(
                    backgroundColor = MulticaColors.Background.copy(alpha = 0.72f),
                    blurRadius = 24.dp,
                    noiseFactor = 0.08f,
                ),
            )
            .background(MulticaColors.Background.copy(alpha = 0.72f))
            .imePadding()
            .semantics(mergeDescendants = false) { contentDescription = "Pilot Glass Bottom Slot" },
    ) {
        content()
    }
}

@Composable
private fun PilotPageHeader(
    title: String,
    leading: @Composable (() -> Unit)? = null,
    trailing: @Composable (() -> Unit)? = null,
    compact: Boolean = false,
) {
    val headerDescription = if (leading == null) "Pilot Web Compact Header" else "Pilot Secondary Page Header"
    if (compact) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 2.dp, bottom = 18.dp)
                .semantics { contentDescription = headerDescription },
        ) {
            Box(
                modifier = Modifier
                    .align(Alignment.CenterHorizontally)
                    .width(54.dp)
                    .height(5.dp)
                    .clip(RoundedCornerShape(999.dp))
                    .background(MulticaColors.Border)
            )
            Spacer(modifier = Modifier.height(14.dp))
            Box(modifier = Modifier.fillMaxWidth()) {
                Box(modifier = Modifier.align(Alignment.CenterStart)) {
                    leading?.invoke()
                }
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleLarge,
                    color = MulticaColors.TextPrimary,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.align(Alignment.Center),
                )
                Box(modifier = Modifier.align(Alignment.CenterEnd)) {
                    trailing?.invoke()
                }
            }
        }
        return
    }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 48.dp)
            .padding(bottom = 12.dp)
            .semantics { contentDescription = headerDescription },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        leading?.invoke()
        val titleStyle = MaterialTheme.typography.titleLarge.copy(
            fontSize = 22.sp,
            lineHeight = 27.sp,
            fontWeight = FontWeight.SemiBold,
        )
        Text(
            text = title,
            style = titleStyle,
            color = MulticaColors.TextPrimary,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier
                .weight(1f)
                .then(if (leading == null) Modifier else Modifier.padding(start = 10.dp)),
        )
        trailing?.invoke()
    }
}

