private fun clean(value: String?): String {
    val text = value?.trim().orEmpty()
    return if (text.equals("null", ignoreCase = true)) "" else text
}

private fun agentCustomEnvPlaceholder(agent: Models.Agent, zh: Boolean): String {
    val count = agent.customEnv.size
    if (count <= 0) return ""
    return if (zh) {
        "已保存 $count 个环境变量。留空则保持不变，输入 KEY=value 可替换。"
    } else {
        "$count environment variables saved. Leave unchanged to keep them, or enter KEY=value lines to replace."
    }
}

private fun agentModelOptions(data: PilotAgentSettingsData, model: String, zh: Boolean): List<AgentFormModelOption> {
    val current = clean(model)
    val options = mutableListOf(
        AgentFormModelOption(
            value = "",
            label = if (zh) "默认模型" else "Default model",
            detail = if (zh) "交给 runtime 使用默认配置" else "Use the runtime default configuration",
        )
    )
    val seen = linkedSetOf("")
    if (current.isNotBlank() && seen.add(current)) {
        options += AgentFormModelOption(
            value = current,
            label = current,
            detail = if (zh) "当前模型" else "Current model",
        )
    }
    data.agents
        .map { clean(it.model) }
        .filter { it.isNotBlank() && seen.add(it) }
        .sorted()
        .forEach { value ->
            options += AgentFormModelOption(
                value = value,
                label = value,
                detail = if (zh) "来自现有 Agent" else "Used by an existing agent",
            )
        }
    return options
}

private fun agentConcurrencyOptions(maxTasksText: String): List<Int> {
    val current = maxTasksText.toIntOrNull()?.coerceIn(1, 50) ?: 1
    return (listOf(1, 2, 3, 4, 5, 6, 8, 10, 20, 50) + current)
        .map { it.coerceIn(1, 50) }
        .distinct()
        .sorted()
}

private fun parseCustomEnvLines(text: String): Map<String, String> {
    return text
        .lineSequence()
        .map { it.trim() }
        .filter { it.isNotEmpty() }
        .mapNotNull { line ->
            val index = line.indexOf('=')
            if (index <= 0) null else line.substring(0, index).trim() to line.substring(index + 1)
        }
        .filter { it.first.isNotEmpty() }
        .toMap(LinkedHashMap())
}

private fun parseCustomArgsLines(text: String): List<String> {
    return text
        .lineSequence()
        .map { it.trim() }
        .filter { it.isNotEmpty() }
        .toList()
}

private fun agentMetricsSummary(agent: Models.Agent, data: PilotAgentSettingsData, zh: Boolean): String {
    val runCount = data.runCounts.firstOrNull { it.agentId == agent.id }?.runCount ?: 0
    val activity = data.activity.filter { it.agentId == agent.id }
    val taskCount = activity.sumOf { it.taskCount }
    val failedCount = activity.sumOf { it.failedCount }
    val activeCount = data.taskSnapshot.count { it.agentId == agent.id && it.status in setOf("queued", "dispatched", "running") }
    return if (zh) {
        "30 天运行 $runCount · 30 天活动 $taskCount · 失败 $failedCount · 活跃 $activeCount"
    } else {
        "Runs 30d: $runCount · Activity 30d: $taskCount · Failed: $failedCount · Active: $activeCount"
    }
}

private fun agentRuntimeLabel(agent: Models.Agent, data: PilotAgentSettingsData): String {
    val runtime = data.runtimes.firstOrNull { it.id == agent.runtimeId }
    return listOf(
        clean(runtime?.name ?: "").ifBlank { clean(agent.runtimeId).ifBlank { "No runtime" } },
        clean(runtime?.runtimeMode ?: "").ifBlank { clean(runtime?.provider ?: "") },
    ).filter { it.isNotBlank() }.joinToString(" · ")
}

private fun agentRecentTask(agent: Models.Agent, data: PilotAgentSettingsData): Models.AgentTask? {
    return data.taskSnapshot
        .filter { it.agentId == agent.id }
        .maxByOrNull { clean(it.completedAt).ifBlank { clean(it.startedAt).ifBlank { clean(it.createdAt) } } }
}

private fun agentTaskSummary(task: Models.AgentTask, zh: Boolean): String {
    val source = clean(task.kind).ifBlank { if (task.issueId.isNotBlank()) "issue" else "" }
    val time = clean(task.completedAt).ifBlank { clean(task.startedAt).ifBlank { clean(task.createdAt) } }
    val reason = clean(task.failureReason).ifBlank { clean(task.triggerSummary) }
    val parts = listOf(clean(task.status), source, shortDate(time), reason).filter { it.isNotBlank() }
    return parts.joinToString(" · ").ifBlank { if (zh) "暂无任务详情" else "No task detail" }
}

private fun agentTasksSummary(agent: Models.Agent, data: PilotAgentSettingsData, zh: Boolean): String {
    val tasks = data.taskSnapshot.filter { it.agentId == agent.id }
    val active = tasks.filter { it.status in setOf("queued", "dispatched", "running") }
    val latest = tasks.maxByOrNull { clean(it.completedAt).ifBlank { clean(it.startedAt).ifBlank { clean(it.createdAt) } } }
    if (active.isEmpty()) {
        val fallback = latest?.let { agentTaskSummary(it, zh) }.orEmpty()
        return if (fallback.isBlank()) {
            if (zh) "暂无活跃任务" else "No active tasks"
        } else {
            "${if (zh) "暂无活跃任务" else "No active tasks"} · $fallback"
        }
    }
    val latestActive = active.maxByOrNull { clean(it.startedAt).ifBlank { clean(it.createdAt) } } ?: active.first()
    return if (zh) {
        "${active.size} 个活跃任务 · ${agentTaskSummary(latestActive, true)}"
    } else {
        "${active.size} active · ${agentTaskSummary(latestActive, false)}"
    }
}

private fun shortDate(value: String?): String {
    val text = clean(value)
    if (text.length >= 16) return text.substring(0, 16).replace('T', ' ')
    return text
}

private fun relativeDate(value: String?, zh: Boolean): String {
    val millis = parseDueDateMillis(value) ?: return shortDate(value)
    val deltaSeconds = ((System.currentTimeMillis() - millis) / 1000).coerceAtLeast(0)
    if (deltaSeconds < 60) return if (zh) "刚刚" else "now"
    val minutes = deltaSeconds / 60
    if (minutes < 60) return if (zh) "${minutes}分钟前" else "${minutes}m ago"
    val hours = minutes / 60
    if (hours < 24) return if (zh) "${hours}小时前" else "${hours}h ago"
    val days = hours / 24
    if (days < 7) return if (zh) "${days}天前" else "${days}d ago"
    return shortDate(value)
}

private fun formatDueDateMillis(millis: Long?): String {
    val formatter = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", Locale.US)
    formatter.timeZone = TimeZone.getTimeZone("UTC")
    return formatter.format(Date(millis ?: System.currentTimeMillis()))
}

private fun parseDueDateMillis(value: String?): Long? {
    val text = clean(value)
    if (text.isBlank()) return null
    val patterns = listOf("yyyy-MM-dd'T'HH:mm:ss'Z'", "yyyy-MM-dd")
    for (pattern in patterns) {
        val formatter = SimpleDateFormat(pattern, Locale.US)
        formatter.timeZone = TimeZone.getTimeZone("UTC")
        val parsed = runCatching { formatter.parse(text)?.time }.getOrNull()
        if (parsed != null) return parsed
    }
    return null
}

private fun displayNameForUri(context: Context, uri: Uri): String {
    val cursor = context.contentResolver.query(uri, null, null, null, null)
    cursor?.use {
        val index = it.getColumnIndex(OpenableColumns.DISPLAY_NAME)
        if (index >= 0 && it.moveToFirst()) {
            val name = it.getString(index)
            if (!name.isNullOrBlank()) return name
        }
    }
    return "avatar.png"
}

private fun formatBytes(bytes: Long): String {
    if (bytes <= 0L) return ""
    if (bytes < 1024L) return "$bytes B"
    val kb = bytes / 1024.0
    if (kb < 1024.0) return String.format("%.1f KB", kb)
    return String.format("%.1f MB", kb / 1024.0)
}

private fun preview(value: String): String? {
    val text = value.replace('\n', ' ').trim()
    if (text.isBlank()) return null
    return if (text.length > 180) text.substring(0, 180) + "..." else text
}

private fun messageSummary(message: Models.TaskMessage): String {
    val text = clean(message.content).ifBlank { clean(message.output) }
    return if (text.length > 1200) text.substring(0, 1200) + "..." else text
}

private fun roleLabel(role: String?, zh: Boolean): String {
    return when (clean(role).lowercase()) {
        "user" -> if (zh) "你" else "You"
        "assistant" -> if (zh) "助手" else "Assistant"
        "agent" -> if (zh) "Agent" else "Agent"
        else -> clean(role).ifBlank { if (zh) "消息" else "Message" }
    }
}

